INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT 'c2a94e8d-b395-7af2-b02f-4214c301e5b0', 'e01a7f53-4c97-7ac0-a0ae-79deabf45ffe', 1, 'PUBLISHED', 'PCA & Dimensionality Reduction', '[{"id":"c769de23-bc86-7f90-8c96-0c8491ac8ffa","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Principal component analysis finds new, uncorrelated axes — the directions along which the data varies most — and lets you keep only the first few. It compresses, denoises and visualises data, but only captures linear structure."}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Standardise","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Centre every feature (PCA does this) and usually scale to unit variance (you must do this)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Covariance","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Compute the covariance matrix of the features."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Eigen-decompose","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Its eigenvectors are the principal components; each eigenvalue is the variance along that component."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Project","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Keep the top-k components: "},{"type":"text","text":"Z = X_centred · W_k","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}]}]}},"revision":1},{"id":"39c66d7f-182e-786d-8b28-142c8e85430f","type":"code","position":"a1","content":{"language":"python","code":"import numpy as np\nfrom sklearn.decomposition import PCA\n\nrng = np.random.default_rng(0)\nx = rng.normal(size=500)\nX = np.c_[x, 0.5 * x + rng.normal(scale=0.3, size=500)]     # two correlated features\n\neigvals, eigvecs = np.linalg.eigh(np.cov(X, rowvar=False))  # by hand\nprint((eigvals[::-1] / eigvals.sum()).round(3))             # [0.954 0.046] ← share of variance per component\n\npca = PCA().fit(X)\nprint(pca.explained_variance_ratio_.round(3))              # [0.954 0.046] ← same\nprint(np.abs(pca.components_[0]).round(3))                 # [0.882 0.471] ← PC1 direction (sign is arbitrary)","filename":"Python"},"revision":1},{"id":"5a4e9513-d78b-7c94-9532-34a6d14063ea","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"Scale first"}]},"revision":1},{"id":"b5c6843d-ba2e-7c04-9736-32f1f300937c","type":"text","position":"a3","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"PCA maximises variance, so a feature measured in large units dominates. On the wine data, proline (values in the hundreds to thousands) alone makes up almost all the “variance” until the features are standardised:"}]}]}},"revision":1},{"id":"bca21610-de3c-7186-9cd7-0b88a80265d7","type":"code","position":"a4","content":{"language":"python","code":"from sklearn.datasets import load_wine\nfrom sklearn.decomposition import PCA\nfrom sklearn.pipeline import make_pipeline\nfrom sklearn.preprocessing import StandardScaler\n\nX, _ = load_wine(return_X_y=True)\nprint(PCA(n_components=3).fit(X).explained_variance_ratio_.round(3))   # [0.998 0.002 0.   ] ← PC1 is just proline\nscaled = make_pipeline(StandardScaler(), PCA(n_components=3)).fit(X)\nprint(scaled[-1].explained_variance_ratio_.round(3))                   # [0.362 0.192 0.111] ← real structure","filename":"Python"},"revision":1},{"id":"be0624cd-a8f3-7c5d-a563-452862df7813","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"How many components?"}]},"revision":1},{"id":"41f2d04e-1d44-76be-8ae7-78a95fb69253","type":"code","position":"a6","content":{"language":"python","code":"import numpy as np\nfrom sklearn.datasets import load_digits\nfrom sklearn.decomposition import PCA\n\nX, _ = load_digits(return_X_y=True)                     # 64 pixel features\ncum = np.cumsum(PCA().fit(X).explained_variance_ratio_)\nprint(int(np.argmax(cum >= 0.95)) + 1)                  # 29 ← components needed for 95% of the variance\n\npca = PCA(n_components=0.95).fit(X)                     # or ask for the fraction directly\nX_back = pca.inverse_transform(pca.transform(X))\nprint(pca.n_components_, round(np.mean((X - X_back) ** 2), 2))   # 29 0.85 ← reconstruction error is small","filename":"Python"},"revision":1},{"id":"d7f58698-94a0-7e49-a170-4024b53957c3","type":"text","position":"a7","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Common rules: keep enough components for 90–99% of the variance, look for an elbow in the scree plot, or treat k as a hyperparameter and pick it by the downstream model''s cross-validated score."}]}]}},"revision":1},{"id":"6d445fda-535d-7bbd-97c7-3c8904982213","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"Uses and caveats"}]},"revision":1},{"id":"123d84d7-aa24-7211-8aea-682eac0d88ec","type":"table","position":"a9","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Use"}],[{"type":"text","text":"Caveat"}]],[[{"type":"text","text":"Visualise high-dimensional data in 2-D/3-D"}],[{"type":"text","text":"Only linear structure; clusters may overlap in a linear projection"}]],[[{"type":"text","text":"Compress, denoise, speed up downstream models"}],[{"type":"text","text":"Fit PCA on the training split only (inside the "},{"type":"text","text":"Pipeline","marks":[{"type":"code"}]},{"type":"text","text":")"}]],[[{"type":"text","text":"Remove multicollinearity (components are uncorrelated)"}],[{"type":"text","text":"Components are mixtures of all features — harder to explain"}]],[[{"type":"text","text":"Fight the curse of dimensionality"}],[{"type":"text","text":"PCA ignores the target: a low-variance direction can be the predictive one"}]]]},"revision":1},{"id":"d81f8527-3383-7b00-ace9-2fa8122b145a","type":"text","position":"aA","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Relatives: "},{"type":"text","text":"TruncatedSVD","marks":[{"type":"code"}]},{"type":"text","text":" works on sparse matrices (text — “latent semantic analysis”); "},{"type":"text","text":"LDA","marks":[{"type":"bold"}]},{"type":"text","text":" (linear discriminant analysis) is supervised and finds directions that separate classes; "},{"type":"text","text":"KernelPCA","marks":[{"type":"code"}]},{"type":"text","text":" handles non-linear structure."}]}]}},"revision":1},{"id":"fe78c4cb-9cde-731a-8fa5-147919b9f456","type":"heading","position":"aB","content":{"level":1,"content":[{"type":"text","text":"t-SNE and UMAP — for looking, not for modelling"}]},"revision":1},{"id":"cc9affb8-313a-72b3-ae2b-ee6a5d208c7e","type":"table","position":"aC","content":{"hasHeaderRow":true,"rows":[[[],[{"type":"text","text":"t-SNE"}],[{"type":"text","text":"UMAP"}]],[[{"type":"text","text":"Preserves"}],[{"type":"text","text":"Local neighbourhoods"}],[{"type":"text","text":"Local neighbourhoods, somewhat more global structure"}]],[[{"type":"text","text":"Key setting"}],[{"type":"text","text":"perplexity","marks":[{"type":"code"}]},{"type":"text","text":" (~5–50)"}],[{"type":"text","text":"n_neighbors","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"min_dist","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Speed"}],[{"type":"text","text":"Slow on large data"}],[{"type":"text","text":"Faster"}]],[[{"type":"text","text":"New points"}],[{"type":"text","text":"No "},{"type":"text","text":"transform","marks":[{"type":"code"}]},{"type":"text","text":" in scikit-learn — refit"}],[{"type":"text","text":"Can transform new data"}]],[[{"type":"text","text":"Where"}],[{"type":"text","text":"sklearn.manifold.TSNE","marks":[{"type":"code"}]}],[{"type":"text","text":"umap-learn","marks":[{"type":"code"}]},{"type":"text","text":" package"}]]]},"revision":1},{"id":"b6b4db0c-d3fd-76c2-8ae2-83e5389fbd30","type":"callout","position":"aD","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"In t-SNE/UMAP plots, cluster "},{"type":"text","text":"sizes","marks":[{"type":"bold"}]},{"type":"text","text":" and the "},{"type":"text","text":"distances between clusters","marks":[{"type":"bold"}]},{"type":"text","text":" are not meaningful, and results change with the random seed and hyperparameters. Use them to explore, not as features or as evidence that clusters exist."}]}]}},"revision":1},{"id":"fe5bf745-b16c-7507-8580-3b4bd4011daf","type":"question","position":"aE","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What does PCA do?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"It rotates the (centred) data onto orthogonal axes ordered by how much variance they capture — the eigenvectors of the covariance matrix — and optionally drops the low-variance ones. The result is a lower-dimensional, uncorrelated representation that keeps as much variance as possible."}]}]}},"revision":1},{"id":"44a4ef88-4340-7eb1-ba42-82494c722958","type":"question","position":"aF","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why must you scale data before PCA?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"PCA maximises variance, and variance depends on units. Unscaled, the feature with the largest numeric range dominates the first components regardless of how informative it is. Standardising gives every feature an equal starting weight."}]}]}},"revision":1},{"id":"80db3aa9-f93c-700b-93d2-2e660fdb8c01","type":"question","position":"aG","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"PCA vs t-SNE?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"PCA is linear, deterministic, fast, preserves global variance and can project new data — good for preprocessing. t-SNE is non-linear and stochastic, preserves local neighbourhoods for 2-D visualisation, distorts global distances and isn''t used to transform new data for models."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
