SELECT '65630886-d298-7c21-a7b9-af39708d4a47', '98590806-2bcb-7d7a-b3f4-32cd1ce4399c', 1, 'PUBLISHED', 'Hypothesis Tests & Significance', '[{"id":"0e922bf6-2e04-726b-8b09-0c0ac6b0adfb","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A hypothesis test asks whether a difference — between groups, between models — is larger than chance alone would plausibly produce. Used carefully, it separates real improvements from noise."}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"State hypotheses","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Null "},{"type":"text","text":"H₀","marks":[{"type":"code"}]},{"type":"text","text":": no difference (model B''s accuracy = model A''s). Alternative "},{"type":"text","text":"H₁","marks":[{"type":"code"}]},{"type":"text","text":": there is a difference."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Choose α","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"The false-positive rate you accept, usually 0.05 — decided before looking at the data."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Compute a test statistic","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"How far the observed data is from what "},{"type":"text","text":"H₀","marks":[{"type":"code"}]},{"type":"text","text":" predicts, in units of its standard error."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Get the p-value","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"The probability, "},{"type":"text","text":"assuming H₀ is true","marks":[{"type":"bold"}]},{"type":"text","text":", of a result at least as extreme as observed."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Decide","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Reject "},{"type":"text","text":"H₀","marks":[{"type":"code"}]},{"type":"text","text":" if p ≤ α; otherwise “fail to reject” (not the same as proving "},{"type":"text","text":"H₀","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]}]}]}},"revision":1},{"id":"cd3fe967-e052-75aa-b4a4-32c0e2b10cc0","type":"table","position":"a1","content":{"hasHeaderRow":true,"rows":[[[],[{"type":"text","text":"H₀ true"}],[{"type":"text","text":"H₀ false"}]],[[{"type":"text","text":"Reject H₀","marks":[{"type":"bold"}]}],[{"type":"text","text":"Type I error (false positive) — probability α"}],[{"type":"text","text":"Correct — probability = "},{"type":"text","text":"power","marks":[{"type":"bold"}]},{"type":"text","text":" (1 − β)"}]],[[{"type":"text","text":"Fail to reject","marks":[{"type":"bold"}]}],[{"type":"text","text":"Correct"}],[{"type":"text","text":"Type II error (false negative) — probability β"}]]]},"revision":1},{"id":"fbbcd316-7543-7bfe-b3da-43c2a00d742d","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"What a p-value is not"}]},"revision":1},{"id":"e64aff45-9aa0-7c97-a49b-8486219baef9","type":"text","position":"a3","content":{"doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Not the probability that "},{"type":"text","text":"H₀","marks":[{"type":"code"}]},{"type":"text","text":" is true, nor that the result is due to chance."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Not the size or importance of the effect — with huge samples, trivial differences become “significant”."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Not a pass/fail on truth: p = 0.049 and p = 0.051 are practically the same evidence."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Report the "},{"type":"text","text":"effect size with a confidence interval","marks":[{"type":"bold"}]},{"type":"text","text":" alongside the p-value."}]}]}]}]}},"revision":1},{"id":"3fa6db92-d897-7f0c-bb12-52bdce597d3f","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Choosing a test"}]},"revision":1},{"id":"81dcfe2c-5b5d-73c9-864a-2f126d504bfa","type":"table","position":"a5","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Question"}],[{"type":"text","text":"Test"}],[{"type":"text","text":"SciPy"}]],[[{"type":"text","text":"Mean of two independent groups"}],[{"type":"text","text":"Welch''s t-test (no equal-variance assumption)"}],[{"type":"text","text":"ttest_ind(a, b, equal_var=False)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Same units measured twice / paired"}],[{"type":"text","text":"Paired t-test"}],[{"type":"text","text":"ttest_rel","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Two groups, no normality assumption"}],[{"type":"text","text":"Mann–Whitney U"}],[{"type":"text","text":"mannwhitneyu","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Means of 3+ groups"}],[{"type":"text","text":"One-way ANOVA"}],[{"type":"text","text":"f_oneway","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Two categorical variables / proportions"}],[{"type":"text","text":"Chi-square test of independence; z-test for two proportions"}],[{"type":"text","text":"chi2_contingency","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Same distribution?"}],[{"type":"text","text":"Kolmogorov–Smirnov"}],[{"type":"text","text":"ks_2samp","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Two classifiers on the same test set"}],[{"type":"text","text":"McNemar''s test (on disagreements)"}],[{"type":"text","text":"binomtest","marks":[{"type":"code"}]},{"type":"text","text":" on the discordant counts"}]]]},"revision":1},{"id":"2585d4d3-493d-7705-bac3-7e92a27dd8e1","type":"code","position":"a6","content":{"language":"python","code":"import numpy as np\nfrom scipy import stats\n\nrng = np.random.default_rng(0)\na = rng.normal(loc=50, scale=10, size=200)      # e.g. session minutes, variant A\nb = rng.normal(loc=53, scale=12, size=200)      # variant B\n\nt, p = stats.ttest_ind(b, a, equal_var=False)\nprint(round(t, 2), round(p, 4))                 # 1.61 0.1076 ← not significant at 0.05 (true gap is 3, but n is small)\n\ndiff = b.mean() - a.mean()\nse = np.sqrt(a.var(ddof=1) / len(a) + b.var(ddof=1) / len(b))\nprint(round(diff, 2), [round(float(diff - 1.96 * se), 2), round(float(diff + 1.96 * se), 2)])   # 1.79 [-0.38, 3.95] ← effect and its 95% CI: includes 0\n\ntable = np.array([[120, 880], [150, 850]])      # clicked / not clicked, per variant\nchi2, p_chi, dof, _ = stats.chi2_contingency(table)\nprint(round(chi2, 2), round(p_chi, 4), dof)     # 3.6 0.0577 1 ← 12% vs 15% CTR: borderline with 1,000 users each","filename":"Python"},"revision":1},{"id":"b379dec5-9187-7f18-837c-ad108a78bd87","type":"callout","position":"a7","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A 95% confidence interval comes from a procedure that captures the true value in 95% of repeated experiments. If the interval for a difference excludes 0, the corresponding two-sided test at α = 0.05 rejects "},{"type":"text","text":"H₀","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"4ce514db-4a27-7942-af58-2dfc201277a7","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"Bootstrap confidence intervals"}]},"revision":1},{"id":"bd9e38fc-868c-7f42-a77f-9dc085e33153","type":"text","position":"a9","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"For metrics with no simple formula (F1, AUC, median), resample the test set "},{"type":"text","text":"with replacement","marks":[{"type":"bold"}]},{"type":"text","text":" many times, recompute the metric each time, and read off percentiles:"}]}]}},"revision":1},{"id":"562980c4-7670-7933-8533-e21ec76bfa1c","type":"code","position":"aA","content":{"language":"python","code":"import numpy as np\nfrom sklearn.datasets import load_breast_cancer\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.metrics import f1_score\nfrom sklearn.model_selection import train_test_split\nfrom sklearn.pipeline import make_pipeline\nfrom sklearn.preprocessing import StandardScaler\n\nX, y = load_breast_cancer(return_X_y=True)\nX_tr, X_te, y_tr, y_te = train_test_split(X, y, stratify=y, random_state=0)\npred = make_pipeline(StandardScaler(), LogisticRegression()).fit(X_tr, y_tr).predict(X_te)\n\nrng = np.random.default_rng(0)\nboot = []\nfor _ in range(2000):\n    idx = rng.integers(0, len(y_te), len(y_te))       # resample test rows with replacement\n    boot.append(f1_score(y_te[idx], pred[idx]))\nprint(round(f1_score(y_te, pred), 3), np.percentile(boot, [2.5, 97.5]).round(3))   # 0.967 [0.937 0.99 ] ← F1 and its 95% CI","filename":"Python"},"revision":1},{"id":"1bca87ea-36c0-74e3-acff-a018ac83b79b","type":"heading","position":"aB","content":{"level":1,"content":[{"type":"text","text":"Is model B really better than model A?"}]},"revision":1},{"id":"4f6a26d8-8370-7d9e-998c-efede7f23467","type":"text","position":"aC","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Both models are scored on the "},{"type":"text","text":"same","marks":[{"type":"bold"}]},{"type":"text","text":" test rows, so compare them in a paired way. McNemar''s test looks only at the rows where they disagree: "},{"type":"text","text":"b","marks":[{"type":"code"}]},{"type":"text","text":" = A right & B wrong, "},{"type":"text","text":"c","marks":[{"type":"code"}]},{"type":"text","text":" = A wrong & B right. Under "},{"type":"text","text":"H₀","marks":[{"type":"code"}]},{"type":"text","text":" each disagreement is a coin flip:"}]}]}},"revision":1},{"id":"ca916d62-eaae-70d0-9aa8-d72c5b6fbce3","type":"code","position":"aD","content":{"language":"python","code":"import numpy as np\nfrom scipy.stats import binomtest\n\nrng = np.random.default_rng(1)\ny = rng.integers(0, 2, 1000)\na_right = rng.random(1000) < 0.85                  # model A: ~85% accurate\nb_right = np.where(rng.random(1000) < 0.8, a_right, rng.random(1000) < 0.90)   # B: correlated with A, slightly better\n\nb = int(np.sum(a_right & ~b_right))\nc = int(np.sum(~a_right & b_right))\nprint(a_right.mean(), b_right.mean(), b, c)        # 0.832 0.841 17 26\nprint(round(binomtest(b, b + c, 0.5).pvalue, 4))   # 0.2221 ← exact McNemar p-value: B''s 9 extra wins could be chance","filename":"Python"},"revision":1},{"id":"8ec336b3-568f-739f-ac7a-b4606fa37eab","type":"text","position":"aE","content":{"doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Across CV folds, a paired t-test on per-fold scores is common but optimistic (folds share training data); the corrected resampled t-test (Nadeau & Bengio) or repeated CV is safer."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A bootstrap CI of the "},{"type":"text","text":"difference","marks":[{"type":"bold"}]},{"type":"text","text":" in metric (resampling rows, scoring both models on the same resample) is simple and works for any metric."}]}]}]}]}},"revision":1},{"id":"453be954-25c8-7630-b4f2-aa6774db40c5","type":"heading","position":"aF","content":{"level":1,"content":[{"type":"text","text":"Multiple comparisons"}]},"revision":1},{"id":"7a9b8c56-5178-793f-bf47-a9830ca18da5","type":"code","position":"aG","content":{"language":"python","code":"import numpy as np\n\nprint(round(1 - 0.95 ** 20, 3))                    # 0.642 ← P(at least one false positive) in 20 tests at α = 0.05\n\np = np.array([0.001, 0.008, 0.012, 0.04, 0.2])     # p-values from 5 tests\nprint((p <= 0.05 / len(p)).tolist())               # [True, True, False, False, False] ← Bonferroni: α / m\nm = len(p)                                         # Benjamini–Hochberg (controls the false discovery rate)\norder = np.argsort(p)\npassed = p[order] <= 0.05 * np.arange(1, m + 1) / m\nk = passed.nonzero()[0].max() + 1 if passed.any() else 0\nprint(sorted(order[:k].tolist()))                  # [0, 1, 2, 3] ← indices of discoveries","filename":"Python"},"revision":1},{"id":"11dcffc1-3e6c-771a-82b5-1611ffb4b5ab","type":"callout","position":"aH","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Testing many metrics, segments or model variants and reporting only the significant ones ("},{"type":"text","text":"p-hacking","marks":[{"type":"bold"}]},{"type":"text","text":") guarantees false discoveries. Pre-register the primary metric, correct for multiple tests, and confirm surprises on fresh data."}]}]}},"revision":1},{"id":"b9e16d57-8bb7-7bbb-979f-664d450ae912","type":"question","position":"aI","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is a p-value?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The probability of observing data at least as extreme as what we saw, assuming the null hypothesis is true. A small p-value means the data would be surprising under H₀. It is not the probability that H₀ is true, and it says nothing about how big or important the effect is."}]}]}},"revision":1},{"id":"6325e9fb-2041-74c3-8bdd-f34f530b367d","type":"question","position":"aJ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What are Type I and Type II errors?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Type I: rejecting a true null (false positive), controlled by α. Type II: failing to reject a false null (false negative), probability β; power = 1 − β grows with sample size and effect size."}]}]}},"revision":1},{"id":"b9be0cf8-9e23-700a-a60b-4710ba8262cb","type":"question","position":"aK","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you know if a new model is significantly better than the old one?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Evaluate both on the same held-out data and use a paired method: McNemar''s test on disagreements for accuracy, or a bootstrap confidence interval of the metric difference. Make sure the difference is also practically meaningful and confirm with an online A/B test if the model affects users."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
WHERE EXISTS (SELECT 1 FROM "notes"."Note" n WHERE n.id = '98590806-2bcb-7d7a-b3f4-32cd1ce4399c' AND n."ownerId" = '019a118c-f480-7000-8000-000000000001' AND n."publishedVersionId" IS NULL AND n.visibility = 'PRIVATE' AND n."deletedAt" IS NULL AND n."draftUpdatedAt" = TIMESTAMPTZ '2026-10-07 03:23:53+00')
