  ('2585d4d3-493d-7705-bac3-7e92a27dd8e1', 'a6', 'code', '{"language":"python","code":"import numpy as np\nfrom scipy import stats\n\nrng = np.random.default_rng(0)\na = rng.normal(loc=50, scale=10, size=200)      # e.g. session minutes, variant A\nb = rng.normal(loc=53, scale=12, size=200)      # variant B\n\nt, p = stats.ttest_ind(b, a, equal_var=False)\nprint(round(t, 2), round(p, 4))                 # 1.61 0.1076 ← not significant at 0.05 (true gap is 3, but n is small)\n\ndiff = b.mean() - a.mean()\nse = np.sqrt(a.var(ddof=1) / len(a) + b.var(ddof=1) / len(b))\nprint(round(diff, 2), [round(float(diff - 1.96 * se), 2), round(float(diff + 1.96 * se), 2)])   # 1.79 [-0.38, 3.95] ← effect and its 95% CI: includes 0\n\ntable = np.array([[120, 880], [150, 850]])      # clicked / not clicked, per variant\nchi2, p_chi, dof, _ = stats.chi2_contingency(table)\nprint(round(chi2, 2), round(p_chi, 4), dof)     # 3.6 0.0577 1 ← 12% vs 15% CTR: borderline with 1,000 users each","filename":"Python"}'),
  ('b379dec5-9187-7f18-837c-ad108a78bd87', 'a7', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A 95% confidence interval comes from a procedure that captures the true value in 95% of repeated experiments. If the interval for a difference excludes 0, the corresponding two-sided test at α = 0.05 rejects "},{"type":"text","text":"H₀","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('4ce514db-4a27-7942-af58-2dfc201277a7', 'a8', 'heading', '{"level":1,"content":[{"type":"text","text":"Bootstrap confidence intervals"}]}'),
  ('bd9e38fc-868c-7f42-a77f-9dc085e33153', 'a9', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"For metrics with no simple formula (F1, AUC, median), resample the test set "},{"type":"text","text":"with replacement","marks":[{"type":"bold"}]},{"type":"text","text":" many times, recompute the metric each time, and read off percentiles:"}]}]}}'),
