SELECT 'c41283b6-6ccc-7a7c-8ed5-33e32a2d29e9', 'f67b98ff-ccfc-70a0-ba49-2f7f59196d03', 1, 'PUBLISHED', 'Train, Validation & Test Sets', '[{"id":"94dc844e-18f1-7f97-8cd3-e9a913b2df07","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"You can''t measure generalisation on the data you trained on. Hold data back: a "},{"type":"text","text":"validation","marks":[{"type":"bold"}]},{"type":"text","text":" set to make choices and a "},{"type":"text","text":"test","marks":[{"type":"bold"}]},{"type":"text","text":" set, used once, to report how the final model will do on new data."}]}]}},"revision":1},{"id":"c2064c4a-a1e7-7c33-9a07-6f374fc6bc31","type":"table","position":"a1","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Split"}],[{"type":"text","text":"Used for"}],[{"type":"text","text":"Typical share"}]],[[{"type":"text","text":"Training"}],[{"type":"text","text":"Fitting parameters ("},{"type":"text","text":"fit","marks":[{"type":"code"}]},{"type":"text","text":")"}],[{"type":"text","text":"60–80%"}]],[[{"type":"text","text":"Validation"}],[{"type":"text","text":"Choosing hyperparameters, features, the model, the decision threshold; early stopping"}],[{"type":"text","text":"10–20% (or cross-validation instead)"}]],[[{"type":"text","text":"Test"}],[{"type":"text","text":"One final, unbiased estimate of performance — after all decisions are made"}],[{"type":"text","text":"10–20%"}]]]},"revision":1},{"id":"acf8638b-a68a-707d-aff4-33de4f9fbf0c","type":"text","position":"a2","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The shares are rules of thumb. With millions of rows, 1% can be a perfectly large test set; with a few hundred rows, prefer cross-validation for model selection and keep a small test set — or use nested cross-validation."}]}]}},"revision":1},{"id":"71b16de4-e12e-75ca-815a-86ae7114a489","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"A three-way split"}]},"revision":1},{"id":"7b9d7f2f-15a6-78d7-80ed-3816a168aa8f","type":"code","position":"a4","content":{"language":"python","code":"from sklearn.datasets import make_classification\nfrom sklearn.model_selection import train_test_split\n\nX, y = make_classification(n_samples=1000, weights=[0.9], random_state=0)   # ~10% positives\n\nX_tmp, X_test, y_tmp, y_test = train_test_split(X, y, test_size=0.2, stratify=y, random_state=42)\nX_train, X_val, y_train, y_val = train_test_split(X_tmp, y_tmp, test_size=0.25,   # 0.25 × 0.8 = 0.2\n                                                  stratify=y_tmp, random_state=42)\nprint(len(X_train), len(X_val), len(X_test))                                    # 600 200 200\nprint(round(y_train.mean(), 3), round(y_val.mean(), 3), round(y_test.mean(), 3))  # 0.102 0.105 0.1 ← same class balance","filename":"Python"},"revision":1},{"id":"00dd8906-c122-77b2-912e-d4bc98c63b59","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Why stratify"}]},"revision":1},{"id":"6315fede-1fed-7c98-8343-74c24ce9b2d0","type":"text","position":"a6","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"With a rare class, a purely random split can leave the test set with almost no positives. "},{"type":"text","text":"stratify=y","marks":[{"type":"code"}]},{"type":"text","text":" keeps the class proportions identical in every split:"}]}]}},"revision":1},{"id":"5e893905-d943-7c01-b15d-dbe4013f04c8","type":"code","position":"a7","content":{"language":"python","code":"import numpy as np\nfrom sklearn.model_selection import train_test_split\n\ny = np.array([1] * 5 + [0] * 95)                    # 5% positives\nrandom_counts = [int(train_test_split(y, test_size=0.2, random_state=s)[1].sum()) for s in range(8)]\nstrat_counts = [int(train_test_split(y, test_size=0.2, stratify=y, random_state=s)[1].sum()) for s in range(8)]\nprint(random_counts)    # [1, 0, 3, 0, 1, 0, 1, 0] ← positives in the 20-row test set, per seed\nprint(strat_counts)     # [1, 1, 1, 1, 1, 1, 1, 1]","filename":"Python"},"revision":1},{"id":"c782aa68-ffe8-783a-8283-33d971579362","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"When a random split is wrong"}]},"revision":1},{"id":"3f6f5e8c-6e8c-7488-833c-0ebb31f30c8e","type":"table","position":"a9","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Data"}],[{"type":"text","text":"Problem with a random split"}],[{"type":"text","text":"Split instead by"}]],[[{"type":"text","text":"Time-ordered (sales, prices, logs)"}],[{"type":"text","text":"Training on the future to predict the past"}],[{"type":"text","text":"Time: train on earlier, validate/test on later"}]],[[{"type":"text","text":"Grouped (several rows per patient, user, device)"}],[{"type":"text","text":"The model recognises the entity, not the pattern"}],[{"type":"text","text":"Group: all rows of an entity in one split"}]],[[{"type":"text","text":"Near-duplicates (same image resized, reposted listings)"}],[{"type":"text","text":"Test rows are copies of training rows"}],[{"type":"text","text":"Deduplicate first, or group duplicates"}]]]},"revision":1},{"id":"899852b9-f2da-731d-ae07-a948bcd56810","type":"heading","position":"aA","content":{"level":1,"content":[{"type":"text","text":"Rules that keep evaluation honest"}]},"revision":1},{"id":"96ee17a7-1e94-73ea-84bf-79f223c552e5","type":"text","position":"aB","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Split "},{"type":"text","text":"first","marks":[{"type":"bold"}]},{"type":"text","text":", before fitting any imputer, scaler, encoder or feature selector."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Fit everything on the training data; only "},{"type":"text","text":"transform","marks":[{"type":"code"}]},{"type":"text","text":" the validation and test data."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Make every decision with validation data or cross-validation."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Look at the test set "},{"type":"text","text":"once","marks":[{"type":"bold"}]},{"type":"text","text":". If you then change the model because of it, it has become a validation set and its score is optimistic."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"After choosing the model, refit it on train + validation before deploying (more data, same recipe)."}]}]}]}]}},"revision":1},{"id":"f53aa9a1-e9f2-72f8-9f6d-a17dab6c0898","type":"heading","position":"aC","content":{"level":1,"content":[{"type":"text","text":"Reading the gaps"}]},"revision":1},{"id":"1767edcf-34a7-71d0-bc22-481c21b4fa89","type":"table","position":"aD","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Training error"}],[{"type":"text","text":"Validation error"}],[{"type":"text","text":"Diagnosis"}],[{"type":"text","text":"Next step"}]],[[{"type":"text","text":"High"}],[{"type":"text","text":"High (similar)"}],[{"type":"text","text":"Underfitting (high bias)"}],[{"type":"text","text":"More capacity, better features, less regularisation"}]],[[{"type":"text","text":"Low"}],[{"type":"text","text":"Much higher"}],[{"type":"text","text":"Overfitting (high variance)"}],[{"type":"text","text":"More data, regularisation, simpler model, early stopping"}]],[[{"type":"text","text":"Low"}],[{"type":"text","text":"Low"}],[{"type":"text","text":"Good fit"}],[{"type":"text","text":"Confirm on the test set"}]]]},"revision":1},{"id":"2983c9cb-5065-7268-9263-ae62926c7b0d","type":"text","position":"aE","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"See "},{"type":"text","text":"Bias–Variance & Overfitting","marks":[{"type":"bold"}]},{"type":"text","text":" for the theory and learning curves."}]}]}},"revision":1},{"id":"1fca9bef-6cb8-7049-a0be-5832ad7c0d6a","type":"question","position":"aF","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why do we need a validation set in addition to a test set?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Every choice made by comparing scores — hyperparameters, features, models — fits the data those scores came from. If you make them on the test set, the test score becomes optimistically biased. The validation set absorbs that selection bias; the untouched test set then gives an honest final estimate."}]}]}},"revision":1},{"id":"1d21fdd4-9a83-7e8b-8332-9161ae408363","type":"question","position":"aG","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"You tuned on the test set by mistake. What now?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Treat that score as a validation score, not a generalisation estimate. Get a fresh held-out set (new data, or a later time period) for the final evaluation, and switch to cross-validation for tuning."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
