SELECT '976c5788-89a3-78c7-87d3-c1319527b28c', 'ffa9fcd3-6b19-71c3-859a-4f4be44f334f', 1, 'PUBLISHED', 'Types of Learning', '[{"id":"e8bcbe0d-9b3a-79f4-93d9-2bf0333ec720","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"ML problems are grouped by the feedback the learner gets: "},{"type":"text","text":"labels","marks":[{"type":"bold"}]},{"type":"text","text":" (supervised), "},{"type":"text","text":"no labels","marks":[{"type":"bold"}]},{"type":"text","text":" (unsupervised), "},{"type":"text","text":"a few labels","marks":[{"type":"bold"}]},{"type":"text","text":" (semi-supervised), "},{"type":"text","text":"labels made from the data itself","marks":[{"type":"bold"}]},{"type":"text","text":" (self-supervised) or "},{"type":"text","text":"rewards","marks":[{"type":"bold"}]},{"type":"text","text":" (reinforcement learning)."}]}]}},"revision":1},{"id":"880e0dc9-4577-7dd0-8d73-3d5da345d38a","type":"table","position":"a1","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Type"}],[{"type":"text","text":"Training data"}],[{"type":"text","text":"Goal"}],[{"type":"text","text":"Typical tasks & algorithms"}]],[[{"type":"text","text":"Supervised"}],[{"type":"text","text":"Inputs "},{"type":"text","text":"X","marks":[{"type":"code"}]},{"type":"text","text":" with labels "},{"type":"text","text":"y","marks":[{"type":"code"}]}],[{"type":"text","text":"Predict "},{"type":"text","text":"y","marks":[{"type":"code"}]},{"type":"text","text":" for new "},{"type":"text","text":"X","marks":[{"type":"code"}]}],[{"type":"text","text":"Classification, regression — linear/logistic regression, trees, SVM, boosting"}]],[[{"type":"text","text":"Unsupervised"}],[{"type":"text","text":"Inputs "},{"type":"text","text":"X","marks":[{"type":"code"}]},{"type":"text","text":" only"}],[{"type":"text","text":"Find structure"}],[{"type":"text","text":"Clustering (k-means, DBSCAN), dimensionality reduction (PCA), anomaly detection"}]],[[{"type":"text","text":"Semi-supervised"}],[{"type":"text","text":"Few labelled + many unlabelled rows"}],[{"type":"text","text":"Use unlabelled data to improve a supervised model"}],[{"type":"text","text":"Self-training, label propagation"}]],[[{"type":"text","text":"Self-supervised"}],[{"type":"text","text":"Raw data; labels created from the data (the next word, a masked patch)"}],[{"type":"text","text":"Learn general representations"}],[{"type":"text","text":"Pre-training language and vision models"}]],[[{"type":"text","text":"Reinforcement"}],[{"type":"text","text":"States, actions, rewards from an environment"}],[{"type":"text","text":"A policy maximising cumulative reward"}],[{"type":"text","text":"Game playing, robotics, recommendations as sequential decisions"}]]]},"revision":1},{"id":"6181a796-80fa-7648-9789-7edb2efa9bf7","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"Supervised vs unsupervised on the same data"}]},"revision":1},{"id":"6dd936b8-a935-7d77-9c63-69337c45d56b","type":"text","position":"a3","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The iris dataset has 150 flowers of 3 species. A classifier learns from the species labels; k-means never sees them but still finds groups that largely match them:"}]}]}},"revision":1},{"id":"79fe84fe-0696-7f63-922b-64fe4bc3f16a","type":"code","position":"a4","content":{"language":"python","code":"from sklearn.cluster import KMeans\nfrom sklearn.datasets import load_iris\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.metrics import adjusted_rand_score\n\nX, y = load_iris(return_X_y=True)\n\nclf = LogisticRegression(max_iter=1000).fit(X, y)                 # supervised: uses y\nprint(clf.predict(X[[0, 50, 100]]))                               # [0 1 2] ← species 0, 1, 2\n\nkm = KMeans(n_clusters=3, n_init=10, random_state=0).fit(X)       # unsupervised: never sees y\nprint(km.labels_[[0, 50, 100]])                                   # [1 0 2] ← cluster ids are arbitrary names\nprint(round(adjusted_rand_score(y, km.labels_), 2))               # 0.73 ← 1.0 = perfect match, ≈0 = random; versicolor/virginica overlap","filename":"Python"},"revision":1},{"id":"afebae26-4817-7b01-ba51-c9158bca02a0","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Supervised: classification vs regression"}]},"revision":1},{"id":"6fca6eb7-0f74-7c94-8008-b08b76627474","type":"table","position":"a6","content":{"hasHeaderRow":true,"rows":[[[],[{"type":"text","text":"Classification"}],[{"type":"text","text":"Regression"}]],[[{"type":"text","text":"Target"}],[{"type":"text","text":"A category (spam / not spam; cat / dog / bird)"}],[{"type":"text","text":"A number (price, temperature, demand)"}]],[[{"type":"text","text":"Output"}],[{"type":"text","text":"Class label, usually with a probability or score"}],[{"type":"text","text":"A real value"}]],[[{"type":"text","text":"Loss (training)"}],[{"type":"text","text":"Log-loss (cross-entropy), hinge"}],[{"type":"text","text":"Squared error, absolute error, Huber"}]],[[{"type":"text","text":"Metrics"}],[{"type":"text","text":"Accuracy, precision, recall, F1, ROC-AUC, PR-AUC"}],[{"type":"text","text":"MAE, RMSE, R²"}]],[[{"type":"text","text":"Variants"}],[{"type":"text","text":"Binary, multi-class (one of k), multi-label (any subset of k)"}],[{"type":"text","text":"Single- or multi-output"}]]]},"revision":1},{"id":"4b463129-4fc5-7d31-aca0-f5cf80bd6312","type":"callout","position":"a7","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"“Logistic regression” is a "},{"type":"text","text":"classification","marks":[{"type":"bold"}]},{"type":"text","text":" algorithm — the name comes from regressing the log-odds. And a numeric-looking target is not automatically regression: star ratings 1–5 are often better treated as ordered classes."}]}]}},"revision":1},{"id":"4e08eec2-d818-79a3-a704-4551c75ebbab","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"Other ways to slice ML"}]},"revision":1},{"id":"ea797db6-276a-751d-8aac-ae5484f15924","type":"table","position":"a9","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Distinction"}],[{"type":"text","text":"One side"}],[{"type":"text","text":"Other side"}]],[[{"type":"text","text":"Batch vs online"}],[{"type":"text","text":"Batch: train on the full dataset, retrain periodically"}],[{"type":"text","text":"Online: update incrementally as data arrives ("},{"type":"text","text":"partial_fit","marks":[{"type":"code"}]},{"type":"text","text":" in "},{"type":"text","text":"SGDClassifier","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"MultinomialNB","marks":[{"type":"code"}]},{"type":"text","text":")"}]],[[{"type":"text","text":"Model-based vs instance-based"}],[{"type":"text","text":"Model-based: learn parameters, then discard the data (linear models)"}],[{"type":"text","text":"Instance-based: keep the training data and compare new points to it (k-NN)"}]],[[{"type":"text","text":"Parametric vs non-parametric"}],[{"type":"text","text":"Parametric: a fixed number of parameters regardless of data size (linear/logistic regression, Naive Bayes)"}],[{"type":"text","text":"Non-parametric: complexity grows with the data (k-NN, decision trees, kernel SVMs)"}]],[[{"type":"text","text":"Discriminative vs generative"}],[{"type":"text","text":"Discriminative: model "},{"type":"text","text":"P(y | x)","marks":[{"type":"code"}]},{"type":"text","text":" or the boundary directly (logistic regression, SVM)"}],[{"type":"text","text":"Generative: model how data is produced, "},{"type":"text","text":"P(x | y)·P(y)","marks":[{"type":"code"}]},{"type":"text","text":" (Naive Bayes, Gaussian mixtures)"}]]]},"revision":1},{"id":"e2bf00d5-f960-7e98-86c1-555adeca8c2c","type":"heading","position":"aA","content":{"level":1,"content":[{"type":"text","text":"Reinforcement learning in one paragraph"}]},"revision":1},{"id":"71f68efa-f4dc-756d-8f61-f8d12d572173","type":"text","position":"aB","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An "},{"type":"text","text":"agent","marks":[{"type":"bold"}]},{"type":"text","text":" observes a "},{"type":"text","text":"state","marks":[{"type":"bold"}]},{"type":"text","text":", takes an "},{"type":"text","text":"action","marks":[{"type":"bold"}]},{"type":"text","text":", receives a "},{"type":"text","text":"reward","marks":[{"type":"bold"}]},{"type":"text","text":" and a new state from the "},{"type":"text","text":"environment","marks":[{"type":"bold"}]},{"type":"text","text":", and learns a "},{"type":"text","text":"policy","marks":[{"type":"bold"}]},{"type":"text","text":" (state → action) that maximises total future reward. Unlike supervised learning, nobody gives the correct action — only delayed, scalar feedback — so the agent must balance "},{"type":"text","text":"exploration","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"exploitation","marks":[{"type":"bold"}]},{"type":"text","text":". Q-learning, MDPs and value iteration are worked through in the "},{"type":"text","text":"Artificial Intelligence","marks":[{"type":"bold"}]},{"type":"text","text":" notes."}]}]}},"revision":1},{"id":"55c0648e-470f-78ad-a793-8177bcdb7d44","type":"question","position":"aC","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Is anomaly detection supervised or unsupervised?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Either. With labelled fraud cases it is (heavily imbalanced) supervised classification. Without labels it is unsupervised: model what “normal” looks like and flag points that don''t fit (Isolation Forest, one-class SVM). Often a few labels are used only to evaluate an unsupervised detector."}]}]}},"revision":1},{"id":"680e1242-7912-75ff-a360-57b6be73569d","type":"question","position":"aD","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is self-supervised learning and why does it matter?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The labels are generated from the data itself — predict the next token, a masked word or a hidden image patch. It needs no human labelling, so it scales to internet-sized data; it is how large language and vision models are pre-trained before being fine-tuned on small labelled datasets."}]}]}},"revision":1},{"id":"e363ba64-1778-7a92-bf84-1efb16722c9d","type":"question","position":"aE","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Parametric vs non-parametric — give an example of each."}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Logistic regression is parametric: one weight per feature no matter how many rows. k-NN is non-parametric: it stores all training points, so its effective complexity grows with the data. Non-parametric models are more flexible but need more data and are slower at prediction time."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
