SELECT '54557151-a15c-71ed-9bbf-6eca06d7373e', '81c08ac8-f7c4-7d37-bc1f-eac68bc0f0cb', 1, 'PUBLISHED', 'CNN Architectures & ResNet', '[{"id":"b0d45bae-fa2a-7b1c-bcfa-16788c050d8e","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The classic CNNs trace how the field learned to go deeper: bigger datasets and GPUs (AlexNet), small stacked filters (VGG), and finally skip connections (ResNet) that made 100+ layers trainable."}]}]}},"revision":1},{"id":"78890bf9-200c-7b79-8240-11fc85518c6a","type":"table","position":"a1","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Model"}],[{"type":"text","text":"Year"}],[{"type":"text","text":"Key idea"}],[{"type":"text","text":"Depth / params"}]],[[{"type":"text","text":"LeNet-5"}],[{"type":"text","text":"1998"}],[{"type":"text","text":"Conv → pool → conv → pool → dense; read handwritten digits"}],[{"type":"text","text":"5 layers, 60 K"}]],[[{"type":"text","text":"AlexNet"}],[{"type":"text","text":"2012"}],[{"type":"text","text":"ReLU, dropout, data augmentation, trained on GPUs — won ImageNet by a wide margin"}],[{"type":"text","text":"8 layers, 60 M"}]],[[{"type":"text","text":"VGG-16"}],[{"type":"text","text":"2014"}],[{"type":"text","text":"Only 3×3 convs, stacked deep; simple and uniform"}],[{"type":"text","text":"16 layers, 138 M"}]],[[{"type":"text","text":"GoogLeNet / Inception"}],[{"type":"text","text":"2014"}],[{"type":"text","text":"Parallel 1×1, 3×3, 5×5 branches; 1×1 convs to cut channels"}],[{"type":"text","text":"22 layers, 7 M"}]],[[{"type":"text","text":"ResNet"}],[{"type":"text","text":"2015"}],[{"type":"text","text":"Residual connections","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"y = F(x) + x","marks":[{"type":"code"}]}],[{"type":"text","text":"18–152 layers, 11–60 M"}]],[[{"type":"text","text":"MobileNet / EfficientNet"}],[{"type":"text","text":"2017–19"}],[{"type":"text","text":"Depthwise-separable convs; scaling width/depth/resolution together"}],[{"type":"text","text":"Few M, for phones"}]],[[{"type":"text","text":"ConvNeXt, ViT"}],[{"type":"text","text":"2020–22"}],[{"type":"text","text":"Transformer ideas for vision: patches + attention (ViT), modernised CNNs"}],[{"type":"text","text":"—"}]]]},"revision":1},{"id":"e4594428-7a6a-716a-a9d7-0a364b576c15","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"A small CNN, shape by shape"}]},"revision":1},{"id":"faf30f05-d93a-7f73-857d-35daa60f944b","type":"code","position":"a3","content":{"language":"python","code":"import torch\nfrom torch import nn\n\ntorch.manual_seed(0)\nmodel = nn.Sequential(\n    nn.Conv2d(1, 16, 3, padding=1), nn.BatchNorm2d(16), nn.ReLU(),   # 28×28\n    nn.MaxPool2d(2),                                                  # → 14×14\n    nn.Conv2d(16, 32, 3, padding=1), nn.BatchNorm2d(32), nn.ReLU(),\n    nn.MaxPool2d(2),                                                  # → 7×7\n    nn.AdaptiveAvgPool2d(1), nn.Flatten(),                            # → 32 numbers\n    nn.Linear(32, 10),                                                # → 10 class logits\n)\nx = torch.randn(4, 1, 28, 28)             # a batch of 4 MNIST-sized images\nshapes = []\nfor layer in model:\n    x = layer(x)\n    if isinstance(layer, (nn.MaxPool2d, nn.Flatten, nn.Linear)):\n        shapes.append(tuple(x.shape))\nprint(shapes)                             # [(4, 16, 14, 14), (4, 32, 7, 7), (4, 32), (4, 10)]\nprint(sum(p.numel() for p in model.parameters()))   # 5226","filename":"Python"},"revision":1},{"id":"9f159d7a-d640-7a9d-92af-5994287c8cd7","type":"text","position":"a4","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The pattern — conv/BN/ReLU blocks, downsampling that halves the resolution while channels double, global pooling, a linear head — describes most CNNs."}]}]}},"revision":1},{"id":"01c7ceb8-a844-7259-b505-470c24080c13","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Residual connections"}]},"revision":1},{"id":"d7315919-1251-781b-b9c7-98e4f4c012c4","type":"callout","position":"a6","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Residual block","marks":[{"type":"bold"}]},{"type":"text","text":" — instead of learning "},{"type":"text","text":"H(x)","marks":[{"type":"code"}]},{"type":"text","text":" directly, the block learns the change "},{"type":"text","text":"F(x) = H(x) − x","marks":[{"type":"code"}]},{"type":"text","text":" and outputs "},{"type":"text","text":"F(x) + x","marks":[{"type":"code"}]},{"type":"text","text":". If the best thing is to do nothing, it only has to push "},{"type":"text","text":"F","marks":[{"type":"code"}]},{"type":"text","text":" to zero."}]}]}},"revision":1},{"id":"6c6e4da1-0d72-74ec-82eb-4b634856b678","type":"text","position":"a7","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"x → conv → BN → ReLU → conv → BN = F(x) → F(x) + x → ReLU"}]}]}},"revision":1},{"id":"6c0ad932-4668-7ee0-8862-3287e31b5c38","type":"code","position":"a8","content":{"language":"python","code":"import torch\nfrom torch import nn\n\nclass ResidualBlock(nn.Module):\n    def __init__(self, channels):\n        super().__init__()\n        self.body = nn.Sequential(\n            nn.Conv2d(channels, channels, 3, padding=1, bias=False), nn.BatchNorm2d(channels), nn.ReLU(),\n            nn.Conv2d(channels, channels, 3, padding=1, bias=False), nn.BatchNorm2d(channels),\n        )\n\n    def forward(self, x):\n        return torch.relu(self.body(x) + x)          # the skip connection\n\ntorch.manual_seed(0)\nblock = ResidualBlock(8)\nx = torch.randn(2, 8, 16, 16)\nprint(block(x).shape)                                # torch.Size([2, 8, 16, 16]) ← shape preserved so x can be added\n\nnn.init.zeros_(block.body[4].weight)                 # zero the last BN''s scale → F(x) = 0\nprint(torch.allclose(block(x), torch.relu(x)))       # True ← the block passes x straight through","filename":"Python"},"revision":1},{"id":"8ee693d7-6a6c-7e03-a65a-d694685ea579","type":"text","position":"a9","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why it works: the gradient of "},{"type":"text","text":"F(x) + x","marks":[{"type":"code"}]},{"type":"text","text":" with respect to "},{"type":"text","text":"x","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"∂F/∂x + 1","marks":[{"type":"code"}]},{"type":"text","text":". The "},{"type":"text","text":"+1","marks":[{"type":"bold"}]},{"type":"text","text":" path carries gradients straight back through any number of blocks, so early layers keep learning. When the shapes differ (more channels, stride 2), the shortcut uses a 1×1 conv to match them."}]}]}},"revision":1},{"id":"048a1500-1a3b-713d-95eb-dc454fbab8ad","type":"callout","position":"aA","content":{"variant":"note","title":"1×1 convolutions","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Mix channels at each pixel without looking at neighbours — cheap way to shrink or expand channel count (bottlenecks in Inception/ResNet-50)."}]}]}},"revision":1},{"id":"8dc48fb8-8421-7ec9-8adc-d2e0615279bd","type":"callout","position":"aB","content":{"variant":"note","title":"Depthwise-separable conv","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A per-channel 3×3 conv followed by a 1×1 conv: ~8–9× fewer operations than a full 3×3 conv (MobileNet)."}]}]}},"revision":1},{"id":"ee87fa06-6c9c-7c72-bc6a-4e1fb341ab7c","type":"question","position":"aC","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why do residual connections help train very deep networks?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"They give gradients an identity path (the "},{"type":"text","text":"+x","marks":[{"type":"code"}]},{"type":"text","text":"), so they don''t vanish through many layers, and they make it easy for extra layers to do nothing harmful (learn "},{"type":"text","text":"F = 0","marks":[{"type":"code"}]},{"type":"text","text":"). Plain 56-layer nets trained worse than 20-layer ones; ResNets kept improving past 100 layers."}]}]}},"revision":1},{"id":"1a96b192-15de-7db1-815e-d486db989482","type":"question","position":"aD","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What does a 1×1 convolution do?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"It''s a linear layer applied at every pixel across channels: it changes the number of channels (e.g. 256 → 64) and mixes information between them, cheaply, without changing the spatial size."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
