INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT '073e6ec8-64d2-7018-8910-e936e7cfd710', '8a8bed76-e366-7d88-8ada-23bfe894db26', 1, 'PUBLISHED', 'Convolutions, Padding, Stride & Pooling', '[{"id":"d90758c1-a23c-724d-9aa7-e3a4a60fa9a6","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A convolutional layer slides small learned filters over an image. Each filter detects one local pattern (an edge, a texture) everywhere in the image, using the same few weights at every position."}]}]}},"revision":1},{"id":"2102e1fd-edb4-7958-ab5f-889c82cb01a1","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Why not a dense layer?"}]},"revision":1},{"id":"2aa10aa0-5395-71b1-a6e6-ba985fc6100f","type":"callout","position":"a2","content":{"variant":"note","title":"Locality","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Nearby pixels are related; a 3×3 filter looks only at a small neighbourhood."}]}]}},"revision":1},{"id":"2506cc27-b5f6-758e-830f-c39a220688e6","type":"callout","position":"a3","content":{"variant":"note","title":"Weight sharing","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The same filter is used at every position — far fewer parameters than connecting every pixel to every unit."}]}]}},"revision":1},{"id":"4498b33f-2c10-7f92-9c7a-b8bcee83792c","type":"callout","position":"a4","content":{"variant":"note","title":"Translation equivariance","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Shift the input and the feature map shifts the same way: a cat is detected wherever it is."}]}]}},"revision":1},{"id":"18e846c2-13f2-7061-94bc-48833bee83eb","type":"callout","position":"a5","content":{"variant":"note","title":"Hierarchy","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Stacked layers see larger regions: edges → textures → parts → objects."}]}]}},"revision":1},{"id":"aec69700-74e6-75da-a874-dcc43b466112","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"The operation"}]},"revision":1},{"id":"b9cdbf46-3a27-75ce-88ad-31107f22e108","type":"text","position":"a7","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"At each position, multiply the filter element-wise with the patch underneath and sum (deep-learning “convolution” is technically cross-correlation — the filter isn''t flipped)."}]}]}},"revision":1},{"id":"b865997d-6ea0-74c7-9d40-106b1e4f42b3","type":"code","position":"a8","content":{"language":"python","code":"import numpy as np\n\ndef conv2d(img, k):\n    kh, kw = k.shape\n    out = np.zeros((img.shape[0] - kh + 1, img.shape[1] - kw + 1))\n    for i in range(out.shape[0]):\n        for j in range(out.shape[1]):\n            out[i, j] = np.sum(img[i:i + kh, j:j + kw] * k)\n    return out\n\nimg = np.array([[0, 0, 0, 9, 9, 9]] * 5, dtype=float)    # dark left half, bright right half\nvertical_edge = np.array([[-1, 0, 1],\n                          [-1, 0, 1],\n                          [-1, 0, 1]], dtype=float)     # Sobel-like filter\nout = conv2d(img, vertical_edge)\nprint(out.shape)            # (3, 4) ← 5×6 input, 3×3 filter\nprint(out[0].tolist())      # [0.0, 27.0, 27.0, 0.0] ← fires only where brightness changes","filename":"Python"},"revision":1},{"id":"07cfbee9-e679-7dbd-9dd9-a493b17caaa0","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Output size: padding and stride"}]},"revision":1},{"id":"3d23667d-7f39-76a4-84f9-1dd31fee32df","type":"text","position":"aA","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"out = ⌊ (n + 2p − k) / s ⌋ + 1 n = input size, k = kernel, p = padding, s = stride","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"937a8d0c-a098-7d74-9ebf-da3b6c42af55","type":"table","position":"aB","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Setting"}],[{"type":"text","text":"Effect"}]],[[{"type":"text","text":"Padding "},{"type":"text","text":"p = (k−1)/2","marks":[{"type":"code"}]},{"type":"text","text":" (“same”)"}],[{"type":"text","text":"Output keeps the input size (stride 1) — edges get processed too"}]],[[{"type":"text","text":"No padding (“valid”)"}],[{"type":"text","text":"Output shrinks by "},{"type":"text","text":"k − 1","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Stride 2"}],[{"type":"text","text":"Moves the filter 2 pixels at a time — roughly halves height and width"}]],[[{"type":"text","text":"Dilation "},{"type":"text","text":"d","marks":[{"type":"code"}]}],[{"type":"text","text":"Spreads the filter taps out — larger view, same parameters"}]]]},"revision":1},{"id":"410b7540-59ae-7e3f-9908-2c761dd198ff","type":"code","position":"aC","content":{"language":"python","code":"import torch\nfrom torch import nn\n\nout_size = lambda n, k, p=0, s=1: (n + 2 * p - k) // s + 1\nprint(out_size(32, 3), out_size(32, 3, p=1), out_size(32, 3, p=1, s=2), out_size(224, 7, p=3, s=2))   # 30 32 16 112\n\nx = torch.randn(8, 3, 32, 32)                    # (batch, channels, height, width)\nconv = nn.Conv2d(in_channels=3, out_channels=16, kernel_size=3, padding=1, stride=2)\nprint(conv(x).shape)                             # torch.Size([8, 16, 16, 16])\nprint(conv.weight.shape, conv.bias.shape)        # torch.Size([16, 3, 3, 3]) torch.Size([16]) ← 16 filters, each 3×3×3\nprint(sum(p.numel() for p in conv.parameters()))   # 448 ← 16·(3·3·3) + 16","filename":"Python"},"revision":1},{"id":"fbb3585f-8411-7ab1-8407-36846d3ee6f3","type":"text","position":"aD","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"conv parameters = C_out × (C_in × k × k) + C_out — independent of the image size","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"68df566d-3a62-77bc-b090-9fe2dc774d86","type":"callout","position":"aE","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Each filter spans "},{"type":"text","text":"all","marks":[{"type":"bold"}]},{"type":"text","text":" input channels: a 3×3 filter on an RGB image has 3×3×3 = 27 weights. The layer''s output has one channel (feature map) per filter. Compare: a dense layer from a 32×32×3 image to 16×16×16 outputs would need about 12.6 million weights; this conv has 448."}]}]}},"revision":1},{"id":"41757d4f-702c-7cf9-b1ae-3c97a86504d7","type":"heading","position":"aF","content":{"level":1,"content":[{"type":"text","text":"Pooling"}]},"revision":1},{"id":"84da4fec-5617-75e3-9d4e-3f72b588ebed","type":"code","position":"aG","content":{"language":"python","code":"import torch\nfrom torch import nn\n\nx = torch.tensor([[[[1.0, 3.0, 2.0, 0.0],\n                    [4.0, 2.0, 1.0, 1.0],\n                    [0.0, 1.0, 5.0, 6.0],\n                    [2.0, 2.0, 7.0, 8.0]]]])            # (1, 1, 4, 4)\nprint(nn.MaxPool2d(2)(x).squeeze().tolist())          # [[4.0, 2.0], [2.0, 8.0]] ← max of each 2×2 block\nprint(nn.AvgPool2d(2)(x).squeeze().tolist())          # [[2.5, 1.0], [1.25, 6.5]]\nprint(nn.AdaptiveAvgPool2d(1)(x).flatten().tolist())  # [2.8125] ← global average pooling","filename":"Python"},"revision":1},{"id":"2c56d325-ebb7-7bdb-b99e-e4c26ff18312","type":"text","position":"aH","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Pooling shrinks feature maps (less compute, bigger receptive field) and adds a little tolerance to small shifts. It has "},{"type":"text","text":"no parameters","marks":[{"type":"bold"}]},{"type":"text","text":". Modern CNNs often use stride-2 convolutions instead, and end with "},{"type":"text","text":"global average pooling","marks":[{"type":"bold"}]},{"type":"text","text":" — one number per channel — before the classifier."}]}]}},"revision":1},{"id":"e3c35973-bced-7f96-80e9-aa33268dde4b","type":"heading","position":"aI","content":{"level":1,"content":[{"type":"text","text":"Receptive field"}]},"revision":1},{"id":"279f3a18-bda8-7b3f-8553-e08c5988ae62","type":"text","position":"aJ","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The receptive field is the patch of the input that can influence one output unit. Each 3×3 conv (stride 1) adds 2 pixels; each stride multiplies how fast later layers grow it."}]}]}},"revision":1},{"id":"423a7f65-36f0-77b1-ad32-e46568532460","type":"code","position":"aK","content":{"language":"python","code":"def receptive_field(layers):          # layers: list of (kernel, stride)\n    rf, jump = 1, 1\n    for k, s in layers:\n        rf += (k - 1) * jump\n        jump *= s\n    return rf\n\nprint(receptive_field([(3, 1)] * 2))                 # 5 ← two 3×3 convs see 5×5 (like one 5×5)\nprint(receptive_field([(3, 1)] * 3))                 # 7 ← three see 7×7\nprint(receptive_field([(3, 1), (2, 2), (3, 1), (2, 2), (3, 1)]))   # 18 ← pooling speeds growth","filename":"Python"},"revision":1},{"id":"38923c33-55f1-7f48-9d00-79e3e5619120","type":"callout","position":"aL","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Two stacked 3×3 convs see the same 5×5 area as one 5×5 conv but use "},{"type":"text","text":"2·9 = 18","marks":[{"type":"code"}]},{"type":"text","text":" weights per channel pair instead of 25 — and add an extra non-linearity. That''s VGG''s key insight."}]}]}},"revision":1},{"id":"bca18c75-db51-745d-be7c-6486f99de3ba","type":"question","position":"aM","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you compute the output size of a conv layer?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"⌊(n + 2p − k)/s⌋ + 1","marks":[{"type":"code"}]},{"type":"text","text":". Example: 224×224 input, 7×7 kernel, padding 3, stride 2 → "},{"type":"text","text":"⌊(224 + 6 − 7)/2⌋ + 1 = 112","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"af8cf5d1-0bcf-7c1d-a3a1-9153da7c9ed1","type":"question","position":"aN","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why are CNNs better than MLPs for images?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"They exploit image structure: local connectivity and weight sharing cut parameters by orders of magnitude, translation equivariance means a pattern is recognised anywhere, and stacking builds a feature hierarchy. An MLP on raw pixels has to learn every pattern separately at every position."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
