  ('38923c33-55f1-7f48-9d00-79e3e5619120', 'aL', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Two stacked 3×3 convs see the same 5×5 area as one 5×5 conv but use "},{"type":"text","text":"2·9 = 18","marks":[{"type":"code"}]},{"type":"text","text":" weights per channel pair instead of 25 — and add an extra non-linearity. That''s VGG''s key insight."}]}]}}'),
  ('bca18c75-db51-745d-be7c-6486f99de3ba', 'aM', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you compute the output size of a conv layer?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"⌊(n + 2p − k)/s⌋ + 1","marks":[{"type":"code"}]},{"type":"text","text":". Example: 224×224 input, 7×7 kernel, padding 3, stride 2 → "},{"type":"text","text":"⌊(224 + 6 − 7)/2⌋ + 1 = 112","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
