INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT 'ad877355-ac52-775f-be70-34eb73760a01', '9e1cb138-ac6d-7f9d-bd5b-1c6b1d34bb8e', 1, 'PUBLISHED', 'MLPs & the Forward Pass', '[{"id":"4b544698-dec9-78f4-b16f-af5171f22729","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A multi-layer perceptron (MLP) stacks fully-connected layers with activations in between. The forward pass is just matrix multiplies — computed for a whole batch at once."}]}]}},"revision":1},{"id":"e24b27ab-1ec1-7bc3-bc23-a2b20dd7d800","type":"callout","position":"a1","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Fully-connected (dense / linear) layer","marks":[{"type":"bold"}]},{"type":"text","text":" — every output unit is connected to every input: "},{"type":"text","text":"Y = X W + b","marks":[{"type":"code"}]},{"type":"text","text":", where "},{"type":"text","text":"X","marks":[{"type":"code"}]},{"type":"text","text":" is (batch, n_in), "},{"type":"text","text":"W","marks":[{"type":"code"}]},{"type":"text","text":" is (n_in, n_out) and "},{"type":"text","text":"b","marks":[{"type":"code"}]},{"type":"text","text":" is (n_out,)."}]}]}},"revision":1},{"id":"df590e89-b217-7254-8e8a-fcec35de16c3","type":"text","position":"a2","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input layer (features) → Hidden layer 1 + ReLU → Hidden layer 2 + ReLU → Output layer (logits)"}]}]}},"revision":1},{"id":"9f77c072-d0c6-7dca-b9e4-840f43b3811e","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"Shapes and parameter counts"}]},"revision":1},{"id":"0afa9e07-e3da-7aa8-a4bf-8bea8d74abae","type":"text","position":"a4","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"parameters of a dense layer = n_in × n_out + n_out (weights + biases)","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"1f3c4deb-cdde-77e3-9393-2b89846e3a05","type":"code","position":"a5","content":{"language":"python","code":"import numpy as np\n\nrng = np.random.default_rng(0)\nsizes = [4, 16, 8, 3]                  # 4 features → 16 → 8 → 3 classes\nparams = [(rng.normal(0, 0.5, (a, b)), np.zeros(b)) for a, b in zip(sizes, sizes[1:])]\n\ndef forward(X):\n    h = X\n    for i, (W, b) in enumerate(params):\n        h = h @ W + b\n        if i < len(params) - 1:       # ReLU on hidden layers only\n            h = np.maximum(0, h)\n    return h                           # logits\n\nX = rng.normal(size=(5, 4))            # a batch of 5 samples\nprint(forward(X).shape)                # (5, 3)\nprint(sum(W.size + b.size for W, b in params))   # 243 ← (4·16+16) + (16·8+8) + (8·3+3)","filename":"Python"},"revision":1},{"id":"5d30756d-7243-7fc7-b0c8-24199fc09050","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"A hidden layer solves XOR"}]},"revision":1},{"id":"8246a7a1-9a23-7280-8f16-290378ac4f14","type":"text","position":"a7","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"With hand-picked weights, two ReLU units are enough: "},{"type":"text","text":"h₁ = relu(x₁ + x₂)","marks":[{"type":"code"}]},{"type":"text","text":" counts the ones, "},{"type":"text","text":"h₂ = relu(x₁ + x₂ − 1)","marks":[{"type":"code"}]},{"type":"text","text":" fires only when both are 1, and the output is "},{"type":"text","text":"h₁ − 2h₂","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"d3d93496-0484-7ab0-adda-944eeedda94b","type":"code","position":"a8","content":{"language":"python","code":"import numpy as np\n\nX = np.array([[0, 0], [0, 1], [1, 0], [1, 1]])\nW1 = np.array([[1, 1], [1, 1]]); b1 = np.array([0, -1])\nW2 = np.array([1, -2]);          b2 = 0\n\nH = np.maximum(0, X @ W1 + b1)\nprint(H.tolist())                  # [[0, 0], [1, 0], [1, 0], [2, 1]] ← the hidden representation\nprint((H @ W2 + b2).tolist())      # [0, 1, 1, 0] ← XOR","filename":"Python"},"revision":1},{"id":"fe66438e-66a7-7ba7-8001-b2b74c222ce9","type":"callout","position":"a9","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The hidden layer re-maps the inputs so that the classes "},{"type":"text","text":"become","marks":[{"type":"italic"}]},{"type":"text","text":" linearly separable — (0,1) and (1,0) both land on "},{"type":"text","text":"[1, 0]","marks":[{"type":"code"}]},{"type":"text","text":". That is what “learning a representation” means. Backpropagation finds such weights automatically (see "},{"type":"text","text":"Backpropagation","marks":[{"type":"bold"}]},{"type":"text","text":")."}]}]}},"revision":1},{"id":"e3568fe1-293f-739a-a170-1a02096df87b","type":"heading","position":"aA","content":{"level":1,"content":[{"type":"text","text":"The same network in PyTorch"}]},"revision":1},{"id":"40ff6036-7b87-7cf8-9aac-ffb9498e91d6","type":"code","position":"aB","content":{"language":"python","code":"import torch\nfrom torch import nn\n\ntorch.manual_seed(0)\nmodel = nn.Sequential(\n    nn.Linear(4, 16), nn.ReLU(),\n    nn.Linear(16, 8), nn.ReLU(),\n    nn.Linear(8, 3),                  # raw logits — the loss applies softmax\n)\nX = torch.randn(5, 4)\nprint(model(X).shape)                                    # torch.Size([5, 3])\nprint(sum(p.numel() for p in model.parameters()))       # 243","filename":"Python"},"revision":1},{"id":"faa2cd1e-1cac-7ad9-aced-a68371269cc5","type":"heading","position":"aC","content":{"level":1,"content":[{"type":"text","text":"Universal approximation"}]},"revision":1},{"id":"8e86cfda-6657-74d6-b35b-d46953a1687a","type":"callout","position":"aD","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Universal approximation theorem","marks":[{"type":"bold"}]},{"type":"text","text":" — an MLP with "},{"type":"text","text":"one","marks":[{"type":"bold"}]},{"type":"text","text":" hidden layer and a non-linear activation can approximate any continuous function on a bounded domain as closely as you like — given enough hidden units."}]}]}},"revision":1},{"id":"5e9f2cd2-8291-7df0-8d6c-45db8db59603","type":"callout","position":"aE","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The theorem says a good network "},{"type":"text","text":"exists","marks":[{"type":"italic"}]},{"type":"text","text":", not that gradient descent will find it or that it will generalise. The required width can be astronomically large; in practice "},{"type":"text","text":"depth","marks":[{"type":"bold"}]},{"type":"text","text":" gives the same power with far fewer parameters."}]}]}},"revision":1},{"id":"06be6443-74f8-755d-b065-a6b52d7d79bb","type":"table","position":"aF","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Choice"}],[{"type":"text","text":"Rule of thumb"}]],[[{"type":"text","text":"Hidden layers"}],[{"type":"text","text":"1–3 for tabular data; deeper nets need tricks (normalisation, residuals)"}]],[[{"type":"text","text":"Width"}],[{"type":"text","text":"Powers of two (64, 128, 256…) — wide enough to overfit a small batch"}]],[[{"type":"text","text":"Hidden activation"}],[{"type":"text","text":"ReLU / GELU"}]],[[{"type":"text","text":"Output layer"}],[{"type":"text","text":"Linear, with "},{"type":"text","text":"n_out","marks":[{"type":"code"}]},{"type":"text","text":" = 1 (regression / binary) or number of classes"}]]]},"revision":1},{"id":"a4c79db5-24a1-716e-90f3-edf8d89c7daa","type":"question","position":"aG","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What happens in a forward pass?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input flows layer by layer: each layer computes "},{"type":"text