INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT '3c2a411b-9cf5-7998-b849-9a94a2cb0666', '9d818142-fa3d-71c2-91d9-9441f205b5b6', 1, 'PUBLISHED', 'Optimizers: Momentum, RMSProp, Adam', '[{"id":"4d5f5120-2899-7d73-9c97-a5bc27bc91ef","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Plain SGD uses only the current gradient. Modern optimizers also remember past gradients — to build speed in consistent directions (momentum) and to give each parameter its own step size (RMSProp, Adam)."}]}]}},"revision":1},{"id":"db0a85fb-8ebf-76a5-b98f-d4a23ab985dc","type":"table","position":"a1","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Optimizer"}],[{"type":"text","text":"Update (g = gradient)"}],[{"type":"text","text":"Idea"}]],[[{"type":"text","text":"SGD"}],[{"type":"text","text":"θ ← θ − η·g","marks":[{"type":"code"}]}],[{"type":"text","text":"Step against the gradient"}]],[[{"type":"text","text":"Momentum"}],[{"type":"text","text":"v ← βv + g; θ ← θ − η·v","marks":[{"type":"code"}]}],[{"type":"text","text":"A heavy ball: speeds up along consistent directions, damps zig-zag"}]],[[{"type":"text","text":"Nesterov"}],[{"type":"text","text":"Gradient evaluated at the look-ahead point "},{"type":"text","text":"θ − ηβv","marks":[{"type":"code"}]}],[{"type":"text","text":"Momentum that corrects earlier"}]],[[{"type":"text","text":"RMSProp"}],[{"type":"text","text":"s ← ρs + (1−ρ)g²; θ ← θ − η·g / (√s + ε)","marks":[{"type":"code"}]}],[{"type":"text","text":"Divide by recent gradient size — per-parameter step"}]],[[{"type":"text","text":"Adam"}],[{"type":"text","text":"m ← β₁m + (1−β₁)g; v ← β₂v + (1−β₂)g²; θ ← θ − η·m̂ / (√v̂ + ε)","marks":[{"type":"code"}]}],[{"type":"text","text":"Momentum + RMSProp, with bias correction "},{"type":"text","text":"m̂ = m / (1−β₁ᵗ)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"AdamW"}],[{"type":"text","text":"Adam + "},{"type":"text","text":"θ ← θ − η·λ·θ","marks":[{"type":"code"}]},{"type":"text","text":" applied separately"}],[{"type":"text","text":"Weight decay "},{"type":"text","text":"decoupled","marks":[{"type":"bold"}]},{"type":"text","text":" from the adaptive step"}]]]},"revision":1},{"id":"bc46af76-44f0-7778-8f5f-07d33153f337","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"Racing them on a narrow valley"}]},"revision":1},{"id":"7bd3051c-1c4a-727e-8d80-d427c5acbaac","type":"text","position":"a3","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"f(x, y) = x² + 100y²","marks":[{"type":"code"}]},{"type":"text","text":" is steep in "},{"type":"text","text":"y","marks":[{"type":"code"}]},{"type":"text","text":" and flat in "},{"type":"text","text":"x","marks":[{"type":"code"}]},{"type":"text","text":" — like many real loss surfaces. Plain SGD must keep its step below 0.01 to avoid bouncing out of the valley in "},{"type":"text","text":"y","marks":[{"type":"code"}]},{"type":"text","text":", and then crawls along "},{"type":"text","text":"x","marks":[{"type":"code"}]},{"type":"text","text":". All three start at "},{"type":"text","text":"(5, 1)","marks":[{"type":"code"}]},{"type":"text","text":" and take 100 steps; the minimum is "},{"type":"text","text":"f = 0","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"09e9dba4-15b1-7534-9659-f0bcde712c9a","type":"code","position":"a4","content":{"language":"python","code":"import numpy as np\n\ngrad = lambda t: np.array([2 * t[0], 200 * t[1]])     # ∇ of f = x² + 100y²\nf = lambda t: t[0] ** 2 + 100 * t[1] ** 2\nstart, steps = np.array([5.0, 1.0]), 100\n\ndef sgd(lr=0.009):                                    # above 0.01 it diverges in y\n    t = start.copy()\n    for _ in range(steps):\n        t -= lr * grad(t)\n    return f(t)\n\ndef momentum(lr=0.005, beta=0.9):\n    t, v = start.copy(), np.zeros(2)\n    for _ in range(steps):\n        v = beta * v + grad(t)\n        t -= lr * v\n    return f(t)\n\ndef adam(lr=0.3, b1=0.9, b2=0.999, eps=1e-8):\n    t, m, v = start.copy(), np.zeros(2), np.zeros(2)\n    for k in range(1, steps + 1):\n        g = grad(t)\n        m = b1 * m + (1 - b1) * g\n        v = b2 * v + (1 - b2) * g ** 2\n        m_hat, v_hat = m / (1 - b1 ** k), v / (1 - b2 ** k)\n        t -= lr * m_hat / (np.sqrt(v_hat) + eps)\n    return f(t)\n\nprint(f\"{sgd():.4f}\")        # 0.6611 ← still far from the minimum\nprint(f\"{momentum():.4f}\")   # 0.0004\nprint(f\"{adam():.4f}\")       # 0.0007","filename":"Python"},"revision":1},{"id":"384bc3d9-b574-7a1e-85b6-87cf455f0b95","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"In PyTorch"}]},"revision":1},{"id":"899fdaaa-f54b-712b-95b2-cb0cca52d264","type":"code","position":"a6","content":{"language":"python","code":"import torch\nfrom torch import nn\n\nmodel = nn.Linear(10, 1)\nopt_sgd = torch.optim.SGD(model.parameters(), lr=0.1, momentum=0.9, nesterov=True)\nopt_adam = torch.optim.Adam(model.parameters(), lr=1e-3)\nopt_adamw = torch.optim.AdamW(model.parameters(), lr=1e-3, weight_decay=0.01)\n\nprint(opt_adamw.defaults[\"betas\"], opt_adamw.defaults[\"eps\"])   # (0.9, 0.999) 1e-08","filename":"Python"},"revision":1},{"id":"b314fe34-0c01-7dde-928f-e65c53313c89","type":"text","position":"a7","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"optimizer.zero_grad()","marks":[{"type":"code"},{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Clear old gradients — PyTorch "},{"type":"text","text":"accumulates","marks":[{"type":"bold"}]},{"type":"text","text":" them otherwise."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"loss.backward()","marks":[{"type":"code"},{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Compute fresh gradients into each parameter''s "},{"type":"text","text":".grad","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"optimizer.step()","marks":[{"type":"code"},{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Update the parameters using those gradients (and the optimizer''s memory)."}]}]}]}]}},"revision":1},{"id":"8e442b04-1e6b-70d8-b670-65970c4acf6c","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"Adam vs AdamW"}]},"revision":1},{"id":"55b90ea5-c85b-77d2-a258-513265f5ac3a","type":"text","position":"a9","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"L2 regularisation adds "},{"type":"text","text":"λθ","marks":[{"type":"code"}]},{"type":"text","text":" to the gradient. In Adam that term is then divided by "},{"type":"text","text":"√v̂","marks":[{"type":"code"}]},{"type":"text","text":", so parameters with large gradients get "},{"type":"text","text":"less","marks":[{"type":"italic"}]},{"type":"text","text":" regularisation — not what we want. "},{"type":"text","text":"AdamW","marks":[{"type":"bold"}]},{"type":"text","text":" applies the decay directly to the weights, outside the adaptive step. It''s the default for Transformers."}]}]}},"revision":1},{"id":"33a76a35-d01b-7d2f-8c91-78965d8dd0c1","type":"table","position":"aA","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Choose"}],[{"type":"text","text":"When"}]],[[{"type":"text","text":"AdamW (lr ≈ 1e-3 … 1e-4)"}],[{"type":"text","text":"Default for most work: Transformers, MLPs, fine-tuning"}]],[[{"type":"text","text":"SGD + momentum 0.9 (lr ≈ 0.1) + schedule"}],[{"type":"text","text":"CNNs on images, when you can tune — often generalises slightly better"}]],[[{"type":"text","text":"Adam"}],[{"type":"text","text":"Quick prototypes; same as AdamW with "},{"type":"text","text":"weight_decay=0","marks":[{"type":"code"}]}]]]},"revision":1},{"id":"f5783b7d-57f4-7432-b2d3-1f7a77960095","type":"callout","position":"aB","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An optimizer keeps state: Adam stores two extra tensors ("},{"type":"text","text":"m","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"v","marks":[{"type":"code"}]},{"type":"text","text":") per parameter — the model''s weights ×3 in memory. Save the optimizer''s "},{"type":"text","text":"state_dict()","marks":[{"type":"code"}]},{"type":"text","text":" with checkpoints or resumed training will behave differently."}]}]}},"revision":1},{"id":"5f9c8006-1470-7389-b45d-e25da70d6658","type":"question","position":"aC","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why does Adam need bias correction?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"m","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"v","marks":[{"type":"code"}]},{"type":"text","text":" start at zero, so during the first steps they''re biased toward zero (e.g. after step 1, "},{"type":"text","text":"m = 0.1·g","marks":[{"type":"code"}]},{"type":"text","text":"). Dividing by "},{"type":"text","text":"1 − βᵗ","marks":[{"type":"code"}]},{"type":"text","text":" rescales them to proper averages; the correction fades as "},{"type":"text","text":"t","marks":[{"type":"code"}]},{"type":"text","text":" grows."}]}]}},"revision":1},{"id":"a3587291-4660-75cf-bc21-c99a2c7e865c","type":"question","position":"aD","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What does momentum do?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"It keeps an exponentially-weighted running sum of past gradients. Components that point the same way every step add up (faster progress along valleys); components that flip sign cancel (less zig-zagging)."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
