INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT '46c34c1b-6251-7e5b-8ab3-ee1ac8907c1f', 'bc59671e-12c2-7468-8fa6-2c30783a64c3', 1, 'PUBLISHED', 'The Training Loop', '[{"id":"6252231e-f23c-7533-bbc6-34426508cd0b","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Every PyTorch project has the same heartbeat: for each batch — forward, loss, zero_grad, backward, step. Around it: an evaluation loop in "},{"type":"text","text":"eval()","marks":[{"type":"code"}]},{"type":"text","text":" mode under "},{"type":"text","text":"no_grad()","marks":[{"type":"code"}]},{"type":"text","text":", and checkpoints."}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"model.train()","marks":[{"type":"code"},{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Dropout on, BatchNorm uses batch statistics."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Forward","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"logits = model(xb)","marks":[{"type":"code"}]},{"type":"text","text":" then "},{"type":"text","text":"loss = loss_fn(logits, yb)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"optimizer.zero_grad()","marks":[{"type":"code"},{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Clear gradients from the previous step."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"loss.backward()","marks":[{"type":"code"},{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Compute gradients."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"optimizer.step()","marks":[{"type":"code"},{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Update weights (then "},{"type":"text","text":"scheduler.step()","marks":[{"type":"code"}]},{"type":"text","text":" if you use one)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Evaluate","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"model.eval()","marks":[{"type":"code"}]},{"type":"text","text":" + "},{"type":"text","text":"torch.no_grad()","marks":[{"type":"code"}]},{"type":"text","text":" on the validation set; keep the best checkpoint."}]}]}]}]}},"revision":1},{"id":"ff6145cd-1178-7343-92c8-dfb898ba433f","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"A complete example"}]},"revision":1},{"id":"261409b6-0983-7442-9ed6-28e0bc6eadb2","type":"text","position":"a2","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Classify points by whether they lie inside a circle — a non-linear boundary a linear model can''t learn."}]}]}},"revision":1},{"id":"0f6e1f1e-def8-7862-873c-2c6916e2e8b6","type":"code","position":"a3","content":{"language":"python","code":"import torch\nfrom torch import nn\nfrom torch.utils.data import DataLoader, TensorDataset\n\ntorch.manual_seed(0)\nX = torch.rand(1000, 2) * 2 - 1                      # points in [-1, 1]²\ny = ((X ** 2).sum(dim=1) < 0.5).long()               # class 1 inside the circle\ntrain_ds, val_ds = TensorDataset(X[:800], y[:800]), TensorDataset(X[800:], y[800:])\ntrain_loader = DataLoader(train_ds, batch_size=32, shuffle=True)\nval_loader = DataLoader(val_ds, batch_size=200)\n\nmodel = nn.Sequential(nn.Linear(2, 32), nn.ReLU(), nn.Linear(32, 32), nn.ReLU(), nn.Linear(32, 2))\nloss_fn = nn.CrossEntropyLoss()\noptimizer = torch.optim.AdamW(model.parameters(), lr=1e-2)\n\ndef evaluate(loader):\n    model.eval()\n    correct = total = 0\n    with torch.no_grad():\n        for xb, yb in loader:\n            correct += (model(xb).argmax(dim=1) == yb).sum().item()\n            total += len(yb)\n    return correct / total\n\nfor epoch in range(20):\n    model.train()\n    for xb, yb in train_loader:\n        loss = loss_fn(model(xb), yb)\n        optimizer.zero_grad()\n        loss.backward()\n        optimizer.step()\n\nprint(f\"train acc {evaluate(train_loader):.2f}, val acc {evaluate(val_loader):.2f}\")   # train acc 0.99, val acc 0.97","filename":"Python"},"revision":1},{"id":"b9f75719-5f58-74cd-a8f0-8f02e93bf607","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Saving and loading"}]},"revision":1},{"id":"7357b6ec-dda7-7f24-bb98-d27f16ac1378","type":"code","position":"a5","content":{"language":"python","code":"import torch\nfrom torch import nn\n\ntorch.manual_seed(0)\nmodel = nn.Linear(3, 1)\noptimizer = torch.optim.AdamW(model.parameters(), lr=1e-3)\n\ntorch.save(model.state_dict(), \"model.pt\")                   # weights only — the usual way\ntorch.save({\"epoch\": 5, \"model\": model.state_dict(),          # full checkpoint to resume training\n            \"optimizer\": optimizer.state_dict()}, \"checkpoint.pt\")\n\nrestored = nn.Linear(3, 1)                                    # rebuild the architecture first…\nrestored.load_state_dict(torch.load(\"model.pt\"))              # …then load the weights\nrestored.eval()\nx = torch.ones(1, 3)\nprint(torch.equal(model(x), restored(x)))                     # True\n\nckpt = torch.load(\"checkpoint.pt\")\nprint(ckpt[\"epoch\"], list(ckpt[\"model\"].keys()))              # 5 [''weight'', ''bias'']","filename":"Python"},"revision":1},{"id":"dfeb2052-cc4f-74bf-b1f7-a6dde7c19ee6","type":"callout","position":"a6","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"state_dict","marks":[{"type":"code"}]},{"type":"text","text":" is an ordered dict of parameter and buffer tensors keyed by name. Save that (not the whole pickled model object) — it survives code refactors and is safe to load with "},{"type":"text","text":"torch.load(..., weights_only=True)","marks":[{"type":"code"}]},{"type":"text","text":", the default in recent PyTorch."}]}]}},"revision":1},{"id":"5ff444ec-37a1-7a43-94f4-87828b17a97e","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Using a GPU"}]},"revision":1},{"id":"9a4e83da-d207-7b7b-8eb1-2cb51a0244e8","type":"code","position":"a8","content":{"language":"python","code":"device = torch.device(\"cuda\" if torch.cuda.is_available()\n                      else \"mps\" if torch.backends.mps.is_available() else \"cpu\")\nmodel = model.to(device)                     # parameters move once\nfor xb, yb in train_loader:\n    xb, yb = xb.to(device), yb.to(device)    # every batch must follow\n    ...\n# load a GPU checkpoint on a CPU-only machine:\nstate = torch.load(\"model.pt\", map_location=\"cpu\")","filename":"Python"},"revision":1},{"id":"6ba167a0-89e3-734f-99ac-3d70c8f146f7","type":"callout","position":"a9","content":{"variant":"tip","title":"Do","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Call "},{"type":"text","text":"model.eval()","marks":[{"type":"code"}]},{"type":"text","text":" and wrap validation/inference in "},{"type":"text","text":"torch.no_grad()","marks":[{"type":"code"}]},{"type":"text","text":" (or "},{"type":"text","text":"torch.inference_mode()","marks":[{"type":"code"}]},{"type":"text","text":"); log "},{"type":"text","text":"loss.item()","marks":[{"type":"code"}]},{"type":"text","text":", not the tensor."}]}]}},"revision":1},{"id":"8e49d4a0-1e7b-7f02-986b-d1586aed5068","type":"callout","position":"aA","content":{"variant":"danger","title":"Avoid","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Accumulate "},{"type":"text","text":"total_loss += loss","marks":[{"type":"code"}]},{"type":"text","text":" — it keeps every step''s graph alive and leaks memory."}]}]}},"revision":1},{"id":"ae6a0422-88e