INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT 'd34c0d04-1f6a-7f05-a9d1-fb4bc22c6c43', '27d5d054-4232-790e-88d0-ddc10d4165cd', 1, 'PUBLISHED', 'Training in Practice', '[{"id":"b5cf6a26-ad07-7c67-88e7-c0a62b53b4aa","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Most failed training runs are bugs or bad settings, not bad architectures. A short, disciplined routine — start small, overfit one batch, read the loss curves, then tune — finds problems quickly."}]}]}},"revision":1},{"id":"7c94e468-70c8-7477-a27b-3d0b52fd5fa2","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"A debugging routine"}]},"revision":1},{"id":"10df41ea-68ff-7295-81a8-5fc28afe2fa6","type":"text","position":"a2","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Look at the data","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Plot samples with their labels; check shapes, ranges, class balance, normalisation, and that inputs and labels still line up after shuffling."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Check the first loss","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"For "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":" balanced classes it should be ≈ "},{"type":"text","text":"ln k","marks":[{"type":"code"}]},{"type":"text","text":". Far off → wrong loss, wrong labels or bad init."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Overfit one small batch","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"A healthy model + training loop drives the loss on 10–50 examples to ~0. If it can''t, there''s a bug."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Train a simple baseline","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Small model, Adam(W) at "},{"type":"text","text":"1e-3","marks":[{"type":"code"}]},{"type":"text","text":", no fancy tricks. Get something working end-to-end."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Scale up and regularise","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Bigger model, more data, augmentation, schedules — one change at a time, tracking validation metrics."}]}]}]}]}},"revision":1},{"id":"fd2da76e-bcbb-7311-a2ae-d783c7cda903","type":"code","position":"a3","content":{"language":"python","code":"import torch\nfrom torch import nn\n\ntorch.manual_seed(0)\nxb = torch.randn(16, 10)                          # one small batch with random labels —\nyb = torch.randint(0, 4, (16,))                   # impossible to generalise, easy to memorise\nmodel = nn.Sequential(nn.Linear(10, 64), nn.ReLU(), nn.Linear(64, 4))\nopt = torch.optim.Adam(model.parameters(), lr=1e-2)\nloss_fn = nn.CrossEntropyLoss()\n\nfirst = loss_fn(model(xb), yb).item()\nfor _ in range(200):\n    loss = loss_fn(model(xb), yb)\n    opt.zero_grad(); loss.backward(); opt.step()\n\nprint(round(first, 1), round(torch.log(torch.tensor(4.0)).item(), 1))   # 1.4 1.4 ← first loss ≈ ln 4\nprint(loss.item() < 0.01)                                              # True ← memorised: the loop works","filename":"Python"},"revision":1},{"id":"6fa499c4-cd72-7813-abef-eca1f5a66ea2","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Reading loss curves"}]},"revision":1},{"id":"43deb530-688a-7a32-b06c-cdbf13823333","type":"table","position":"a5","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"What you see"}],[{"type":"text","text":"Diagnosis"}],[{"type":"text","text":"Try"}]],[[{"type":"text","text":"Train ↓, validation ↓ then ↑"}],[{"type":"text","text":"Overfitting"}],[{"type":"text","text":"Early stopping, regularisation, augmentation, more data"}]],[[{"type":"text","text":"Both high and flat"}],[{"type":"text","text":"Underfitting or LR too low"}],[{"type":"text","text":"Bigger model, higher LR, train longer, check for bugs"}]],[[{"type":"text","text":"Loss jumps to "},{"type":"text","text":"nan","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"inf","marks":[{"type":"code"}]}],[{"type":"text","text":"Exploding gradients, LR too high, "},{"type":"text","text":"log(0)","marks":[{"type":"code"}]}],[{"type":"text","text":"Lower LR, gradient clipping, warmup, check the loss inputs"}]],[[{"type":"text","text":"Very noisy loss"}],[{"type":"text","text":"LR too high or batch too small"}],[{"type":"text","text":"Lower LR, larger batch, LR decay"}]],[[{"type":"text","text":"Validation better than training"}],[{"type":"text","text":"Dropout/augmentation only in training — or a leaky validation set"}],[{"type":"text","text":"Usually fine; check for leakage"}]],[[{"type":"text","text":"Plateau, then sudden drop"}],[{"type":"text","text":"Poor init or LR schedule kicking in"}],[{"type":"text","text":"Warmup, better init"}]]]},"revision":1},{"id":"7d6a2c76-7e74-7845-b761-fe3d12a4e1a8","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"Hyper-parameter tuning"}]},"revision":1},{"id":"f10a8f9f-67cc-7a3f-8af1-d945078f9987","type":"table","position":"a7","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Priority"}],[{"type":"text","text":"Hyper-parameter"}],[{"type":"text","text":"Typical search"}]],[[{"type":"text","text":"1"}],[{"type":"text","text":"Learning rate"}],[{"type":"text","text":"Log scale: 1e-4, 3e-4, 1e-3, 3e-3…"}]],[[{"type":"text","text":"2"}],[{"type":"text","text":"Batch size / schedule / epochs"}],[{"type":"text","text":"As large as memory allows; cosine + warmup"}]],[[{"type":"text","text":"3"}],[{"type":"text","text":"Weight decay, dropout"}],[{"type":"text","text":"0–0.1; 0–0.5"}]],[[{"type":"text","text":"4"}],[{"type":"text","text":"Architecture (depth, width)"}],[{"type":"text","text":"Scale up until validation stops improving"}]]]},"revision":1},{"id":"344a9d71-4203-7121-b662-89a96ac97f36","type":"callout","position":"a8","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Prefer "},{"type":"text","text":"random search","marks":[{"type":"bold"}]},{"type":"text","text":" over grid search (it explores important dimensions better), sample learning rates on a log scale, and tune on a smaller budget before full runs. Tools such as Optuna or Ray Tune automate this; Weights & Biases or TensorBoard track the runs."}]}]}},"revision":1},{"id":"c2426384-ba4b-7d01-824f-d2b38d543057","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Mixed precision"}]},"revision":1},{"id":"b299b235-1a25-76aa-9239-2a2f3c829914","type":"text","position":"aA","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Running most operations in 16-bit floats ("},{"type":"text","text":"float16","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"bfloat16","marks":[{"type":"code"}]},{"type":"text","text":") halves memory and uses fast tensor cores, with little accuracy loss. "},{"type":"text","text":"torch.autocast","marks":[{"type":"code"}]},{"type":"text","text":" picks the precision per operation — matrix multiplies in 16-bit, sensitive reductions in 32-bit."}]}]}},"revision":1},{"id":"ddd8420b-52e0-7050-ba88-65bd0ff299fb","type":"code","position":"aB","content":{"language":"python","code":"import torch\nfrom torch import nn\n\nmodel = nn.Linear(8, 4)\nx = torch.randn(2, 8)\nwith torch.autocast(device_type=\"cpu\", dtype=torch.bfloat16):\n    out = model(x)\nprint(out.dtype, model.weight.dtype)      # torch.bfloat16 torch.float32 ← compute in bf16, weights stay fp32","filename":"Python"},"revision":1},{"id":"5ba9767b-981e-7c04-b2e7-0a9cf2a19cc7","type":"code","position":"aC","content":{"language":"python","code":"scaler = torch.amp.GradScaler(\"cuda\")          # float16 on CUDA needs loss scaling (bfloat16 doesn''t)\nfor xb, yb in loader:\n    optimizer.zero_grad()\n    with torch.autocast(device_type=\"cuda\", dtype=torch.float16):\n        loss = loss_fn(model(xb), yb)\n    scaler.scale(loss).backward()              # scale up so small gradients don''t underflow\n    scaler.step(optimizer)                     # unscales; skips the step if inf/nan appeared\n    scaler.update()","filename":"Python"},"revision":1},{"id":"6698f332-6e04-71f5-b5d1-cb5be6eedd32","type":"heading","position":"aD","content":{"level":1,"content":[{"type":"text","text":"GPU memory and gradient accumulation"}]},"revision":1},{"id":"0a464043-08a4-7add-be97-05ca778f3ff9","type":"text","position":"aE","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Memory holds weights, gradients, optimizer state (Adam: 2× weights) and the activations saved for backprop, which grow with batch size. When a batch doesn''t fit, "},{"type":"text","text":"accumulate","marks":[{"type":"bold"}]},{"type":"text","text":" gradients over several micro-batches before stepping:"}]}]}},"revision":1},{"id":"b5a3b393-b50f-7981-a205-78eb815b26fb","type":"code","position":"aF","content":{"language":"python","code":"import torch\nfrom torch import nn\n\ntorch.manual_seed(0)\nmodel = nn.Linear(4, 1)\nX, y = torch.randn(8, 4), torch.randn(8, 1)\nloss_fn = nn.MSELoss()\n\nmodel.zero_grad()\nloss_fn(model(X), y).backward()                    # one batch of 8\nfull = model.weight.grad.clone()\n\nmodel.zero_grad()\nfor xb, yb in zip(X.split(2), y.split(2)):         # 4 micro-batches of 2\n    (loss_fn(model(xb), yb) / 4).backward()        # divide by the number of micro-batches\nprint(torch.allclose(full, model.weight.grad, atol=1e-6))   # True ← same gradient","filename":"Python"},"revision":1},{"id":"e5062462-b32f-7f48-b5ce-bd84b1625d4c","type":"table","position":"aG","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Speed-up"}],[{"type":"text","text":"How"}]],[[{"type":"text","text":"Keep the GPU fed"}],[{"type":"text","text":"num_workers > 0","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"pin_memory=True","marks":[{"type":"code"}]},{"type":"text","text":", avoid "},{"type":"text","text":".item()","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":".cpu()","marks":[{"type":"code"}]},{"type":"text","text":" inside the loop"}]],[[{"type":"text","text":"Mixed precision"}],[{"type":"text","text":"torch.autocast","marks":[{"type":"code"}]},{"type":"text","text":" + bf16/fp16"}]],[[{"type":"text","text":"Compile"}],[{"type":"text","text":"model = torch.compile(model)","marks":[{"type":"code"}]},{"type":"text","text":" fuses operations"}]],[[{"type":"text","text":"Bigger batches"}],[{"type":"text","text":"Better hardware use (retune the LR)"}]],[[{"type":"text","text":"Multiple GPUs"}],[{"type":"text","text":"DistributedDataParallel","marks":[{"type":"code"}]},{"type":"text","text":" (DDP); FSDP to shard huge models"}]],[[{"type":"text","text":"Save memory"}],[{"type":"text","text":"Gradient checkpointing (recompute activations), smaller batch + accumulation"}]]]},"revision":1},{"id":"d8df862e-19dd-7c35-bf68-e2893d9c3ade","type":"question","position":"aH","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Your loss isn''t decreasing. How do you debug it?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Check the data and labels first, then the initial loss against "},{"type":"text","text":"ln k","marks":[{"type":"code"}]},{"type":"text","text":", then try to overfit a single small batch. If that fails, look for bugs: missing "},{"type":"text","text":"zero_grad","marks":[{"type":"code"}]},{"type":"text","text":", softmax before "},{"type":"text","text":"CrossEntropyLoss","marks":[{"type":"code"}]},{"type":"text","text":", wrong label dtype/shape, frozen parameters, forgetting "},{"type":"text","text":"optimizer.step()","marks":[{"type":"code"}]},{"type":"text","text":", or an LR that''s far too high or low. Then inspect gradient norms per layer."}]}]}},"revision":1},{"id":"59c01ea3-9900-7d20-9f0a-eecfff9c904d","type":"question","position":"aI","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is mixed precision training?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Doing most computation in 16-bit floats while keeping a 32-bit master copy of the weights. It cuts memory and speeds up training on tensor-core GPUs. With float16 a gradient scaler prevents small gradients from underflowing; bfloat16 has float32''s range and usually doesn''t need one."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
