INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT 'bfed028b-f33d-7eb6-97ea-b3eb42deb479', 'd3920111-d6ba-7296-a476-d010ecedf316', 1, 'PUBLISHED', 'Transfer Learning & Fine-Tuning', '[{"id":"17440f4d-9ed7-799e-99bd-6e63f211b256","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Don''t train from scratch when someone has already trained a model on millions of examples. Reuse its learned features, replace the head for your task, and fine-tune — you need far less data and compute."}]},{"type":"paragraph","content":[{"type":"text","text":"Pretrained backbone (e.g. ImageNet ResNet) → Replace the head → Train head (backbone frozen) → Optionally unfreeze & fine-tune with a low LR"}]}]}},"revision":1},{"id":"d756b9f3-7ded-798d-b447-f09330bc8b35","type":"table","position":"a1","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Your data"}],[{"type":"text","text":"Similar to pretraining data"}],[{"type":"text","text":"Different from it"}]],[[{"type":"text","text":"Small","marks":[{"type":"bold"}]}],[{"type":"text","text":"Feature extraction: freeze everything, train only the head"}],[{"type":"text","text":"Freeze early layers, fine-tune later ones carefully"}]],[[{"type":"text","text":"Large","marks":[{"type":"bold"}]}],[{"type":"text","text":"Fine-tune the whole network"}],[{"type":"text","text":"Fine-tune everything (or train longer / from scratch)"}]]]},"revision":1},{"id":"c83422df-b965-7849-a395-d1a80e6a3dde","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"Freezing and replacing the head"}]},"revision":1},{"id":"37712fa1-3b27-7c54-b141-49b0620f7cbb","type":"text","position":"a3","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Here a small network stands in for a pretrained backbone; with a real one the code is identical."}]}]}},"revision":1},{"id":"b2cf7227-19c7-7ee0-ae0c-57b2e3e1b575","type":"code","position":"a4","content":{"language":"python","code":"import torch\nfrom torch import nn\n\ntorch.manual_seed(0)\nbackbone = nn.Sequential(                              # pretend these weights came from ImageNet\n    nn.Conv2d(3, 32, 3, padding=1), nn.ReLU(),\n    nn.Conv2d(32, 64, 3, padding=1), nn.ReLU(),\n    nn.AdaptiveAvgPool2d(1), nn.Flatten(),\n)\nfor p in backbone.parameters():\n    p.requires_grad = False                            # freeze: no gradients, no updates\n\nmodel = nn.Sequential(backbone, nn.Linear(64, 5))      # new head for our 5 classes\ntrainable = sum(p.numel() for p in model.parameters() if p.requires_grad)\ntotal = sum(p.numel() for p in model.parameters())\nprint(trainable, total)                                # 325 19717 ← only the head trains\n\noptimizer = torch.optim.AdamW((p for p in model.parameters() if p.requires_grad), lr=1e-3)\nprint(model(torch.randn(2, 3, 32, 32)).shape)          # torch.Size([2, 5])","filename":"Python"},"revision":1},{"id":"5b4e43ed-d9f8-7c5d-831f-a84e51f6a9a9","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Fine-tuning with smaller learning rates for the backbone"}]},"revision":1},{"id":"7d05daa9-0a76-7017-a387-c1865e7ea053","type":"code","position":"a6","content":{"language":"python","code":"import torch\nfrom torch import nn\n\nbackbone, head = nn.Linear(10, 10), nn.Linear(10, 2)\noptimizer = torch.optim.AdamW([\n    {\"params\": backbone.parameters(), \"lr\": 1e-5},     # gentle: keep the pretrained features\n    {\"params\": head.parameters(), \"lr\": 1e-3},         # the new head learns faster\n], weight_decay=0.01)\nprint([g[\"lr\"] for g in optimizer.param_groups])       # [1e-05, 0.001]","filename":"Python"},"revision":1},{"id":"38495e72-5290-7b39-bb5a-07fc2df45675","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"With torchvision"}]},"revision":1},{"id":"bc80aaf7-d424-766b-8804-f47ae30ea4c1","type":"code","position":"a8","content":{"language":"python","code"