INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT 'af752330-f16b-7980-92f1-fdb8e81c37bf', '335a23b8-48a2-75d7-a4ac-9d7af345d872', 1, 'PUBLISHED', 'Transformers', '[{"id":"23ec3c60-77d1-7c44-9408-886423c4300a","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The Transformer (“Attention Is All You Need”, 2017) drops recurrence entirely: stacks of self-attention and feed-forward layers, with residual connections and layer norm. It powers modern language, vision and audio models."}]},{"type":"paragraph","content":[{"type":"text","text":"Tokens → Embeddings + positional encoding → N × [Multi-head attention → Add & Norm → Feed-forward → Add & Norm] → Output head"}]}]}},"revision":1},{"id":"2bd7b79d-a187-718b-b4bc-3e7be3dec696","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Encoder, decoder, or both"}]},"revision":1},{"id":"0a5479d2-2b97-7db9-9927-87456fbe8838","type":"table","position":"a2","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Type"}],[{"type":"text","text":"Attention"}],[{"type":"text","text":"Trained to"}],[{"type":"text","text":"Examples"}],[{"type":"text","text":"Good for"}]],[[{"type":"text","text":"Encoder-only"}],[{"type":"text","text":"Bidirectional self-attention"}],[{"type":"text","text":"Fill in masked tokens"}],[{"type":"text","text":"BERT, RoBERTa"}],[{"type":"text","text":"Classification, embeddings, extraction"}]],[[{"type":"text","text":"Decoder-only"}],[{"type":"text","text":"Causal self-attention"}],[{"type":"text","text":"Predict the next token"}],[{"type":"text","text":"GPT, LLaMA, Claude"}],[{"type":"text","text":"Text generation, chat — today''s LLMs"}]],[[{"type":"text","text":"Encoder–decoder"}],[{"type":"text","text":"Encoder self-attention + decoder cross-attention"}],[{"type":"text","text":"Map input sequence → output sequence"}],[{"type":"text","text":"Original Transformer, T5, Whisper"}],[{"type":"text","text":"Translation, summarisation, speech-to-text"}]]]},"revision":1},{"id":"42b4c5d8-a713-78f6-a71e-c39b0937c9d6","type":"text","position":"a3","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"GenAI","marks":[{"type":"bold"}]},{"type":"text","text":" notes cover the LLM side (GPT vs BERT, tokens, context windows, sampling); here we look at the machinery."}]}]}},"revision":1},{"id":"4d8eefeb-b85c-7c6c-8f83-d54eadae9941","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Positional encoding"}]},"revision":1},{"id":"1f0fee30-af8e-7577-8225-e2c84b50b7ac","type":"text","position":"a5","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Attention is permutation-invariant — shuffle the tokens and each output is just shuffled too — so order must be injected. The original paper adds sinusoids of different frequencies to the embeddings; many models learn position embeddings, and modern LLMs use rotary embeddings (RoPE) applied inside attention."}]},{"type":"paragraph","content":[{"type":"text","text":"PE(pos, 2i) = sin(pos / 10000^(2i/d)) PE(pos, 2i+1) = cos(pos / 10000^(2i/d))","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"845f2505-50d4-7cef-a466-f74137f86ac3","type":"code","position":"a6","content":{"language":"python","code":"import numpy as np\n\ndef positional_encoding(n_positions, d):\n    pos = np.arange(n_positions)[:, None]\n    i = np.arange(0, d, 2)[None, :]\n    angle = pos / 10000 ** (i / d)\n    pe = np.zeros((n_positions, d))\n    pe[:, 0::2], pe[:, 1::2] = np.sin(angle), np.cos(angle)\n    return pe\n\npe = positional_encoding(50, 16)\nprint(pe.shape)                          # (50, 16)\nprint(pe[0, :4].tolist())                # [0.0, 1.0, 0.0, 1.0] ← position 0: sin 0, cos 0, …\nprint(pe[1, :4].round(3).tolist())       # [0.841, 0.54, 0.311, 0.95]\nnear, far = pe[10] @ pe[11], pe[10] @ pe[40]\nprint(near > far)                        # True ← nearby positions have more similar codes","filename":"Python"},"revision":1},{"id":"60390afd-12b4-798b-ae4f-adad3caf183f","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Multi-head attention"}]},"revision":1},{"id":"2cbb719e-666e-751f-ab6b-ea13299e3fa1","type":"text","position":"a8","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Instead of one attention with "},{"type":"text","text":"d_model","marks":[{"type":"code"}]},{"type":"text","text":"-wide vectors, split into "},{"type":"text","text":"h","marks":[{"type":"code"}]},{"type":"text","text":" heads of size "},{"type":"text","text":"d_model / h","marks":[{"type":"code"}]},{"type":"text","text":", attend in each independently, concatenate and project. Different heads learn different relations — one follows syntax, another coreference, another nearby tokens — at the same total cost."}]},{"type":"paragraph","content":[{"type":"text","text":"MultiHead(X) = Concat(head₁, …, head_h) W_O headᵢ = Attention(X W_Qⁱ, X W_Kⁱ, X W_Vⁱ)","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"4f2d55df-b410-72e7-9d3f-2a6c7e789cd0","type":"code","position":"a9","content":{"language":"python","code":"import torch\nfrom torch import nn\n\ntorch.manual_seed(0)\nmha = nn.MultiheadAttention(embed_dim=64, num_heads=8, batch_first=True)   # 8 heads of size 8\nx = torch.randn(2, 10, 64)                       # (batch, tokens, d_model)\nout, weights = mha(x, x, x)                      # self-attention: query = key = value = x\nprint(out.shape, weights.shape)                  # torch.Size([2, 10, 64]) torch.Size([2, 10, 10]) ← weights averaged over heads\nprint(sum(p.numel() for p in mha.parameters()))  # 16640 ← 4 projections of 64×64 (+ biases)","filename":"Python"},"revision":1},{"id":"628beeb4-075c-7c64-b852-a674508dfd4f","type":"heading","position":"aA","content":{"level":1,"content":[{"type":"text","text":"A Transformer block"}]},"revision":1},{"id":"4e3069a4-6872-733a-a7e5-b5a925cfdeeb","type":"code","position":"aB","content":{"language":"python","code":"import torch\nfrom torch import nn\n\nclass TransformerBlock(nn.Module):\n    \"\"\"Pre-LN block, as in GPT-2 and most modern models.\"\"\"\n    def __init__(self, d_model=64, n_heads=4, d_ff=256, dropout=0.1):\n        super().__init__()\n        self.ln1, self.ln2 = nn.LayerNorm(d_model), nn.LayerNorm(d_model)\n        self.attn = nn.MultiheadAttention(d_model, n_heads, dropout=dropout, batch_first=True)\n        self.ff = nn.Sequential(nn.Linear(d_model, d_ff), nn.GELU(), nn.Linear(d_ff, d_model), nn.Dropout(dropout))\n\n    def forward(self, x, causal=True):\n        n = x.shape[1]\n        mask = torch.triu(torch.ones(n, n, dtype=torch.bool), diagonal=1) if causal else None   # True = blocked\n        h = self.ln1(x)\n        x = x + self.attn(h, h, h, attn_mask=mask, need_weights=False)[0]   # residual 1\n        x = x + self.ff(self.ln2(x))                                         # residual 2\n        return x\n\ntorch.manual_seed(0)\nblock = TransformerBlock()\nx = torch.randn(2, 10, 64)\nprint(block(x).shape)                                   # torch.Size([2, 10, 64]) ← same shape in and out: blocks stack\nprint(sum(p.numel() for p in block.parameters()))       # 49984\n\nlayer = nn.TransformerEncoderLayer(d_model=64, nhead=4, dim_feedforward=256, batch_first=True, norm_first=True)\nencoder = nn.TransformerEncoder(layer, num_layers=6, enable_nested_tensor=False)   # built-in, 6 deep\nprint(encoder(x).shape)                                 # torch.Size([2, 10, 64])","filename":"Python"},"revision":1},{"id":"6a4ec5de-a527-7c3c-b555-8c5f79c562f6","type":"table","position":"aC","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Component"}],[{"type":"text","text":"Role"}]],[[{"type":"text","text":"Multi-head self-attention"}],[{"type":"text","text":"Tokens exchange information"}]],[[{"type":"text","text":"Feed-forward network (FFN)"}],[{"type":"text","text":"Processes each token independently; usually 4× wider; holds most parameters"}]],[[{"type":"text","text":"Residual connections"}],[{"type":"text","text":"Gradient highway; each sub-layer adds a refinement"}]],[[{"type":"text","text":"LayerNorm (Pre-LN)"}],[{"type":"text","text":"Stable training of deep stacks"}]],[[{"type":"text","text":"Output head"}],[{"type":"text","text":"Linear layer to vocabulary logits (often tied to the input embedding matrix)"}]]]},"revision":1},{"id":"5c4acd99-5d88-70f9-ad95-0af154cfdcbb","type":"heading","position":"aD","content":{"level":1,"content":[{"type":"text","text":"Why Transformers won"}]},"revision":1},{"id":"fc292116-0f7b-70b9-b681-065329c82f87","type":"text","position":"aE","content":{"doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Parallel","marks":[{"type":"bold"}]},{"type":"text","text":" training over all positions — unlike RNNs — so they use GPUs efficiently."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Direct long-range interactions","marks":[{"type":"bold"}]},{"type":"text","text":" between any two tokens."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Scale predictably","marks":[{"type":"bold"}]},{"type":"text","text":": loss keeps falling as data, parameters and compute grow (scaling laws)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"General","marks":[{"type":"bold"}]},{"type":"text","text":": the same block works on text tokens, image patches (ViT), audio frames and more."}]}]}]}]}},"revision":1},{"id":"2e558fb9-3cdd-797b-be52-4396d249491e","type":"callout","position":"aF","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Costs: attention is O(n²) in context length, and generation is sequential — one token at a time, with a KV cache storing past keys and values. Serving tricks (KV caching, quantisation, speculative decoding) are covered in the "},{"type":"text","text":"GenAI","marks":[{"type":"bold"}]},{"type":"text","text":" notes under LLM Optimization."}]}]}},"revision":1},{"id":"c22964a4-d2e0-7141-ae6b-2f44cb168d98","type":"question","position":"aG","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Walk through a Transformer layer."}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input vectors (token embeddings + positions) go through LayerNorm and multi-head self-attention, whose output is added back to the input (residual). Then another LayerNorm and a position-wise feed-forward network (two linear layers with GELU), again added residually. The shape is unchanged, so N such layers stack."}]}]}},"revision":1},{"id":"6e4f1f72-b2ec-7286-b398-d976a20ef51c","type":"question","position":"aH","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why do Transformers need positional encodings?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Self-attention treats the input as a set — it has no notion of order. Positional encodings (sinusoidal, learned, or rotary) inject each token''s position so “dog bites man” differs from “man bites dog”."}]}]}},"revision":1},{"id":"7fadb99b-9f7d-7d45-bdc1-3a5f40ab3cda","type":"question","position":"aI","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the purpose of multiple attention heads?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Each head attends in its own lower-dimensional subspace, so the layer can capture several kinds of relationships at once (syntax, coreference, position) for about the same cost as one full-width head."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
WHERE EXISTS (SELECT 1 FROM "notes"."Note" n WHERE n.id = '335a23b8-48a2-75d7-a4ac-9d7af345d872' AND n."ownerId" = '019a118c-f480-7000-8000-000000000001' AND n."publishedVersionId" IS NULL AND n.visibility = 'PRIVATE' AND n."deletedAt" IS NULL AND n."draftUpdatedAt" = TIMESTAMPTZ '2026-10-07 03:23:53+00')
