INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT 'f13c784c-c892-7545-bdc4-e869f680cb13', '0288f027-ddcb-7590-a739-b3a120ff7862', 1, 'PUBLISHED', 'Vanishing Gradients & Weight Init', '[{"id":"7cf46c32-5ac2-7988-858e-3321e3c3f18e","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"In a deep network the signal is multiplied by one weight matrix per layer — forwards and backwards. If each multiplication shrinks it a little, gradients vanish; if each grows it a little, they explode. Good initialisation keeps the scale steady."}]}]}},"revision":1},{"id":"f985d3fe-4bb7-71ea-9c5a-cd880ad7b423","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Why not start from zero?"}]},"revision":1},{"id":"cef7159c-3d06-78ea-925e-074bacc8ddda","type":"text","position":"a2","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"If every weight in a layer starts equal, every unit computes the same output and receives the same gradient — they stay identical forever ("},{"type":"text","text":"symmetry","marks":[{"type":"bold"}]},{"type":"text","text":"). Random initialisation breaks the tie; the question is how large the random values should be."}]}]}},"revision":1},{"id":"ec37dffe-9e4d-73d3-9b7d-976d7f842258","type":"code","position":"a3","content":{"language":"python","code":"import numpy as np\n\nX = np.array([[1.0, 2.0], [0.5, -1.0]])\nW1 = np.full((2, 3), 0.5)                     # all hidden weights equal\nH = np.tanh(X @ W1)\nprint(H.round(3).tolist())                    # [[0.905, 0.905, 0.905], [-0.245, -0.245, -0.245]] ← 3 hidden units, identical columns","filename":"Python"},"revision":1},{"id":"a11dae74-9dfc-7163-b2a3-e9f294666647","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Watching activations vanish"}]},"revision":1},{"id":"b333eea8-1172-79ad-a89a-10230686482b","type":"code","position":"a5","content":{"language":"python","code":"import numpy as np\n\ndef final_std(scale, act, layers=20, width=256):\n    rng = np.random.default_rng(0)\n    h = rng.normal(size=(512, width))\n    for _ in range(layers):\n        W = rng.normal(0, scale, size=(width, width))\n        h = act(h @ W)\n    return float(h.std())\n\nrelu = lambda z: np.maximum(0, z)\nprint(f\"{final_std(0.01, np.tanh):.1e}\")               # 1.1e-16 ← too small: signal dies\nprint(f\"{final_std(1.0, relu):.1e}\")                   # 1.2e+21 ← too large: explodes\nprint(f\"{final_std(np.sqrt(1 / 256), np.tanh):.2f}\")   # 0.15 ← Xavier with tanh: survives\nprint(f\"{final_std(np.sqrt(2 / 256), relu):.2f}\")      # 1.05 ← He with ReLU: stays ~1","filename":"Python"},"revision":1},{"id":"8c816e11-c108-7b3f-b4a8-cab400350687","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"Xavier and He"}]},"revision":1},{"id":"e758d14c-9ce6-7fc1-8de3-dcd6f2f4c057","type":"table","position":"a7","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Scheme"}],[{"type":"text","text":"Weight variance"}],[{"type":"text","text":"Use with"}],[{"type":"text","text":"PyTorch"}]],[[{"type":"text","text":"Xavier / Glorot"}],[{"type":"text","text":"2 / (fan_in + fan_out)","marks":[{"type":"code"}]},{"type":"text","text":" (≈ "},{"type":"text","text":"1 / fan_in","marks":[{"type":"code"}]},{"type":"text","text":")"}],[{"type":"text","text":"tanh, sigmoid, linear"}],[{"type":"text","text":"nn.init.xavier_uniform_","marks":[{"type":"code"}]}]],[[{"type":"text","text":"He / Kaiming"}],[{"type":"text","text":"2 / fan_in","marks":[{"type":"code"}]}],[{"type":"text","text":"ReLU and variants"}],[{"type":"text","text":"nn.init.kaiming_normal_(w, nonlinearity=''relu'')","marks":[{"type":"code"}]}]],[[{"type":"text","text":"PyTorch default for "},{"type":"text","text":"nn.Linear","marks":[{"type":"code"}]}],[{"type":"text","text":"Uniform(±1/√fan_in)"}],[{"type":"text","text":"Reasonable baseline"}],[{"type":"text","text":"applied automatically"}]]]},"revision":1},{"id":"3aeff941-20c7-7314-a51b-72247009ddf8","type":"text","position":"a8","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The idea: a sum of "},{"type":"text","text":"fan_in","marks":[{"type":"code"}]},{"type":"text","text":" random terms has variance "},{"type":"text","text":"fan_in × Var(w) × Var(x)","marks":[{"type":"code"}]},{"type":"text","text":". Setting "},{"type":"text","text":"Var(w) = 1/fan_in","marks":[{"type":"code"}]},{"type":"text","text":" keeps the output variance equal to the input''s. ReLU zeroes half its inputs, halving the variance — so He doubles it back with "},{"type":"text","text":"2/fan_in","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"43048885-08fd-7c49-8920-446df6103499","type":"code","position":"a9","content":{"language":"python","code":"import torch\nfrom torch import nn\n\ntorch.manual_seed(0)\nlayer = nn.Linear(512, 512)\nnn.init.kaiming_normal_(layer.weight, nonlinearity=\"relu\")\nnn.init.zeros_(layer.bias)\nprint(round(layer.weight.std().item(), 3), round((2 / 512) ** 0.5, 3))   # 0.063 0.062 ← measured vs target std","filename":"Python"},"revision":1},{"id":"91762927-ef8e-7040-8919-050f157c849b","type":"heading","position":"aA","content":{"level":1,"content":[{"type":"text","text":"Vanishing and exploding gradients"}]},"revision":1},{"id":"f04072c1-ca9f-7bbc-a690-56de8d2673db","type":"text","position":"aB","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"By the chain rule, the gradient at layer 1 is a "},{"type":"text","text":"product","marks":[{"type":"bold"}]},{"type":"text","text":" of one factor per layer above it. Factors below 1 (saturated sigmoids: slope ≤ 0.25) shrink it exponentially — early layers stop learning. Factors above 1 (large weights, long RNN unrolls) blow it up — the loss becomes "},{"type":"text","text":"nan","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"8a1e0e27-a273-7034-9f48-d202d6f2812a","type":"code","position":"aC","content":{"language":"python","code":"import torch\nfrom torch import nn\n\ndef first_layer_grad(act, he=False, depth=15):\n    torch.manual_seed(0)\n    layers = []\n    for _ in range(depth):\n        lin = nn.Linear(32, 32)\n        if he:\n            nn.init.kaiming_normal_(lin.weight, nonlinearity=\"relu\")\n        layers += [lin, act()]\n    net = nn.Sequential(*layers, nn.Linear(32, 1))\n    net(torch.randn(64, 32)).pow(2).mean().backward()\n    return net[0].weight.grad.abs().mean().item()\n\nprint(f\"{first_layer_grad(nn.Sigmoid):.0e}\")        # 3e-15 ← sigmoid: vanished\nprint(f\"{first_layer_grad(nn.ReLU):.0e}\")           # 2e-10 ← ReLU, default init: still shrinks\nprint(f\"{first_layer_grad(nn.ReLU, he=True):.0e}\")  # 1e-03 ← ReLU + He init: healthy","filename":"Python"},"revision":1},{"id":"a5d1c78c-9e6b-7c17-80af-54a89aed812a","type":"table","position":"aD","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Fix"}],[{"type":"text","text":"Helps with"}]],[[{"type":"text","text":"ReLU-family activations"}],[{"type":"text","text":"Vanishing (slope 1 for positive inputs)"}]],[[{"type":"text","text":"Xavier / He initialisation"}],[{"type":"text","text":"Both — keeps the scale steady at the start"}]],[[{"type":"text","text":"BatchNorm / LayerNorm"}],[{"type":"text","text":"Both — re-normalises activations every layer"}]],[[{"type":"text","text":"Residual (skip) connections"}],[{"type":"text","text":"Vanishing — gradient flows through the identity path (ResNets, Transformers)"}]],[[{"type":"text","text":"Gradient clipping"}],[{"type":"text","text":"Exploding — caps the gradient norm"}]],[[{"type":"text","text":"LSTM / GRU gates"}],[{"type":"text","text":"Vanishing through time in RNNs"}]]]},"revision":1},{"id":"de968306-6083-7f2a-90dd-8564bbed04dd","type":"heading","position":"aE","content":{"level":1,"content":[{"type":"text","text":"Gradient clipping"}]},"revision":1},{"id":"913e1a8e-e159-7cc7-9a9f-f9ab3260bb7b","type":"code","position":"aF","content":{"language":"python","code":"import torch\nfrom torch import nn\n\nmodel = nn.Linear(4, 1)\nfor p in model.parameters():\n    p.grad = torch.full_like(p, 10.0)             # pretend a huge gradient arrived\n\nbefore = nn.utils.clip_grad_norm_(model.parameters(), max_norm=1.0)   # returns the norm before clipping\nafter = torch.cat([p.grad.flatten() for p in model.parameters()]).norm()\nprint(round(before.item(), 2), round(after.item(), 2))   # 22.36 1.0","filename":"Python"},"revision":1},{"id":"2d11fd08-7b44-7274-bfa8-389d77d9931f","type":"callout","position":"aG","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Clipping rescales the whole gradient vector when its norm exceeds "},{"type":"text","text":"max_norm","marks":[{"type":"code"}]},{"type":"text","text":" — the direction is kept, only the step length is capped. Call it between "},{"type":"text","text":"loss.backward()","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"optimizer.step()","marks":[{"type":"code"}]},{"type":"text","text":". It''s standard for RNNs and Transformers ("},{"type":"text","text":"max_norm=1.0","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]}},"revision":1},{"id":"0e769bba-991a-7a93-b056-661df4a88ba3","type":"question","position":"aH","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the vanishing gradient problem and how do you fix it?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Gradients shrink exponentially as they flow backwards through many layers (or time steps) because they''re multiplied by factors smaller than 1, so early layers barely learn. Fixes: ReLU-type activations, He/Xavier init, normalisation layers, residual connections, and gated RNNs (LSTM/GRU)."}]}]}},"revision":1},{"id":"f9096f14-3de0-7fe2-a272-18fa13b04577","type":"question","position":"aI","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why can''t all weights be initialised to zero?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Every unit in a layer would compute the same function and get the same update, so the layer behaves like a single unit forever. (Biases can start at zero — the random weights already break the symmetry.)"}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
