SELECT '1313cedb-4344-7af4-9b99-c11c64e8aba3', '72348b43-d6cd-7d9e-bf2e-c4bb79432e5f', 1, 'PUBLISHED', 'Characters, ASCII & DIY String Functions', '[{"id":"01a3d191-648e-7569-8cd5-28a858fca174","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Every character is a number. Knowing the codes lets you build string functions yourself — a common interview exercise and the basis of text encoding."}]}]}},"revision":1},{"id":"30505eb7-90aa-71bc-923e-38df8a9ec562","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"ord() and chr()"}]},"revision":1},{"id":"4db5fdab-cfa9-70a5-a1e1-4040009eda0e","type":"code","position":"a2","content":{"language":"python","code":"text = \"The quick brown fox\"\nprint([ord(c) for c in \"Tq \"])                    # [84, 113, 32]\nprint(chr(97), chr(65), chr(93))                  # a A ]\ncodes = [ord(c) for c in text]\nprint(\"\".join(chr(n) for n in codes) == text)     # True\nprint(\"\".join(chr(n) for n in range(65, 91)))     # ABCDEFGHIJKLMNOPQRSTUVWXYZ\nprint(\"\".join(chr(n) for n in range(90, 64, -1))) # ZYXWVUTSRQPONMLKJIHGFEDCBA","filename":"Python"},"revision":1},{"id":"2ca35e39-0ac0-7232-b82e-af1e50771c8a","type":"table","position":"a3","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Range"}],[{"type":"text","text":"Characters"}]],[[{"type":"text","text":"48–57"}],[{"type":"text","text":"0","marks":[{"type":"code"}]},{"type":"text","text":"–"},{"type":"text","text":"9","marks":[{"type":"code"}]}]],[[{"type":"text","text":"65–90"}],[{"type":"text","text":"A","marks":[{"type":"code"}]},{"type":"text","text":"–"},{"type":"text","text":"Z","marks":[{"type":"code"}]}]],[[{"type":"text","text":"97–122"}],[{"type":"text","text":"a","marks":[{"type":"code"}]},{"type":"text","text":"–"},{"type":"text","text":"z","marks":[{"type":"code"}]},{"type":"text","text":" (each lowercase letter = its uppercase + 32)"}]],[[{"type":"text","text":"32"}],[{"type":"text","text":"space"}]]]},"revision":1},{"id":"648863c1-3a33-78e2-9278-078783dce63b","type":"callout","position":"a4","content":{"variant":"note","title":"Correction","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The notebook prints "},{"type":"text","text":"ascii","marks":[{"type":"code"}]},{"type":"text","text":" instead of its list "},{"type":"text","text":"ascii_","marks":[{"type":"code"}]},{"type":"text","text":" and gets "},{"type":"text","text":"<built-in function ascii>","marks":[{"type":"code"}]},{"type":"text","text":" — "},{"type":"text","text":"ascii","marks":[{"type":"code"}]},{"type":"text","text":" is a built-in function. Avoid names that shadow built-ins ("},{"type":"text","text":"list","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"str","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"sum","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"ascii","marks":[{"type":"code"}]},{"type":"text","text":"…)."}]}]}},"revision":1},{"id":"a1a40378-6952-7576-aecb-e642c3feae17","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"DIY upper, lower and title"}]},"revision":1},{"id":"300e23d0-dbb7-7694-a146-3499aa66f384","type":"code","position":"a6","content":{"language":"python","code":"def upper(text):\n    return \"\".join(chr(ord(c) - 32) if \"a\" <= c <= \"z\" else c for c in text)\n\ndef lower(text):\n    return \"\".join(chr(ord(c) + 32) if \"A\" <= c <= \"Z\" else c for c in text)\n\ndef title(text):\n    return \" \".join(upper(w[:1]) + lower(w[1:]) for w in text.split(\" \"))\n\nprint(upper(\"delhi\"), lower(\"CARTOON\"))               # DELHI cartoon\nprint(title(\"let us study machine learning today\"))   # Let Us Study Machine Learning Today\nprint(title(\"hello  world\"))                          # Hello  World","filename":"Python"},"revision":1},{"id":"ba5bc543-ba96-7dc4-b6a5-4dd8d8c26aa1","type":"callout","position":"a7","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"w[:1]","marks":[{"type":"code"}]},{"type":"text","text":" instead of "},{"type":"text","text":"w[0]","marks":[{"type":"code"}]},{"type":"text","text":" keeps "},{"type":"text","text":"title","marks":[{"type":"code"}]},{"type":"text","text":" from crashing on empty words (two spaces in a row)."}]}]}},"revision":1},{"id":"48648a15-652a-72ce-8ea7-8476478a934d","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"DIY isalpha and isdigit"}]},"revision":1},{"id":"ace36a13-b7db-7163-bcee-cef54f1a916b","type":"code","position":"a9","content":{"language":"python","code":"def is_alpha(text):\n    return len(text) > 0 and all(\"A\" <= c <= \"Z\" or \"a\" <= c <= \"z\" for c in text)\n\ndef is_digit(text):\n    return len(text) > 0 and all(\"0\" <= c <= \"9\" for c in text)\n\nprint(is_alpha(\"datascience\"), is_alpha(\"1234\"))     # True False\nprint(is_digit(\"1234\"), is_digit(\"machinelearning\")) # True False","filename":"Python"},"revision":1},{"id":"14545f2c-9c70-749b-9c92-fd0e26f1ff66","type":"callout","position":"aA","content":{"variant":"warning","title":"Bug in the notebook","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The notebook''s "},{"type":"text","text":"check_alpha","marks":[{"type":"code"}]},{"type":"text","text":" returns "},{"type":"text","text":"False","marks":[{"type":"code"}]},{"type":"text","text":" for "},{"type":"text","text":"''datascience''","marks":[{"type":"code"}]},{"type":"text","text":" — its "},{"type":"text","text":"if len(text) == c","marks":[{"type":"code"}]},{"type":"text","text":" check sits "},{"type":"text","text":"inside","marks":[{"type":"bold"}]},{"type":"text","text":" the loop, so it decides after the first character. Check after the loop (or use "},{"type":"text","text":"all()","marks":[{"type":"code"}]},{"type":"text","text":" as above)."}]}]}},"revision":1},{"id":"100ae1d3-7a4b-7d1d-9240-0b7bad670445","type":"heading","position":"aB","content":{"level":1,"content":[{"type":"text","text":"Finding runs of digits and words"}]},"revision":1},{"id":"487ccd9c-0ca9-7a3c-a71c-2a813064a1b9","type":"code","position":"aC","content":{"language":"python","code":"txt = \"The number is 8372493 not 423423\"\nruns, current = [], \"\"\nfor ch in txt:\n    if ch.isdigit():\n        current += ch\n    elif current:\n        runs.append(current)\n        current = \"\"\nif current:\n    runs.append(current)\nprint(runs)                                     # [''8372493'', ''423423'']\n\nsentence = \"GFG is launching a new Data Structure in Python Course\"\nprint([w for w in sentence.split() if w.lower().startswith(\"i\")])   # [''is'', ''in'']\nprint([w for w in sentence.split() if w.lower().endswith(\"e\")])     # [''Structure'', ''Course'']\nprint(\"let us study data science\".find(\"data\"))                     # 13","filename":"Python"},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
