SELECT 'fdbf3e89-4cfa-7100-8389-18eeabf1fbc2', '54938c72-aa97-7c94-8053-09bd961188cc', 1, 'PUBLISHED', 'SVM, Decision Trees & Random Forests', '[{"id":"7c17a8a1-3717-760c-8703-85d18119f562","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Three classic classifiers on the Iris dataset (150 flowers, 4 measurements, 3 species) — how they decide, and what each is good at."}]}]}},"revision":1},{"id":"c3068c34-0e13-74cb-8b6e-b7928e224b8d","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Support Vector Machine (SVM)"}]},"revision":1},{"id":"a9ad6c0c-4200-7218-b217-c229c7287306","type":"callout","position":"a2","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"SVM","marks":[{"type":"bold"}]},{"type":"text","text":" — finds the boundary that separates the classes with the "},{"type":"text","text":"widest margin","marks":[{"type":"bold"}]},{"type":"text","text":". With a kernel such as "},{"type":"text","text":"rbf","marks":[{"type":"code"}]},{"type":"text","text":", the boundary can curve."}]}]}},"revision":1},{"id":"fafbcb7f-260c-79bb-aafd-7ba3dc8411a2","type":"code","position":"a3","content":{"language":"python","code":"from sklearn import datasets\nfrom sklearn.model_selection import train_test_split\nfrom sklearn.svm import SVC\nfrom sklearn.metrics import accuracy_score\n\niris = datasets.load_iris()\nX = iris.data[:, :2]              # only 2 features (sepal length & width) so it can be plotted in 2-D\ny = iris.target\nX_train, X_test, y_train, y_test = train_test_split(X, y, test_size=0.3, random_state=0)\n\nmodel = SVC(kernel=\"rbf\", C=1.0, gamma=\"auto\").fit(X_train, y_train)\nprint(f\"Accuracy: {accuracy_score(y_test, model.predict(X_test)):.2f}\")   # Accuracy: 0.80","filename":"Python"},"revision":1},{"id":"b838cc28-8ff6-74a1-930b-f05981060120","type":"table","position":"a4","content":