SELECT '9b1753c5-edf1-74a0-9b84-524ae3339926', '5b2bc252-4e93-75b0-a2f9-dff3da9bd5cc', 1, 'PUBLISHED', 'Reading & Writing Files', '[{"id":"4c4869e9-4a71-7878-9a2d-3d6b39c75930","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Most data science starts with a file. Python''s built-in "},{"type":"text","text":"open()","marks":[{"type":"code"}]},{"type":"text","text":" reads and writes text files — and a few string methods already give you basic text statistics."}]}]}},"revision":1},{"id":"15eab9d9-a393-7a10-a45b-1f6114a27355","type":"callout","position":"a1","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"File object","marks":[{"type":"bold"}]},{"type":"text","text":" — what "},{"type":"text","text":"open(path, mode)","marks":[{"type":"code"}]},{"type":"text","text":" returns: a handle with "},{"type":"text","text":"read","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"readline","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"readlines","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"write","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"seek","marks":[{"type":"code"}]},{"type":"text","text":". Always close it — or better, use "},{"type":"text","text":"with","marks":[{"type":"code"}]},{"type":"text","text":", which closes it for you."}]}]}},"revision":1},{"id":"28910bf3-701e-7367-b6e1-90cf66e73b02","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"Modes"}]},"revision":1},{"id":"2dcf23ea-3841-7b28-b533-c94672626312","type":"table","position":"a3","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Mode"}],[{"type":"text","text":"Meaning"}],[{"type":"text","text":"If the file exists"}],[{"type":"text","text":"If it doesn''t"}]],[[{"type":"text","text":"''r''","marks":[{"type":"code"}]}],[{"type":"text","text":"Read (default)"}],[{"type":"text","text":"Reads from the start"}],[{"type":"text","text":"FileNotFoundError","marks":[{"type":"code"}]}]],[[{"type":"text","text":"''w''","marks":[{"type":"code"}]}],[{"type":"text","text":"Write"}],[{"type":"text","text":"Erases","marks":[{"type":"bold"}]},{"type":"text","text":" it first"}],[{"type":"text","text":"Creates it"}]],[[{"type":"text","text":"''a''","marks":[{"type":"code"}]}],[{"type":"text","text":"Append"}],[{"type":"text","text":"Writes at the end"}],[{"type":"text","text":"Creates it"}]],[[{"type":"text","text":"''r+''","marks":[{"type":"code"}]}],[{"type":"text","text":"Read and write"}],[{"type":"text","text":"Starts at the beginning"}],[{"type":"text","text":"FileNotFoundError","marks":[{"type":"code"}]}]],[[{"type":"text","text":"''x''","marks":[{"type":"code"}]}],[{"type":"text","text":"Create only"}],[{"type":"text","text":"FileExistsError","marks":[{"type":"code"}]}],[{"type":"text","text":"Creates it"}]]]},"revision":1},{"id":"fbef3a13-e985-7953-b5c0-b33c91b9a68f","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Writing: write vs writelines"}]},"revision":1},{"id":"d9f82f84-951e-7b76-ae9b-a88a6f103705","type":"code","position":"a5","content":{"language":"python","code":"lines = [\"This is Delhi \\n\", \"This is Paris \\n\", \"This is London \\n\"]\nwith open(\"myfile.txt\", \"w\", encoding=\"utf-8\") as f:\n    f.write(\"Hello \\n\")          # one string\n    f.writelines(lines)          # an iterable of strings (no newlines are added for you)\n\nwith open(\"myfile.txt\", encoding=\"utf-8\") as f:\n    print(f.read())","filename":"Python"},"revision":1},{"id":"1298d640-c4f0-7a3c-916a-6c837e2d8200","type":"code","position":"a6","content":{"language":"","code":"Hello\nThis is Delhi\nThis is Paris\nThis is London","filename":"Output"},"revision":1},{"id":"8f7fdab0-8f3b-70b3-aaaa-e920d014f0d8","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Reading: read, readline, readlines, seek"}]},"revision":1},{"id":"fbaab2e5-d6b2-72cf-a914-09424c19d8a7","type":"code","position":"a8","content":{"language":"python","code":"with open(\"myfile.txt\", encoding=\"utf-8\") as f:\n    print(repr(f.read(9)))       # ''Hello \\nTh''   ← 9 characters, across lines\n    f.seek(0)                    # jump back to the start\n    print(repr(f.readline()))    # ''Hello \\n''     ← up to and including the newline\n    f.seek(0)\n    print(f.readlines())         # [''Hello \\n'', ''This is Delhi \\n'', ''This is Paris \\n'', ''This is London \\n'']","filename":"Python"},"revision":1},{"id":"ebc5105c-fd61-7d96-9ae9-c73432502ced","type":"table","position":"a9","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Method"}],[{"type":"text","text":"Returns"}]],[[{"type":"text","text":"f.read()","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"f.read(n)","marks":[{"type":"code"}]}],[{"type":"text","text":"The whole file / the next "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" characters, as one string"}]],[[{"type":"text","text":"f.readline()","marks":[{"type":"code"}]}],[{"type":"text","text":"The next line, including its "},{"type":"text","text":"\\n","marks":[{"type":"code"}]}]],[[{"type":"text","text":"f.readlines()","marks":[{"type":"code"}]}],[{"type":"text","text":"A list of all remaining lines"}]],[[{"type":"text","text":"for line in f:","marks":[{"type":"code"}]}],[{"type":"text","text":"Lines one at a time — memory-friendly for big files"}]],[[{"type":"text","text":"f.seek(n)","marks":[{"type":"code"}]}],[{"type":"text","text":"Moves the position to byte "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" (0 = start)"}]]]},"revision":1},{"id":"f9c9f2f9-977c-7355-b51e-848cee174ee0","type":"heading","position":"aA","content":{"level":1,"content":[{"type":"text","text":"Append vs write"}]},"revision":1},{"id":"6e992108-c6b8-7233-9eca-b100b8a3a5a8","type":"code","position":"aB","content":{"language":"python","code":"with open(\"notes.txt\", \"w\") as f:\n    f.write(\"Today \\n\")\nwith open(\"notes.txt\", \"a\") as f:        # append keeps what was there\n    f.write(\"Tomorrow \\n\")\nwith open(\"notes.txt\") as f:\n    print(f.readlines())                  # [''Today \\n'', ''Tomorrow \\n'']\n\nwith open(\"notes.txt\", \"w\") as f:        # write erases it first\n    f.write(\"Only this \\n\")\nwith open(\"notes.txt\") as f:\n    print(f.readlines())                  # [''Only this \\n'']","filename":"Python"},"revision":1},{"id":"bd4b5d88-2f82-74b3-a2cd-ccbc31a3e94a","type":"callout","position":"aC","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Opening with "},{"type":"text","text":"''w''","marks":[{"type":"code"}]},{"type":"text","text":" silently wipes the file. Use "},{"type":"text","text":"''a''","marks":[{"type":"code"}]},{"type":"text","text":" to add to it, or "},{"type":"text","text":"''x''","marks":[{"type":"code"}]},{"type":"text","text":" to refuse overwriting."}]}]}},"revision":1},{"id":"0575664b-0185-7cd0-b4c2-280bdf3666e5","type":"heading","position":"aD","content":{"level":1,"content":[{"type":"text","text":"Quick text statistics"}]},"revision":1},{"id":"a13aa436-c35b-78a9-8737-129310a0f7b4","type":"code","position":"aE","content":{"language":"python","code":"text = \"\"\"Data science turns raw data into insight. It mixes statistics and programming.\n\nPython is the most popular language for it.\"\"\"\n\nparagraphs = [p for p in text.split(\"\\n\\n\") if p.strip()]\nsentences = [s for s in text.replace(\"\\n\", \" \").split(\".\") if s.strip()]\nwords = text.split()                     # split() with no argument handles any whitespace\n\nprint(len(paragraphs), len(sentences), len(words))   # 2 3 20","filename":"Python"},"revision":1},{"id":"cf446157-3450-7c5d-a56a-d62bf9e044be","type":"callout","position":"aF","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"split(\" \")","marks":[{"type":"code"}]},{"type":"text","text":" counts empty strings between double spaces and keeps newlines inside words — "},{"type":"text","text":"split()","marks":[{"type":"code"}]},{"type":"text","text":" with no argument is almost always what you want for words."}]}]}},"revision":1},{"id":"00190393-4cf3-7715-8eb8-1815c5ae4f0e","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Cleaning unwanted characters"}]},"revision":1},{"id":"9782fa56-8721-7a66-9ba5-58e5bd53438e","type":"code","position":"aH","content":{"language":"python","code":"raw = \"Hello!! World@ #2026 [7] [12]\"\nfor ref in [f\"[{i}]\" for i in range(1, 20)]:     # remove citation markers like [7]\n    raw = raw.replace(ref, \"\")\nfor ch in \"!@#\":                                 # remove unwanted symbols\n    raw = raw.replace(ch, \"\")\nprint(\" \".join(raw.split()))                     # Hello World 2026","filename":"Python"},"revision":1},{"id":"491dd9d1-1a4d-7e8d-ae26-ccf627189538","type":"callout","position":"aI","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"For anything more than a few characters, a regular expression is cleaner: "},{"type":"text","text":"re.sub(r\"\\[\\d+\\]|[!@#]\", \"\", raw)","marks":[{"type":"code"}]},{"type":"text","text":" — see "},{"type":"text","text":"Regular Expressions","marks":[{"type":"italic"}]},{"type":"text","text":"."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
