SELECT '41071e3e-6104-7db9-ab3f-1f9f9a00ebdb', '30fb3e65-b938-73e7-915e-8f095168acc8', 1, 'PUBLISHED', 'The scikit-learn Workflow', '[{"id":"d86e306e-cf46-7f98-babf-4041c482875b","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Every scikit-learn model follows the same few steps — so once you know one, you know them all."}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Load data","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Features "},{"type":"text","text":"X","marks":[{"type":"code"}]},{"type":"text","text":" (a 2-D table: rows = samples, columns = features) and target "},{"type":"text","text":"y","marks":[{"type":"code"}]},{"type":"text","text":" (what to predict)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Split","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"train_test_split","marks":[{"type":"code"}]},{"type":"text","text":" holds back unseen data to measure honestly."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Create & fit","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"model = SomeModel(...)","marks":[{"type":"code"}]},{"type":"text","text":" then "},{"type":"text","text":"model.fit(X_train, y_train)","marks":[{"type":"code"}]},{"type":"text","text":" learns from the training set."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Predict","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"model.predict(X_test)","marks":[{"type":"code"}]},{"type":"text","text":" on data it has never seen."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Evaluate","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Compare predictions with the truth: "},{"type":"text","text":"accuracy_score","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"classification_report","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"mean_squared_error","marks":[{"type":"code"}]},{"type":"text","text":"…"}]}]}]}]}},"revision":1},{"id":"fb17a0e8-acbf-7632-9129-b4c458f42044","type":"code","position":"a1","content":{"language":"python","code":"from sklearn.datasets import load_iris\nfrom sklearn.model_selection import train_test_split\nfrom sklearn.neighbors import KNeighborsClassifier\nfrom sklearn.metrics import accuracy_score\n\nX, y = load_iris(return_X_y=True)                        # 150 flowers, 4 measurements, 3 species\nX_train, X_test, y_train, y_test = train_test_split(X, y, test_size=0.3, random_state=0)\nprint(X.shape, X_train.shape, X_test.shape)              # (150, 4) (105, 4) (45, 4)\n\nmodel = KNeighborsClassifier(n_neighbors=5)\nmodel.fit(X_train, y_train)\ny_pred = model.predict(X_test)\nprint(round(accuracy_score(y_test, y_pred), 2))          # 0.98","filename":"Python"},"revision":1},{"id":"e6b19d15-a503-708f-9a0a-dc18d446e4c2","type":"callout","position":"a2","content":{"variant":"note","title":"Supervised","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Learns from labelled examples: "},{"type":"text","text":"classification","marks":[{"type":"bold"}]},{"type":"text","text":" (a category — spam / not spam) or "},{"type":"text","text":"regression","marks":[{"type":"bold"}]},{"type":"text","text":" (a number — price)."}]}]}},"revision":1},{"id":"463a10bc-c596-7784-b21e-0b8364247b4f","type":"callout","position":"a3","content":{"variant":"note","title":"Unsupervised","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Finds structure in unlabelled data: "},{"type":"text","text":"clustering","marks":[{"type":"bold"}]},{"type":"text","text":" (K-Means), dimensionality reduction (PCA)."}]}]}},"revision":1},{"id":"91778376-782c-72a6-aae2-a0610f2c156a","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Why split the data?"}]},"revision":1},{"id":"1cf98857-545d-7763-945f-2d7ba00d0aaa","type":"text","position":"a5","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A model scored on the data it trained on can simply memorise it. Testing on held-out data shows how it will do on new, real inputs. "},{"type":"text","text":"random_state","marks":[{"type":"code"}]},{"type":"text","text":" fixes the shuffle so results are reproducible."}]}]}},"revision":1},{"id":"26926e2c-a2d6-7fc7-a8d5-fcc65e9b68a8","type":"callout","position":"a6","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Overfitting","marks":[{"type":"bold"}]},{"type":"text","text":" = great on training data, poor on test data (the model memorised noise). "},{"type":"text","text":"Underfitting","marks":[{"type":"bold"}]},{"type":"text","text":" = poor on both (the model is too simple). Compare train vs test scores to tell them apart."}]}]}},"revision":1},{"id":"c37dceda-2dd8-78ed-9127-326c298beb30","type":"table","position":"a7","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Metric"}],[{"type":"text","text":"For"}],[{"type":"text","text":"Meaning"}]],[[{"type":"text","text":"Accuracy"}],[{"type":"text","text":"Classification"}],[{"type":"text","text":"Share of correct predictions — misleading when classes are imbalanced"}]],[[{"type":"text","text":"Precision"}],[{"type":"text","text":"Classification"}],[{"type":"text","text":"Of those predicted positive, how many really are"}]],[[{"type":"text","text":"Recall"}],[{"type":"text","text":"Classification"}],[{"type":"text","text":"Of the real positives, how many were found"}]],[[{"type":"text","text":"F1-score"}],[{"type":"text","text":"Classification"}],[{"type":"text","text":"Balance of precision and recall"}]],[[{"type":"text","text":"MSE / RMSE, R²"}],[{"type":"text","text":"Regression"}],[{"type":"text","text":"Average squared error / share of variance explained"}]]]},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
