  ('1407aae5-05ee-7dab-995f-f4a3d10504bb', 'a1', 'code', '{"language":"python","code":"from sklearn.feature_extraction.text import CountVectorizer\nfrom sklearn.naive_bayes import MultinomialNB\n\ntexts = [\"the team won the cricket match\", \"stocks fell as markets closed lower\",\n         \"a great goal in the final\", \"the bank raised interest rates\",\n         \"fans cheered the winning shot\", \"investors sold shares today\"]\nlabels = [\"sports\", \"finance\", \"sports\", \"finance\", \"sports\", \"finance\"]\n\nvectorizer = CountVectorizer()\nX = vectorizer.fit_transform(texts)          # sparse matrix: 6 documents × vocabulary\nprint(X.shape)                               # (6, 27)\n\nmodel = MultinomialNB().fit(X, labels)\nnew = vectorizer.transform([\"the match was a great win\", \"interest rates and shares\"])\nprint(model.predict(new).tolist())           # [''sports'', ''finance'']","filename":"Python"}'),
  ('e9494476-3ff6-7297-8c8d-65aced9f4560', 'a2', 'callout', '{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Call "},{"type":"text","text":"fit_transform","marks":[{"type":"code"}]},{"type":"text","text":" on training text only, then "},{"type":"text","text":"transform","marks":[{"type":"code"}]},{"type":"text","text":" on new text — otherwise the vocabulary (and the columns) change between training and prediction."}]}]}}'),
