SELECT '31508f66-e572-7179-b30c-a1b836f01f06', 'c01ffcbb-c985-7186-9937-df8d172ca99a', 1, 'PUBLISHED', 'Array Operations', '[{"id":"40859642-792b-7523-b3d4-d4f025e68e8a","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Arithmetic, aggregation, sorting, joining, splitting and filtering — all without writing a loop."}]}]}},"revision":1},{"id":"0ed9a59b-da2e-71c2-b6d1-5f1f02c5aa0d","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Element-wise arithmetic"}]},"revision":1},{"id":"60efceb3-5a18-78be-9059-94b0379d8828","type":"code","position":"a2","content":{"language":"python","code":"import numpy as np\na = np.array([1, 2, 3, 4])\nb = np.array([5, 6, 7, 8])\nprint(a + 2, a * 2, a / 2)        # [3 4 5 6] [2 4 6 8] [0.5 1.  1.5 2. ]\nprint(a + b, b - a)               # [ 6  8 10 12] [4 4 4 4]\nprint(np.add(1, b), np.multiply(a, b))   # [6 7 8 9] [ 5 12 21 32]","filename":"Python"},"revision":1},{"id":"ba813318-1582-74b2-85af-176002c72c2b","type":"callout","position":"a3","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Combining an array with a single number (or arrays of compatible shapes) is called "},{"type":"text","text":"broadcasting","marks":[{"type":"bold"}]},{"type":"text","text":" — the number is applied to every element."}]}]}},"revision":1},{"id":"84dea190-342b-78ba-8e42-c6ecb7a8fa72","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Aggregations and axes"}]},"revision":1},{"id":"12ece21d-4d48-764b-810b-4ad1ab6b3747","type":"code","position":"a5","content":{"language":"python","code":"import numpy as np\nm = np.array([[1, 4, 2],\n              [3, 4, 6]])\nprint(m.max(), m.min(), m.sum())      # 6 1 20\nprint(m.max(axis=0))                  # [3 4 6]   ← down each column\nprint(m.max(axis=1))                  # [4 6]     ← across each row\nprint(m.mean(axis=1))                 # [2.33333333 4.33333333]","filename":"Python"},"revision":1},{"id":"d8f26e12-e45e-7f58-9355-fec4efd66440","type":"callout","position":"a6","content":{"variant":"note","title":"axis=0","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Collapse the rows — one result "},{"type":"text","text":"per column","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"020ca4b8-151c-7354-99dc-a2ddad53312b","type":"callout","position":"a7","content":{"variant":"note","title":"axis=1","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Collapse the columns — one result "},{"type":"text","text":"per row","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"107f169a-3158-7cbd-89e5-9e43b6bf1a82","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"Sorting"}]},"revision":1},{"id":"b901747b-8efa-7946-8f7f-db342d998121","type":"code","position":"a9","content":{"language":"python","code":"import numpy as np\narr = np.array([[1, 4, 2], [3, 4, 6], [0, -1, 5]])\nprint(np.sort(arr))                   # sorts each row (axis=-1 by default)\nprint(np.sort(arr, axis=0))           # sorts each column","filename":"Python"},"revision":1},{"id":"7335d4c3-e929-7d48-b02e-258c85f1601b","type":"code","position":"aA","content":{"language":"","code":"[[ 1  2  4]\n [ 3  4  6]\n [-1  0  5]]\n[[ 0 -1  2]\n [ 1  4  5]\n [ 3  4  6]]","filename":"Output"},"revision":1},{"id":"a1e09419-e0ac-78d1-947e-2633923c8cbd","type":"callout","position":"aB","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"kind=\"quicksort\" | \"mergesort\" | \"stable\"","marks":[{"type":"code"}]},{"type":"text","text":" picks the algorithm; the result is the same, only speed and stability (order of equal elements) differ."}]}]}},"revision":1},{"id":"8cb7a