SELECT '6cc09752-a630-7a1e-814f-5ef1285e2091', 'ee8c8767-08f8-7756-aafe-5ed19d9fec4a', 1, 'PUBLISHED', 'requests & BeautifulSoup', '[{"id":"1c5ad68f-945c-7afb-9b54-ca950b332a9a","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Web scraping = download a page''s HTML ("},{"type":"text","text":"requests","marks":[{"type":"code"}]},{"type":"text","text":"), then pick out the data you need ("},{"type":"text","text":"BeautifulSoup","marks":[{"type":"code"}]},{"type":"text","text":"). It''s how you build datasets that don''t come as a CSV."}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Request","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"requests.get(url, headers=…)","marks":[{"type":"code"}]},{"type":"text","text":" downloads the page."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Parse","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"BeautifulSoup(html, \"html.parser\")","marks":[{"type":"code"}]},{"type":"text","text":" turns HTML text into a searchable tree."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Extract","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"find","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"find_all","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"select","marks":[{"type":"code"}]},{"type":"text","text":" locate elements; "},{"type":"text","text":".text","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":".get(\"href\")","marks":[{"type":"code"}]},{"type":"text","text":" read them."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Store","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Collect rows in a list, then save with pandas ("},{"type":"text","text":"to_csv","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]}]}]}},"revision":1},{"id":"9474afa9-cc48-7e4a-8c16-90bd90e225e3","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"1. Download the page"}]},"revision":1},{"id":"96424c42-6a18-76a8-8cbb-03db8f803822","type":"code","position":"a2","content":{"language":"python","code":"import requests\n\nheaders = {\"User-Agent\": \"Mozilla/5.0 (compatible; LearnViaNotesBot/1.0)\"}\nr = requests.get(\"https://quotes.toscrape.com/page/1/\", headers=headers, timeout=10)\nprint(r.status_code)          # 200 means OK; 404 not found, 403 forbidden, 429 too many requests\nhtml = r.text                 # decoded text (r.content is the raw bytes)","filename":"Python"},"revision":1},{"id":"d86d3ae9-c646-7487-8be5-624b366e45bc","type":"callout","position":"a3","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Some sites reject requests without a browser-like "},{"type":"text","text":"User-Agent","marks":[{"type":"code"}]},{"type":"text","text":" header — that''s why the notebook sets one. Always pass a "},{"type":"text","text":"timeout","marks":[{"type":"code"}]},{"type":"text","text":" so a slow site can''t hang your script."}]}]}},"revision":1},{"id":"c0458e94-f401-78bd-8a4f-deaec96b6fe1","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"2. Parse and extract"}]},"revision":1},{"id":"f0f00f7b-672a-7890-92ba-80e87482efe7","type":"code","position":"a5","content":{"language":"python","code":"html = \"\"\"\n<div class=\"quote\">\n  <span class=\"text\">“The world as we have created it is a process of our thinking.”</span>\n  <small class=\"author\">Albert Einstein</small> <a href=\"/author/Albert-Einstein\">(about)</a>\n  <a class=\"tag\" href=\"/tag/change/\">change</a> <a class=\"tag\" href=\"/tag/thinking/\">thinking</a>\n</div>\n<div class=\"quote\">\n  <span class=\"text\">“It is our choices that show what we truly are.”</span>\n  <small class=\"author\">J.K. Rowling</small> <a href=\"/author/J-K-Rowling\">(about)</a>\n  <a class=\"tag\" href=\"/tag/choices/\">choices</a>\n</div>\n\"\"\"\n\nfrom bs4 import BeautifulSoup\nsoup = BeautifulSoup(html, \"html.parser\")\n\nfirst = soup.find(\"div\", class_=\"quote\")                      # first match (or None)\nprint(first.find(\"small\", class_=\"author\").text)              # Albert Einstein\n\nfor q in soup.find_all(\"div\", class_=\"quote\"):                # every match\n    text = q.find(\"span\", class_=\"text\").text.strip(\"“”\")\n    tags = [t.text for t in q.find_all(\"a\", class_=\"tag\")]\n    print(text[:22], \"|\", \", \".join(tags))","filename":"Python"},"revision":1},{"id":"aff8cf44-785b-70cd-b992-220c71d696f6","type":"code","position":"a6","content":{"language":"","code":"Albert Einstein\nThe world as we have c | change, thinking\nIt is our choices that | choices","filename":"Output"},"revision":1},{"id":"6e3f0a4e-c6b0-7844-b60c-619b739f3c5f","type":"table","position":"a7","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Call"}],[{"type":"text","text":"Returns"}]],[[{"type":"text","text":"soup.find(tag, class_=…)","marks":[{"type":"code"}]}],[{"type":"text","text":"The first matching element, or "},{"type":"text","text":"None","marks":[{"type":"code"}]}]],[[{"type":"text","text":"soup.find_all(tag, attrs={…})","marks":[{"type":"code"}]}],[{"type":"text","text":"A list of all matches"}]],[[{"type":"text","text":"soup.select(\"div.quote span.text\")","marks":[{"type":"code"}]}],[{"type":"text","text":"Matches for a CSS selector"}]],[[{"type":"text","text":"el.text","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"el.get_text(strip=True)","marks":[{"type":"code"}]}],[{"type":"text","text":"The element''s text"}]],[[{"type":"text","text":"el.get(\"href\")","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"el[\"href\"]","marks":[{"type":"code"}]}],[{"type":"text","text":"An attribute ("},{"type":"text","text":"get","marks":[{"type":"code"}]},{"type":"text","text":" returns "},{"type":"text","text":"None","marks":[{"type":"code"}]},{"type":"text","text":" if missing)"}]]]},"revision":1},{"id":"3112853e-72ae-7151-8636-31aca463564b","type":"code","position":"a8","content":{"language":"python","code":"html = \"\"\"\n<div class=\"quote\">\n  <span class=\"text\">“The world as we have created it is a process of our thinking.”</span>\n  <small class=\"author\">Albert Einstein</small> <a href=\"/author/Albert-Einstein\">(about)</a>\n  <a class=\"tag\" href=\"/tag/change/\">change</a> <a class=\"tag\" href=\"/tag/thinking/\">thinking</a>\n</div>\n<div class=\"quote\">\n  <span class=\"text\">“It is our choices that show what we truly are.”</span>\n  <small class=\"author\">J.K. Rowling</small> <a href=\"/author/J-K-Rowling\">(about)</a>\n  <a class=\"tag\" href=\"/tag/choices/\">choices</a>\n</div>\n\"\"\"\n\nfrom bs4 import BeautifulSoup\nsoup = BeautifulSoup(html, \"html.parser\")\nprint([a.get(\"href\") for a in soup.select(\"div.quote > a:not(.tag)\")])   # [''/author/Albert-Einstein'', ''/author/J-K-Rowling'']\nprint(len(soup.select(\"a.tag\")))                                          # 3","filename":"Python"},"revision":1},{"id":"1abe00da-4e4b-78b8-80f5-7713e88364ce","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Parsers"}]},"revision":1},{"id":"2373512a-494b-7ee5-af11-01d0f6e0bb2a","type":"table","position":"aA","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Parser"}],[{"type":"text","text":"Install"}],[{"type":"text","text":"Notes"}]],[[{"type":"text","text":"html.parser","marks":[{"type":"code"}]}],[{"type":"text","text":"Built in"}],[{"type":"text","text":"Good default"}]],[[{"type":"text",