FROM (VALUES
  ('06b8dc4e-f42d-77c9-a986-948ad503c1aa', 'a0', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Two ways to describe “what an object must be able to do”: "},{"type":"text","text":"ABCs","marks":[{"type":"bold"}]},{"type":"text","text":" check it by inheritance (nominal typing), "},{"type":"text","text":"Protocols","marks":[{"type":"bold"}]},{"type":"text","text":" by shape (structural typing — static duck typing)."}]}]}}'),
  ('50e7b60e-35a1-7c27-b5ce-57fe766f440e', 'a1', 'heading', '{"level":1,"content":[{"type":"text","text":"abc.ABC and @abstractmethod"}]}'),
  ('eabeb53a-9ab4-7e44-bbfd-c912a4494871', 'a2', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An abstract base class can''t be instantiated while it has abstract methods. Subclasses must implement every one of them — the error appears when you "},{"type":"text","text":"create an object","marks":[{"type":"italic"}]},{"type":"text","text":", not when you call the missing method."}]}]}}'),
  ('91dab854-a302-76e0-ac31-9776e3d65879', 'a3', 'code', '{"language":"python","code":"from abc import ABC, abstractmethod\n\nclass Exporter(ABC):\n    \"\"\"Template method pattern: export() fixes the algorithm, subclasses fill in the steps.\"\"\"\n\n    def export(self, rows):\n        return [self.header()] + [self.format_row(r) for r in rows]\n\n    @abstractmethod\n    def header(self) -> str: ...\n\n    @abstractmethod\n    def format_row(self, row) -> str: ...\n\nclass CsvExporter(Exporter):\n    def header(self):\n        return \"name,score\"\n    def format_row(self, row):\n        return f\"{row[0]},{row[1]}\"\n\nclass Broken(Exporter):\n    def header(self):\n        return \"x\"\n\nprint(CsvExporter().export([(\"asha\", 91), (\"ravi\", 84)]))   # [''name,score'', ''asha,91'', ''ravi,84'']\ntry:\n    Broken()\nexcept TypeError as e:\n    print(e)   # Can''t instantiate abstract class Broken without an implementation for abstract method ''format_row''\nprint(sorted(Exporter.__abstractmethods__))                  # [''format_row'', ''header'']","filename":"Python"}'),
  ('6a2a3950-ff34-7906-9ce9-d48dc971767b', 'a4', 'heading', '{"level":1,"content":[{"type":"text","text":"Abstract properties & class methods"}]}'),
  ('d91de752-5bdf-728d-8263-03f4a3b5ada0', 'a5', 'code', '{"language":"python","code":"from abc import ABC, abstractmethod\n\nclass Shape(ABC):\n    @property\n    @abstractmethod                    # @abstractmethod must be the innermost decorator\n    def sides(self) -> int: ...\n\n    @classmethod\n    @abstractmethod\n    def unit(cls) -> \"Shape\": ...\n\n    def describe(self):                # ABCs can hold ordinary, shared methods too\n        return f\"{type(self).__name__} with {self.sides} sides\"\n\nclass Triangle(Shape):\n    sides = 3                          # a plain class attribute satisfies the abstract property\n    @classmethod\n    def unit(cls):\n        return cls()\n\nprint(Triangle.unit().describe())      # Triangle with 3 sides","filename":"Python"}'),
  ('b3565049-bd8f-7ac0-a577-237cd8b7a27c', 'a6', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An abstract method may still have a body; subclasses can call it with "},{"type":"text","text":"super().method()","marks":[{"type":"code"}]},{"type":"text","text":" — handy for shared default behaviour that must be consciously opted into."}]}]}}'),
  ('e401d613-e594-75f4-b451-9fc361e38987', 'a7', 'heading', '{"level":1,"content":[{"type":"text","text":"collections.abc: get methods for free"}]}'),
  ('eeace3ec-358d-72cc-bdba-b1fbe81d14f1', 'a8', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The ABCs in "},{"type":"text","text":"collections.abc","marks":[{"type":"code"}]},{"type":"text","text":" are "},{"type":"text","text":"mixins","marks":[{"type":"italic"}]},{"type":"text","text":": implement the few abstract methods and inherit the rest. Implement "},{"type":"text","text":"__getitem__","marks":[{"type":"code"}]},{"type":"text","text":" + "},{"type":"text","text":"__len__","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"Sequence","marks":[{"type":"code"}]},{"type":"text","text":" gives you "},{"type":"text","text":"in","marks":[{"type":"code"}]},{"type":"text","text":", iteration, "},{"type":"text","text":"reversed","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"index","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"count","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('a2bcf7ed-b5d4-7524-b788-c1be3909e563', 'a9', 'code', '{"language":"python","code":"from collections.abc import Sequence\n\nclass Countdown(Sequence):\n    def __init__(self, n):\n        self.n = n\n    def __len__(self):\n        return self.n\n    def __getitem__(self, i):\n        if isinstance(i, slice):\n            return [self[j] for j in range(*i.indices(len(self)))]\n        if i < 0:\n            i += self.n\n        if not 0 <= i < self.n:\n            raise IndexError(i)\n        return self.n - i\n\nc = Countdown(5)\nprint(list(c), c[-1], c[1:3])             # [5, 4, 3, 2, 1] 1 [4, 3]\nprint(3 in c, c.index(2), c.count(9))     # True 3 0\nprint(list(reversed(c)))                  # [1, 2, 3, 4, 5]","filename":"Python"}'),
