INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT 'ce7c8058-99d4-7852-a2a1-0d6b1e4fdce8', 'bd9e0cc5-f008-7ee6-a7ed-0c55266db740', 1, 'PUBLISHED', 'Advanced Decorators', '[{"id":"5fad4ff5-86ef-7938-aba0-43736a2db453","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Beyond the basic wrapper: decorators with optional arguments, decorators that are classes, decorators "},{"type":"text","text":"for","marks":[{"type":"italic"}]},{"type":"text","text":" classes, registries, and the traps to avoid."}]}]}},"revision":1},{"id":"0006aaef-b141-7419-b7ab-85c505029501","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Recap: the three shapes"}]},"revision":1},{"id":"a2900958-6883-7082-899c-39bdf4ba75f6","type":"table","position":"a2","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Usage"}],[{"type":"text","text":"What Python calls"}],[{"type":"text","text":"Your decorator must be"}]],[[{"type":"text","text":"@d","marks":[{"type":"code"}]}],[{"type":"text","text":"f = d(f)","marks":[{"type":"code"}]}],[{"type":"text","text":"a callable taking the function"}]],[[{"type":"text","text":"@d(3)","marks":[{"type":"code"}]}],[{"type":"text","text":"f = d(3)(f)","marks":[{"type":"code"}]}],[{"type":"text","text":"a factory returning a decorator"}]],[[{"type":"text","text":"@d","marks":[{"type":"code"}]},{"type":"text","text":" on a class"}],[{"type":"text","text":"C = d(C)","marks":[{"type":"code"}]}],[{"type":"text","text":"a callable taking the class"}]]]},"revision":1},{"id":"2bea44fe-32dc-7681-b701-eb05d24b9f17","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"Optional arguments: "},{"type":"text","text":"@d","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"@d(…)","marks":[{"type":"code"}]}]},"revision":1},{"id":"f7549d3b-58ee-71c8-b720-319ac77c0cc7","type":"text","position":"a4","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Make the function the first, optional positional parameter and the options keyword-only. If a function arrives, decorate it now; otherwise return a decorator."}]}]}},"revision":1},{"id":"221c5bb8-4346-7c9a-a525-0737b1958ede","type":"code","position":"a5","content":{"language":"python","code":"import functools\n\ndef repeat(func=None, *, times=2):\n    def decorator(f):\n        @functools.wraps(f)\n        def wrapper(*args, **kwargs):\n            return [f(*args, **kwargs) for _ in range(times)]\n        return wrapper\n    if func is None:            # used as @repeat(times=3)\n        return decorator\n    return decorator(func)      # used as bare @repeat\n\n@repeat\ndef hi():\n    return \"hi\"\n\n@repeat(times=3)\ndef yo():\n    return \"yo\"\n\nprint(hi(), yo())   # [''hi'', ''hi''] [''yo'', ''yo'', ''yo'']","filename":"Python"},"revision":1},{"id":"5e84c289-6c60-7401-9d1f-45612bb79186","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"Class-based decorators with state"}]},"revision":1},{"id":"be434553-f5b0-7fca-908d-54c4261d6604","type":"text","position":"a7","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Any callable can be a decorator. A class whose "},{"type":"text","text":"__init__","marks":[{"type":"code"}]},{"type":"text","text":" takes the function and whose "},{"type":"text","text":"__call__","marks":[{"type":"code"}]},{"type":"text","text":" runs it keeps state naturally in attributes."}]}]}},"revision":1},{"id":"bca3bb66-2d25-789b-90f9-d2e5477307ec","type":"code","position":"a8","content":{"language":"python","code":"import functools\n\nclass CountCalls:\n    def __init__(self, func):\n        functools.update_wrapper(self, func)   # copy __name__, __doc__\n        self.func = func\n        self.calls = 0\n\n    def __call__(self, *args, **kwargs):\n        self.calls += 1\n        return self.func(*args, **kwargs)\n\n@CountCalls\ndef add(a, b):\n    \"\"\"Add two numbers.\"\"\"\n    return a + b\n\nadd(1, 2); add(3, 4)\nprint(add.calls, add.__name__, add(5, 5))   # 2 add 10","filename":"Python"},"revision":1},{"id":"4db286f2-3a51-766a-b901-d511b4de527b","type":"callout","position":"a9","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A class-based decorator applied to a "},{"type":"text","text":"method","marks":[{"type":"bold"}]},{"type":"text","text":" breaks "},{"type":"text","text":"self","marks":[{"type":"code"}]},{"type":"text","text":": instances of "},{"type":"text","text":"CountCalls","marks":[{"type":"code"}]},{"type":"text","text":" aren''t descriptors, so "},{"type":"text","text":"obj.method","marks":[{"type":"code"}]},{"type":"text","text":" doesn''t bind. Add a "},{"type":"text","text":"__get__","marks":[{"type":"code"}]},{"type":"text","text":" returning "},{"type":"text","text":"functools.partial(self.__call__, obj)","marks":[{"type":"code"}]},{"type":"text","text":", or use a function-based decorator for methods."}]}]}},"revision":1},{"id":"0397be7a-5e33-79c8-aa56-79f35c6d4a31","type":"heading","position":"aA","content":{"level":1,"content":[{"type":"text","text":"Decorating methods"}]},"revision":1},{"id":"fe0b0836-30c7-7312-859b-ac14084e80b8","type":"text","position":"aB","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Function-based decorators work on methods unchanged — "},{"type":"text","text":"self","marks":[{"type":"code"}]},{"type":"text","text":" simply arrives as the first element of "},{"type":"text","text":"*args","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"b3e55a10-6ff1-7c8b-9f7c-dc32682410a9","type":"code","position":"aC","content":{"language":"python","code":"import functools\n\ndef require_login(method):\n    @functools.wraps(method)\n    def wrapper(self, *args, **kwargs):\n        if not self.logged_in:\n            raise PermissionError(f\"{method.__name__} needs login\")\n        return method(self, *args, **kwargs)\n    return wrapper\n\nclass Account:\n    def __init__(self):\n        self.logged_in = False\n    @require_login\n    def balance(self):\n        return 100\n\nacc = Account()\ntry:\n    acc.balance()\nexcept PermissionError as e:\n    print(e)                  # balance needs login\nacc.logged_in = True\nprint(acc.balance())          # 100","filename":"Python"},"revision":1},{"id":"96a00e3e-34d9-7497-b0b5-a0a6eafb29d5","type":"heading","position":"aD","content":{"level":1,"content":[{"type":"text","text":"Class decorators"}]},"revision":1},{"id":"be0dc7f1-2f17-7dda-9a80-820a6c3b3da3","type":"text","position":"aE","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A class decorator receives the finished class and returns it (modified) or a replacement. "},{"type":"text","text":"@dataclass","marks":[{"type":"code"}]},{"type":"text","text":" is the famous one — it reads the annotations and generates "},{"type":"text","text":"__init__","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"__repr__","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"__eq__","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"b419f7e1-a4f0-7e63-b89d-a60107a82a77","type":"code","position":"aF","content":{"language":"python","code":"def add_repr(cls):\n    def __repr__(self):\n        fields = \", \".join(f\"{k}={v!r}\" for k, v in vars(self).items())\n        return f\"{cls.__name__}({fields})\"\n    cls.__repr__ = __repr__\n    return cls\n\ndef singleton(cls):\n    instances = {}\n    def get(*args, **kwargs):\n        if cls not in instances:\n            instances[cls] = cls(*args, **kwargs)\n        return instances[cls]\n    return get\n\n@add_repr\nclass User:\n    def __init__(self, name, age):\n        self.name, self.age = name, age\n\n@singleton\nclass Config:\n    pass\n\nprint(User(\"asha\", 30))           # User(name=''asha'', age=30)\nprint(Config() is Config())       # True","filename":"Python"},"revision":1},{"id":"eecea783-7921-79e4-a7a6-de0fdc353948","type":"callout","position":"aG","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"singleton","marks":[{"type":"code"}]},{"type":"text","text":" above replaces the class with a function, so "},{"type":"text","text":"isinstance(x, Config)","marks":[{"type":"code"}]},{"type":"text","text":" no longer works. Decorators that "},{"type":"text","text":"return the class","marks":[{"type":"italic"}]},{"type":"text","text":" are safer than ones that replace it."}]}]}},"revision":1},{"id":"bf68c694-b35e-7a15-86c6-8d85d3548400","type":"heading","position":"aH","content":{"level":1,"content":[{"type":"text","text":"Registries & plugins"}]},"revision":1},{"id":"09dc643f-f754-789d-b6b8-0b0208651c01","type":"text","position":"aI","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A decorator doesn''t have to wrap anything — it can just "},{"type":"text","text":"record","marks":[{"type":"bold"}]},{"type":"text","text":" the function and return it unchanged. This is how Flask routes, pytest fixtures and CLI command groups work."}]}]}},"revision":1},{"id":"b9ca6331-846e-78b5-a711-cf60624e680f","type":"code","position":"aJ","content":{"language":"python","code":"HANDLERS = {}\n\ndef on(event):\n    def register(func):\n        HANDLERS[event] = func\n        return func               # unchanged\n    return register\n\n@on(\"signup\")\ndef welcome(user):\n    return f\"welcome {user}\"\n\n@on(\"delete\")\ndef goodbye(user):\n    return f\"bye {user}\"\n\ndef dispatch(event, user):\n    return HANDLERS[event](user)\n\nprint(sorted(HANDLERS))           # [''delete'', ''signup'']\nprint(dispatch(\"signup\", \"asha\")) # welcome asha","filename":"Python"},"revision":1},{"id":"996de654-45f3-7b3a-838d-96cc155f91ae","type":"heading","position":"aK","content":{"level":1,"content":[{"type":"text","text":"Stacking order"}]},"revision":1},{"id":"71fce201-83bb-76c8-a420-b5587161c3f0","type":"text","position":"aL","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Decorators are "},{"type":"text","text":"applied","marks":[{"type":"bold"}]},{"type":"text","text":" bottom-up (closest to "},{"type":"text","text":"def","marks":[{"type":"code"}]},{"type":"text","text":" first) but the wrappers "},{"type":"text","text":"run","marks":[{"type":"bold"}]},{"type":"text","text":" top-down, like layers of an onion."}]}]}},"revision":1},{"id":"bbc6bcba-a825-7196-8f99-3c7f5b131666","type":"code","position":"aM","content":{"language":"python","code":"import functools\n\ndef layer(name):\n    def deco(f):\n        print(f\"apply {name}\")\n        @functools.wraps(f)\n        def wrapper():\n            print(f\"enter {name}\")\n            result = f()\n            print(f\"exit {name}\")\n            return result\n        return wrapper\n    return deco\n\n@layer(\"outer\")\n@layer(\"inner\")\ndef work():\n    print(\"work\")\n\nwork()","filename":"Python"},"revision":1},{"id":"8f2219bc-f245-76a3-ba73-bd963f5e73f2","type":"code","position":"aN","content":{"language":"text","code":"apply inner\napply outer\nenter outer\nenter inner\nwork\nexit inner\nexit outer","filename":"Output"},"revision":1},{"id":"d0e7f40e-0549-78e9-9353-d2cb00b19e69","type":"callout","position":"aO","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Order matters: "},{"type":"text","text":"@app.route","marks":[{"type":"code"}]},{"type":"text","text":" above "},{"type":"text","text":"@login_required","marks":[{"type":"code"}]},{"type":"text","text":" protects the route; the other way round registers the "},{"type":"text","text":"unprotected","marks":[{"type":"italic"}]},{"type":"text","text":" function. Similarly put "},{"type":"text","text":"@cache","marks":[{"type":"code"}]},{"type":"text","text":" where you want the cache to sit relative to logging or timing."}]}]}},"revision":1},{"id":"522d5bc0-ad89-769b-a654-a289551ec1f5","type":"heading","position":"aP","content":{"level":1,"content":[{"type":"text","text":"Validation from type hints"}]},"revision":1},{"id":"5fe45d6a-97da-72df-af27-03bb8fb223bc","type":"code","position":"aQ","content":{"language":"python","code":"import functools, inspect\n\ndef enforce_types(func):\n    sig = inspect.signature(func)\n    @functools.wraps(func)\n    def wrapper(*args, **kwargs):\n        bound = sig.bind(*args, **kwargs)\n        for name, value in bound.arguments.items():\n            expected = func.__annotations__.get(name)\n            if isinstance(expected, type) and not isinstance(value, expected):\n                raise TypeError(f\"{name} must be {expected.__name__}\")\n        return func(*args, **kwargs)\n    return wrapper\n\n@enforce_types\ndef repeat_text(text: str, n: int) -> str:\n    return text * n\n\nprint(repeat_text(\"ab\", 2))           # abab\ntry:\n    repeat_text(\"ab\", \"2\")\nexcept TypeError as e:\n    print(e)                          # n must be int\nprint(inspect.signature(repeat_text)) # (text: str, n: int) -> str","filename":"Python"},"revision":1},{"id":"a55801fa-aad8-7382-8568-48fac90290a3","type":"callout","position":"aR","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"functools.wraps","marks":[{"type":"code"}]},{"type":"text","text":" sets "},{"type":"text","text":"__wrapped__","marks":[{"type":"code"}]},{"type":"text","text":", which "},{"type":"text","text":"inspect.signature","marks":[{"type":"code"}]},{"type":"text","text":" follows — so the decorated function still shows its real signature in help, IDEs and docs."}]}]}},"revision":1},{"id":"d20340e9-bd64-7558-b7f8-7570b7fdb7f2","type":"heading","position":"aS","content":{"level":1,"content":[{"type":"text","text":"Decorators that are also context managers"}]},"revision":1},{"id":"cdf8a8d5-3bf6-7802-8f93-27c8d54e06e2","type":"code","position":"aT","content":{"language":"python","code":"from contextlib import ContextDecorator\n\nclass traced(ContextDecorator):\n    def __init__(self, label):\n        self.label = label\n    def __enter__(self):\n        print(f\"start {self.label}\")\n        return self\n    def __exit__(self, *exc):\n        print(f\"end {self.label}\")\n        return False\n\n@traced(\"job\")                    # as a decorator\ndef job():\n    print(\"working\")\n\njob()\nwith traced(\"block\"):             # as a with-statement\n    print(\"inline\")","filename":"Python"},"revision":1},{"id":"3b2c51a0-6833-70b9-9504-8c84741ef440","type":"code","position":"aU","content":{"language":"text","code":"start job\nworking\nend job\nstart block\ninline\nend block","filename":"Output"},"revision":1},{"id":"5e816a4e-be62-7e3a-ac2e-53fede7148d7","type":"heading","position":"aV","content":{"level":1,"content":[{"type":"text","text":"Pitfalls"}]},"revision":1},{"id":"d2e2b578-0676-7c1d-8a24-58d3ed3bc498","type":"callout","position":"aW","content":{"variant":"note","title":"Forgetting wraps","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Name, docstring and signature are lost — confusing tracebacks, broken introspection."}]}]}},"revision":1},{"id":"4ec0b5cd-e0b5-736e-b14e-2dccee69ac40","type":"callout","position":"aX","content":{"variant":"note","title":"Forgetting to return","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The wrapper must "},{"type":"text","text":"return func(...)","marks":[{"type":"code"}]},{"type":"text","text":", and the decorator must "},{"type":"text","text":"return wrapper","marks":[{"type":"code"}]},{"type":"text","text":" — otherwise the function becomes "},{"type":"text","text":"None","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"0acc5757-8b28-7a9e-ba79-ca44ed5b9524","type":"callout","position":"aY","content":{"variant":"note","title":"@d vs @d()","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A factory used without parentheses receives the function as its option argument — support both forms or be consistent."}]}]}},"revision":1},{"id":"a6ee9627-9b47-7df4-a686-a63c544c6c76","type":"callout","position":"aZ","content":{"variant":"note","title":"Import-time side effects","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Decorator bodies run when the module is imported. Keep them cheap; do the work inside the wrapper."}]}]}},"revision":1},{"id":"ce81d49c-b6a6-7f87-81fd-e86aef9c373f","type":"question","position":"aa","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you write a decorator that accepts arguments?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Add a level: an outer function takes the arguments and returns the actual decorator, which takes the function and returns the wrapper. "},{"type":"text","text":"@retry(times=3)","marks":[{"type":"code"}]},{"type":"text","text":" means "},{"type":"text","text":"f = retry(times=3)(f)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"08659d89-d68e-7390-b804-5c53289cc54f","type":"question","position":"ab","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is a class decorator? Give an example."}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A callable that receives a class and returns a class (usually the same one, modified). "},{"type":"text","text":"@dataclass","marks":[{"type":"code"}]},{"type":"text","text":" inspects the annotations and adds "},{"type":"text","text":"__init__","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"__repr__","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"__eq__","marks":[{"type":"code"}]},{"type":"text","text":"; "},{"type":"text","text":"@functools.total_ordering","marks":[{"type":"code"}]},{"type":"text","text":" adds comparison methods."}]}]}},"revision":1},{"id":"e9d3d8df-7e2e-75e6-a6b1-dfe542231929","type":"question","position":"ac","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"In what order are stacked decorators applied?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Bottom-up: "},{"type":"text","text":"@a @b def f","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"f = a(b(f))","marks":[{"type":"code"}]},{"type":"text","text":". At call time the outermost wrapper ("},{"type":"text","text":"a","marks":[{"type":"code"}]},{"type":"text","text":") runs first and calls into "},{"type":"text","text":"b","marks":[{"type":"code"}]},{"type":"text","text":"''s wrapper, which calls "},{"type":"text","text":"f","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
