SELECT c.id::uuid, '6f2ca396-fe97-70a5-a549-7ef60d3ea580', c.position, c.type::"notes"."CardType", c.content::jsonb, 1, TIMESTAMPTZ '2026-10-07 03:23:53+00', TIMESTAMPTZ '2026-10-07 03:23:53+00'
FROM (VALUES
  ('ab6b09b4-10ae-771e-a59e-a0f39ece87b6', 'a0', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"asyncio","marks":[{"type":"code"}]},{"type":"text","text":" runs thousands of I/O tasks on "},{"type":"text","text":"one thread","marks":[{"type":"bold"}]},{"type":"text","text":" by switching between them at every "},{"type":"text","text":"await","marks":[{"type":"code"}]},{"type":"text","text":". It''s cooperative multitasking: fast and lock-free, as long as nobody blocks the loop."}]}]}}'),
  ('570f20e7-cb2d-7cce-bc49-412239cd1efc', 'a1', 'callout', '{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Event loop","marks":[{"type":"bold"}]},{"type":"text","text":" — a scheduler that runs ready tasks one at a time. A task runs until it "},{"type":"text","text":"await","marks":[{"type":"code"}]},{"type":"text","text":"s something that isn''t ready (a socket, a timer); the loop then parks it and runs another task, resuming it when its I/O completes."}]}]}}'),
  ('4bd60ca0-f67b-7b2e-bdf0-0cb00b376ec2', 'a2', 'heading', '{"level":1,"content":[{"type":"text","text":"Coroutines, tasks & futures"}]}'),
  ('a28af22d-accf-772a-9f06-3d5da33c0b99', 'a3', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Object"}],[{"type":"text","text":"What it is"}],[{"type":"text","text":"Created by"}]],[[{"type":"text","text":"Coroutine"}],[{"type":"text","text":"The paused computation returned by calling an "},{"type":"text","text":"async def","marks":[{"type":"code"}]},{"type":"text","text":" function. Does "},{"type":"text","text":"nothing","marks":[{"type":"bold"}]},{"type":"text","text":" until awaited or wrapped in a task."}],[{"type":"text","text":"coro = fetch()","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Task"}],[{"type":"text","text":"A coroutine scheduled on the loop — it runs concurrently with the code that created it."}],[{"type":"text","text":"asyncio.create_task(coro)","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"TaskGroup.create_task","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Future"}],[{"type":"text","text":"A low-level placeholder for a result; tasks are futures. Rarely created by hand."}],[{"type":"text","text":"loop.create_future()","marks":[{"type":"code"}]}]]]}'),
  ('197af0f7-96a9-7517-9fa3-189f912ab70a', 'a4', 'code', '{"language":"python","code":"import asyncio\n\nasync def greet(name):\n    await asyncio.sleep(0)                # yield control to the loop once\n    return f\"hi {name}\"\n\ncoro = greet(\"asha\")\nprint(type(coro).__name__)                # coroutine  ← nothing has run yet\nprint(asyncio.run(coro))                  # hi asha    ← run() starts a loop, runs it, closes it","filename":"Python"}'),
  ('a0a86de1-4eac-7624-a201-f0b32de9ae20', 'a5', 'heading', '{"level":1,"content":[{"type":"text","text":"Sequential awaits vs concurrent tasks"}]}'),
  ('969cafe1-b57c-72df-82c6-e6c6f0176d99', 'a6', 'code', '{"language":"python","code":"import asyncio\n\nasync def job(name, delay, log):\n    log.append(f\"start {name}\")\n    await asyncio.sleep(delay)\n    log.append(f\"end {name}\")\n\nasync def sequential():\n    log = []\n    await job(\"a\", 0.02, log)             # waits for a to finish…\n    await job(\"b\", 0.01, log)             # …before b even starts\n    return log\n\nasync def concurrent():\n    log = []\n    t1 = asyncio.create_task(job(\"a\", 0.02, log))   # both scheduled now\n    t2 = asyncio.create_task(job(\"b\", 0.01, log))\n    await t1\n    await t2\n    return log\n\nprint(asyncio.run(sequential()))   # [''start a'', ''end a'', ''start b'', ''end b'']\nprint(asyncio.run(concurrent()))   # [''start a'', ''start b'', ''end b'', ''end a'']","filename":"Python"}'),
  ('3a59bd16-452e-7f2a-9951-46ebef8d11f7', 'a7', 'callout', '{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"await coro()","marks":[{"type":"code"}]},{"type":"text","text":" one after another is "},{"type":"text","text":"sequential","marks":[{"type":"bold"}]},{"type":"text","text":". Concurrency only happens when several tasks exist at once — via "},{"type":"text","text":"create_task","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"gather","marks":[{"type":"code"}]},{"type":"text","text":" or a "},{"type":"text","text":"TaskGroup","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('c812ff72-f55f-7f86-9467-7ecb3b268345', 'a8', 'heading', '{"level":1,"content":[{"type":"text","text":"gather"}]}'),
  ('4f11cc4f-5f0c-7fb8-b47e-6a3bc047717b', 'a9', 'code', '{"language":"python","code":"import asyncio\n\nasync def fetch(i):\n    await asyncio.sleep(0.01 * (3 - i))   # later items finish first…\n    if i == 1:\n        raise ValueError(f\"item {i} failed\")\n    return i * 10\n\nasync def main():\n    results = await asyncio.gather(*(fetch(i) for i in range(3)), return_exceptions=True)\n    print(results)                        # [0, ValueError(''item 1 failed''), 20]  ← …but order = input order\n    try:\n        await asyncio.gather(fetch(0), fetch(1))\n    except ValueError as e:\n        print(\"first error:\", e)          # first error: item 1 failed\n\nasyncio.run(main())","filename":"Python"}'),
  ('34213cab-4845-7434-86a0-a4f49bed6952', 'aA', 'heading', '{"level":1,"content":[{"type":"text","text":"TaskGroup — structured concurrency (3.11+)"}]}'),
  ('01631efd-992d-7cfb-bcc0-28e7c0703de4', 'aB', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"async with asyncio.TaskGroup()","marks":[{"type":"code"}]},{"type":"text","text":" waits for every task created in it. If one fails, the others are "},{"type":"text","text":"cancelled","marks":[{"type":"bold"}]},{"type":"text","text":" and all errors are raised together as an "},{"type":"text","text":"ExceptionGroup","marks":[{"type":"code"}]},{"type":"text","text":" — no orphaned tasks."}]}]}}'),
  ('98935b28-3b5c-79ca-a86e-f21a596ea830', 'aC', 'code', '{"language":"python","code":"import asyncio\n\nasync def worker(n):\n    await asyncio.sleep(0.01)\n    if n == 2:\n        raise KeyError(n)\n    return n\n\nasync def main():\n    async with asyncio.TaskGroup() as tg:\n        tasks = [tg.create_task(worker(n)) for n in range(2)]\n    print([t.result() for t in tasks])    # [0, 1]  ← all done when the block exits\n\n    try:\n        async with asyncio.TaskGroup() as tg:\n            tg.create_task(worker(2))\n            slow = tg.create_task(asyncio.sleep(10))\n    except* KeyError as eg:\n        print(type(eg).__name__, len(eg.exceptions))   # ExceptionGroup 1\n    print(slow.cancelled())               # True  ← the sibling was cancelled\n\nasyncio.run(main())","filename":"Python"}'),
  ('ce1a9641-fa99-7ea3-a087-89f6d6df4e2f', 'aD', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Prefer "},{"type":"text","text":"TaskGroup","marks":[{"type":"code"}]},{"type":"text","text":" over bare "},{"type":"text","text":"create_task","marks":[{"type":"code"}]},{"type":"text","text":" + "},{"type":"text","text":"gather","marks":[{"type":"code"}]},{"type":"text","text":" in new code. A bare task that nobody keeps a reference to can even be garbage-collected mid-flight — keep references or use a group."}]}]}}'),
  ('387c16eb-61e1-7aab-b398-d329cbec55bf', 'aE', 'heading', '{"level":1,"content":[{"type":"text","text":"Timeouts & cancellation"}]}'),
  ('b389a886-c85a-7359-a78a-d9ad712d1784', 'aF', 'code', '{"language":"python","code":"import asyncio\n\nasync def main():\n    try:\n        async with asyncio.timeout(0.01):          # 3.11+\n            await asyncio.sleep(1)\n    except TimeoutError:\n        print(\"timeout block\")                     # timeout block\n\n    try:\n        await asyncio.wait_for(asyncio.sleep(1), timeout=0.01)\n    except TimeoutError:\n        print(\"wait_for\")                          # wait_for\n\nasyncio.run(main())","filename":"Python"}'),
  ('09d669fb-d1f5-7789-a899-3a8180e20e51', 'aG', 'code', '{"language":"python","code":"import asyncio\n\nasync def worker(log):\n    try:\n        await asyncio.sleep(1)\n    except asyncio.CancelledError:\n        log.append(\"cleaning up\")\n        raise                             # always re-raise CancelledError\n\nasync def main():\n    log = []\n    t = asyncio.create_task(worker(log))\n    await asyncio.sleep(0)                # let it start\n    t.cancel()                            # throws CancelledError into it at its await\n    try:\n        await t\n    except asyncio.CancelledError:\n        log.append(\"cancelled\")\n    print(log, t.cancelled())             # [''cleaning up'', ''cancelled''] True\n\nasyncio.run(main())","filename":"Python"}'),
  ('b88ae6e3-60a0-7aa2-9687-c4ae3e54797b', 'aH', 'callout', '{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Swallowing "},{"type":"text","text":"CancelledError","marks":[{"type":"code"}]},{"type":"text","text":" ("},{"type":"text","text":"except Exception","marks":[{"type":"code"}]},{"type":"text","text":" doesn''t catch it, but a bare "},{"type":"text","text":"except:","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"except BaseException","marks":[{"type":"code"}]},{"type":"text","text":" does) breaks timeouts and "},{"type":"text","text":"TaskGroup","marks":[{"type":"code"}]},{"type":"text","text":" shutdown. Clean up, then re-raise."}]}]}}'),
  ('1f022262-1ec3-7958-8a37-606e9e772cc3', 'aI', 'heading', '{"level":1,"content":[{"type":"text","text":"Queues & semaphores"}]}'),
  ('2426641f-8c47-7123-a468-b923dda48172', 'aJ', 'code', '{"language":"python","code":"import asyncio\n\nasync def consumer(q, out):\n    while True:\n        item = await q.get()\n        out.append(item * item)\n        q.task_done()\n\nasync def main():\n    q = asyncio.Queue(maxsize=2)          # put() waits when full\n    out = []\n    workers = [asyncio.create_task(consumer(q, out)) for _ in range(2)]\n    for i in range(5):                    # the producer\n        await q.put(i)\n    await q.join()                        # every item processed\n    for w in workers:\n        w.cancel()\n    await asyncio.gather(*workers, return_exceptions=True)\n    print(sorted(out))                    # [0, 1, 4, 9, 16]\n\nasyncio.run(main())","filename":"Python"}'),
  ('c8de5972-39a8-7559-8b45-9bcaa2df1dde', 'aK', 'code', '{"language":"python","code":"import asyncio\n\nasync def main():\n    sem = asyncio.Semaphore(3)            # at most 3 \"requests\" in flight\n    active = peak = 0\n\n    async def fetch(i):\n        nonlocal active, peak\n        async with sem:\n            active += 1\n            peak = max(peak, active)\n            await asyncio.sleep(0.01)\n            active -= 1\n            return i\n\n    results = await asyncio.gather(*(fetch(i) for i in range(10)))\n    print(results == list(range(10)), peak)   # True 3\n\nasyncio.run(main())","filename":"Python"}'),
  ('3cd54612-0e85-75d8-92fc-82c32e545798', 'aL', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"No lock is needed around "},{"type":"text","text":"active += 1","marks":[{"type":"code"}]},{"type":"text","text":" here: with one thread, a task can only be interrupted at an "},{"type":"text","text":"await","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('baedb5f5-e8fe-76da-b647-bac215963000', 'aM', 'heading', '{"level":1,"content":[{"type":"text","text":"Blocking code: "},{"type":"text","text":"asyncio.to_thread","marks":[{"type":"code"}]}]}'),
  ('d2a71f7a-ea81-7171-a75a-ce25dd38eafb', 'aN', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A blocking call ("},{"type":"text","text":"time.sleep","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"requests.get","marks":[{"type":"code"}]},{"type":"text","text":", heavy CPU) freezes the "},{"type":"text","text":"whole loop","marks":[{"type":"bold"}]},{"type":"text","text":" — every other task stops. Push it to a worker thread:"}]}]}}'),
