on","code":"from typing import NamedTuple\n\nclass Employee(NamedTuple):\n    name: str\n    dept: str = \"eng\"\n\n    def badge(self) -> str:\n        return f\"{self.name}@{self.dept}\"\n\ne = Employee(\"asha\")\nprint(e, e.badge())          # Employee(name=''asha'', dept=''eng'') asha@eng\ntry:\n    e.name = \"ravi\"\nexcept AttributeError:\n    print(\"immutable\")       # immutable","filename":"Python"},"revision":1},{"id":"8f6b5610-3ed9-79a5-8d9d-0ce350877506","type":"table","position":"a5","content":{"hasHeaderRow":true,"rows":[[[],[{"type":"text","text":"namedtuple","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"NamedTuple","marks":[{"type":"code"}]}],[{"type":"text","text":"@dataclass","marks":[{"type":"code"}]}],[{"type":"text","text":"dict","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Mutable"}],[{"type":"text","text":"No"}],[{"type":"text","text":"Yes (or "},{"type":"text","text":"frozen=True","marks":[{"type":"code"}]},{"type":"text","text":")"}],[{"type":"text","text":"Yes"}]],[[{"type":"text","text":"Access"}],[{"type":"text","text":"p.x","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"p[0]","marks":[{"type":"code"}]}],[{"type":"text","text":"p.x","marks":[{"type":"code"}]}],[{"type":"text","text":"p[''x'']","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Hashable"}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"Only if frozen"}],[{"type":"text","text":"No"}]],[[{"type":"text","text":"Best for"}],[{"type":"text","text":"Small immutable records, returning several values"}],[{"type":"text","text":"Rich objects with defaults & methods"}],[{"type":"text","text":"Dynamic / JSON-like data"}]]]},"revision":1},{"id":"33335b6b-8cb1-7e9c-ba45-0bd9bd17aaa0","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"Counter — counting with arithmetic"}]},"revision":1},{"id":"ca7ce50e-c834-757b-9f64-59e4e12e7909","type":"code","position":"a7","content":{"language":"python","code":"from collections import Counter\n\ninventory = Counter(apple=3, pear=1)\ninventory.update([\"apple\", \"kiwi\"])          # add counts\nprint(inventory)                             # Counter({''apple'': 4, ''pear'': 1, ''kiwi'': 1})\ninventory.subtract({\"pear\": 2})              # can go negative\nprint(inventory[\"pear\"], inventory.total())  # -1 4\n\na, b = Counter(\"aabbc\"), Counter(\"abd\")\nprint(a + b)          # Counter({''a'': 3, ''b'': 3, ''c'': 1, ''d'': 1})\nprint(a - b)          # Counter({''a'': 1, ''b'': 1, ''c'': 1})   ← drops counts <= 0\nprint(a & b)          # Counter({''a'': 1, ''b'': 1})           ← min of each\nprint(sorted(Counter(x=2, y=1).elements()))   # [''x'', ''x'', ''y'']","filename":"Python"},"revision":1},{"id":"cadcfa12-7004-7a87-8342-72d989bf08ff","type":"callout","position":"a8","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"Counter","marks":[{"type":"code"}]},{"type":"text","text":" is a "},{"type":"text","text":"dict","marks":[{"type":"code"}]},{"type":"text","text":" subclass: missing keys read as "},{"type":"text","text":"0","marks":[{"type":"code"}]},{"type":"text","text":", and "},{"type":"text","text":"+","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"-","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"&","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"|","marks":[{"type":"code"}]},{"type":"text","text":" combine counters. "},{"type":"text","text":"most_common(k)","marks":[{"type":"code"}]},{"type":"text","text":" gives the top k."}]}]}},"revision":1},{"id":"44213837-406b-7646-83dd-8da201285011","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"defaultdict variations"}]},"revision":1},{"id":"bf6bef95-e6c0-77d5-ad8d-16e6d2fb56c0","type":"code","position":"aA","content":{"language":"python","code":"from collections import defaultdict\n\nseen_first = defaultdict(lambda: \"unknown\")     # any zero-arg callable\nprint(seen_first[\"x\"])                          # unknown\n\ndef tree():\n    return defaultdict(tree)                    # infinitely nested dict\nt = tree()\nt[\"india\"][\"ts\"][\"hyd\"] = 1\nprint(t[\"india\"][\"ts\"][\"hyd\"], \"ap\" in t[\"india\"])   # 1 False\n\ntotals = defaultdict(int)\nfor dept, amount in [(\"eng\", 5), (\"ops\", 2), (\"eng\", 3)]:\n    totals[dept] += amount\nprint(dict(totals))                              # {''eng'': 8, ''ops'': 2}","filename":"Python"},"revision":1},{"id":"c6a5b454-5b6e-77ef-bb49-d8d7d6e1c2e7","type":"callout","position":"aB","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Merely "},{"type":"text","text":"reading","marks":[{"type":"italic"}]},{"type":"text","text":" "},{"type":"text","text":"d[missing]","marks":[{"type":"code"}]},{"type":"text","text":" on a "},{"type":"text","text":"defaultdict","marks":[{"type":"code"}]},{"type":"text","text":" inserts the key. Use "},{"type":"text","text":"key in d","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"d.get(key)","marks":[{"type":"code"}]},{"type":"text","text":" when you only want to check."}]}]}},"revision":1},{"id":"1d99ea1f-79d0-7a92-89a0-102c7b017d01","type":"heading","position":"aC","content":{"level":1,"content":[{"type":"text","text":"OrderedDict — order you can manipulate"}]},"revision":1},{"id":"764e1db9-fa7b-74c1-b239-52782f0e461b","type":"text","position":"aD","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Plain dicts keep insertion order since 3.7, so "},{"type":"text","text":"OrderedDict","marks":[{"type":"code"}]},{"type":"text","text":" is now for its extras: "},{"type":"text","text":"move_to_end","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"popitem(last=False)","marks":[{"type":"code"}]},{"type":"text","text":", and order-sensitive equality."}]}]}},"revision":1},{"id":"8612418c-0f01-7dd9-8e9e-7874bd85e4f1","type":"code","position":"aE","content":{"language":"python","code":"from collections import OrderedDict\n\na = OrderedDict(x=1, y=2)\nb = OrderedDict(y=2, x=1)\nprint(a == b, dict(a) == dict(b))     # False True   ← OrderedDict compares order\n\na.move_to_end(\"x\")                    # x becomes the newest\nprint(list(a))                        # [''y'', ''x'']\nprint(a.popitem(last=False))          # (''y'', 2)   ← FIFO pop of the oldest","filename":"Python"},"revision":1},{"id":"724661d8-55f8-7ee9-8620-af9608ea1f66","type":"code","position":"aF","content":{"language":"python","code":"from collections import OrderedDict\n\nclass LRUCache:\n    def __init__(self, capacity):\n        self.capacity = capacity\n        self.data = OrderedDict()\n\n    def get(self, key):\n        if key not in self.data:\n            return -1\n        self.data.move_to_end(key)            # mark as recently used\n        return self.data[key]\n\n    def put(self, key, value):\n        self.data[key] = value\n        self.data.move_to_end(key)\n        if len(self.data) > self.capacity:\n            self.data.popitem(last=False)     # evict least recently used\n\ncache = LRUCache(2)\ncache.put(1, \"a\"); cache.put(2, \"b\")\ncache.get(1)                                  # 1 is now most recent\ncache.put(3, \"c\")                             # evicts 2\nprint(list(cache.data), cache.get(2))         # [1, 3] -1","filename":"Python — LRU cache (a classic interview question)"},"revision":1},{"id":"89223f6f-97b8-7260-94d5-ea6bf117e7b1","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"ChainMap — layered lookups"}]},"revision":1},{"id":"a932531d-8af7-7a59-94bf-1f478e1fce83","type":"text","position":"aH","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"ChainMap(a, b, c)","marks":[{"type":"code"}]},{"type":"text","text":" searches several dicts in order "},{"type":"text","text":"without copying","marks":[{"type":"bold"}]},{"type":"text","text":" them. Writes go to the first map. Perfect for defaults → config file → environment → command-line layering, or nested scopes."}]}]}},"revision":1},{"id":"518e85d9-65b7-76e6-886f-fa3a9c1aac65","type":"code","position":"aI","content":{"language":"python","code":"from collections import ChainMap\n\ndefaults = {\"theme\": \"light\", \"lang\": \"en\", \"debug\": False}\nuser = {\"theme\": \"dark\"}\ncli = {\"debug\": True}\n\nsettings = ChainMap(cli, user, defaults)\nprint(settings[\"theme\"], settings[\"lang\"], settings[\"debug\"])   # dark en True\n\nsettings[\"lang\"] = \"te\"                  # written to the first map (cli)\nprint(cli, defaults[\"lang\"])             # {''debug'': True, ''lang'': ''te''} en\n\nscope = ChainMap({\"x\": 1})\ninner = scope.new_child({\"x\": 2})        # push a new scope\nprint(inner[\"x\"], inner.parents[\"x\"])    # 2 1","filename":"Python"},"revision":1},{"id":"38da29a2-53b1-7bbe-80d5-31d4a06794c8","type":"heading","position":"aJ","content":{"level":1,"content":[{"type":"text","text":"UserDict & UserList — safe subclassing"}]},"revision":1},{"id":"c30f0c61-7137-7fde-97a6-d9cb39856d6e","type":"text","position":"aK","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Subclassing "},{"type":"text","text":"dict","marks":[{"type":"code"}]},{"type":"text","text":" directly is tricky: "},{"type":"text","text":"update()","marks":[{"type":"code"}]},{"type":"text","text":" and the constructor bypass your overridden "},{"type":"text","text":"__setitem__","marks":[{"type":"code"}]},{"type":"text","text":". "},{"type":"text","text":"UserDict","marks":[{"type":"code"}]},{"type":"text","text":" stores the data in "},{"type":"text","text":"self.data","marks":[{"type":"code"}]},{"type":"text","text":" and routes every write through your methods."}]}]}},"revision":1},{"id":"71ca76fa-2673-7ca8-9544-42b9b7747e15","type":"code","position":"aL","content":{"language":"python","code":"from collections import UserDict\n\nclass LowerDict(dict):\n    def __setitem__(self, k, v):\n        super().__setitem__(k.lower(), v)\n\nclass LowerUserDict(UserDict):\n    def __setitem__(self, k, v):\n        super().__setitem__(k.lower(), v)\n\nprint(LowerDict({\"A\": 1}))                    # {''A'': 1}   ← override bypassed!\nprint(LowerUserDict({\"A\": 1}).data)           # {''a'': 1}","filename":"Python"},"revision":1},{"id":"9768b905-e8e1-756d-9348-7fef52c93109","type":"heading","position":"aM","content":{"level":1,"content":[{"type":"text","text":"Two more handy containers"}]},"revision":1},{"id":"1600ad2b-0d32-748d-bae0-ff1cf18970b6","type":"code","position":"aN","content":{"language":"python","code":"from array import array\nfrom types import SimpleNamespace\n\nnums = array(\"i\", [1, 2, 3])        # compact typed array of C ints\nnums.append(4)\nprint(nums.tolist(), nums.itemsize) # [1, 2, 3, 4] 4\n\ncfg = SimpleNamespace(host=\"localhost\", port=8000)   # attribute bag\ncfg.debug = True\nprint(cfg.port, cfg)   # 8000 namespace(host=''localhost'', port=8000, debug=True)","filename":"Python"},"revision":1},{"id":"f50da8e5-baf8-7362-9676-b764ba4afc1d","type":"heading","position":"aO","content":{"level":1,"content":[{"type":"text","text":"Choosing the right container"}]},"revision":1},{"id":"c989f1ac-cedf-738d-9e52-16de0bf82669","type":"table","position":"aP","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Need"}],[{"type":"text","text":"Use"}]],[[{"type":"text","text":"Immutable record with named fields"}],[{"type":"text","text":"namedtuple","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"typing.NamedTuple","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Count things, combine counts"}],[{"type":"text","text":"Counter","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Group values / auto-create missing entries"}],[{"type":"text","text":"defaultdict","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Reorder keys, LRU cache, FIFO dict"}],[{"type":"text","text":"OrderedDict","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Look up through several dicts in priority order"}],[{"type":"text","text":"ChainMap","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Queue / sliding window"}],[{"type":"text","text":"deque","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Custom dict/list behaviour"}],[{"type":"text","text":"UserDict","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"UserList","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Millions of numbers, low memory"}],[{"type":"text","text":"array","marks":[{"type":"code"}]},{"type":"text","text":" (or NumPy)"}]],[[{"type":"text","text":"Quick attribute bag"}],[{"type":"text","text":"types.SimpleNamespace","marks":[{"type":"code"}]}]]]},"revision":1},{"id":"9fdb5d28-70b1-7d46-b758-7aded6e28080","type":"question","position":"aQ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why use OrderedDict now that dict preserves insertion order?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"For its extra behaviour: "},{"type":"text","text":"move_to_end","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"popitem(last=False)","marks":[{"type":"code"}]},{"type":"text","text":" (FIFO) and equality that takes order into account. It''s the idiomatic base for an LRU cache."}]}]}},"revision":1},{"id":"18ea3a0e-98b5-728f-b9dc-02c24b872225","type":"question","position":"aR","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Implement an LRU cache in O(1) per operation."}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Use an "},{"type":"text","text":"OrderedDict","marks":[{"type":"code"}]},{"type":"text","text":": on "},{"type":"text","text":"get","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"move_to_end(key)","marks":[{"type":"code"}]},{"type":"text","text":"; on "},{"type":"text","text":"put","marks":[{"type":"code"}]},{"type":"text","text":", insert, "},{"type":"text","text":"move_to_end","marks":[{"type":"code"}]},{"type":"text","text":", and if over capacity "},{"type":"text","text":"popitem(last=False)","marks":[{"type":"code"}]},{"type":"text","text":". Under the hood this is a hash map plus a doubly linked list — the same design you''d write by hand in Java or C++. For caching function results, "},{"type":"text","text":"functools.lru_cache","marks":[{"type":"code"}]},{"type":"text","text":" does it for you."}]}]}},"revision":1},{"id":"a2825b64-6e68-769e-ab11-bcaaa6c6b24e","type":"question","position":"aS","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"namedtuple or dataclass?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"namedtuple","marks":[{"type":"code"}]},{"type":"text","text":" for small, immutable, tuple-compatible records (unpacking, hashing, low memory). "},{"type":"text","text":"dataclass","marks":[{"type":"code"}]},{"type":"text","text":" when you need mutability, default factories, validation in "},{"type":"text","text":"__post_init__","marks":[{"type":"code"}]},{"type":"text","text":" or many methods."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
