  ('ad423108-bdde-75ab-9aaa-61e030f1803f', 'a0', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The rest of the "},{"type":"text","text":"collections","marks":[{"type":"code"}]},{"type":"text","text":" toolbox — lightweight records, counting arithmetic, order-aware dicts, layered lookups — plus when to use each."}]}]}}'),
  ('75db970a-5b59-7410-822e-00d7fde70202', 'a1', 'heading', '{"level":1,"content":[{"type":"text","text":"namedtuple — a tuple with field names"}]}'),
  ('333345b9-efa3-7fe8-a4a3-e05ea1a10443', 'a2', 'code', '{"language":"python","code":"from collections import namedtuple\n\nPoint = namedtuple(\"Point\", [\"x\", \"y\"])\np = Point(3, 4)\nx, y = p                             # still a tuple: unpacking, indexing, hashing\nprint(p.x, p[1], x + y)              # 3 4 7\nprint(p._replace(x=10), p)           # Point(x=10, y=4) Point(x=3, y=4)\nprint(p._asdict())                   # {''x'': 3, ''y'': 4}\nprint(Point._fields)                 # (''x'', ''y'')\nprint(Point._make([5, 6]))           # Point(x=5, y=6)\n\nConn = namedtuple(\"Conn\", \"host port timeout\", defaults=[30])\nprint(Conn(\"db\", 5432))              # Conn(host=''db'', port=5432, timeout=30)","filename":"Python"}'),
  ('442b3b83-2b09-7aa7-8c73-81f4c0029285', 'a3', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"typing.NamedTuple","marks":[{"type":"code"}]},{"type":"text","text":" is the class-syntax version — same runtime behaviour, but with type hints, docstrings and methods."}]}]}}'),
  ('561f67ea-4c9c-7be5-804d-ff364f81c2c9', 'a4', 'code', '{"language":"python","code":"from typing import NamedTuple\n\nclass Employee(NamedTuple):\n    name: str\n    dept: str = \"eng\"\n\n    def badge(self) -> str:\n        return f\"{self.name}@{self.dept}\"\n\ne = Employee(\"asha\")\nprint(e, e.badge())          # Employee(name=''asha'', dept=''eng'') asha@eng\ntry:\n    e.name = \"ravi\"\nexcept AttributeError:\n    print(\"immutable\")       # immutable","filename":"Python"}'),
  ('8f6b5610-3ed9-79a5-8d9d-0ce350877506', 'a5', 'table', '{"hasHeaderRow":true,"rows":[[[],[{"type":"text","text":"namedtuple","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"NamedTuple","marks":[{"type":"code"}]}],[{"type":"text","text":"@dataclass","marks":[{"type":"code"}]}],[{"type":"text","text":"dict","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Mutable"}],[{"type":"text","text":"No"}],[{"type":"text","text":"Yes (or "},{"type":"text","text":"frozen=True","marks":[{"type":"code"}]},{"type":"text","text":")"}],[{"type":"text","text":"Yes"}]],[[{"type":"text","text":"Access"}],[{"type":"text","text":"p.x","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"p[0]","marks":[{"type":"code"}]}],[{"type":"text","text":"p.x","marks":[{"type":"code"}]}],[{"type":"text","text":"p[''x'']","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Hashable"}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"Only if frozen"}],[{"type":"text","text":"No"}]],[[{"type":"text","text":"Best for"}],[{"type":"text","text":"Small immutable records, returning several values"}],[{"type":"text","text":"Rich objects with defaults & methods"}],[{"type":"text","text":"Dynamic / JSON-like data"}]]]}'),
  ('33335b6b-8cb1-7e9c-ba45-0bd9bd17aaa0', 'a6', 'heading', '{"level":1,"content":[{"type":"text","text":"Counter — counting with arithmetic"}]}'),
  ('ca7ce50e-c834-757b-9f64-59e4e12e7909', 'a7', 'code', '{"language":"python","code":"from collections import Counter\n\ninventory = Counter(apple=3, pear=1)\ninventory.update([\"apple\", \"kiwi\"])          # add counts\nprint(inventory)                             # Counter({''apple'': 4, ''pear'': 1, ''kiwi'': 1})\ninventory.subtract({\"pear\": 2})              # can go negative\nprint(inventory[\"pear\"], inventory.total())  # -1 4\n\na, b = Counter(\"aabbc\"), Counter(\"abd\")\nprint(a + b)          # Counter({''a'': 3, ''b'': 3, ''c'': 1, ''d'': 1})\nprint(a - b)          # Counter({''a'': 1, ''b'': 1, ''c'': 1})   ← drops counts <= 0\nprint(a & b)          # Counter({''a'': 1, ''b'': 1})           ← min of each\nprint(sorted(Counter(x=2, y=1).elements()))   # [''x'', ''x'', ''y'']","filename":"Python"}'),
  ('cadcfa12-7004-7a87-8342-72d989bf08ff', 'a8', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"Counter","marks":[{"type":"code"}]},{"type":"text","text":" is a "},{"type":"text","text":"dict","marks":[{"type":"code"}]},{"type":"text","text":" subclass: missing keys read as "},{"type":"text","text":"0","marks":[{"type":"code"}]},{"type":"text","text":", and "},{"type":"text","text":"+","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"-","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"&","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"|","marks":[{"type":"code"}]},{"type":"text","text":" combine counters. "},{"type":"text","text":"most_common(k)","marks":[{"type":"code"}]},{"type":"text","text":" gives the top k."}]}]}}'),
  ('44213837-406b-7646-83dd-8da201285011', 'a9', 'heading', '{"level":1,"content":[{"type":"text","text":"defaultdict variations"}]}'),
  ('bf6bef95-e6c0-77d5-ad8d-16e6d2fb56c0', 'aA', 'code', '{"language":"python","code":"from collections import defaultdict\n\nseen_first = defaultdict(lambda: \"unknown\")     # any zero-arg callable\nprint(seen_first[\"x\"])                          # unknown\n\ndef tree():\n    return defaultdict(tree)                    # infinitely nested dict\nt = tree()\nt[\"india\"][\"ts\"][\"hyd\"] = 1\nprint(t[\"india\"][\"ts\"][\"hyd\"], \"ap\" in t[\"india\"])   # 1 False\n\ntotals = defaultdict(int)\nfor dept, amount in [(\"eng\", 5), (\"ops\", 2), (\"eng\", 3)]:\n    totals[dept] += amount\nprint(dict(totals))                              # {''eng'': 8, ''ops'': 2}","filename":"Python"}'),
