SELECT 'c5f3a6e5-0586-7c1b-8438-da4a6930e30b', '25c489b0-ee33-7290-9ae9-4eb3245a2288', 1, 'PUBLISHED', 'Concurrency: Threads, Processes & asyncio', '[{"id":"dfc03d1a-efd9-7b27-8a3d-911d10dbc645","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Three tools for doing many things at once. Which one to pick depends on whether your program waits on I/O or burns CPU — because of the GIL."}]}]}},"revision":1},{"id":"8fd2d1bd-64ba-7096-bc14-42b2a6151ec0","type":"callout","position":"a1","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"GIL (Global Interpreter Lock)","marks":[{"type":"bold"}]},{"type":"text","text":" — a mutex in CPython that lets only "},{"type":"text","text":"one thread execute Python bytecode at a time","marks":[{"type":"bold"}]},{"type":"text","text":". Threads still help while waiting on I/O (the GIL is released), but they don''t speed up CPU-bound Python code."}]}]}},"revision":1},{"id":"746ceaff-8529-7ca7-81e1-0e811bc865ad","type":"table","position":"a2","content":{"hasHeaderRow":true,"rows":[[[],[{"type":"text","text":"threading","marks":[{"type":"code"}]}],[{"type":"text","text":"multiprocessing","marks":[{"type":"code"}]}],[{"type":"text","text":"asyncio","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Model"}],[{"type":"text","text":"OS threads, shared memory"}],[{"type":"text","text":"Separate processes, separate memory"}],[{"type":"text","text":"One thread, cooperative tasks"}]],[[{"type":"text","text":"Best for"}],[{"type":"text","text":"I/O-bound (network, disk)"}],[{"type":"text","text":"CPU-bound","marks":[{"type":"bold"}]},{"type":"text","text":" (math, image processing)"}],[{"type":"text","text":"Many concurrent I/O waits (thousands of sockets)"}]],[[{"type":"text","text":"GIL"}],[{"type":"text","text":"Limits CPU parallelism"}],[{"type":"text","text":"Bypassed — each process has its own"}],[{"type":"text","text":"Not relevant — single thread"}]],[[{"type":"text","text":"Cost"}],[{"type":"text","text":"Light; needs locks for shared data"}],[{"type":"text","text":"Heavy start-up; data must be pickled"}],[{"type":"text","text":"Very light; code must be "},{"type":"text","text":"async","marks":[{"type":"code"}]}]]]},"revision":1},{"id":"e0a33b88-24de-792d-8e76-d5e5c4951109","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"Concurrency vs parallelism"}]},"revision":1},{"id":"c930a991-e29d-7bd0-86fa-42ad406d53d9","type":"callout","position":"a4","content":{"variant":"note","title":"Concurrency","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Dealing","marks":[{"type":"italic"}]},{"type":"text","text":" with many things at once: tasks make progress in overlapping time periods, possibly by taking turns on one core. Threads under the GIL and "},{"type":"text","text":"asyncio","marks":[{"type":"code"}]},{"type":"text","text":" give you this."}]}]}},"revision":1},{"id":"b27cd342-7176-7e18-a213-0c969b5e0daa","type":"callout","position":"a5","content":{"variant":"note","title":"Parallelism","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Doing","marks":[{"type":"italic"}]},{"type":"text","text":" many things at once: tasks literally run at the same instant on different cores. In CPython that means processes (or a free-threaded build, or C extensions that release the GIL)."}]}]}},"revision":1},{"id":"0fc00554-43c7-71ba-bf4d-c6ac7824ab29","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"The GIL in detail"}]},"revision":1},{"id":"214eb26c-7c58-765b-90ad-c2a4d1ec98ba","type":"text","position":"a7","content":{"doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"What it protects:","marks":[{"type":"bold"}]},{"type":"text","text":" CPython''s internals — above all the reference counts on every object. Without it, two threads doing "},{"type":"text","text":"refcount += 1","marks":[{"type":"code"}]},{"type":"text","text":" could corrupt memory."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"When it is released:","marks":[{"type":"bold"}]},{"type":"text","text":" during blocking I/O ("},{"type":"text","text":"socket.recv","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"file.read","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"time.sleep","marks":[{"type":"code"}]},{"type":"text","text":"), and inside many C extensions doing heavy work (NumPy, "},{"type":"text","text":"hashlib","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"zlib","marks":[{"type":"code"}]},{"type":"text","text":"). The running thread is also forced to hand it over every few milliseconds ("},{"type":"text","text":"sys.getswitchinterval()","marks":[{"type":"code"}]},{"type":"text","text":", 5 ms by default)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"What it does NOT do:","marks":[{"type":"bold"}]},{"type":"text","text":" make "},{"type":"text","text":"your","marks":[{"type":"italic"}]},{"type":"text","text":" code thread-safe. "},{"type":"text","text":"counter += 1","marks":[{"type":"code"}]},{"type":"text","text":" is several bytecodes, and a switch can happen between them — you still need locks."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Free-threaded build:","marks":[{"type":"bold"}]},{"type":"text","text":" CPython 3.13 added an optional build without the GIL ("},{"type":"text","text":"python3.13t","marks":[{"type":"code"}]},{"type":"text","text":"); in 3.14 it is officially supported (PEP 779) as "},{"type":"text","text":"python3.14t","marks":[{"type":"code"}]},{"type":"text","text":". Pure-Python threads then run truly in parallel, at a small single-thread cost."}]}]}]}]}},"revision":1},{"id":"2d4c04ed-af4a-7382-867a-30da75de2fe9","type":"code","position":"a8","content":{"language":"python","code":"import sys\nprint(sys.getswitchinterval())                 # 0.005\n# Only exists on 3.13+; True on the normal build, False on a free-threaded one:\ngil = getattr(sys, \"_is_gil_enabled\", lambda: True)()\nprint(isinstance(gil, bool))                   # True","filename":"Python"},"revision":1},{"id":"11f9590e-fa7a-727b-bf22-416a9742809f","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Which tool? A decision flow"}]},"revision":1},{"id":"5bd97619-2885-7de7-8219-a386b4b154c7","type":"text","position":"aA","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Is the work mostly waiting?","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Network calls, disk, databases, sleeping → it''s "},{"type":"text","text":"I/O-bound","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"I/O-bound, a handful to hundreds of tasks","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"ThreadPoolExecutor","marks":[{"type":"code"}]},{"type":"text","text":" — works with ordinary blocking libraries like "},{"type":"text","text":"requests","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"I/O-bound, thousands of connections","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"asyncio","marks":[{"type":"code"}]},{"type":"text","text":" with async libraries ("},{"type":"text","text":"aiohttp","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"httpx","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"asyncpg","marks":[{"type":"code"}]},{"type":"text","text":") — one thread, tiny per-task cost."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Is it computing in Python?","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Loops, parsing, math → "},{"type":"text","text":"CPU-bound","marks":[{"type":"bold"}]},{"type":"text","text":": "},{"type":"text","text":"ProcessPoolExecutor","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"multiprocessing","marks":[{"type":"code"}]},{"type":"text","text":", or vectorise with NumPy, or a free-threaded build."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Mixed?","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"asyncio","marks":[{"type":"code"}]},{"type":"text","text":" for the I/O, "},{"type":"text","text":"loop.run_in_executor","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"asyncio.to_thread","marks":[{"type":"code"}]},{"type":"text","text":" or a process pool for the heavy bits."}]}]}]}]}},"revision":1},{"id":"56fbb63d-304c-7f4c-aa0b-05823c269183","type":"heading","position":"aB","content":{"level":1,"content":[{"type":"text","text":"Threads for I/O"}]},"revision":1},{"id":"7742087d-5d2b-794a-8b0d-7fbcbabccb5a","type":"code","position":"aC","content":{"language":"python","code":"from concurrent.futures import ThreadPoolExecutor\nimport time\n\ndef fetch(i):\n    time.sleep(0.2)              # stands in for a network call (releases the GIL)\n    return i * i\n\nstart = time.perf_counter()\nwith ThreadPoolExecutor(max_workers=5) as pool:\n    results = list(pool.map(fetch, range(5)))\nelapsed = time.perf_counter() - start\nprint(results, elapsed < 0.5)    # [0, 1, 4, 9, 16] True","filename":"Python"},"revision":1},{"id":"ef58ec77-e669-7715-8b23-63cca90454bc","type":"heading","position":"aD","content":{"level":1,"content":[{"type":"text","text":"Processes for CPU"}]},"revision":1},{"id":"4b7d6e7c-3b4a-721d-91d6-434e0eb9c315","type":"code","position":"aE","content":{"language":"python","code":"from concurrent.futures import ProcessPoolExecutor\n\ndef heavy(n):\n    return sum(i * i for i in range(n))\n\nif __name__ == \"__main__\":       # required: child processes re-import this module\n    with ProcessPoolExecutor() as pool:\n        print(list(pool.map(heavy, [10**6] * 4)))","filename":"Python"},"revision":1},{"id":"161a8d76-65c4-7163-9561-341667784472","type":"heading","position":"aF","content":{"level":1,"content":[{"type":"text","text":"asyncio for massive I/O concurrency"}]},"revision":1},{"id":"8ec957cd-6b98-72e6-a434-bb002dc5044c","type":"code","position":"aG","content":{"language":"python","code":"import asyncio\n\nasync def download(name, delay):\n    await asyncio.sleep(delay)   # yields control while \"waiting\"\n    return f\"{name} done\"\n\nasync def main():\n    results = await asyncio.gather(download(\"a\", 0.1), download(\"b\", 0.1))\n    print(results)               # [''a done'', ''b done'']\n\nasyncio.run(main())","filename":"Python"},"revision":1},{"id":"3d0cb859-9598-7b62-8203-1720d33172fc","type":"heading","position":"aH","content":{"level":1,"content":[{"type":"text","text":"Shared state needs a lock"}]},"revision":1},{"id":"251e85b8-5a40-7473-9227-e3c4263cd45c","type":"code","position":"aI","content":{"language":"python","code":"import threading\n\ncounter = 0\nlock = threading.Lock()\n\ndef work():\n    global counter\n    for _ in range(100_000):\n        with lock:               # without the lock, updates can be lost\n            counter += 1\n\nthreads = [threading.Thread(target=work) for _ in range(4)]\nfor t in threads: t.start()\nfor t in threads: t.join()\nprint(counter)                   # 400000","filename":"Python"},"revision":1},{"id":"1df2f594-8582-7f33-9a25-b08f6c59d358","type":"callout","position":"aJ","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"counter += 1","marks":[{"type":"code"}]},{"type":"text","text":" is several bytecode steps (load, add, store), so a thread switch in between loses updates. Protect shared mutable state with a "},{"type":"text","text":"Lock","marks":[{"type":"code"}]},{"type":"text","text":" or use a "},{"type":"text","text":"queue.Queue","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"ac7909f0-e565-7f2a-a900-f8db8e69b692","type":"callout","position":"aK","content":{"variant":"note","title":"Recent change","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Python 3.13 shipped an experimental "},{"type":"text","text":"free-threaded","marks":[{"type":"italic"}]},{"type":"text","text":" build (no GIL); 3.14 makes it officially supported but still optional — the default "},{"type":"text","text":"python3","marks":[{"type":"code"}]},{"type":"text","text":" keeps the GIL. For interviews, explain the GIL as above and mention free-threading as the direction of travel."}]}]}},"revision":1},{"id":"55f021f8-b2c3-7e5f-9018-6acb0e948c13","type":"question","position":"aL","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"If Python has a GIL, why are threads useful at all?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Because most real programs spend their time "},{"type":"text","text":"waiting","marks":[{"type":"bold"}]},{"type":"text","text":" — for the network, the disk or a database. A thread blocked on I/O releases the GIL, so other threads run meanwhile. Threads give concurrency for I/O-bound work; for CPU-bound pure-Python work use processes (or a free-threaded build)."}]}]}},"revision":1},{"id":"6cf67db7-8aef-7596-ad81-93c09e3f1899","type":"question","position":"aM","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Does the GIL make my code thread-safe?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"No. It only protects the interpreter''s internals. A compound operation like "},{"type":"text","text":"counter += 1","marks":[{"type":"code"}]},{"type":"text","text":" or check-then-act ("},{"type":"text","text":"if key not in d: d[key] = …","marks":[{"type":"code"}]},{"type":"text","text":") can be interrupted between bytecodes, so shared mutable state still needs a "},{"type":"text","text":"Lock","marks":[{"type":"code"}]},{"type":"text","text":", a "},{"type":"text","text":"queue.Queue","marks":[{"type":"code"}]},{"type":"text","text":", or another synchronisation primitive."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
WHERE EXISTS (SELECT 1 FROM "notes"."Note" n WHERE n.id = '25c489b0-ee33-7290-9ae9-4eb3245a2288' AND n."ownerId" = '019a118c-f480-7000-8000-000000000001' AND n."publishedVersionId" IS NULL AND n.visibility = 'PRIVATE' AND n."deletedAt" IS NULL AND n."draftUpdatedAt" = TIMESTAMPTZ '2026-10-07 03:23:53+00')
ON CONFLICT DO NOTHING;

