SELECT 'c4c421b1-403f-778f-be07-0bd8a8e99417', '1ab2e676-3807-7665-a5ca-554451dc5bf2', 1, 'PUBLISHED', 'concurrent.futures', '[{"id":"4cd17e1a-6c48-7f45-9c31-1828473a476c","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"One high-level API for both threads and processes: submit callables to an "},{"type":"text","text":"executor","marks":[{"type":"italic"}]},{"type":"text","text":" and get back "},{"type":"text","text":"futures","marks":[{"type":"italic"}]},{"type":"text","text":" — placeholders for results that will arrive later."}]}]}},"revision":1},{"id":"d754ef03-ac1e-74de-b77b-94cfa8971cf5","type":"callout","position":"a1","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Future","marks":[{"type":"bold"}]},{"type":"text","text":" — an object representing a pending result. You can ask whether it''s "},{"type":"text","text":"done()","marks":[{"type":"code"}]},{"type":"text","text":", block on "},{"type":"text","text":"result()","marks":[{"type":"code"}]},{"type":"text","text":", fetch its "},{"type":"text","text":"exception()","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"cancel()","marks":[{"type":"code"}]},{"type":"text","text":" it, or attach callbacks."}]}]}},"revision":1},{"id":"4f67d817-60cc-7992-a344-7aa48e446c86","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"The Executor API"}]},"revision":1},{"id":"c1b3c96d-519e-7532-a41e-2201198f19c8","type":"table","position":"a3","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Call"}],[{"type":"text","text":"Does"}]],[[{"type":"text","text":"ex.submit(f, *args, **kw)","marks":[{"type":"code"}]}],[{"type":"text","text":"Schedule one call → returns a "},{"type":"text","text":"Future","marks":[{"type":"code"}]},{"type":"text","text":" immediately"}]],[[{"type":"text","text":"ex.map(f, *iterables, timeout=None)","marks":[{"type":"code"}]}],[{"type":"text","text":"Like built-in "},{"type":"text","text":"map","marks":[{"type":"code"}]},{"type":"text","text":", run in parallel; results in "},{"type":"text","text":"input order","marks":[{"type":"bold"}]}]],[[{"type":"text","text":"ex.shutdown(wait=True, cancel_futures=False)","marks":[{"type":"code"}]}],[{"type":"text","text":"Stop accepting work; called automatically by "},{"type":"text","text":"with","marks":[{"type":"code"}]}]],[[{"type":"text","text":"as_completed(futures, timeout)","marks":[{"type":"code"}]}],[{"type":"text","text":"Yield futures as they "},{"type":"text","text":"finish","marks":[{"type":"bold"}]}]],[[{"type":"text","text":"wait(futures, timeout, return_when)","marks":[{"type":"code"}]}],[{"type":"text","text":"Block until ALL_COMPLETED / FIRST_COMPLETED / FIRST_EXCEPTION"}]]]},"revision":1},{"id":"6b525597-aa9e-727d-85a9-23e877030dd5","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"submit, result & map"}]},"revision":1},{"id":"8d03a2f0-67cf-769f-903a-1a5464628c4d","type":"code","position":"a5","content":{"language":"python","code":"from concurrent.futures import ThreadPoolExecutor\n\ndef square(x):\n    return x * x\n\nwith ThreadPoolExecutor(max_workers=3) as ex:\n    fut = ex.submit(square, 7)\n    print(fut.result())                   # 49  ← blocks until ready\n    print(fut.done())                     # True\n    print(list(ex.map(square, [3, 1, 2])))   # [9, 1, 4]  ← input order, always","filename":"Python"},"revision":1},{"id":"c6168dc2-ca73-7e86-af6f-eedb3789e5ca","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"as_completed: handle results as they arrive"}]},"revision":1},{"id":"d4db915e-d68e-73e3-adbd-f0d459d2cb83","type":"code","position":"a7","content":{"language":"python","code":"import time\nfrom concurrent.futures import ThreadPoolExecutor, as_completed\n\ndef job(name, delay):\n    time.sleep(delay)                     # stands in for a network call\n    return name\n\nwith ThreadPoolExecutor() as ex:\n    futures = {ex.submit(job, n, d): n for n, d in [(\"slow\", 0.05), (\"fast\", 0.0), (\"mid\", 0.02)]}\n    finished = [f.result() for f in as_completed(futures)]   # completion order\nprint(sorted(finished))                   # [''fast'', ''mid'', ''slow'']\nprint(len(futures))                       # 3","filename":"Python"},"revision":1},{"id":"47bc6d71-d0e3-72c2-be2a-6cf0ed27c1e5","type":"callout","position":"a8","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Map each future back to its input with a dict ("},{"type":"text","text":"{future: input}","marks":[{"type":"code"}]},{"type":"text","text":"), because "},{"type":"text","text":"as_completed","marks":[{"type":"code"}]},{"type":"text","text":" yields them in whatever order they finish."}]}]}},"revision":1},{"id":"89e5d2c8-dfec-732b-a8dc-3ef04cc53d84","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Exceptions travel through the future"}]},"revision":1},{"id":"1ff94f42-0592-7b20-96c8-d22733cec459","type":"text","position":"aA","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An exception raised in a worker is stored in the future and "},{"type":"text","text":"re-raised when you call ","marks":[{"type":"bold"}]},{"type":"text","text":"result()","marks":[{"type":"bold"},{"type":"code"}]},{"type":"text","text":" — nothing is printed if you never ask."}]}]}},"revision":1},{"id":"a145848d-4622-724a-9283-b4242ef83f53","type":"code","position":"aB","content":{"language":"python","code":"from concurrent.futures import ThreadPoolExecutor\n\ndef risky(x):\n    if x == 2:\n        raise ValueError(\"bad input 2\")\n    return x\n\nwith ThreadPoolExecutor() as ex:\n    futures = [ex.submit(risky, i) for i in range(4)]\n    outcomes = []\n    for f in futures:\n        try:\n            outcomes.append(f.result())\n        except ValueError as e:\n            outcomes.append(f\"error: {e}\")\nprint(outcomes)                           # [0, 1, ''error: bad input 2'', 3]\nprint(type(futures[2].exception()).__name__)   # ValueError","filename":"Python"},"revision":1},{"id":"a9b1dec4-7824-7a10-9d1d-4d88fd52b378","type":"callout","position":"aC","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"With "},{"type":"text","text":"ex.map","marks":[{"type":"code"}]},{"type":"text","text":", the first failing item raises when the iterator reaches it, and you lose the remaining results. Use "},{"type":"text","text":"submit","marks":[{"type":"code"}]},{"type":"text","text":" + per-future "},{"type":"text","text":"try","marks":[{"type":"code"}]},{"type":"text","text":" when some inputs may fail."}]}]}},"revision":1},{"id":"013a10f2-d57f-764b-9da6-bd858fc471f2","type":"heading","position":"aD","content":{"level":1,"content":[{"type":"text","text":"wait, cancel & timeouts"}]},"revision":1},{"id":"94b460e2-c1ab-737c-adbd-e95eebabfd70","type":"code","position":"aE","content":{"language":"python","code":"import threading\nfrom concurrent.futures import ThreadPoolExecutor, wait, FIRST_COMPLETED\n\ngate = threading.Event()\nwith ThreadPoolExecutor(max_workers=2) as ex:\n    quick = ex.submit(lambda: \"quick\")\n    blocked = ex.submit(gate.wait)        # can''t finish until the gate opens\n    done, pending = wait([quick, blocked], return_when=FIRST_COMPLETED)\n    print([f.result() for f in done], len(pending))   # [''quick''] 1\n    gate.set()","filename":"Python"},"revision":1},{"id":"d7457309-7745-71d9-a736-0c90e602b033","type":"code","position":"aF","content":{"language":"python","code":"import threading\nfrom concurrent.futures import ThreadPoolExecutor\n\nstarted, gate = threading.Event(), threading.Event()\n\ndef blocker():\n    started.set()\n    gate.wait()\n    return \"finished\"\n\nwith ThreadPoolExecutor(max_workers=1) as ex:\n    running = ex.submit(blocker)          # occupies the only worker\n    queued = ex.submit(print, \"never\")    # waits in the queue\n    started.wait()\n    print(queued.cancel(), queued.cancelled())   # True True  ← not started yet\n    print(running.cancel())               # False  ← already running: can''t cancel\n    try:\n        running.result(timeout=0.01)\n    except TimeoutError:\n        print(\"timed out\")                # timed out\n    gate.set()\nprint(running.result())                   # finished","filename":"Python"},"revision":1},{"id":"e100050d-e64e-75b4-858f-59e25342841c","type":"callout","position":"aG","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A timeout on "},{"type":"text","text":"result()","marks":[{"type":"code"}]},{"type":"text","text":" only stops "},{"type":"text","text":"you","marks":[{"type":"italic"}]},{"type":"text","text":" waiting — the task keeps running. Threads can''t be killed; design long tasks to check a stop "},{"type":"text","text":"Event","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"176488a9-0757-7c3a-a714-fbeb4c1a5259","type":"heading","position":"aH","content":{"level":1,"content":[{"type":"text","text":"Callbacks"}]},"revision":1},{"id":"8a3e4b53-8a6b-72f1-81c7-2f8e88e3128c","type":"code","position":"aI","content":{"language":"python","code":"from concurrent.futures import ThreadPoolExecutor\n\nlog = []\nwith ThreadPoolExecutor() as ex:\n    f = ex.submit(sum, [1, 2, 3])\n    f.add_done_callback(lambda fut: log.append(fut.result() * 10))\nprint(log)                                # [60]","filename":"Python"},"revision":1},{"id":"919ce35a-7ff9-7cf0-953c-00650e58c84b","type":"heading","position":"aJ","content":{"level":1,"content":[{"type":"text","text":"Processes & interpreters: same API"}]},"revision":1},{"id":"4299c235-f7ab-76b2-9ca5-a490eb171b53","type":"code","position":"aK","content":{"language":"python","code":"from concurrent.futures import ProcessPoolExecutor\n\ndef count_primes(limit):\n    return sum(all(n % d for d in range(2, int(n ** 0.5) + 1)) for n in range(2, limit))\n\nif __name__ == \"__main__\":\n    with ProcessPoolExecutor() as ex:     # one worker per CPU core by default\n        print(list(ex.map(count_primes, [10_000, 20_000], chunksize=1)))   # [1229, 2262]","filename":"Python"},"revision":1},{"id":"9abf4a25-9fe4-70e3-93a4-842d6a45e965","type":"table","position":"aL","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Executor"}],[{"type":"text","text":"Parallel CPU?"}],[{"type":"text","text":"Default "},{"type":"text","text":"max_workers","marks":[{"type":"code"}]}],[{"type":"text","text":"Notes"}]],[[{"type":"text","text":"ThreadPoolExecutor","marks":[{"type":"code"}]}],[{"type":"text","text":"No (GIL)"}],[{"type":"text","text":"min(32, cpu_count + 4)","marks":[{"type":"code"}]}],[{"type":"text","text":"I/O-bound; shares memory"}]],[[{"type":"text","text":"ProcessPoolExecutor","marks":[{"type":"code"}]}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"number of CPUs"}],[{"type":"text","text":"Arguments/results must pickle; needs "},{"type":"text","text":"__main__","marks":[{"type":"code"}]},{"type":"text","text":" guard"}]],[[{"type":"text","text":"InterpreterPoolExecutor","marks":[{"type":"code"}]},{"type":"text","text":" (3.14)"}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"number of CPUs"}],[{"type":"text","text":"Sub-interpreters in one process, each with its own GIL"}]]]},"revision":1},{"id":"9f33dcaf-25a9-73ea-bd82-3a9e7ed3cb43","type":"callout","position":"aM","content":{"variant":"tip","title":"Do","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Size thread pools for the I/O you''re waiting on (tens of workers is fine); size process pools to the number of cores."}]}]}},"revision":1},{"id":"8ed402ff-fc51-7b09-b0b4-26f036b9df9c","type":"callout","position":"aN","content":{"variant":"danger","title":"Avoid","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Using a "},{"type":"text","text":"ProcessPoolExecutor","marks":[{"type":"code"}]},{"type":"text","text":" for tiny tasks — pickling and IPC overhead will make it slower than a plain loop."}]}]}},"revision":1},{"id":"95f1af87-841b-71cd-9025-3cc70fae3f2d","type":"question","position":"aO","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What''s the difference between ex.map and submit + as_completed?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"map","marks":[{"type":"code"}]},{"type":"text","text":" returns results in input order and raises the first exception when you reach it — simple and tidy. "},{"type":"text","text":"submit","marks":[{"type":"code"}]},{"type":"text","text":" returns one "},{"type":"text","text":"Future","marks":[{"type":"code"}]},{"type":"text","text":" per call; with "},{"type":"text","text":"as_completed","marks":[{"type":"code"}]},{"type":"text","text":" you process each result as soon as it''s ready and handle failures individually."}]}]}},"revision":1},{"id":"5c602e62-be1f-7095-87a1-9475b5494666","type":"question","position":"aP","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you get an exception out of a worker thread?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Call "},{"type":"text","text":"future.result()","marks":[{"type":"code"}]},{"type":"text","text":" — it re-raises the worker''s exception in the caller — or inspect "},{"type":"text","text":"future.exception()","marks":[{"type":"code"}]},{"type":"text","text":". With raw "},{"type":"text","text":"threading.Thread","marks":[{"type":"code"}]},{"type":"text","text":", exceptions are only reported by "},{"type":"text","text":"threading.excepthook","marks":[{"type":"code"}]},{"type":"text","text":", which is why executors are usually nicer."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
WHERE EXISTS (SELECT 1 FROM "notes"."Note" n WHERE n.id = '1ab2e676-3807-7665-a5ca-554451dc5bf2' AND n."ownerId" = '019a118c-f480-7000-8000-000000000001' AND n."publishedVersionId" IS NULL AND n.visibility = 'PRIVATE' AND n."deletedAt" IS NULL AND n."draftUpdatedAt" = TIMESTAMPTZ '2026-10-07 03:23:53+00')
