  ('6b525597-aa9e-727d-85a9-23e877030dd5', 'a4', 'heading', '{"level":1,"content":[{"type":"text","text":"submit, result & map"}]}'),
  ('8d03a2f0-67cf-769f-903a-1a5464628c4d', 'a5', 'code', '{"language":"python","code":"from concurrent.futures import ThreadPoolExecutor\n\ndef square(x):\n    return x * x\n\nwith ThreadPoolExecutor(max_workers=3) as ex:\n    fut = ex.submit(square, 7)\n    print(fut.result())                   # 49  ← blocks until ready\n    print(fut.done())                     # True\n    print(list(ex.map(square, [3, 1, 2])))   # [9, 1, 4]  ← input order, always","filename":"Python"}'),
  ('c6168dc2-ca73-7e86-af6f-eedb3789e5ca', 'a6', 'heading', '{"level":1,"content":[{"type":"text","text":"as_completed: handle results as they arrive"}]}'),
  ('d4db915e-d68e-73e3-adbd-f0d459d2cb83', 'a7', 'code', '{"language":"python","code":"import time\nfrom concurrent.futures import ThreadPoolExecutor, as_completed\n\ndef job(name, delay):\n    time.sleep(delay)                     # stands in for a network call\n    return name\n\nwith ThreadPoolExecutor() as ex:\n    futures = {ex.submit(job, n, d): n for n, d in [(\"slow\", 0.05), (\"fast\", 0.0), (\"mid\", 0.02)]}\n    finished = [f.result() for f in as_completed(futures)]   # completion order\nprint(sorted(finished))                   # [''fast'', ''mid'', ''slow'']\nprint(len(futures))                       # 3","filename":"Python"}'),
  ('47bc6d71-d0e3-72c2-be2a-6cf0ed27c1e5', 'a8', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Map each future back to its input with a dict ("},{"type":"text","text":"{future: input}","marks":[{"type":"code"}]},{"type":"text","text":"), because "},{"type":"text","text":"as_completed","marks":[{"type":"code"}]},{"type":"text","text":" yields them in whatever order they finish."}]}]}}'),
