SELECT 'e5032937-7490-76bc-af2f-f7e16c900122', '3624fa47-bf75-74b2-98a1-683cb5cd8f27', 1, 'PUBLISHED', 'Context Managers & contextlib', '[{"id":"796be330-ffd1-763c-93ee-b4b9e4fc2322","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A context manager pairs setup with guaranteed teardown. "},{"type":"text","text":"with","marks":[{"type":"code"}]},{"type":"text","text":" runs the teardown however the block exits — normally, by "},{"type":"text","text":"return","marks":[{"type":"code"}]},{"type":"text","text":", or by an exception."}]}]}},"revision":1},{"id":"8a9f1e9e-481d-78c8-b593-e9a4c45c84c8","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"The protocol"}]},"revision":1},{"id":"477f56ab-80d3-782d-8297-4f896abc3997","type":"code","position":"a2","content":{"language":"python","code":"class Resource:\n    def __init__(self, name):\n        self.name = name\n    def __enter__(self):\n        print(f\"open {self.name}\")\n        return self                          # bound to the \"as\" target\n    def __exit__(self, exc_type, exc, tb):\n        print(f\"close {self.name} (error: {exc_type.__name__ if exc_type else None})\")\n        return False                         # False/None → let the exception propagate\n\nwith Resource(\"db\") as r:\n    print(\"using\", r.name)\n\ntry:\n    with Resource(\"file\"):\n        raise KeyError(\"boom\")\nexcept KeyError:\n    print(\"caught outside\")","filename":"Python"},"revision":1},{"id":"bf626339-8476-7866-b9f6-6f2941c0f185","type":"code","position":"a3","content":{"language":"text","code":"open db\nusing db\nclose db (error: None)\nopen file\nclose file (error: KeyError)\ncaught outside","filename":"Output"},"revision":1},{"id":"021dc446-bb79-7f31-9b8d-68427fac1f7c","type":"text","position":"a4","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Evaluate","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"The expression after "},{"type":"text","text":"with","marks":[{"type":"code"}]},{"type":"text","text":" produces the manager."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Enter","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"__enter__()","marks":[{"type":"code"}]},{"type":"text","text":" runs; its return value is bound to the "},{"type":"text","text":"as","marks":[{"type":"code"}]},{"type":"text","text":" name."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Body","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"The indented block runs."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Exit","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"__exit__(exc_type, exc, tb)","marks":[{"type":"code"}]},{"type":"text","text":" always runs — all three are "},{"type":"text","text":"None","marks":[{"type":"code"}]},{"type":"text","text":" if there was no exception."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Suppress?","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"If "},{"type":"text","text":"__exit__","marks":[{"type":"code"}]},{"type":"text","text":" returns a truthy value, the exception is swallowed. Almost always return "},{"type":"text","text":"False","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}]}]}},"revision":1},{"id":"c19d8d7f-0a6d-7e5e-9b62-13ee5fc33554","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"A reusable class-based manager"}]},"revision":1},{"id":"8031a5cc-be78-7df0-ae74-382bc4b7d924","type":"code","position":"a6","content":{"language":"python","code":"import time\n\nclass Timer:\n    def __enter__(self):\n        self.start = time.perf_counter()\n        return self\n    def __exit__(self, *exc):\n        self.elapsed = time.perf_counter() - self.start\n        return False\n\nwith Timer() as t:\n    sum(range(100_000))\nprint(t.elapsed > 0)          # True","filename":"Python"},"revision":1},{"id":"517f76f2-6eeb-770c-834b-a0076630d25e","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"@contextmanager","marks":[{"type":"code"}]},{"type":"text","text":": a generator becomes a manager"}]},"revision":1},{"id":"cab78cf8-2d08-7d0b-835f-1044797ef46d","type":"text","position":"a8","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Everything before "},{"type":"text","text":"yield","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"__enter__","marks":[{"type":"code"}]},{"type":"text","text":", the yielded value is the "},{"type":"text","text":"as","marks":[{"type":"code"}]},{"type":"text","text":" target, everything after is "},{"type":"text","text":"__exit__","marks":[{"type":"code"}]},{"type":"text","text":". Wrap the "},{"type":"text","text":"yield","marks":[{"type":"code"}]},{"type":"text","text":" in "},{"type":"text","text":"try","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"finally","marks":[{"type":"code"}]},{"type":"text","text":" or the cleanup is skipped when the body raises."}]}]}},"revision":1},{"id":"13ab607e-6192-7ac7-9306-4a36895738cd","type":"code","position":"a9","content":{"language":"python","code":"from contextlib import contextmanager\n\n@contextmanager\ndef temporary_setting(config, key, value):\n    old = config[key]\n    config[key] = value\n    try:\n        yield config\n    finally:\n        config[key] = old             # restored even if the body raises\n\ncfg = {\"debug\": False}\nwith temporary_setting(cfg, \"debug\", True):\n    print(cfg[\"debug\"])               # True\nprint(cfg[\"debug\"])                   # False","filename":"Python"},"revision":1},{"id":"ca5cd388-32a8-7646-b1e1-42aa8b62b1b7","type":"heading","position":"aA","content":{"level":1,"content":[{"type":"text","text":"contextlib helpers"}]},"revision":1},{"id":"9cb45496-054b-7678-96e3-96edb41e7f6b","type":"code","position":"aB","content":{"language":"python","code":"import io\nfrom contextlib import suppress, redirect_stdout, nullcontext, closing\n\nwith suppress(KeyError):                  # ignore one specific exception\n    {}[\"missing\"]\n\nbuf = io.StringIO()\nwith redirect_stdout(buf):                # capture print output\n    print(\"hidden\")\nprint(buf.getvalue().strip())             # hidden\n\ndef process(lock=None):\n    with lock or nullcontext():           # \"maybe a lock\" without an if/else\n        return \"processed\"\nprint(process())                          # processed\n\nclass Conn:\n    def close(self):\n        self.closed = True\nwith closing(Conn()) as c:                # calls c.close() on exit\n    pass\nprint(c.closed)                           # True","filename":"Python"},"revision":1},{"id":"c8b95cad-b68e-7594-9fe8-8480046ff4a1","type":"table","position":"aC","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Helper"}],[{"type":"text","text":"Purpose"}]],[[{"type":"text","text":"suppress(*excs)","marks":[{"type":"code"}]}],[{"type":"text","text":"Ignore the listed exceptions inside the block"}]],[[{"type":"text","text":"redirect_stdout(f)","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"redirect_stderr(f)","marks":[{"type":"code"}]}],[{"type":"text","text":"Temporarily send prints somewhere else"}]],[[{"type":"text","text":"closing(obj)","marks":[{"type":"code"}]}],[{"type":"text","text":"Call "},{"type":"text","text":"obj.close()","marks":[{"type":"code"}]},{"type":"text","text":" on exit, for objects without "},{"type":"text","text":"__exit__","marks":[{"type":"code"}]}]],[[{"type":"text","text":"nullcontext(value)","marks":[{"type":"code"}]}],[{"type":"text","text":"A do-nothing manager — for optional context"}]],[[{"type":"text","text":"ExitStack()","marks":[{"type":"code"}]}],[{"type":"text","text":"Enter a "},{"type":"text","text":"dynamic","marks":[{"type":"italic"}]},{"type":"text","text":" number of managers; unwinds them in reverse"}]],[[{"type":"text","text":"chdir(path)","marks":[{"type":"code"}]}],[{"type":"text","text":"Temporarily change the working directory (3.11+)"}]],[[{"type":"text","text":"ContextDecorator","marks":[{"type":"code"}]}],[{"type":"text","text":"A manager that can also be used as "},{"type":"text","text":"@decorator","marks":[{"type":"code"}]}]],[[{"type":"text","text":"asynccontextmanager","marks":[{"type":"code"}]}],[{"type":"text","text":"The "},{"type":"text","text":"async with","marks":[{"type":"code"}]},{"type":"text","text":" version of "},{"type":"text","text":"@contextmanager","marks":[{"type":"code"}]}]]]},"revision":1},{"id":"b24e4715-5914-724c-b5c4-19bc220da63d","type":"heading","position":"aD","content":{"level":1,"content":[{"type":"text","text":"ExitStack: many resources at once"}]},"revision":1},{"id":"4696e0f6-20d6-7177-a575-dce4879dbccb","type":"code","position":"aE","content":{"language":"python","code":"import tempfile\nfrom pathlib import Path\nfrom contextlib import ExitStack\n\nfolder = Path(tempfile.mkdtemp())\nnames = [\"a.txt\", \"b.txt\", \"c.txt\"]\nwith ExitStack() as stack:\n    files = [stack.enter_context(open(folder / n, \"w\", encoding=\"utf-8\")) for n in names]\n    for i, f in enumerate(files):\n        f.write(str(i))\n# every file is closed here, even if one open() had failed half-way\nprint(all(f.closed for f in files), (folder / \"c.txt\").read_text())   # True 2","filename":"Python"},"revision":1},{"id":"6dc131cb-7a79-7f6b-97b5-c947f15e60bf","type":"heading","position":"aF","content":{"level":1,"content":[{"type":"text","text":"Several managers in one "},{"type":"text","text":"with","marks":[{"type":"code"}]}]},"revision":1},{"id":"e774997b-f74e-7d00-a34f-1efbd54dc443","type":"code","position":"aG","content":{"language":"python","code":"import io\n\nsrc, dst = io.StringIO(\"copy me\"), io.StringIO()\nwith (\n    src as reader,          # parenthesised form (3.10+) allows one per line\n    dst as writer,\n):\n    writer.write(reader.read())\n    copied = writer.getvalue()\nprint(copied, src.closed, dst.closed)   # copy me True True","filename":"Python"},"revision":1},{"id":"0c8b85f1-ced5-704b-88ab-d63c23031daa","type":"heading","position":"aH","content":{"level":1,"content":[{"type":"text","text":"Async context managers"}]},"revision":1},{"id":"d1ab5673-ae30-7a7a-8a38-6840809f96d5","type":"code","position":"aI","content":{"language":"python","code":"import asyncio\nfrom contextlib import asynccontextmanager\n\n@asynccontextmanager\nasync def session(name):\n    await asyncio.sleep(0)          # e.g. open a network connection\n    try:\n        yield f\"session:{name}\"\n    finally:\n        await asyncio.sleep(0)      # e.g. close it\n\nasync def main():\n    async with session(\"api\") as s:\n        return s\n\nprint(asyncio.run(main()))          # session:api","filename":"Python"},"revision":1},{"id":"32a870f6-7ba0-75d1-8148-4d390440c32f","type":"callout","position":"aJ","content":{"variant":"tip","title":"Do","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Use "},{"type":"text","text":"with","marks":[{"type":"code"}]},{"type":"text","text":" for anything that must be released: files, locks, DB transactions, network connections, temporary state."}]}]}},"revision":1},{"id":"3b280b6a-6cd5-7084-861d-a8601f5997d0","type":"callout","position":"aK","content":{"variant":"danger","title":"Avoid","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Returning "},{"type":"text","text":"True","marks":[{"type":"code"}]},{"type":"text","text":" from "},{"type":"text","text":"__exit__","marks":[{"type":"code"}]},{"type":"text","text":" \"just in case\" — it silently swallows every exception raised in the block."}]}]}},"revision":1},{"id":"3ed5c4be-8c46-72b9-a548-44f156e48880","type":"question","position":"aL","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What happens if an exception occurs inside a with block?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"__exit__","marks":[{"type":"code"}]},{"type":"text","text":" is called with the exception type, value and traceback. If it returns a falsy value the exception continues propagating after cleanup; if it returns "},{"type":"text","text":"True","marks":[{"type":"code"}]},{"type":"text","text":" the exception is suppressed and execution continues after the "},{"type":"text","text":"with","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"741c57ff-6e2e-7fec-ade3-35d80e0aaec6","type":"question","position":"aM","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you write a context manager without a class?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Decorate a generator with "},{"type":"text","text":"contextlib.contextmanager","marks":[{"type":"code"}]},{"type":"text","text":": setup, "},{"type":"text","text":"yield","marks":[{"type":"code"}]},{"type":"text","text":" the resource inside "},{"type":"text","text":"try","marks":[{"type":"code"}]},{"type":"text","text":", clean up in "},{"type":"text","text":"finally","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"0ac679fb-c9f4-7ae3-8135-37da01f44148","type":"question","position":"aN","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When would you use ExitStack?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When the number of resources is only known at runtime (open N files), or when you need to conditionally enter managers or register arbitrary cleanup callbacks with "},{"type":"text","text":"stack.callback(func)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
