SELECT '44d08441-d1db-7ba3-a10e-2c2d8b8d30ad', '6c8fdbdd-a3ef-73d4-87dd-f45de12925aa', 1, 'PUBLISHED', 'Dates & Times (datetime)', '[{"id":"471a531d-e408-721d-960f-7ecd740641cc","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"datetime","marks":[{"type":"code"}]},{"type":"text","text":" models calendar dates, clock times and durations. The golden rule: store and compute in "},{"type":"text","text":"UTC with time-zone-aware objects","marks":[{"type":"bold"}]},{"type":"text","text":", convert to local time only for display."}]}]}},"revision":1},{"id":"568abe91-8ccd-7931-b206-4e2ef244b987","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"The four core types"}]},"revision":1},{"id":"2bfa9dfd-3bc6-79b3-beb3-cabd25ae411b","type":"table","position":"a2","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Type"}],[{"type":"text","text":"Holds"}],[{"type":"text","text":"Example"}]],[[{"type":"text","text":"date","marks":[{"type":"code"}]}],[{"type":"text","text":"Year, month, day"}],[{"type":"text","text":"date(2026, 9, 29)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"time","marks":[{"type":"code"}]}],[{"type":"text","text":"Hour … microsecond (+ optional tz)"}],[{"type":"text","text":"time(14, 5)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"datetime","marks":[{"type":"code"}]}],[{"type":"text","text":"A date and a time (+ optional tz)"}],[{"type":"text","text":"datetime(2026, 9, 29, 14, 5)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"timedelta","marks":[{"type":"code"}]}],[{"type":"text","text":"A duration: days, seconds, microseconds"}],[{"type":"text","text":"timedelta(hours=36)","marks":[{"type":"code"}]}]]]},"revision":1},{"id":"44b7f2c1-1dfb-7f3b-b755-8786555c1856","type":"code","position":"a3","content":{"language":"python","code":"from datetime import date, datetime, timedelta\n\nd = date(2026, 9, 29)\nprint(d.year, d.month, d.day, d.weekday())         # 2026 9 29 1   ← Monday is 0\nprint(d.isoformat(), d.isocalendar().week)         # 2026-09-29 40\n\ndt = datetime(2026, 9, 29, 14, 5)\nprint(dt.date(), dt.time())                        # 2026-09-29 14:05:00\nprint(dt.replace(hour=9, minute=0))                # 2026-09-29 09:00:00","filename":"Python"},"revision":1},{"id":"9bbe576d-ddc4-7373-9e18-d42591e42a96","type":"callout","position":"a4","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"date.today()","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"datetime.now()","marks":[{"type":"code"}]},{"type":"text","text":" depend on when and where the code runs — fine in programs, but never hard-code their output in tests. Pass a fixed "},{"type":"text","text":"datetime","marks":[{"type":"code"}]},{"type":"text","text":" (or a clock function) into code you want to test."}]}]}},"revision":1},{"id":"1d38f987-4560-7409-893a-37c03e522336","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Arithmetic with timedelta"}]},"revision":1},{"id":"8d09bf6a-3c06-7236-9c65-672c24b0696b","type":"code","position":"a6","content":{"language":"python","code":"from datetime import date, datetime, timedelta\n\nprint(date(2026, 12, 25) - date(2026, 9, 29))          # 87 days, 0:00:00\nprint((date(2026, 12, 25) - date(2026, 9, 29)).days)   # 87\n\nstart = datetime(2026, 1, 31, 22, 30)\nprint(start + timedelta(days=1, hours=3))              # 2026-02-02 01:30:00\nprint(start + timedelta(days=30))                      # 2026-03-02 22:30:00   ← no \"add a month\" in timedelta\n\nspan = timedelta(hours=36, minutes=15)\nprint(span, span.total_seconds())                      # 1 day, 12:15:00 130500.0\nprint(datetime(2026, 1, 1) < datetime(2026, 6, 1))     # True","filename":"Python"},"revision":1},{"id":"5340d3c5-8634-7cab-b372-91901050426a","type":"callout","position":"a7","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"timedelta","marks":[{"type":"code"}]},{"type":"text","text":" has no months or years (their length varies). For “same day next month”, compute it yourself or use "},{"type":"text","text":"dateutil.relativedelta","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"01c62444-b19a-7b2a-ac97-393b54180381","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"Formatting & parsing: strftime / strptime"}]},"revision":1},{"id":"904ab5a9-3d50-7cad-b389-81ab0c205ab2","type":"code","position":"a9","content":{"language":"python","code":"from datetime import datetime\n\ndt = datetime(2026, 9, 29, 14, 5, 9)\nprint(dt.strftime(\"%d/%m/%Y %H:%M\"))              # 29/09/2026 14:05\nprint(dt.strftime(\"%A, %d %B %Y at %I:%M %p\"))    # Tuesday, 29 September 2026 at 02:05 PM\nprint(f\"{dt:%Y-%m-%d}\")                           # 2026-09-29   ← format spec in an f-string\n\nparsed = datetime.strptime(\"29-Sep-2026 18:30\", \"%d-%b-%Y %H:%M\")\nprint(parsed)                                     # 2026-09-29 18:30:00\nprint(datetime.fromisoformat(\"2026-09-29T14:05:00+05:30\").utcoffset())   # 5:30:00","filename":"Python"},"revision":1},{"id":"f1182414-76be-7a3b-90cd-6b900949544f","type":"table","position":"aA","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Code"}],[{"type":"text","text":"Meaning"}],[{"type":"text","text":"Example"}]],[[{"type":"text","text":"%Y","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"%y","marks":[{"type":"code"}]}],[{"type":"text","text":"Year, 4 / 2 digits"}],[{"type":"text","text":"2026","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"26","marks":[{"type":"code"}]}]],[[{"type":"text","text":"%m","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"%B","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"%b","marks":[{"type":"code"}]}],[{"type":"text","text":"Month number / full name / short name"}],[{"type":"text","text":"09","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"September","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"Sep","marks":[{"type":"code"}]}]],[[{"type":"text","text":"%d","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"%j","marks":[{"type":"code"}]}],[{"type":"text","text":"Day of month / day of year"}],[{"type":"text","text":"29","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"272","marks":[{"type":"code"}]}]],[[{"type":"text","text":"%H","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"%I","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"%p","marks":[{"type":"code"}]}],[{"type":"text","text":"Hour 24h / 12h / AM-PM"}],[{"type":"text","text":"14","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"02","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"PM","marks":[{"type":"code"}]}]],[[{"type":"text","text":"%M","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"%S","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"%f","marks":[{"type":"code"}]}],[{"type":"text","text":"Minute / second / microsecond"}],[{"type":"text","text":"05","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"09","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"000000","marks":[{"type":"code"}]}]],[[{"type":"text","text":"%A","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"%a","marks":[{"type":"code"}]}],[{"type":"text","text":"Weekday full / short"}],[{"type":"text","text":"Tuesday","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"Tue","marks":[{"type":"code"}]}]],[[{"type":"text","text":"%z","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"%Z","marks":[{"type":"code"}]}],[{"type":"text","text":"UTC offset / zone name"}],[{"type":"text","text":"+0530","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"IST","marks":[{"type":"code"}]}]]]},"revision":1},{"id":"f882d387-e7d3-7d5f-8702-b7ebfbe790ac","type":"callout","position":"aB","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Prefer ISO 8601 ("},{"type":"text","text":"2026-09-29T14:05:00+05:30","marks":[{"type":"code"}]},{"type":"text","text":") for storage and APIs: "},{"type":"text","text":"isoformat()","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"fromisoformat()","marks":[{"type":"code"}]},{"type":"text","text":" round-trip it, and it sorts correctly as text."}]}]}},"revision":1},{"id":"5437a6e4-5542-7c31-aab5-873bb0898422","type":"heading","position":"aC","content":{"level":1,"content":[{"type":"text","text":"Naive vs aware; time zones with zoneinfo"}]},"revision":1},{"id":"8754fc95-2f45-77a3-9b6b-cbec5b35cfe3","type":"callout","position":"aD","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Naive vs aware","marks":[{"type":"bold"}]},{"type":"text","text":" — a "},{"type":"text","text":"naive","marks":[{"type":"italic"}]},{"type":"text","text":" "},{"type":"text","text":"datetime","marks":[{"type":"code"}]},{"type":"text","text":" has no "},{"type":"text","text":"tzinfo","marks":[{"type":"code"}]},{"type":"text","text":" — it''s just wall-clock numbers. An "},{"type":"text","text":"aware","marks":[{"type":"italic"}]},{"type":"text","text":" one carries a UTC offset, so it denotes one exact instant."}]}]}},"revision":1},{"id":"d3655131-385d-7054-b502-30dee54741ef","type":"code","position":"aE","content":{"language":"python","code":"from datetime import datetime, timezone\nfrom zoneinfo import ZoneInfo\n\nutc = datetime(2026, 3, 8, 12, 0, tzinfo=timezone.utc)      # an exact instant\nprint(utc.astimezone(ZoneInfo(\"Asia/Kolkata\")))             # 2026-03-08 17:30:00+05:30\nprint(utc.astimezone(ZoneInfo(\"America/New_York\")))         # 2026-03-08 08:00:00-04:00   ← DST began that morning\n\nmeeting = datetime(2026, 9, 29, 9, 0, tzinfo=ZoneInfo(\"Europe/London\"))\nprint(meeting.astimezone(timezone.utc))                     # 2026-09-29 08:00:00+00:00\n\nnaive = datetime(2026, 1, 1)\ntry:\n    naive < utc\nexcept TypeError:\n    print(\"can''t compare naive and aware\")                  # can''t compare naive and aware","filename":"Python"},"revision":1},{"id":"a384c76b-07c0-707b-9b02-cc93c0c9c0c2","type":"callout","position":"aF","content":{"variant":"tip","title":"Do","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Use "},{"type":"text","text":"datetime.now(timezone.utc)","marks":[{"type":"code"}]},{"type":"text","text":" and store UTC; convert with "},{"type":"text","text":"astimezone(ZoneInfo(...))","marks":[{"type":"code"}]},{"type":"text","text":" when displaying."}]}]}},"revision":1},{"id":"8831e658-79a0-70cf-a3d2-13277305b459","type":"callout","position":"aG","content":{"variant":"danger","title":"Avoid","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"datetime.utcnow()","marks":[{"type":"code"}]},{"type":"text","text":" (deprecated since 3.12 — it returns a "},{"type":"text","text":"naive","marks":[{"type":"italic"}]},{"type":"text","text":" value that looks local) or storing local times without an offset."}]}]}},"revision":1},{"id":"55a178dc-2377-7b6a-bda6-9dfaa528c939","type":"heading","position":"aH","content":{"level":1,"content":[{"type":"text","text":"Timestamps, "},{"type":"text","text":"time","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"calendar","marks":[{"type":"code"}]}]},"revision":1},{"id":"81899807-8b7f-7c55-8900-642b9298bf7d","type":"code","position":"aI","content":{"language":"python","code":"import time, calendar\nfrom datetime import datetime, timezone\n\ninstant = datetime(2026, 9, 29, tzinfo=timezone.utc)\nts = instant.timestamp()                                   # seconds since 1970-01-01 UTC\nprint(ts)                                                  # 1790640000.0\nprint(datetime.fromtimestamp(ts, tz=timezone.utc))         # 2026-09-29 00:00:00+00:00\n\nprint(calendar.isleap(2028), calendar.monthrange(2026, 2)[1])   # True 28\n\nt0 = time.perf_counter()                                   # for measuring durations\nsum(range(10_000))\nprint(time.perf_counter() - t0 >= 0)                       # True","filename":"Python"},"revision":1},{"id":"d393c6c0-8f43-730e-adce-f4194831d41c","type":"table","position":"aJ","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Clock"}],[{"type":"text","text":"Use for"}]],[[{"type":"text","text":"time.time()","marks":[{"type":"code"}]}],[{"type":"text","text":"Wall-clock timestamp (can jump if the system clock changes)"}]],[[{"type":"text","text":"time.monotonic()","marks":[{"type":"code"}]}],[{"type":"text","text":"Timeouts and intervals — never goes backwards"}]],[[{"type":"text","text":"time.perf_counter()","marks":[{"type":"code"}]}],[{"type":"text","text":"Benchmarking — highest resolution"}]],[[{"type":"text","text":"time.sleep(s)","marks":[{"type":"code"}]}],[{"type":"text","text":"Pause the current thread"}]]]},"revision":1},{"id":"e78059d1-1e96-73ee-8e62-29416dc42f08","type":"question","position":"aK","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the difference between a naive and an aware datetime?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A naive datetime has no time-zone information, so it can''t be mapped to a single instant; an aware one has "},{"type":"text","text":"tzinfo","marks":[{"type":"code"}]},{"type":"text","text":" (an offset), so comparisons and arithmetic across zones are correct. Python refuses to compare the two."}]}]}},"revision":1},{"id":"abedc4fe-8c47-7484-9ea5-30ed36a97cd4","type":"question","position":"aL","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How should you store timestamps in a database or API?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"As UTC — either an aware datetime / "},{"type":"text","text":"TIMESTAMP WITH TIME ZONE","marks":[{"type":"code"}]},{"type":"text","text":", or an ISO 8601 string with an offset ("},{"type":"text","text":"2026-09-29T08:00:00+00:00","marks":[{"type":"code"}]},{"type":"text","text":"). Convert to the user''s zone only when displaying."}]}]}},"revision":1},{"id":"8f57d9bb-029a-7e1f-a5a3-603f2d0fac42","type":"question","position":"aM","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why not use time.time() to measure how long code takes?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"It follows the system clock, which can be adjusted (NTP, manual changes). Use "},{"type":"text","text":"time.perf_counter()","marks":[{"type":"code"}]},{"type":"text","text":" (or "},{"type":"text","text":"monotonic()","marks":[{"type":"code"}]},{"type":"text","text":"), which only moves forward."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
