SELECT 'b81267d9-8e51-7893-8189-ec3e052522f4', 'a3be7d02-03e5-7feb-9c56-389f93e0defd', 1, 'PUBLISHED', 'Magic (Dunder) Methods', '[{"id":"602d8fe3-2ea8-74bc-aedc-eee0e04cc224","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Double-underscore methods let your objects plug into Python''s syntax: printing, "},{"type":"text","text":"==","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"len()","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"[]","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"for","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"+","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"with","marks":[{"type":"code"}]},{"type":"text","text":" and more."}]}]}},"revision":1},{"id":"28708072-045d-796f-a3ff-ff808d4beacc","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Representation"}]},"revision":1},{"id":"7807030e-7ccb-7331-b05f-438e82370266","type":"code","position":"a2","content":{"language":"python","code":"class Money:\n    def __init__(self, amount, cur=\"INR\"):\n        self.amount, self.cur = amount, cur\n    def __repr__(self):                  # unambiguous, for developers\n        return f\"Money({self.amount!r}, {self.cur!r})\"\n    def __str__(self):                   # readable, for users\n        return f\"{self.amount:.2f} {self.cur}\"\n\nm = Money(250)\nprint(repr(m))        # Money(250, ''INR'')\nprint(m)              # 250.00 INR\nprint([m])            # [Money(250, ''INR'')]","filename":"Python"},"revision":1},{"id":"717ad00c-e076-7768-a0f1-5754f75fce70","type":"callout","position":"a3","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Containers show their items with "},{"type":"text","text":"repr()","marks":[{"type":"code"}]},{"type":"text","text":". Always define "},{"type":"text","text":"__repr__","marks":[{"type":"code"}]},{"type":"text","text":"; add "},{"type":"text","text":"__str__","marks":[{"type":"code"}]},{"type":"text","text":" when a friendlier form helps."}]}]}},"revision":1},{"id":"4eec95d8-b847-7d2d-b094-198299969d50","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Equality, hashing & ordering"}]},"revision":1},{"id":"148b72ba-baee-7f16-b5d4-e5afd80ec8f8","type":"code","position":"a5","content":{"language":"python","code":"from functools import total_ordering\n\n@total_ordering\nclass Version:\n    def __init__(self, major, minor):\n        self.key = (major, minor)\n    def __eq__(self, other):\n        return isinstance(other, Version) and self.key == other.key\n    def __hash__(self):                   # equal objects must hash equally\n        return hash(self.key)\n    def __lt__(self, other):\n        return self.key < other.key\n\nv1, v2 = Version(1, 2), Version(1, 10)\nprint(v1 < v2, v1 >= v2, v1 == Version(1, 2))   # True False True\nprint(len({v1, Version(1, 2)}))                  # 1","filename":"Python"},"revision":1},{"id":"aef26f2d-23cf-79df-8b97-47fdc6a10b22","type":"callout","position":"a6","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Defining "},{"type":"text","text":"__eq__","marks":[{"type":"code"}]},{"type":"text","text":" without "},{"type":"text","text":"__hash__","marks":[{"type":"code"}]},{"type":"text","text":" makes instances "},{"type":"text","text":"unhashable","marks":[{"type":"bold"}]},{"type":"text","text":" (Python sets "},{"type":"text","text":"__hash__ = None","marks":[{"type":"code"}]},{"type":"text","text":"). If objects can change, don''t make them hashable."}]}]}},"revision":1},{"id":"1635dd8c-43db-71a8-8d16-1a5cc8c44e9f","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Container & iteration protocols"}]},"revision":1},{"id":"6bc249da-9797-766d-b6ac-137ebb3f104c","type":"code","position":"a8","content":{"language":"python","code":"class Playlist:\n    def __init__(self, *songs):\n        self._songs = list(songs)\n    def __len__(self):\n        return len(self._songs)\n    def __getitem__(self, i):             # enables p[i], slicing and iteration\n        return self._songs[i]\n    def __contains__(self, song):\n        return song in self._songs\n\np = Playlist(\"a\", \"b\", \"c\")\nprint(len(p), p[0], p[-1], \"b\" in p)      # 3 a c True\nprint(list(p), p[1:])                     # [''a'', ''b'', ''c''] [''b'', ''c'']","filename":"Python"},"revision":1},{"id":"e7389c94-d0aa-70ac-beeb-52c283a3fb16","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Operators & callables"}]},"revision":1},{"id":"71361e80-3762-7ee3-a4cb-39c5a3680e46","type":"code","position":"aA","content":{"language":"python","code":"class Vec:\n    def __init__(self, x, y):\n        self.x, self.y = x, y\n    def __add__(self, o):\n        return Vec(self.x + o.x, self.y + o.y)\n    def __mul__(self, k):\n        return Vec(self.x * k, self.y * k)\n    def __abs__(self):\n        return (self.x ** 2 + self.y ** 2) ** 0.5\n    def __repr__(self):\n        return f\"Vec({self.x}, {self.y})\"\n\nclass Adder:\n    def __init__(self, n):\n        self.n = n\n    def __call__(self, x):                # instances become callable\n        return x + self.n\n\nprint(Vec(1, 2) + Vec(3, 4), Vec(3, 4) * 2, abs(Vec(3, 4)))   # Vec(4, 6) Vec(6, 8) 5.0\nprint(Adder(10)(5))                                            # 15","filename":"Python"},"revision":1},{"id":"24fdcd06-4c5a-7532-bbd8-3c46357f0278","type":"table","position":"aB","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Syntax"}],[{"type":"text","text":"Calls"}]],[[{"type":"text","text":"str(x)","marks":[{"type":"code"}]},{"type":"text","tex