SELECT '2950865d-678f-723c-8f8c-79b6f81f1477', '329c7bf2-1c4c-77df-96b0-1b08bc46c0d5', 1, 'PUBLISHED', 'Enums in Depth', '[{"id":"faac9676-ec56-7f60-9a45-1739a9196c9e","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An "},{"type":"text","text":"Enum","marks":[{"type":"code"}]},{"type":"text","text":" is a fixed set of named, unique constants. Members are singletons, are iterable in definition order, and make invalid states unrepresentable — no more magic strings and numbers."}]}]}},"revision":1},{"id":"913ce61d-a486-768b-ab97-df7d95649537","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Basics: names, values, lookup"}]},"revision":1},{"id":"a5f2f378-f0c9-733b-8d0e-1fba160a2796","type":"code","position":"a2","content":{"language":"python","code":"from enum import Enum\n\nclass Color(Enum):\n    RED = 1\n    GREEN = 2\n    BLUE = 3\n\nprint(Color.RED, repr(Color.RED))            # Color.RED <Color.RED: 1>\nprint(Color(2), Color[\"BLUE\"])               # Color.GREEN Color.BLUE\nprint(Color.RED.name, Color.RED.value)       # RED 1\nprint(len(Color), [c.name for c in Color])   # 3 [''RED'', ''GREEN'', ''BLUE'']\nprint(Color.RED == 1, Color.RED is Color(1)) # False True\ntry:\n    Color(7)\nexcept ValueError as e:\n    print(e)                                 # 7 is not a valid Color","filename":"Python"},"revision":1},{"id":"59148e68-11db-774d-bb65-ea348f576ce6","type":"table","position":"a3","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"You have"}],[{"type":"text","text":"You want"}],[{"type":"text","text":"Write"}]],[[{"type":"text","text":"a value (e.g. from a DB)"}],[{"type":"text","text":"the member"}],[{"type":"text","text":"Color(2)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"a name (e.g. from config)"}],[{"type":"text","text":"the member"}],[{"type":"text","text":"Color[''GREEN'']","marks":[{"type":"code"}]}]],[[{"type":"text","text":"a member"}],[{"type":"text","text":"its name / value"}],[{"type":"text","text":"m.name","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"m.value","marks":[{"type":"code"}]}]],[[{"type":"text","text":"the class"}],[{"type":"text","text":"all members"}],[{"type":"text","text":"list(Color)","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"Color.__members__","marks":[{"type":"code"}]}]]]},"revision":1},{"id":"7cf138e9-07fc-7489-b1e7-9141edc0c23b","type":"callout","position":"a4","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Members are "},{"type":"text","text":"singletons","marks":[{"type":"bold"}]},{"type":"text","text":", so compare them with "},{"type":"text","text":"is","marks":[{"type":"code"}]},{"type":"text","text":" (or "},{"type":"text","text":"==","marks":[{"type":"code"}]},{"type":"text","text":"). A plain "},{"type":"text","text":"Enum","marks":[{"type":"code"}]},{"type":"text","text":" member never equals its raw value: "},{"type":"text","text":"Color.RED == 1","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"False","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"bb9f3726-0c31-7cd8-8c7d-be2719a3bcbc","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"auto() and generated values"}]},"revision":1},{"id":"44d2f314-2951-7954-882d-5faf73be8a3f","type":"code","position":"a6","content":{"language":"python","code":"from enum import Enum, auto\n\nclass Status(Enum):\n    TODO = auto()\n    DOING = auto()\n    DONE = auto()\n\nclass Method(Enum):\n    @staticmethod\n    def _generate_next_value_(name, start, count, last_values):\n        return name.lower()                # customise what auto() produces\n    GET = auto()\n    POST = auto()\n\nprint([s.value for s in Status])           # [1, 2, 3]\nprint(Method.POST.value)                   # post","filename":"Python"},"revision":1},{"id":"d3a28542-f8a0-76cb-ba49-d29e9bfebff3","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Aliases and @unique"}]},"revision":1},{"id":"228c0173-095a-73a3-adaa-cfbbd47b7115","type":"code","position":"a8","content":{"language":"python","code":"from enum import Enum, unique\n\nclass Shape(Enum):\n    SQUARE = 2\n    CIRCLE = 3\n    BOX = 2                                  # same value → an alias of SQUARE\n\nprint(Shape.BOX, Shape(2))                   # Shape.SQUARE Shape.SQUARE\nprint([s.name for s in Shape], list(Shape.__members__))   # [''SQUARE'', ''CIRCLE''] [''SQUARE'', ''CIRCLE'', ''BOX'']\n\ntry:\n    @unique\n    class Bad(Enum):\n        A = 1\n        B = 1\nexcept ValueError as e:\n    print(e)                                 # duplicate values found in <enum ''Bad''>: B -> A","filename":"Python"},"revision":1},{"id":"c2744e70-16e5-7d47-a1ed-d5d61facd4b1","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"IntEnum, StrEnum & Flag"}]},"revision":1},{"id":"c7d051b0-67ff-7107-89f0-776a7046b79c","type":"code","position":"aA","content":{"language":"python","code":"from enum import IntEnum, StrEnum, auto\n\nclass Priority(IntEnum):\n    LOW = 1\n    HIGH = 3\n\nclass Env(StrEnum):                          # 3.11+\n    DEV = auto()                             # StrEnum''s auto() → the lower-cased name\n    PROD = auto()\n\nprint(Priority.HIGH > Priority.LOW, Priority.HIGH + 1)   # True 4\nprint(sorted([3, Priority.LOW]))                         # [<Priority.LOW: 1>, 3]\nprint(Env.PROD, Env.PROD == \"prod\", Env.DEV.upper())     # prod True DEV\nprint(f\"api-{Env.DEV}.example.com\")                     # api-dev.example.com","filename":"Python"},"revision":1},{"id":"8f296661-f48d-75af-9663-90cbf24006a4","type":"code","position":"aB","content":{"language":"python","code":"from enum import Flag, auto\n\nclass Perm(Flag):\n    READ = auto()        # 1\n    WRITE = auto()       # 2\n    EXEC = auto()        # 4\n    RW = READ | WRITE    # a named combination\n\np = Perm.READ | Perm.EXEC\nprint(p)                                         # Perm.READ|EXEC\nprint(Perm.READ in p, Perm.WRITE in p)           # True False\nprint(Perm.RW.value, [m.name for m in Perm.RW])  # 3 [''READ'', ''WRITE'']\nprint(p & ~Perm.EXEC, bool(Perm(0)))             # Perm.READ False","filename":"Python"},"revision":1},{"id":"bb997dbc-a8b3-7121-bb25-e666dc21d4b9","type":"table","position":"aC","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Type"}],[{"type":"text","text":"Members are also…"}],[{"type":"text","text":"Use when"}]],[[{"type":"text","text":"Enum","marks":[{"type":"code"}]}],[{"type":"text","text":"nothing else"}],[{"type":"text","text":"Default choice — strict, can''t be mixed up with ints/strings"}]],[[{"type":"text","text":"IntEnum","marks":[{"type":"code"}]}],[{"type":"text","text":"int","marks":[{"type":"code"}]},{"type":"text","text":"s"}],[{"type":"text","text":"Interop with code/protocols that expect integers (HTTP status, DB codes)"}]],[[{"type":"text","text":"StrEnum","marks":[{"type":"code"}]}],[{"type":"text","text":"str","marks":[{"type":"code"}]},{"type":"text","text":"s"}],[{"type":"text","text":"Values go into JSON, URLs, logs, config files"}]],[[{"type":"text","text":"Flag","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"IntFlag","marks":[{"type":"code"}]}],[{"type":"text","text":"bit flags"}],[{"type":"text","text":"Combinable options: permissions, feature toggles"}]]]},"revision":1},{"id":"c2010407-2c74-7440-bb17-ff66246de871","type":"callout","position":"aD","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"IntEnum","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"StrEnum","marks":[{"type":"code"}]},{"type":"text","text":" members compare equal to raw ints/strings — convenient, but it gives up some of the type safety that makes enums useful. Prefer plain "},{"type":"text","text":"Enum","marks":[{"type":"code"}]},{"type":"text","text":" unless you need the interop."}]}]}},"revision":1},{"id":"90488d2d-d974-750b-bd57-a3166cb7fdc7","type":"heading","position":"aE","content":{"level":1,"content":[{"type":"text","text":"Methods, properties & data on members"}]},"revision":1},{"id":"b7f1f41b-7992-7be4-b168-40b3a40ea3f0","type":"code","position":"aF","content":{"language":"python","code":"from enum import Enum\n\nclass Planet(Enum):\n    MERCURY = (3.303e23, 2.4397e6)\n    EARTH = (5.976e24, 6.37814e6)\n\n    def __init__(self, mass, radius):       # the tuple value is unpacked into __init__\n        self.mass, self.radius = mass, radius\n\n    @property\n    def gravity(self):\n        return round(6.673e-11 * self.mass / self.radius ** 2, 2)\n\n    @classmethod\n    def heaviest(cls):\n        return max(cls, key=lambda p: p.mass)\n\nprint(Planet.EARTH.gravity, Planet.heaviest().name)   # 9.8 EARTH","filename":"Python"},"revision":1},{"id":"74cb34b8-b6c4-7780-a067-9489b730a662","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Enums in match & JSON"}]},"revision":1},{"id":"711f6f79-ba31-75ff-b500-b3f5d3301e7e","type":"code","position":"aH","content":{"language":"python","code":"import json\nfrom enum import Enum, StrEnum\n\nclass Light(Enum):\n    RED = \"stop\"\n    YELLOW = \"slow\"\n    GREEN = \"go\"\n\ndef action(light):\n    match light:\n        case Light.RED | Light.YELLOW:        # dotted names are value patterns\n            return \"brake\"\n        case Light.GREEN:\n            return \"drive\"\n\nprint(action(Light.YELLOW), action(Light(\"go\")))              # brake drive\n\nclass Role(StrEnum):\n    ADMIN = \"admin\"\n\nprint(json.dumps({\"role\": Role.ADMIN}))                       # {\"role\": \"admin\"}\ntry:\n    json.dumps({\"light\": Light.RED})\nexcept TypeError:\n    print(\"plain Enum is not JSON serializable\")              # plain Enum is not JSON serializable\nprint(json.dumps({\"light\": Light.RED}, default=lambda e: e.value))   # {\"light\": \"stop\"}\nprint(Light(json.loads(''{\"light\": \"stop\"}'')[\"light\"]))       # Light.RED","filename":"Python"},"revision":1},{"id":"3cff8a0e-7834-7df5-95be-5e68afd81fcd","type":"heading","position":"aI","content":{"level":1,"content":[{"type":"text","text":"Interview angle"}]},"revision":1},{"id":"ee4d4249-182c-7d41-93b3-9531128df26b","type":"question","position":"aJ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why use an Enum instead of string or int constants?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Typos become "},{"type":"text","text":"AttributeError","marks":[{"type":"code"}]},{"type":"text","text":"s instead of silent bugs, the set of valid values is explicit and iterable, members carry a readable name in logs and reprs, and type checkers can verify that a function only receives valid members (and that a "},{"type":"text","text":"match","marks":[{"type":"code"}]},{"type":"text","text":" handles all of them)."}]}]}},"revision":1},{"id":"6362cb80-418a-77e2-ba1a-6a6ff24244a5","type":"question","position":"aK","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you convert between an enum and its stored value?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Member.value","marks":[{"type":"code"}]},{"type":"text","text":" to store it (DB/JSON), "},{"type":"text","text":"EnumClass(value)","marks":[{"type":"code"}]},{"type":"text","text":" to get the member back (raises "},{"type":"text","text":"ValueError","marks":[{"type":"code"}]},{"type":"text","text":" for unknown values), and "},{"type":"text","text":"EnumClass[name]","marks":[{"type":"code"}]},{"type":"text","text":" to look up by name."}]}]}},"revision":1},{"id":"7dc058f7-6908-7b95-8f73-1029e773892d","type":"question","position":"aL","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is an enum alias?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A second name defined with the same value. It resolves to the first member ("},{"type":"text","text":"Shape.BOX is Shape.SQUARE","marks":[{"type":"code"}]},{"type":"text","text":") and is skipped during iteration. Decorate the class with "},{"type":"text","text":"@unique","marks":[{"type":"code"}]},{"type":"text","text":" to forbid aliases."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
