  ('faac9676-ec56-7f60-9a45-1739a9196c9e', 'a0', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An "},{"type":"text","text":"Enum","marks":[{"type":"code"}]},{"type":"text","text":" is a fixed set of named, unique constants. Members are singletons, are iterable in definition order, and make invalid states unrepresentable — no more magic strings and numbers."}]}]}}'),
  ('913ce61d-a486-768b-ab97-df7d95649537', 'a1', 'heading', '{"level":1,"content":[{"type":"text","text":"Basics: names, values, lookup"}]}'),
  ('a5f2f378-f0c9-733b-8d0e-1fba160a2796', 'a2', 'code', '{"language":"python","code":"from enum import Enum\n\nclass Color(Enum):\n    RED = 1\n    GREEN = 2\n    BLUE = 3\n\nprint(Color.RED, repr(Color.RED))            # Color.RED <Color.RED: 1>\nprint(Color(2), Color[\"BLUE\"])               # Color.GREEN Color.BLUE\nprint(Color.RED.name, Color.RED.value)       # RED 1\nprint(len(Color), [c.name for c in Color])   # 3 [''RED'', ''GREEN'', ''BLUE'']\nprint(Color.RED == 1, Color.RED is Color(1)) # False True\ntry:\n    Color(7)\nexcept ValueError as e:\n    print(e)                                 # 7 is not a valid Color","filename":"Python"}'),
  ('59148e68-11db-774d-bb65-ea348f576ce6', 'a3', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"You have"}],[{"type":"text","text":"You want"}],[{"type":"text","text":"Write"}]],[[{"type":"text","text":"a value (e.g. from a DB)"}],[{"type":"text","text":"the member"}],[{"type":"text","text":"Color(2)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"a name (e.g. from config)"}],[{"type":"text","text":"the member"}],[{"type":"text","text":"Color[''GREEN'']","marks":[{"type":"code"}]}]],[[{"type":"text","text":"a member"}],[{"type":"text","text":"its name / value"}],[{"type":"text","text":"m.name","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"m.value","marks":[{"type":"code"}]}]],[[{"type":"text","text":"the class"}],[{"type":"text","text":"all members"}],[{"type":"text","text":"list(Color)","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"Color.__members__","marks":[{"type":"code"}]}]]]}'),
  ('7cf138e9-07fc-7489-b1e7-9141edc0c23b', 'a4', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Members are "},{"type":"text","text":"singletons","marks":[{"type":"bold"}]},{"type":"text","text":", so compare them with "},{"type":"text","text":"is","marks":[{"type":"code"}]},{"type":"text","text":" (or "},{"type":"text","text":"==","marks":[{"type":"code"}]},{"type":"text","text":"). A plain "},{"type":"text","text":"Enum","marks":[{"type":"code"}]},{"type":"text","text":" member never equals its raw value: "},{"type":"text","text":"Color.RED == 1","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"False","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('bb9f3726-0c31-7cd8-8c7d-be2719a3bcbc', 'a5', 'heading', '{"level":1,"content":[{"type":"text","text":"auto() and generated values"}]}'),
  ('44d2f314-2951-7954-882d-5faf73be8a3f', 'a6', 'code', '{"language":"python","code":"from enum import Enum, auto\n\nclass Status(Enum):\n    TODO = auto()\n    DOING = auto()\n    DONE = auto()\n\nclass Method(Enum):\n    @staticmethod\n    def _generate_next_value_(name, start, count, last_values):\n        return name.lower()                # customise what auto() produces\n    GET = auto()\n    POST = auto()\n\nprint([s.value for s in Status])           # [1, 2, 3]\nprint(Method.POST.value)                   # post","filename":"Python"}'),
  ('d3a28542-f8a0-76cb-ba49-d29e9bfebff3', 'a7', 'heading', '{"level":1,"content":[{"type":"text","text":"Aliases and @unique"}]}'),
  ('228c0173-095a-73a3-adaa-cfbbd47b7115', 'a8', 'code', '{"language":"python","code":"from enum import Enum, unique\n\nclass Shape(Enum):\n    SQUARE = 2\n    CIRCLE = 3\n    BOX = 2                                  # same value → an alias of SQUARE\n\nprint(Shape.BOX, Shape(2))                   # Shape.SQUARE Shape.SQUARE\nprint([s.name for s in Shape], list(Shape.__members__))   # [''SQUARE'', ''CIRCLE''] [''SQUARE'', ''CIRCLE'', ''BOX'']\n\ntry:\n    @unique\n    class Bad(Enum):\n        A = 1\n        B = 1\nexcept ValueError as e:\n    print(e)                                 # duplicate values found in <enum ''Bad''>: B -> A","filename":"Python"}'),
  ('c2744e70-16e5-7d47-a1ed-d5d61facd4b1', 'a9', 'heading', '{"level":1,"content":[{"type":"text","text":"IntEnum, StrEnum & Flag"}]}'),
  ('c7d051b0-67ff-7107-89f0-776a7046b79c', 'aA', 'code', '{"language":"python","code":"from enum import IntEnum, StrEnum, auto\n\nclass Priority(IntEnum):\n    LOW = 1\n    HIGH = 3\n\nclass Env(StrEnum):                          # 3.11+\n    DEV = auto()                             # StrEnum''s auto() → the lower-cased name\n    PROD = auto()\n\nprint(Priority.HIGH > Priority.LOW, Priority.HIGH + 1)   # True 4\nprint(sorted([3, Priority.LOW]))                         # [<Priority.LOW: 1>, 3]\nprint(Env.PROD, Env.PROD == \"prod\", Env.DEV.upper())     # prod True DEV\nprint(f\"api-{Env.DEV}.example.com\")                     # api-dev.example.com","filename":"Python"}'),
  ('8f296661-f48d-75af-9663-90cbf24006a4', 'aB', 'code', '{"language":"python","code":"from enum import Flag, auto\n\nclass Perm(Flag):\n    READ = auto()        # 1\n    WRITE = auto()       # 2\n    EXEC = auto()        # 4\n    RW = READ | WRITE    # a named combination\n\np = Perm.READ | Perm.EXEC\nprint(p)                                         # Perm.READ|EXEC\nprint(Perm.READ in p, Perm.WRITE in p)           # True False\nprint(Perm.RW.value, [m.name for m in Perm.RW])  # 3 [''READ'', ''WRITE'']\nprint(p & ~Perm.EXEC, bool(Perm(0)))             # Perm.READ False","filename":"Python"}'),
  ('bb997dbc-a8b3-7121-bb25-e666dc21d4b9', 'aC', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Type"}],[{"type":"text","text":"Members are also…"}],[{"type":"text","text":"Use when"}]],[[{"type":"text","text":"Enum","marks":[{"type":"code"}]}],[{"type":"text","text":"nothing else"}],[{"type":"text","text":"Default choice — strict, can''t be mixed up with ints/strings"}]],[[{"type":"text","text":"IntEnum","marks":[{"type":"code"}]}],[{"type":"text","text":"int","marks":[{"type":"code"}]},{"type":"text","text":"s"}],[{"type":"text","text":"Interop with code/protocols that expect integers (HTTP status, DB codes)"}]],[[{"type":"text","text":"StrEnum","marks":[{"type":"code"}]}],[{"type":"text","text":"str","marks":[{"type":"code"}]},{"type":"text","text":"s"}],[{"type":"text","text":"Values go into JSON, URLs, logs, config files"}]],[[{"type":"text","text":"Flag","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"IntFlag","marks":[{"type":"code"}]}],[{"type":"text","text":"bit flags"}],[{"type":"text","text":"Combinable options: permissions, feature toggles"}]]]}'),
