  ('711f6f79-ba31-75ff-b500-b3f5d3301e7e', 'aH', 'code', '{"language":"python","code":"import json\nfrom enum import Enum, StrEnum\n\nclass Light(Enum):\n    RED = \"stop\"\n    YELLOW = \"slow\"\n    GREEN = \"go\"\n\ndef action(light):\n    match light:\n        case Light.RED | Light.YELLOW:        # dotted names are value patterns\n            return \"brake\"\n        case Light.GREEN:\n            return \"drive\"\n\nprint(action(Light.YELLOW), action(Light(\"go\")))              # brake drive\n\nclass Role(StrEnum):\n    ADMIN = \"admin\"\n\nprint(json.dumps({\"role\": Role.ADMIN}))                       # {\"role\": \"admin\"}\ntry:\n    json.dumps({\"light\": Light.RED})\nexcept TypeError:\n    print(\"plain Enum is not JSON serializable\")              # plain Enum is not JSON serializable\nprint(json.dumps({\"light\": Light.RED}, default=lambda e: e.value))   # {\"light\": \"stop\"}\nprint(Light(json.loads(''{\"light\": \"stop\"}'')[\"light\"]))       # Light.RED","filename":"Python"}'),
  ('3cff8a0e-7834-7df5-95be-5e68afd81fcd', 'aI', 'heading', '{"level":1,"content":[{"type":"text","text":"Interview angle"}]}'),
  ('ee4d4249-182c-7d41-93b3-9531128df26b', 'aJ', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why use an Enum instead of string or int constants?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Typos become "},{"type":"text","text":"AttributeError","marks":[{"type":"code"}]},{"type":"text","text":"s instead of silent bugs, the set of valid values is explicit and iterable, members carry a readable name in logs and reprs, and type checkers can verify that a function only receives valid members (and that a "},{"type":"text","text":"match","marks":[{"type":"code"}]},{"type":"text","text":" handles all of them)."}]}]}}'),
