SELECT 'e94f23a9-4547-7137-b064-6f7ff1a713fc', '7b0a7772-845b-7e61-8d18-e7a8da307d88', 1, 'PUBLISHED', 'Exception Hierarchy & Advanced Handling', '[{"id":"0013d4a3-085e-76c7-b234-6d759e68e4d6","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Beyond "},{"type":"text","text":"try","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"except","marks":[{"type":"code"}]},{"type":"text","text":": the full class tree, designing your own error hierarchy, chaining, notes, exception groups, warnings and the patterns (EAFP, retry) that production code relies on."}]}]}},"revision":1},{"id":"5bb1c236-cbe8-75fb-9166-c6d140b1feca","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"The class tree"}]},"revision":1},{"id":"72880bd2-04f1-7bbb-9e7a-1935987cc0b0","type":"code","position":"a2","content":{"language":"text","code":"BaseException\n├── SystemExit              ← sys.exit()\n├── KeyboardInterrupt       ← Ctrl-C\n├── GeneratorExit           ← generator.close()\n├── BaseExceptionGroup\n└── Exception               ← everything you normally catch\n    ├── ArithmeticError     → ZeroDivisionError, OverflowError\n    ├── LookupError         → KeyError, IndexError\n    ├── OSError             → FileNotFoundError, PermissionError, TimeoutError, ConnectionError…\n    ├── ValueError          → UnicodeDecodeError…\n    ├── TypeError, AttributeError, NameError, ImportError (→ ModuleNotFoundError)\n    ├── RuntimeError        → RecursionError, NotImplementedError\n    ├── StopIteration, StopAsyncIteration\n    ├── ExceptionGroup\n    └── Warning             → DeprecationWarning, UserWarning, SyntaxWarning…","filename":"Built-in exception hierarchy (abridged)"},"revision":1},{"id":"64883605-5b84-77eb-a5f1-7c56f3000e44","type":"code","position":"a3","content":{"language":"python","code":"print(issubclass(KeyboardInterrupt, Exception))       # False\nprint(issubclass(KeyboardInterrupt, BaseException))   # True\nprint(issubclass(KeyError, LookupError), issubclass(ZeroDivisionError, ArithmeticError))   # True True\nprint([c.__name__ for c in FileNotFoundError.__mro__])\n# [''FileNotFoundError'', ''OSError'', ''Exception'', ''BaseException'', ''object'']","filename":"Python"},"revision":1},{"id":"001b47d0-0560-7fd0-8baa-cc7359ba514f","type":"callout","position":"a4","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"except Exception","marks":[{"type":"code"}]},{"type":"text","text":" deliberately does "},{"type":"text","text":"not","marks":[{"type":"bold"}]},{"type":"text","text":" catch "},{"type":"text","text":"SystemExit","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"KeyboardInterrupt","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"GeneratorExit","marks":[{"type":"code"}]},{"type":"text","text":" — those mean “stop now”, and swallowing them makes a program impossible to quit. A bare "},{"type":"text","text":"except:","marks":[{"type":"code"}]},{"type":"text","text":" catches "},{"type":"text","text":"BaseException","marks":[{"type":"code"}]},{"type":"text","text":", which is why it''s banned in good code."}]}]}},"revision":1},{"id":"7efe4ec2-4d42-7086-92cd-aaa747b0ce86","type":"code","position":"a5","content":{"language":"python","code":"import sys\ntry:\n    sys.exit(2)                    # sys.exit just raises SystemExit\nexcept SystemExit as e:\n    print(\"exit code\", e.code)     # exit code 2","filename":"Python"},"revision":1},{"id":"71b4abf7-7444-748a-8e22-98a6b9989289","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"Designing a custom hierarchy"}]},"revision":1},{"id":"17e13aa1-f26a-7bfb-aeec-f62c29290369","type":"text","position":"a7","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A library should raise its "},{"type":"text","text":"own","marks":[{"type":"bold"}]},{"type":"text","text":" base exception, with specific subclasses underneath. Callers can then catch everything from your library in one clause, or one precise failure."}]}]}},"revision":1},{"id":"3c03e1d4-5f64-7ca1-a84a-1ffbf23de9d6","type":"code","position":"a8","content":{"language":"python","code":"class PaymentError(Exception):\n    \"\"\"Base class for every error this library raises.\"\"\"\n\nclass CardDeclined(PaymentError):\n    def __init__(self, reason):\n        super().__init__(f\"card declined ({reason})\")\n        self.reason = reason\n\nclass GatewayTimeout(PaymentError):\n    pass\n\ndef charge(amount):\n    if amount < 0:\n        raise ValueError(\"amount must be >= 0\")     # caller bug → a built-in error\n    if amount > 1000:\n        raise CardDeclined(\"limit\")\n    return \"ok\"\n\ntry:\n    charge(5000)\nexcept PaymentError as e:                           # the whole family\n    print(type(e).__name__, \"|\", e, \"|\", e.reason)  # CardDeclined | card declined (limit) | limit","filename":"Python"},"revision":1},{"id":"9ca1013f-484c-7496-8215-9dd6454b1677","type":"callout","position":"a9","content":{"variant":"note","title":"Inherit from Exception","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Never from "},{"type":"text","text":"BaseException","marks":[{"type":"code"}]},{"type":"text","text":" — your errors should be catchable with "},{"type":"text","text":"except Exception","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"acec33ed-795e-743f-92d6-d3e92a424cc9","type":"callout","position":"aA","content":{"variant":"note","title":"Name ends in Error","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"ConfigError","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"RateLimitError","marks":[{"type":"code"}]},{"type":"text","text":" — the PEP 8 convention."}]}]}},"revision":1},{"id":"106f107d-a42f-7c8e-8b10-e1bf4446ec88","type":"callout","position":"aB","content":{"variant":"note","title":"Carry data","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Store useful fields ("},{"type":"text","text":"self.status","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"self.retry_after","marks":[{"type":"code"}]},{"type":"text","text":") instead of making callers parse the message."}]}]}},"revision":1},{"id":"dbed929f-f69c-7d99-a4ef-303c02e7b245","type":"callout","position":"aC","content":{"variant":"note","title":"Reuse built-ins for caller bugs","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Wrong argument type → "},{"type":"text","text":"TypeError","marks":[{"type":"code"}]},{"type":"text","text":"; bad value → "},{"type":"text","text":"ValueError","marks":[{"type":"code"}]},{"type":"text","text":". Custom classes are for "},{"type":"text","text":"domain","marks":[{"type":"italic"}]},{"type":"text","text":" failures."}]}]}},"revision":1},{"id":"0b4b2ac7-62ce-7d6a-9806-e843c8a03ed4","type":"heading","position":"aD","content":{"level":1,"content":[{"type":"text","text":"Catching several types & re-raising"}]},"revision":1},{"id":"86bf50e0-ee72-7954-93a6-9951c62c0496","type":"code","position":"aE","content":{"language":"python","code":"def to_int(x):\n    try:\n        return int(x)\n    except (TypeError, ValueError) as e:     # a tuple catches any of them\n        return type(e).__name__\n\nprint(to_int(\"7\"), to_int(\"x\"), to_int(None))   # 7 ValueError TypeError\n\nlog = []\ndef load(key):\n    try:\n        return {\"a\": 1}[key]\n    except KeyError:\n        log.append(f\"missing {key}\")          # do something useful…\n        raise                                 # …then re-raise the SAME exception\n\ntry:\n    load(\"b\")\nexcept KeyError as e:\n    print(repr(e), log)                       # KeyError(''b'') [''missing b'']","filename":"Python"},"revision":1},{"id":"3c7ed739-2f41-7e32-bbbc-cdf563809770","type":"callout","position":"aF","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"except","marks":[{"type":"code"}]},{"type":"text","text":" clauses are tried top to bottom and the first match wins — put "},{"type":"text","text":"subclasses before base classes","marks":[{"type":"bold"}]},{"type":"text","text":". "},{"type":"text","text":"except OSError:","marks":[{"type":"code"}]},{"type":"text","text":" above "},{"type":"text","text":"except FileNotFoundError:","marks":[{"type":"code"}]},{"type":"text","text":" makes the second one unreachable."}]}]}},"revision":1},{"id":"46c70b68-db7f-720a-8848-df7fc7879303","type":"code","position":"aG","content":{"language":"python","code":"try:\n    1 / 0\nexcept ZeroDivisionError as e:\n    saved = e\nprint(\"e\" in dir(), type(saved).__name__)    # False ZeroDivisionError","filename":"Python"},"revision":1},{"id":"31972fe2-a25d-7d59-bbb4-633a7b7e464a","type":"callout","position":"aH","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The name bound by "},{"type":"text","text":"except … as e","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"deleted","marks":[{"type":"bold"}]},{"type":"text","text":" when the block ends (to break a reference cycle through the traceback). Assign it to another name if you need it later."}]}]}},"revision":1},{"id":"463cc394-cf8e-73b5-9b8a-e8cb9c032bb4","type":"heading","position":"aI","content":{"level":1,"content":[{"type":"text","text":"Chaining: "},{"type":"text","text":"__context__","marks":[{"type":"code"}]},{"type":"text","text":" vs "},{"type":"text","text":"__cause__","marks":[{"type":"code"}]}]},"revision":1},{"id":"5428a434-00b7-71fa-99a4-f19ef58a5743","type":"code","position":"aJ","content":{"language":"python","code":"def implicit():\n    try:\n        1 / 0\n    except ZeroDivisionError:\n        raise ValueError(\"bad ratio\")              # error while handling another\n\ndef explicit():\n    try:\n        1 / 0\n    except ZeroDivisionError as e:\n        raise ValueError(\"bad ratio\") from e       # \"this caused that\"\n\ndef hidden():\n    try:\n        1 / 0\n    except ZeroDivisionError:\n        raise ValueError(\"bad ratio\") from None    # hide the internal detail\n\ndef inspect(f):\n    try:\n        f()\n    except ValueError as e:\n        return type(e.__cause__).__name__, type(e.__context__).__name__, e.__suppress_context__\n\nprint(inspect(implicit))   # (''NoneType'', ''ZeroDivisionError'', False)\nprint(inspect(explicit))   # (''ZeroDivisionError'', ''ZeroDivisionError'', True)\nprint(inspect(hidden))     # (''NoneType'', ''ZeroDivisionError'', True)","filename":"Python"},"revision":1},{"id":"fac0ffe9-b1cd-72e7-8a6d-3f9d3f2dada3","type":"table","position":"aK","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"You write"}],[{"type":"text","text":"Attribute set"}],[{"type":"text","text":"Traceback says"}]],[[{"type":"text","text":"raise New()","marks":[{"type":"code"}]},{"type":"text","text":" inside "},{"type":"text","text":"except","marks":[{"type":"code"}]}],[{"type":"text","text":"__context__","marks":[{"type":"code"}]}],[{"type":"text","text":"“During handling of the above exception, another exception occurred”"}]],[[{"type":"text","text":"raise New() from e","marks":[{"type":"code"}]}],[{"type":"text","text":"__cause__","marks":[{"type":"code"}]},{"type":"text","text":" (+ "},{"type":"text","text":"__context__","marks":[{"type":"code"}]},{"type":"text","text":")"}],[{"type":"text","text":"“The above exception was the direct cause of the following exception”"}]],[[{"type":"text","text":"raise New() from None","marks":[{"type":"code"}]}],[{"type":"text","text":"__suppress_context__ = True","marks":[{"type":"code"}]}],[{"type":"text","text":"Only the new exception"}]]]},"revision":1},{"id":"07b2f818-b30e-736b-ae15-1812c2b3b435","type":"heading","position":"aL","content":{"level":1,"content":[{"type":"text","text":"Adding context: "},{"type":"text","text":"add_note","marks":[{"type":"code"}]},{"type":"text","text":" (3.11+)"}]},"revision":1},{"id":"7bfc8bfd-c334-7b43-a14e-5d31994e3c25","type":"code","position":"aM","content":{"language":"python","code":"import traceback\n\ndef parse_row(n, text):\n    try:\n        return int(text)\n    except ValueError as e:\n        e.add_note(f\"while parsing row {n} of users.csv\")\n        raise\n\ntry:\n    parse_row(3, \"abc\")\nexcept ValueError as e:\n    print(e.__notes__)                                       # [''while parsing row 3 of users.csv'']\n    print(traceback.format_exception_only(e)[-1].strip())    # while parsing row 3 of users.csv","filename":"Python"},"revision":1},{"id":"0e7c5cfb-9679-7ca5-bc7b-ac5243e5d502","type":"text","position":"aN","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Notes are printed under the error message in tracebacks — a lightweight way to add context without wrapping the exception in a new type."}]}]}},"revision":1},{"id":"afd199a0-cbdf-701f-b509-ddb76da6b3b2","type":"heading","position":"aO","content":{"level":1,"content":[{"type":"text","text":"ExceptionGroup and "},{"type":"text","text":"except*","marks":[{"type":"code"}]},{"type":"text","text":" (3.11+)"}]},"revision":1},{"id":"807cef74-56c4-78f0-b01c-c6082862789b","type":"text","position":"aP","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When several independent operations fail at once (parallel tasks, validating many fields), raise them "},{"type":"text","text":"together","marks":[{"type":"bold"}]},{"type":"text","text":" as an "},{"type":"text","text":"ExceptionGroup","marks":[{"type":"code"}]},{"type":"text","text":". "},{"type":"text","text":"except*","marks":[{"type":"code"}]},{"type":"text","text":" handles each type inside the group; several "},{"type":"text","text":"except*","marks":[{"type":"code"}]},{"type":"text","text":" clauses can run for one group."}]}]}},"revision":1},{"id":"5cb337e5-b2b8-7b60-8c8b-701c27e26aaf","type":"code","position":"aQ","content":{"language":"python","code":"def validate(user):\n    errors = []\n    if not user.get(\"name\"):\n        errors.append(ValueError(\"name is required\"))\n    if not isinstance(user.get(\"age\"), int):\n        errors.append(TypeError(\"age must be an int\"))\n    if \"@\" not in user.get(\"email\", \"\"):\n        errors.append(ValueError(\"email is invalid\"))\n    if errors:\n        raise ExceptionGroup(\"invalid user\", errors)\n\ntry:\n    validate({\"name\": \"\", \"age\": \"x\", \"email\": \"nope\"})\nexcept* ValueError as eg:\n    print(\"values:\", [str(e) for e in eg.exceptions])   # values: [''name is required'', ''email is invalid'']\nexcept* TypeError as eg:\n    print(\"types:\", [str(e) for e in eg.exceptions])    # types: [''age must be an int'']","filename":"Python"},"revision":1},{"id":"fb870031-7cc6-796b-b61c-ccf65f3ce707","type":"code","position":"aR","content":{"language":"python","code":"eg = ExceptionGroup(\"batch\", [ValueError(1), KeyError(2), ValueError(3)])\nvalues, rest = eg.split(ValueError)\nprint(len(values.exceptions), [type(e).__name__ for e in rest.exceptions])   # 2 [''KeyError'']","filename":"Python"},"revision":1},{"id":"ffa46cba-5e78-7560-ba4e-5a9778b30268","type":"callout","position":"aS","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"asyncio.TaskGroup","marks":[{"type":"code"}]},{"type":"text","text":" raises an "},{"type":"text","text":"ExceptionGroup","marks":[{"type":"code"}]},{"type":"text","text":" when tasks fail, so "},{"type":"text","text":"except*","marks":[{"type":"code"}]},{"type":"text","text":" is the natural way to handle concurrent failures."}]}]}},"revision":1},{"id":"56f5d3db-8672-712b-8c38-f02317432ca8","type":"heading","position":"aT","content":{"level":1,"content":[{"type":"text","text":"Inspecting tracebacks"}]},"revision":1},{"id":"0e15dfd6-d0c1-7b77-b5b3-001bdbf6edf3","type":"code","position":"aU","content":{"language":"python","code":"import traceback\n\ndef inner():\n    return 1 / 0\ndef outer():\n    return inner()\n\ntry:\n    outer()\nexcept ZeroDivisionError as e:\n    frames = traceback.extract_tb(e.__traceback__)\n    print([f.name for f in frames])                          # [''<module>'', ''outer'', ''inner'']\n    print(traceback.format_exception_only(e)[0].strip())     # ZeroDivisionError: division by zero","filename":"Python"},"revision":1},{"id":"29aa5d11-8fef-7760-b4b9-14cd6c0fcec1","type":"text","position":"aV","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"traceback.format_exc()","marks":[{"type":"code"}]},{"type":"text","text":" returns the full traceback as a string (for logging); "},{"type":"text","text":"logger.exception(\"msg\")","marks":[{"type":"code"}]},{"type":"text","text":" does the same automatically inside an "},{"type":"text","text":"except","marks":[{"type":"code"}]},{"type":"text","text":" block."}]}]}},"revision":1},{"id":"5672842c-2b69-748f-9547-facded818358","type":"heading","position":"aW","content":{"level":1,"content":[{"type":"text","text":"assert","marks":[{"type":"code"}]},{"type":"text","text":" — for invariants, not validation"}]},"revision":1},{"id":"d4ba76cb-3c35-7142-bbc8-67b71db2829a","type":"code","position":"aX","content":{"language":"python","code":"def mean(xs):\n    assert xs, \"mean() of an empty list\"     # a developer''s sanity check\n    return sum(xs) / len(xs)\n\ntry:\n    mean([])\nexcept AssertionError as e:\n    print(e)                                 # mean() of an empty list","filename":"Python"},"revision":1},{"id":"21b66497-00e5-70fe-838b-ef27a0c85244","type":"callout","position":"aY","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"python -O","marks":[{"type":"code"}]},{"type":"text","text":" strips every "},{"type":"text","text":"assert","marks":[{"type":"code"}]},{"type":"text","text":". Never use it to check user input, permissions or anything that must hold in production — "},{"type":"text","text":"raise ValueError","marks":[{"type":"code"}]},{"type":"text","text":" instead. And "},{"type":"text","text":"assert (cond, \"msg\")","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"always true","marks":[{"type":"bold"}]},{"type":"text","text":" (a non-empty tuple); Python emits a "},{"type":"text","text":"SyntaxWarning","marks":[{"type":"code"}]},{"type":"text","text":" for it."}]}]}},"revision":1},{"id":"a083699f-d3b1-773b-a9a7-521f40b96586","type":"heading","position":"aZ","content":{"level":1,"content":[{"type":"text","text":"Warnings"}]},"revision":1},{"id":"09e8fd0b-0be5-77fe-aa9b-1eedf478f520","type":"text","position":"aa","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A warning reports something suspicious without stopping the program — most often a deprecation. Warnings are printed once per location by default and can be filtered or turned into errors."}]}]}},"revision":1},{"id":"d3ced545-ad8e-7915-89aa-7d78b2a5235a","type":"code","position":"ab","content":{"language":"python","code":"import warnings\n\ndef old_api():\n    warnings.warn(\"old_api() is deprecated; use new_api()\", DeprecationWarning, stacklevel=2)\n    return 42\n\nwith warnings.catch_warnings(record=True) as caught:\n    warnings.simplefilter(\"always\")\n    result = old_api()\n\nprint(result, caught[0].category.__name__)   # 42 DeprecationWarning\nprint(caught[0].message)                     # old_api() is deprecated; use new_api()","filename":"Python"},"revision":1},{"id":"6737d5d7-edc0-7cc3-a540-bfe00158db9f","type":"table","position":"ac","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Filter action"}],[{"type":"text","text":"Effect"}]],[[{"type":"text","text":"\"default\"","marks":[{"type":"code"}]}],[{"type":"text","text":"Print the first occurrence per location"}]],[[{"type":"text","text":"\"always\"","marks":[{"type":"code"}]}],[{"type":"text","text":"Print every occurrence"}]],[[{"type":"text","text":"\"ignore\"","marks":[{"type":"code"}]}],[{"type":"text","text":"Never print"}]],[[{"type":"text","text":"\"error\"","marks":[{"type":"code"}]}],[{"type":"text","text":"Turn the warning into an exception — great in test suites ("},{"type":"text","text":"python -W error","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"pytest -W error","marks":[{"type":"code"}]},{"type":"text","text":")"}]]]},"revision":1},{"id":"2164b660-ce40-7781-a176-a48b4c2fb678","type":"heading","position":"ad","content":{"level":1,"content":[{"type":"text","text":"finally","marks":[{"type":"code"}]},{"type":"text","text":" beats "},{"type":"text","text":"return","marks":[{"type":"code"}]}]},"revision":1},{"id":"ac0c40b4-d530-7431-8ef8-76662db7e518","type":"code","position":"ae","content":{"language":"python","code":"def f():\n    try:\n        return \"from try\"\n    finally:\n        print(\"finally runs first\")   # finally runs first\n\nprint(f())                            # from try","filename":"Python"},"revision":1},{"id":"afb388fa-d316-7cc8-be10-2818d9bc710b","type":"code","position":"af","content":{"language":"python","code":"import warnings\n\n# A return inside finally silently DISCARDS an in-flight exception.\n# Python 3.14 warns about it at compile time (PEP 765); silenced here to show the behaviour.\nsrc = \"\"\"\ndef swallow():\n    try:\n        raise ValueError(\"lost!\")\n    finally:\n        return \"finally wins\"\n\"\"\"\nwith warnings.catch_warnings():\n    warnings.simplefilter(\"ignore\", SyntaxWarning)\n    ns = {}\n    exec(src, ns)\nprint(ns[\"swallow\"]())      # finally wins","filename":"Python"},"revision":1},{"id":"8d48b027-4a62-750a-a998-c288f98e2917","type":"callout","position":"ag","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Never "},{"type":"text","text":"return","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"break","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"continue","marks":[{"type":"code"}]},{"type":"text","text":" out of a "},{"type":"text","text":"finally","marks":[{"type":"code"}]},{"type":"text","text":" block — the exception being propagated vanishes without a trace."}]}]}},"revision":1},{"id":"3033ebfa-d6ed-703e-aa91-43f7ece73e0d","type":"heading","position":"ah","content":{"level":1,"content":[{"type":"text","text":"EAFP, cost and the retry pattern"}]},"revision":1},{"id":"5a7897d9-2f8f-77ff-b67b-e4532ca73104","type":"text","position":"ai","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Setting up a "},{"type":"text","text":"try","marks":[{"type":"code"}]},{"type":"text","text":" block is essentially free in Python 3.11+ (“zero-cost” exceptions); "},{"type":"text","text":"raising","marks":[{"type":"italic"}]},{"type":"text","text":" costs a few microseconds. So EAFP — just try and handle failure — is idiomatic when failure is the exception, not the rule."}]}]}},"revision":1},{"id":"70238d8c-2ca6-75a5-b366-87a747075c93","type":"code","position":"aj","content":{"language":"python","code":"def get_port(cfg):\n    try:\n        return int(cfg[\"port\"])\n    except (KeyError, ValueError):\n        return 8080\n\nprint(get_port({\"port\": \"5432\"}), get_port({}), get_port({\"port\": \"x\"}))   # 5432 8080 8080","filename":"Python"},"revision":1},{"id":"adcf5e2d-3186-7462-ab16-09ccaea54fc1","type":"code","position":"ak","content":{"language":"python","code":"import time\n\ndef retry(fn, attempts=3, base_delay=0.001, retry_on=(ConnectionError, TimeoutError)):\n    for attempt in range(1, attempts + 1):\n        try:\n            return fn()\n        except retry_on:\n            if attempt == attempts:\n                raise                                    # out of attempts: propagate\n            time.sleep(base_delay * 2 ** (attempt - 1))  # exponential backoff\n\ncalls = []\ndef flaky():\n    calls.append(1)\n    if len(calls) < 3:\n        raise ConnectionError(\"connection reset\")\n    return \"connected\"\n\nprint(retry(flaky), len(calls))   # connected 3","filename":"Python — retry with exponential backoff"},"revision":1},{"id":"5392b02d-9463-7cec-b629-1db203ba4180","type":"callout","position":"al","content":{"variant":"tip","title":"Do","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Retry only "},{"type":"text","text":"transient","marks":[{"type":"italic"}]},{"type":"text","text":" errors (timeouts, connection resets), cap the attempts, back off exponentially (add jitter in production) and log each failure."}]}]}},"revision":1},{"id":"cbf0c7e5-f69a-75d4-a227-0759be3c2d6b","type":"callout","position":"am","content":{"variant":"danger","title":"Avoid","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Retrying everything — a "},{"type":"text","text":"ValueError","marks":[{"type":"code"}]},{"type":"text","text":" from bad input will fail identically every time."}]}]}},"revision":1},{"id":"81d5925a-9fc8-7cfa-a0a2-f88141de2c1f","type":"heading","position":"an","content":{"level":1,"content":[{"type":"text","text":"Interview questions"}]},"revision":1},{"id":"52cb45de-1009-784c-8a93-6d2936c93701","type":"question","position":"ao","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why shouldn''t you write except: or except BaseException:?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"They catch "},{"type":"text","text":"KeyboardInterrupt","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"SystemExit","marks":[{"type":"code"}]},{"type":"text","text":" too, so Ctrl-C and "},{"type":"text","text":"sys.exit()","marks":[{"type":"code"}]},{"type":"text","text":" stop working, and they hide real bugs. Catch "},{"type":"text","text":"Exception","marks":[{"type":"code"}]},{"type":"text","text":" at most (e.g. at a top-level request handler that logs and continues), and specific types everywhere else."}]}]}},"revision":1},{"id":"e005f759-ea49-78c9-b9be-ea7e67091df0","type":"question","position":"ap","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the difference between raise X from e and raise X from None?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"from e","marks":[{"type":"code"}]},{"type":"text","text":" records "},{"type":"text","text":"e","marks":[{"type":"code"}]},{"type":"text","text":" as the explicit cause ("},{"type":"text","text":"__cause__","marks":[{"type":"code"}]},{"type":"text","text":") and the traceback shows both, linked by “direct cause”. "},{"type":"text","text":"from None","marks":[{"type":"code"}]},{"type":"text","text":" suppresses the context so only the new exception is shown — useful when the original is an implementation detail."}]}]}},"revision":1},{"id":"0d64a890-5469-7060-98be-cb090374f16a","type":"question","position":"aq","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What does except* do?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"It matches exceptions "},{"type":"text","text":"inside","marks":[{"type":"italic"}]},{"type":"text","text":" an "},{"type":"text","text":"ExceptionGroup","marks":[{"type":"code"}]},{"type":"text","text":". Each "},{"type":"text","text":"except*","marks":[{"type":"code"}]},{"type":"text","text":" clause receives a sub-group of the matching exceptions; multiple clauses can run for the same group, and any unmatched exceptions are re-raised in a new group."}]}]}},"revision":1},{"id":"437a7c63-2fa0-7c32-9331-4db0b36a46e3","type":"question","position":"ar","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When would you define a custom exception?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When callers need to react to a specific domain failure ("},{"type":"text","text":"CardDeclined","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"RateLimited","marks":[{"type":"code"}]},{"type":"text","text":") differently from others. Give the library one base class so callers can catch all of its errors, and attach structured data as attributes."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
WHERE EXISTS (SELECT 1 FROM "notes"."Note" n WHERE n.id = '7b0a7772-845b-7e61-8d18-e7a8da307d88' AND n."ownerId" = '019a118c-f480-7000-8000-000000000001' AND n."publishedVersionId" IS NULL AND n.visibility = 'PRIVATE' AND n."deletedAt" IS NULL AND n."draftUpdatedAt" = TIMESTAMPTZ '2026-10-07 03:23:53+00')
ON CONFLICT DO NOTHING;

INSERT INTO "notes"."Card" ("id", "noteId", "position", "type", "content", "revision", "createdAt", "updatedAt")
SELECT c.id::uuid, '7b0a7772-845b-7e61-8d18-e7a8da307d88', c.position, c.type::"notes"."CardType", c.content::jsonb, 1, TIMESTAMPTZ '2026-10-07 03:23:53+00', TIMESTAMPTZ '2026-10-07 03:23:53+00'
FROM (VALUES
  ('0013d4a3-085e-76c7-b234-6d759e68e4d6', 'a0', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Beyond "},{"type":"text","text":"try","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"except","marks":[{"type":"code"}]},{"type":"text","text":": the full class tree, designing your own error hierarchy, chaining, notes, exception groups, warnings and the patterns (EAFP, retry) that production code relies on."}]}]}}'),
  ('5bb1c236-cbe8-75fb-9166-c6d140b1feca', 'a1', 'heading', '{"level":1,"content":[{"type":"text","text":"The class tree"}]}'),
  ('72880bd2-04f1-7bbb-9e7a-1935987cc0b0', 'a2', 'code', '{"language":"text","code":"BaseException\n├── SystemExit              ← sys.exit()\n├── KeyboardInterrupt       ← Ctrl-C\n├── GeneratorExit           ← generator.close()\n├── BaseExceptionGroup\n└── Exception               ← everything you normally catch\n    ├── ArithmeticError     → ZeroDivisionError, OverflowError\n    ├── LookupError         → KeyError, IndexError\n    ├── OSError             → FileNotFoundError, PermissionError, TimeoutError, ConnectionError…\n    ├── ValueError          → UnicodeDecodeError…\n    ├── TypeError, AttributeError, NameError, ImportError (→ ModuleNotFoundError)\n    ├── RuntimeError        → RecursionError, NotImplementedError\n    ├── StopIteration, StopAsyncIteration\n    ├── ExceptionGroup\n    └── Warning             → DeprecationWarning, UserWarning, SyntaxWarning…","filename":"Built-in exception hierarchy (abridged)"}'),
  ('64883605-5b84-77eb-a5f1-7c56f3000e44', 'a3', 'code', '{"language":"python","code":"print(issubclass(KeyboardInterrupt, Exception))       # False\nprint(issubclass(KeyboardInterrupt, BaseException))   # True\nprint(issubclass(KeyError, LookupError), issubclass(ZeroDivisionError, ArithmeticError))   # True True\nprint([c.__name__ for c in FileNotFoundError.__mro__])\n# [''FileNotFoundError'', ''OSError'', ''Exception'', ''BaseException'', ''object'']","filename":"Python"}'),
  ('001b47d0-0560-7fd0-8baa-cc7359ba514f', 'a4', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"except Exception","marks":[{"type":"code"}]},{"type":"text","text":" deliberately does "},{"type":"text","text":"not","marks":[{"type":"bold"}]},{"type":"text","text":" catch "},{"type":"text","text":"SystemExit","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"KeyboardInterrupt","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"GeneratorExit","marks":[{"type":"code"}]},{"type":"text","text":" — those mean “stop now”, and swallowing them makes a program impossible to quit. A bare "},{"type":"text","text":"except:","marks":[{"type":"code"}]},{"type":"text","text":" catches "},{"type":"text","text":"BaseException","marks":[{"type":"code"}]},{"type":"text","text":", which is why it''s banned in good code."}]}]}}'),
  ('7efe4ec2-4d42-7086-92cd-aaa747b0ce86', 'a5', 'code', '{"language":"python","code":"import sys\ntry:\n    sys.exit(2)                    # sys.exit just raises SystemExit\nexcept SystemExit as e:\n    print(\"exit code\", e.code)     # exit code 2","filename":"Python"}'),
  ('71b4abf7-7444-748a-8e22-98a6b9989289', 'a6', 'heading', '{"level":1,"content":[{"type":"text","text":"Designing a custom hierarchy"}]}'),
  ('17e13aa1-f26a-7bfb-aeec-f62c29290369', 'a7', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A library should raise its "},{"type":"text","text":"own","marks":[{"type":"bold"}]},{"type":"text","text":" base exception, with specific subclasses underneath. Callers can then catch everything from your library in one clause, or one precise failure."}]}]}}'),
  ('3c03e1d4-5f64-7ca1-a84a-1ffbf23de9d6', 'a8', 'code', '{"language":"python","code":"class PaymentError(Exception):\n    \"\"\"Base class for every error this library raises.\"\"\"\n\nclass CardDeclined(PaymentError):\n    def __init__(self, reason):\n        super().__init__(f\"card declined ({reason})\")\n        self.reason = reason\n\nclass GatewayTimeout(PaymentError):\n    pass\n\ndef charge(amount):\n    if amount < 0:\n        raise ValueError(\"amount must be >= 0\")     # caller bug → a built-in error\n    if amount > 1000:\n        raise CardDeclined(\"limit\")\n    return \"ok\"\n\ntry:\n    charge(5000)\nexcept PaymentError as e:                           # the whole family\n    print(type(e).__name__, \"|\", e, \"|\", e.reason)  # CardDeclined | card declined (limit) | limit","filename":"Python"}'),
  ('9ca1013f-484c-7496-8215-9dd6454b1677', 'a9', 'callout', '{"variant":"note","title":"Inherit from Exception","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Never from "},{"type":"text","text":"BaseException","marks":[{"type":"code"}]},{"type":"text","text":" — your errors should be catchable with "},{"type":"text","text":"except Exception","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('acec33ed-795e-743f-92d6-d3e92a424cc9', 'aA', 'callout', '{"variant":"note","title":"Name ends in Error","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"ConfigError","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"RateLimitError","marks":[{"type":"code"}]},{"type":"text","text":" — the PEP 8 convention."}]}]}}'),
  ('106f107d-a42f-7c8e-8b10-e1bf4446ec88', 'aB', 'callout', '{"variant":"note","title":"Carry data","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Store useful fields ("},{"type":"text","text":"self.status","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"self.retry_after","marks":[{"type":"code"}]},{"type":"text","text":") instead of making callers parse the message."}]}]}}'),
  ('dbed929f-f69c-7d99-a4ef-303c02e7b245', 'aC', 'callout', '{"variant":"note","title":"Reuse built-ins for caller bugs","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Wrong argument type → "},{"type":"text","text":"TypeError","marks":[{"type":"code"}]},{"type":"text","text":"; bad value → "},{"type":"text","text":"ValueError","marks":[{"type":"code"}]},{"type":"text","text":". Custom classes are for "},{"type":"text","text":"domain","marks":[{"type":"italic"}]},{"type":"text","text":" failures."}]}]}}'),
  ('0b4b2ac7-62ce-7d6a-9806-e843c8a03ed4', 'aD', 'heading', '{"level":1,"content":[{"type":"text","text":"Catching several types & re-raising"}]}'),
  ('86bf50e0-ee72-7954-93a6-9951c62c0496', 'aE', 'code', '{"language":"python","code":"def to_int(x):\n    try:\n        return int(x)\n    except (TypeError, ValueError) as e:     # a tuple catches any of them\n        return type(e).__name__\n\nprint(to_int(\"7\"), to_int(\"x\"), to_int(None))   # 7 ValueError TypeError\n\nlog = []\ndef load(key):\n    try:\n        return {\"a\": 1}[key]\n    except KeyError:\n        log.append(f\"missing {key}\")          # do something useful…\n        raise                                 # …then re-raise the SAME exception\n\ntry:\n    load(\"b\")\nexcept KeyError as e:\n    print(repr(e), log)                       # KeyError(''b'') [''missing b'']","filename":"Python"}'),
  ('3c7ed739-2f41-7e32-bbbc-cdf563809770', 'aF', 'callout', '{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"except","marks":[{"type":"code"}]},{"type":"text","text":" clauses are tried top to bottom and the first match wins — put "},{"type":"text","text":"subclasses before base classes","marks":[{"type":"bold"}]},{"type":"text","text":". "},{"type":"text","text":"except OSError:","marks":[{"type":"code"}]},{"type":"text","text":" above "},{"type":"text","text":"except FileNotFoundError:","marks":[{"type":"code"}]},{"type":"text","text":" makes the second one unreachable."}]}]}}'),
  ('46c70b68-db7f-720a-8848-df7fc7879303', 'aG', 'code', '{"language":"python","code":"try:\n    1 / 0\nexcept ZeroDivisionError as e:\n    saved = e\nprint(\"e\" in dir(), type(saved).__name__)    # False ZeroDivisionError","filename":"Python"}'),
  ('31972fe2-a25d-7d59-bbb4-633a7b7e464a', 'aH', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The name bound by "},{"type":"text","text":"except … as e","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"deleted","marks":[{"type":"bold"}]},{"type":"text","text":" when the block ends (to break a reference cycle through the traceback). Assign it to another name if you need it later."}]}]}}'),
  ('463cc394-cf8e-73b5-9b8a-e8cb9c032bb4', 'aI', 'heading', '{"level":1,"content":[{"type":"text","text":"Chaining: "},{"type":"text","text":"__context__","marks":[{"type":"code"}]},{"type":"text","text":" vs "},{"type":"text","text":"__cause__","marks":[{"type":"code"}]}]}'),
  ('5428a434-00b7-71fa-99a4-f19ef58a5743', 'aJ', 'code', '{"language":"python","code":"def implicit():\n    try:\n        1 / 0\n    except ZeroDivisionError:\n        raise ValueError(\"bad ratio\")              # error while handling another\n\ndef explicit():\n    try:\n        1 / 0\n    except ZeroDivisionError as e:\n        raise ValueError(\"bad ratio\") from e       # \"this caused that\"\n\ndef hidden():\n    try:\n        1 / 0\n    except ZeroDivisionError:\n        raise ValueError(\"bad ratio\") from None    # hide the internal detail\n\ndef inspect(f):\n    try:\n        f()\n    except ValueError as e:\n        return type(e.__cause__).__name__, type(e.__context__).__name__, e.__suppress_context__\n\nprint(inspect(implicit))   # (''NoneType'', ''ZeroDivisionError'', False)\nprint(inspect(explicit))   # (''ZeroDivisionError'', ''ZeroDivisionError'', True)\nprint(inspect(hidden))     # (''NoneType'', ''ZeroDivisionError'', True)","filename":"Python"}'),
  ('fac0ffe9-b1cd-72e7-8a6d-3f9d3f2dada3', 'aK', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"You write"}],[{"type":"text","text":"Attribute set"}],[{"type":"text","text":"Traceback says"}]],[[{"type":"text","text":"raise New()","marks":[{"type":"code"}]},{"type":"text","text":" inside "},{"type":"text","text":"except","marks":[{"type":"code"}]}],[{"type":"text","text":"__context__","marks":[{"type":"code"}]}],[{"type":"text","text":"“During handling of the above exception, another exception occurred”"}]],[[{"type":"text","text":"raise New() from e","marks":[{"type":"code"}]}],[{"type":"text","text":"__cause__","marks":[{"type":"code"}]},{"type":"text","text":" (+ "},{"type":"text","text":"__context__","marks":[{"type":"code"}]},{"type":"text","text":")"}],[{"type":"text","text":"“The above exception was the direct cause of the following exception”"}]],[[{"type":"text","text":"raise New() from None","marks":[{"type":"code"}]}],[{"type":"text","text":"__suppress_context__ = True","marks":[{"type":"code"}]}],[{"type":"text","text":"Only the new exception"}]]]}'),
  ('07b2f818-b30e-736b-ae15-1812c2b3b435', 'aL', 'heading', '{"level":1,"content":[{"type":"text","text":"Adding context: "},{"type":"text","text":"add_note","marks":[{"type":"code"}]},{"type":"text","text":" (3.11+)"}]}'),
  ('7bfc8bfd-c334-7b43-a14e-5d31994e3c25', 'aM', 'code', '{"language":"python","code":"import traceback\n\ndef parse_row(n, text):\n    try:\n        return int(text)\n    except ValueError as e:\n        e.add_note(f\"while parsing row {n} of users.csv\")\n        raise\n\ntry:\n    parse_row(3, \"abc\")\nexcept ValueError as e:\n    print(e.__notes__)                                       # [''while parsing row 3 of users.csv'']\n    print(traceback.format_exception_only(e)[-1].strip())    # while parsing row 3 of users.csv","filename":"Python"}'),
  ('0e7c5cfb-9679-7ca5-bc7b-ac5243e5d502', 'aN', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Notes are printed under the error message in tracebacks — a lightweight way to add context without wrapping the exception in a new type."}]}]}}'),
  ('afd199a0-cbdf-701f-b509-ddb76da6b3b2', 'aO', 'heading', '{"level":1,"content":[{"type":"text","text":"ExceptionGroup and "},{"type":"text","text":"except*","marks":[{"type":"code"}]},{"type":"text","text":" (3.11+)"}]}'),
  ('807cef74-56c4-78f0-b01c-c6082862789b', 'aP', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When several independent operations fail at once (parallel tasks, validating many fields), raise them "},{"type":"text","text":"together","marks":[{"type":"bold"}]},{"type":"text","text":" as an "},{"type":"text","text":"ExceptionGroup","marks":[{"type":"code"}]},{"type":"text","text":". "},{"type":"text","text":"except*","marks":[{"type":"code"}]},{"type":"text","text":" handles each type inside the group; several "},{"type":"text","text":"except*","marks":[{"type":"code"}]},{"type":"text","text":" clauses can run for one group."}]}]}}'),
  ('5cb337e5-b2b8-7b60-8c8b-701c27e26aaf', 'aQ', 'code', '{"language":"python","code":"def validate(user):\n    errors = []\n    if not user.get(\"name\"):\n        errors.append(ValueError(\"name is required\"))\n    if not isinstance(user.get(\"age\"), int):\n        errors.append(TypeError(\"age must be an int\"))\n    if \"@\" not in user.get(\"email\", \"\"):\n        errors.append(ValueError(\"email is invalid\"))\n    if errors:\n        raise ExceptionGroup(\"invalid user\", errors)\n\ntry:\n    validate({\"name\": \"\", \"age\": \"x\", \"email\": \"nope\"})\nexcept* ValueError as eg:\n    print(\"values:\", [str(e) for e in eg.exceptions])   # values: [''name is required'', ''email is invalid'']\nexcept* TypeError as eg:\n    print(\"types:\", [str(e) for e in eg.exceptions])    # types: [''age must be an int'']","filename":"Python"}'),
  ('fb870031-7cc6-796b-b61c-ccf65f3ce707', 'aR', 'code', '{"language":"python","code":"eg = ExceptionGroup(\"batch\", [ValueError(1), KeyError(2), ValueError(3)])\nvalues, rest = eg.split(ValueError)\nprint(len(values.exceptions), [type(e).__name__ for e in rest.exceptions])   # 2 [''KeyError'']","filename":"Python"}'),
  ('ffa46cba-5e78-7560-ba4e-5a9778b30268', 'aS', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"asyncio.TaskGroup","marks":[{"type":"code"}]},{"type":"text","text":" raises an "},{"type":"text","text":"ExceptionGroup","marks":[{"type":"code"}]},{"type":"text","text":" when tasks fail, so "},{"type":"text","text":"except*","marks":[{"type":"code"}]},{"type":"text","text":" is the natural way to handle concurrent failures."}]}]}}'),
  ('56f5d3db-8672-712b-8c38-f02317432ca8', 'aT', 'heading', '{"level":1,"content":[{"type":"text","text":"Inspecting tracebacks"}]}'),
  ('0e15dfd6-d0c1-7b77-b5b3-001bdbf6edf3', 'aU', 'code', '{"language":"python","code":"import traceback\n\ndef inner():\n    return 1 / 0\ndef outer():\n    return inner()\n\ntry:\n    outer()\nexcept ZeroDivisionError as e:\n    frames = traceback.extract_tb(e.__traceback__)\n    print([f.name for f in frames])                          # [''<module>'', ''outer'', ''inner'']\n    print(traceback.format_exception_only(e)[0].strip())     # ZeroDivisionError: division by zero","filename":"Python"}'),
  ('29aa5d11-8fef-7760-b4b9-14cd6c0fcec1', 'aV', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"traceback.format_exc()","marks":[{"type":"code"}]},{"type":"text","text":" returns the full traceback as a string (for logging); "},{"type":"text","text":"logger.exception(\"msg\")","marks":[{"type":"code"}]},{"type":"text","text":" does the same automatically inside an "},{"type":"text","text":"except","marks":[{"type":"code"}]},{"type":"text","text":" block."}]}]}}'),
  ('5672842c-2b69-748f-9547-facded818358', 'aW', 'heading', '{"level":1,"content":[{"type":"text","text":"assert","marks":[{"type":"code"}]},{"type":"text","text":" — for invariants, not validation"}]}'),
  ('d4ba76cb-3c35-7142-bbc8-67b71db2829a', 'aX', 'code', '{"language":"python","code":"def mean(xs):\n    assert xs, \"mean() of an empty list\"     # a developer''s sanity check\n    return sum(xs) / len(xs)\n\ntry:\n    mean([])\nexcept AssertionError as e:\n    print(e)                                 # mean() of an empty list","filename":"Python"}'),
  ('21b66497-00e5-70fe-838b-ef27a0c85244', 'aY', 'callout', '{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"python -O","marks":[{"type":"code"}]},{"type":"text","text":" strips every "},{"type":"text","text":"assert","marks":[{"type":"code"}]},{"type":"text","text":". Never use it to check user input, permissions or anything that must hold in production — "},{"type":"text","text":"raise ValueError","marks":[{"type":"code"}]},{"type":"text","text":" instead. And "},{"type":"text","text":"assert (cond, \"msg\")","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"always true","marks":[{"type":"bold"}]},{"type":"text","text":" (a non-empty tuple); Python emits a "},{"type":"text","text":"SyntaxWarning","marks":[{"type":"code"}]},{"type":"text","text":" for it."}]}]}}'),
  ('a083699f-d3b1-773b-a9a7-521f40b96586', 'aZ', 'heading', '{"level":1,"content":[{"type":"text","text":"Warnings"}]}'),
  ('09e8fd0b-0be5-77fe-aa9b-1eedf478f520', 'aa', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A warning reports something suspicious without stopping the program — most often a deprecation. Warnings are printed once per location by default and can be filtered or turned into errors."}]}]}}'),
  ('d3ced545-ad8e-7915-89aa-7d78b2a5235a', 'ab', 'code', '{"language":"python","code":"import warnings\n\ndef old_api():\n    warnings.warn(\"old_api() is deprecated; use new_api()\", DeprecationWarning, stacklevel=2)\n    return 42\n\nwith warnings.catch_warnings(record=True) as caught:\n    warnings.simplefilter(\"always\")\n    result = old_api()\n\nprint(result, caught[0].category.__name__)   # 42 DeprecationWarning\nprint(caught[0].message)                     # old_api() is deprecated; use new_api()","filename":"Python"}'),
  ('6737d5d7-edc0-7cc3-a540-bfe00158db9f', 'ac', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Filter action"}],[{"type":"text","text":"Effect"}]],[[{"type":"text","text":"\"default\"","marks":[{"type":"code"}]}],[{"type":"text","text":"Print the first occurrence per location"}]],[[{"type":"text","text":"\"always\"","marks":[{"type":"code"}]}],[{"type":"text","text":"Print every occurrence"}]],[[{"type":"text","text":"\"ignore\"","marks":[{"type":"code"}]}],[{"type":"text","text":"Never print"}]],[[{"type":"text","text":"\"error\"","marks":[{"type":"code"}]}],[{"type":"text","text":"Turn the warning into an exception — great in test suites ("},{"type":"text","text":"python -W error","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"pytest -W error","marks":[{"type":"code"}]},{"type":"text","text":")"}]]]}'),
  ('2164b660-ce40-7781-a176-a48b4c2fb678', 'ad', 'heading', '{"level":1,"content":[{"type":"text","text":"finally","marks":[{"type":"code"}]},{"type":"text","text":" beats "},{"type":"text","text":"return","marks":[{"type":"code"}]}]}'),
  ('ac0c40b4-d530-7431-8ef8-76662db7e518', 'ae', 'code', '{"language":"python","code":"def f():\n    try:\n        return \"from try\"\n    finally:\n        print(\"finally runs first\")   # finally runs first\n\nprint(f())                            # from try","filename":"Python"}'),
  ('afb388fa-d316-7cc8-be10-2818d9bc710b', 'af', 'code', '{"language":"python","code":"import warnings\n\n# A return inside finally silently DISCARDS an in-flight exception.\n# Python 3.14 warns about it at compile time (PEP 765); silenced here to show the behaviour.\nsrc = \"\"\"\ndef swallow():\n    try:\n        raise ValueError(\"lost!\")\n    finally:\n        return \"finally wins\"\n\"\"\"\nwith warnings.catch_warnings():\n    warnings.simplefilter(\"ignore\", SyntaxWarning)\n    ns = {}\n    exec(src, ns)\nprint(ns[\"swallow\"]())      # finally wins","filename":"Python"}'),
  ('8d48b027-4a62-750a-a998-c288f98e2917', 'ag', 'callout', '{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Never "},{"type":"text","text":"return","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"break","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"continue","marks":[{"type":"code"}]},{"type":"text","text":" out of a "},{"type":"text","text":"finally","marks":[{"type":"code"}]},{"type":"text","text":" block — the exception being propagated vanishes without a trace."}]}]}}'),
  ('3033ebfa-d6ed-703e-aa91-43f7ece73e0d', 'ah', 'heading', '{"level":1,"content":[{"type":"text","text":"EAFP, cost and the retry pattern"}]}'),
  ('5a7897d9-2f8f-77ff-b67b-e4532ca73104', 'ai', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Setting up a "},{"type":"text","text":"try","marks":[{"type":"code"}]},{"type":"text","text":" block is essentially free in Python 3.11+ (“zero-cost” exceptions); "},{"type":"text","text":"raising","marks":[{"type":"italic"}]},{"type":"text","text":" costs a few microseconds. So EAFP — just try and handle failure — is idiomatic when failure is the exception, not the rule."}]}]}}'),
  ('70238d8c-2ca6-75a5-b366-87a747075c93', 'aj', 'code', '{"language":"python","code":"def get_port(cfg):\n    try:\n        return int(cfg[\"port\"])\n    except (KeyError, ValueError):\n        return 8080\n\nprint(get_port({\"port\": \"5432\"}), get_port({}), get_port({\"port\": \"x\"}))   # 5432 8080 8080","filename":"Python"}'),
  ('adcf5e2d-3186-7462-ab16-09ccaea54fc1', 'ak', 'code', '{"language":"python","code":"import time\n\ndef retry(fn, attempts=3, base_delay=0.001, retry_on=(ConnectionError, TimeoutError)):\n    for attempt in range(1, attempts + 1):\n        try:\n            return fn()\n        except retry_on:\n            if attempt == attempts:\n                raise                                    # out of attempts: propagate\n            time.sleep(base_delay * 2 ** (attempt - 1))  # exponential backoff\n\ncalls = []\ndef flaky():\n    calls.append(1)\n    if len(calls) < 3:\n        raise ConnectionError(\"connection reset\")\n    return \"connected\"\n\nprint(retry(flaky), len(calls))   # connected 3","filename":"Python — retry with exponential backoff"}'),
  ('5392b02d-9463-7cec-b629-1db203ba4180', 'al', 'callout', '{"variant":"tip","title":"Do","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Retry only "},{"type":"text","text":"transient","marks":[{"type":"italic"}]},{"type":"text","text":" errors (timeouts, connection resets), cap the attempts, back off exponentially (add jitter in production) and log each failure."}]}]}}'),
  ('cbf0c7e5-f69a-75d4-a227-0759be3c2d6b', 'am', 'callout', '{"variant":"danger","title":"Avoid","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Retrying everything — a "},{"type":"text","text":"ValueError","marks":[{"type":"code"}]},{"type":"text","text":" from bad input will fail identically every time."}]}]}}'),
  ('81d5925a-9fc8-7cfa-a0a2-f88141de2c1f', 'an', 'heading', '{"level":1,"content":[{"type":"text","text":"Interview questions"}]}'),
  ('52cb45de-1009-784c-8a93-6d2936c93701', 'ao', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why shouldn''t you write except: or except BaseException:?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"They catch "},{"type":"text","text":"KeyboardInterrupt","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"SystemExit","marks":[{"type":"code"}]},{"type":"text","text":" too, so Ctrl-C and "},{"type":"text","text":"sys.exit()","marks":[{"type":"code"}]},{"type":"text","text":" stop working, and they hide real bugs. Catch "},{"type":"text","text":"Exception","marks":[{"type":"code"}]},{"type":"text","text":" at most (e.g. at a top-level request handler that logs and continues), and specific types everywhere else."}]}]}}'),
  ('e005f759-ea49-78c9-b9be-ea7e67091df0', 'ap', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the difference between raise X from e and raise X from None?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"from e","marks":[{"type":"code"}]},{"type":"text","text":" records "},{"type":"text","text":"e","marks":[{"type":"code"}]},{"type":"text","text":" as the explicit cause ("},{"type":"text","text":"__cause__","marks":[{"type":"code"}]},{"type":"text","text":") and the traceback shows both, linked by “direct cause”. "},{"type":"text","text":"from None","marks":[{"type":"code"}]},{"type":"text","text":" suppresses the context so only the new exception is shown — useful when the original is an implementation detail."}]}]}}'),
  ('0d64a890-5469-7060-98be-cb090374f16a', 'aq', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What does except* do?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"It matches exceptions "},{"type":"text","text":"inside","marks":[{"type":"italic"}]},{"type":"text","text":" an "},{"type":"text","text":"ExceptionGroup","marks":[{"type":"code"}]},{"type":"text","text":". Each "},{"type":"text","text":"except*","marks":[{"type":"code"}]},{"type":"text","text":" clause receives a sub-group of the matching exceptions; multiple clauses can run for the same group, and any unmatched exceptions are re-raised in a new group."}]}]}}'),
  ('437a7c63-2fa0-7c32-9331-4db0b36a46e3', 'ar', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When would you define a custom exception?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When callers need to react to a specific domain failure ("},{"type":"text","text":"CardDeclined","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"RateLimited","marks":[{"type":"code"}]},{"type":"text","text":") differently from others. Give the library one base class so callers can catch all of its errors, and attach structured data as attributes."}]}]}}')
) AS c(id, position, type, content)
