add = lambda a, b: a + b
print(add(2, 3))                                            # 5
words = ["banana", "Apple", "cherry"]
print(sorted(words, key=str.lower))                         # [''Apple'', ''banana'', ''cherry'']
print(sorted(words, key=lambda w: (len(w), w)))             # [''Apple'', ''banana'', ''cherry'']
print(max(["aa", "b", "cccc"], key=len))                    # cccc
