rt\n        start -= 1\n\nprint(list(Countdown(3)), list(countdown(3)))   # [3, 2, 1] [3, 2, 1]","filename":"Python"},"revision":1},{"id":"a4ef1006-a83c-7fdb-84d8-3b2b6d691c21","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Generator states"}]},"revision":1},{"id":"8ed0b867-0ac1-7439-b0e0-9bd51c7ce1e4","type":"code","position":"a5","content":{"language":"python","code":"from inspect import getgeneratorstate\n\ndef gen():\n    yield 1\n    yield 2\n\ng = gen()\nprint(getgeneratorstate(g))      # GEN_CREATED\nnext(g)\nprint(getgeneratorstate(g))      # GEN_SUSPENDED\nlist(g)\nprint(getgeneratorstate(g))      # GEN_CLOSED","filename":"Python"},"revision":1},{"id":"99412591-b0d8-7434-ae06-9bdac7e8b2e9","type":"table","position":"a6","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"State"}],[{"type":"text","text":"Meaning"}]],[[{"type":"text","text":"GEN_CREATED","marks":[{"type":"code"}]}],[{"type":"text","text":"Created, body hasn''t started — the first "},{"type":"text","text":"next()","marks":[{"type":"code"}]},{"type":"text","text":" runs up to the first "},{"type":"text","text":"yield","marks":[{"type":"code"}]}]],[[{"type":"text","text":"GEN_RUNNING","marks":[{"type":"code"}]}],[{"type":"text","text":"Currently executing (only visible from inside)"}]],[[{"type":"text","text":"GEN_SUSPENDED","marks":[{"type":"code"}]}],[{"type":"text","text":"Paused at a "},{"type":"text","text":"yield","marks":[{"type":"code"}]},{"type":"text","text":", locals preserved"}]],[[{"type":"text","text":"GEN_CLOSED","marks":[{"type":"code"}]}],[{"type":"text","text":"Finished, closed, or raised — further "},{"type":"text","text":"next()","marks":[{"type":"code"}]},{"type":"text","text":" raises "},{"type":"text","text":"StopIteration","marks":[{"type":"code"}]}]]]},"revision":1},{"id":"f16eb9f6-679a-7130-9979-2bcb183ca78a","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"send()","marks":[{"type":"code"}]},{"type":"text","text":": values flow "},{"type":"text","text":"into","marks":[{"type":"italic"}]},{"type":"text","text":" the generator"}]},"revision":1},{"id":"c24d9a90-a4a7-702d-9b6a-b4d3c276b3a3","type":"text","position":"a8","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"x = yield value","marks":[{"type":"code"}]},{"type":"text","text":" hands "},{"type":"text","text":"value","marks":[{"type":"code"}]},{"type":"text","text":" out and pauses; when resumed with "},{"type":"text","text":"g.send(v)","marks":[{"type":"code"}]},{"type":"text","text":", the "},{"type":"text","text":"yield","marks":[{"type":"code"}]},{"type":"text","text":" expression evaluates to "},{"type":"text","text":"v","marks":[{"type":"code"}]},{"type":"text","text":". "},{"type":"text","text":"next(g)","marks":[{"type":"code"}]},{"type":"text","text":" is the same as "},{"type":"text","text":"g.send(None)","marks":[{"type":"code"}]},{"type":"text","text":". The first call must be "},{"type":"text","text":"next()","marks":[{"type":"code"}]},{"type":"text","text":" (or "},{"type":"text","text":"send(None)","marks":[{"type":"code"}]},{"type":"text","text":") to "},{"type":"text","text":"prime","marks":[{"type":"italic"}]},{"type":"text","text":" the generator."}]}]}},"revision":1},{"id":"fdf05da7-6f6d-7aa7-96af-302cc9c993eb","type":"code","position":"a9","content":{"language":"python","code":"def running_average():\n    total, count, avg = 0, 0, None\n    while True:\n        value = yield avg           # hand out avg, wait for the next value\n        total += value\n        count += 1\n        avg = total / count\n\navg = running_average()\nnext(avg)                           # prime: run to the first yield\nprint(avg.send(10))                 # 10.0\nprint(avg.send(20))                 # 15.0\nprint(avg.send(60))                 # 30.0","filename":"Python"},"revision":1},{"id":"0291afcb-5ddb-7d24-83af-f367517149a0","type":"heading","position":"aA","content":{"level":1,"content":[{"type":"text","text":"throw()","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"close()","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"GeneratorExit","marks":[{"type":"code"}]}]},"revision":1},{"id":"2d12b90d-1a4b-713e-a228-1d545935670d","type":"code","position":"aB","content":{"language":"python","code":"def worker():\n    try:\n        while True:\n            try:\n                job = yield\n                print(\"did\", job)\n            except ValueError as e:\n                print(\"recovered from\", e)      # the error is raised AT the paused yield\n    finally:\n        print(\"cleanup\")                         # runs on close() — GeneratorExit\n\nw = worker()\nnext(w)\nw.send(\"a\")                                      # did a\nw.throw(ValueError(\"bad job\"))                   # recovered from bad job\nw.close()                                        # cleanup","filename":"Python"},"revision":1},{"id":"b6acd394-610a-7130-8318-86b1cf182c69","type":"code","position":"aC","content":{"language":"text","code":"did a\nrecovered from bad job\ncleanup","filename":"Output"},"revision":1},{"id":"e95513b2-dcc0-7958-b927-14af53ce0ccb","type":"callout","position":"aD","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Never swallow "},{"type":"text","text":"GeneratorExit","marks":[{"type":"code"}]},{"type":"text","text":" and keep yielding — "},{"type":"text","text":"close()","marks":[{"type":"code"}]},{"type":"text","text":" then raises "},{"type":"text","text":"RuntimeError: generator ignored GeneratorExit","marks":[{"type":"code"}]},{"type":"text","text":". Do cleanup in "},{"type":"text","text":"finally","marks":[{"type":"code"}]},{"type":"text","text":" and let it propagate."}]}]}},"revision":1},{"id":"994fc522-3ded-7734-a909-2f596c9b53f0","type":"heading","position":"aE","content":{"level":1,"content":[{"type":"text","text":"Return values & "},{"type":"text","text":"yield from","marks":[{"type":"code"}]}]},"revision":1},{"id":"aef2101b-8cdf-719d-9745-7f0ce8fc192f","type":"text","position":"aF","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A generator''s "},{"type":"text","text":"return x","marks":[{"type":"code"}]},{"type":"text","text":" becomes "},{"type":"text","text":"StopIteration(x).value","marks":[{"type":"code"}]},{"type":"text","text":". "},{"type":"text","text":"yield from sub","marks":[{"type":"code"}]},{"type":"text","text":" re-yields everything "},{"type":"text","text":"sub","marks":[{"type":"code"}]},{"type":"text","text":" produces, forwards "},{"type":"text","text":"send","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"throw","marks":[{"type":"code"}]},{"type":"text","text":" to it, and evaluates to its return value."}]}]}},"revision":1},{"id":"d15c4296-1f37-7481-a3e5-9e4c57e3937a","type":"code","position":"aG","content":{"language":"python","code":"def read_block(lines):\n    count = 0\n    for line in lines:\n        if line == \"END\":\n            return count                 # becomes the value of \"yield from\"\n        yield line.upper()\n        count += 1\n\ndef document(lines):\n    it = iter(lines)\n    n1 = yield from read_block(it)\n    n2 = yield from read_block(it)\n    yield f\"blocks had {n1} and {n2} lines\"\n\nprint(list(document([\"a\", \"b\", \"END\", \"c\", \"END\"])))\n# [''A'', ''B'', ''C'', ''blocks had 2 and 1 lines'']","filename":"Python"},"revision":1},{"id":"eb0cf692-254a-7a97-b650-ac882f08678e","type":"code","position":"aH","content":{"language":"text","code":"[''A'', ''B'', ''C'', ''blocks had 2 and 1 lines'']","filename":"Output"},"revision":1},{"id":"8e8e8f46-60b4-7d00-9607-53c249646e03","type":"code","position":"aI","content":{"language":"python","code":"def tree(node):                          # recursive delegation: walk a nested structure\n    name, children = node\n    yield name\n    for child in children:\n        yield from tree(child)\n\nt = (\"root\", [(\"a\", [(\"a1\", [])]), (\"b\", [])])\nprint(list(tree(t)))                     # [''root'', ''a'', ''a1'', ''b'']","filename":"Python"},"revision":1},{"id":"37a29447-fa38-76ba-915a-70cb9e45ec0f","type":"heading","position":"aJ","content":{"level":1,"content":[{"type":"text","text":"Pipelines"}]},"revision":1},{"id":"6d7ca0b6-9927-7ff3-9173-8dfdc77a97a7","type":"code","position":"aK","content":{"language":"python","code":"def parse(lines):\n    for line in lines:\n        name, amount = line.split(\",\")\n        yield name, float(amount)\n\ndef only_large(rows, limit):\n    return ((n, a) for n, a in rows if a >= limit)\n\ndef total(rows):\n    return sum(a for _, a in rows)\n\nlog = [\"tea,40\", \"laptop,55000\", \"phone,18000\", \"pen,10\"]\nprint(total(only_large(parse(log), 1000)))    # 73000.0","filename":"Python"},"revision":1},{"id":"e560e76b-b7fc-750f-bb9c-db7438e35a94","type":"callout","position":"aL","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Each stage pulls one item at a time from the previous one, so the whole pipeline runs in constant memory — whether the input is 4 lines or a 40 GB log file."}]}]}},"revision":1},{"id":"64f403a4-cd71-7c6e-995b-222260140ade","type":"heading","position":"aM","content":{"level":1,"content":[{"type":"text","text":"From generators to "},{"type":"text","text":"async","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"await","marks":[{"type":"code"}]}]},"revision":1},{"id":"d59fdc01-157b-7f54-9a79-21300af46bdb","type":"text","position":"aN","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"2001 — generators (PEP 255)","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"yield","marks":[{"type":"code"}]},{"type":"text","text":" makes pausable functions."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"2005 — ","marks":[{"type":"bold"}]},{"type":"text","text":"send","marks":[{"type":"code"},{"type":"bold"}]},{"type":"text","text":"/","marks":[{"type":"bold"}]},{"type":"text","text":"throw","marks":[{"type":"code"},{"type":"bold"}]},{"type":"text","text":"/","marks":[{"type":"bold"}]},{"type":"text","text":"close","marks":[{"type":"code"},{"type":"bold"}]},{"type":"text","text":" (PEP 342)","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Generators become coroutines that can receive values."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"2012 — ","marks":[{"type":"bold"}]},{"type":"text","text":"yield from","marks":[{"type":"code"},{"type":"bold"}]},{"type":"text","text":" (PEP 380)","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Delegation lets coroutines call sub-coroutines; asyncio was first built on it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"2015 — ","marks":[{"type":"bold"}]},{"type":"text","text":"async def","marks":[{"type":"code"},{"type":"bold"}]},{"type":"text","text":" / ","marks":[{"type":"bold"}]},{"type":"text","text":"await","marks":[{"type":"code"},{"type":"bold"}]},{"type":"text","text":" (PEP 492)","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Native coroutine syntax, separate from generators, with the same suspend/resume idea."}]}]}]}]}},"revision":1},{"id":"68bbb21c-6421-7bac-820d-d916e1b0fbc8","type":"callout","position":"aO","content":{"variant":"warning","title":"One-shot","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A generator can be consumed "},{"type":"text","text":"once","marks":[{"type":"bold"}]},{"type":"text","text":". Passing the same generator to two functions gives the second one nothing — materialise it with "},{"type":"text","text":"list()","marks":[{"type":"code"}]},{"type":"text","text":" or use "},{"type":"text","text":"itertools.tee","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"3da7961e-0176-7d0a-b8de-20e17d370120","type":"question","position":"aP","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What does send() do, and why must you call next() first?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"send(v)","marks":[{"type":"code"}]},{"type":"text","text":" resumes a paused generator and makes the pending "},{"type":"text","text":"yield","marks":[{"type":"code"}]},{"type":"text","text":" expression evaluate to "},{"type":"text","text":"v","marks":[{"type":"code"}]},{"type":"text","text":". A freshly created generator isn''t paused at a "},{"type":"text","text":"yield","marks":[{"type":"code"}]},{"type":"text","text":" yet, so the first resume must be "},{"type":"text","text":"next(g)","marks":[{"type":"code"}]},{"type":"text","text":" (or "},{"type":"text","text":"send(None)","marks":[{"type":"code"}]},{"type":"text","text":") — sending a non-"},{"type":"text","text":"None","marks":[{"type":"code"}]},{"type":"text","text":" value raises "},{"type":"text","text":"TypeError","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"163542bb-c8c5-746e-9cf9-e32d1532ded1","type":"question","position":"aQ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you get a generator''s return value?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"With "},{"type":"text","text":"yield from","marks":[{"type":"code"}]},{"type":"text","text":" (the expression''s value), or by catching "},{"type":"text","text":"StopIteration","marks":[{"type":"code"}]},{"type":"text","text":" and reading "},{"type":"text","text":".value","marks":[{"type":"code"}]},{"type":"text","text":". A plain "},{"type":"text","text":"for","marks":[{"type":"code"}]},{"type":"text","text":" loop discards it."}]}]}},"revision":1},{"id":"dac93867-4b5f-7232-9dae-956d257af372","type":"question","position":"aR","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Generator vs coroutine in modern Python?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A generator ("},{"type":"text","text":"def","marks":[{"type":"code"}]},{"type":"text","text":" + "},{"type":"text","text":"yield","marks":[{"type":"code"}]},{"type":"text","text":") produces a stream of values. A native coroutine ("},{"type":"text","text":"async def","marks":[{"type":"code"}]},{"type":"text","text":") is awaited and scheduled by an event loop; it can''t be iterated with "},{"type":"text","text":"for","marks":[{"type":"code"}]},{"type":"text","text":". Both suspend and resume a frame, but they are different types with different protocols."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
