INSERT INTO "notes"."Card" ("id", "noteId", "position", "type", "content", "revision", "createdAt", "updatedAt")
SELECT c.id::uuid, '1a07fd7f-4f81-7ba4-b377-7e3ee550f1c4', c.position, c.type::"notes"."CardType", c.content::jsonb, 1, TIMESTAMPTZ '2026-10-07 03:23:53+00', TIMESTAMPTZ '2026-10-07 03:23:53+00'
FROM (VALUES
  ('6cad2215-34a9-7cce-8327-3043615ff4c5', 'a0', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Generators are more than lazy lists: they can receive values, be told to stop, return a result and delegate to each other — the machinery that "},{"type":"text","text":"async","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"await","marks":[{"type":"code"}]},{"type":"text","text":" grew out of."}]}]}}'),
  ('0480b829-f5c6-780a-b1b0-2e22b0eceea9', 'a1', 'heading', '{"level":1,"content":[{"type":"text","text":"Iterator class vs generator"}]}'),
  ('86be2e2a-6633-7e0c-979b-6b128b8fb762', 'a2', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Both objects below behave identically in a "},{"type":"text","text":"for","marks":[{"type":"code"}]},{"type":"text","text":" loop. The generator version gets "},{"type":"text","text":"__iter__","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"__next__","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"StopIteration","marks":[{"type":"code"}]},{"type":"text","text":" for free."}]}]}}'),
  ('12b57f32-ef6f-789e-a337-68a4533128ea', 'a3', 'code', '{"language":"python","code":"class Countdown:                       # hand-written iterator\n    def __init__(self, start):\n        self.n = start\n    def __iter__(self):\n        return self\n    def __next__(self):\n        if self.n <= 0:\n            raise StopIteration\n        self.n -= 1\n        return self.n + 1\n\ndef countdown(start):                  # the same thing as a generator\n    while start > 0:\n        yield start\n        start -= 1\n\nprint(list(Countdown(3)), list(countdown(3)))   # [3, 2, 1] [3, 2, 1]","filename":"Python"}'),
  ('a4ef1006-a83c-7fdb-84d8-3b2b6d691c21', 'a4', 'heading', '{"level":1,"content":[{"type":"text","text":"Generator states"}]}'),
  ('8ed0b867-0ac1-7439-b0e0-9bd51c7ce1e4', 'a5', 'code', '{"language":"python","code":"from inspect import getgeneratorstate\n\ndef gen():\n    yield 1\n    yield 2\n\ng = gen()\nprint(getgeneratorstate(g))      # GEN_CREATED\nnext(g)\nprint(getgeneratorstate(g))      # GEN_SUSPENDED\nlist(g)\nprint(getgeneratorstate(g))      # GEN_CLOSED","filename":"Python"}'),
  ('99412591-b0d8-7434-ae06-9bdac7e8b2e9', 'a6', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"State"}],[{"type":"text","text":"Meaning"}]],[[{"type":"text","text":"GEN_CREATED","marks":[{"type":"code"}]}],[{"type":"text","text":"Created, body hasn''t started — the first "},{"type":"text","text":"next()","marks":[{"type":"code"}]},{"type":"text","text":" runs up to the first "},{"type":"text","text":"yield","marks":[{"type":"code"}]}]],[[{"type":"text","text":"GEN_RUNNING","marks":[{"type":"code"}]}],[{"type":"text","text":"Currently executing (only visible from inside)"}]],[[{"type":"text","text":"GEN_SUSPENDED","marks":[{"type":"code"}]}],[{"type":"text","text":"Paused at a "},{"type":"text","text":"yield","marks":[{"type":"code"}]},{"type":"text","text":", locals preserved"}]],[[{"type":"text","text":"GEN_CLOSED","marks":[{"type":"code"}]}],[{"type":"text","text":"Finished, closed, or raised — further "},{"type":"text","text":"next()","marks":[{"type":"code"}]},{"type":"text","text":" raises "},{"type":"text","text":"StopIteration","marks":[{"type":"code"}]}]]]}'),
  ('f16eb9f6-679a-7130-9979-2bcb183ca78a', 'a7', 'heading', '{"level":1,"content":[{"type":"text","text":"send()","marks":[{"type":"code"}]},{"type":"text","text":": values flow "},{"type":"text","text":"into","marks":[{"type":"italic"}]},{"type":"text","text":" the generator"}]}'),
  ('c24d9a90-a4a7-702d-9b6a-b4d3c276b3a3', 'a8', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"x = yield value","marks":[{"type":"code"}]},{"type":"text","text":" hands "},{"type":"text","text":"value","marks":[{"type":"code"}]},{"type":"text","text":" out and pauses; when resumed with "},{"type":"text","text":"g.send(v)","marks":[{"type":"code"}]},{"type":"text","text":", the "},{"type":"text","text":"yield","marks":[{"type":"code"}]},{"type":"text","text":" expression evaluates to "},{"type":"text","text":"v","marks":[{"type":"code"}]},{"type":"text","text":". "},{"type":"text","text":"next(g)","marks":[{"type":"code"}]},{"type":"text","text":" is the same as "},{"type":"text","text":"g.send(None)","marks":[{"type":"code"}]},{"type":"text","text":". The first call must be "},{"type":"text","text":"next()","marks":[{"type":"code"}]},{"type":"text","text":" (or "},{"type":"text","text":"send(None)","marks":[{"type":"code"}]},{"type":"text","text":") to "},{"type":"text","text":"prime","marks":[{"type":"italic"}]},{"type":"text","text":" the generator."}]}]}}'),
  ('fdf05da7-6f6d-7aa7-96af-302cc9c993eb', 'a9', 'code', '{"language":"python","code":"def running_average():\n    total, count, avg = 0, 0, None\n    while True:\n        value = yield avg           # hand out avg, wait for the next value\n        total += value\n        count += 1\n        avg = total / count\n\navg = running_average()\nnext(avg)                           # prime: run to the first yield\nprint(avg.send(10))                 # 10.0\nprint(avg.send(20))                 # 15.0\nprint(avg.send(60))                 # 30.0","filename":"Python"}'),
  ('0291afcb-5ddb-7d24-83af-f367517149a0', 'aA', 'heading', '{"level":1,"content":[{"type":"text","text":"throw()","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"close()","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"GeneratorExit","marks":[{"type":"code"}]}]}'),
  ('2d12b90d-1a4b-713e-a228-1d545935670d', 'aB', 'code', '{"language":"python","code":"def worker():\n    try:\n        while True:\n            try:\n                job = yield\n                print(\"did\", job)\n            except ValueError as e:\n                print(\"recovered from\", e)      # the error is raised AT the paused yield\n    finally:\n        print(\"cleanup\")                         # runs on close() — GeneratorExit\n\nw = worker()\nnext(w)\nw.send(\"a\")                                      # did a\nw.throw(ValueError(\"bad job\"))                   # recovered from bad job\nw.close()                                        # cleanup","filename":"Python"}'),
  ('b6acd394-610a-7130-8318-86b1cf182c69', 'aC', 'code', '{"language":"text","code":"did a\nrecovered from bad job\ncleanup","filename":"Output"}'),
  ('e95513b2-dcc0-7958-b927-14af53ce0ccb', 'aD', 'callout', '{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Never swallow "},{"type":"text","text":"GeneratorExit","marks":[{"type":"code"}]},{"type":"text","text":" and keep yielding — "},{"type":"text","text":"close()","marks":[{"type":"code"}]},{"type":"text","text":" then raises "},{"type":"text","text":"RuntimeError: generator ignored GeneratorExit","marks":[{"type":"code"}]},{"type":"text","text":". Do cleanup in "},{"type":"text","text":"finally","marks":[{"type":"code"}]},{"type":"text","text":" and let it propagate."}]}]}}'),
  ('994fc522-3ded-7734-a909-2f596c9b53f0', 'aE', 'heading', '{"level":1,"content":[{"type":"text","text":"Return values & "},{"type":"text","text":"yield from","marks":[{"type":"code"}]}]}'),
  ('aef2101b-8cdf-719d-9745-7f0ce8fc192f', 'aF', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A generator''s "},{"type":"text","text":"return x","marks":[{"type":"code"}]},{"type":"text","text":" becomes "},{"type":"text","text":"StopIteration(x).value","marks":[{"type":"code"}]},{"type":"text","text":". "},{"type":"text","text":"yield from sub","marks":[{"type":"code"}]},{"type":"text","text":" re-yields everything "},{"type":"text","text":"sub","marks":[{"type":"code"}]},{"type":"text","text":" produces, forwards "},{"type":"text","text":"send","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"throw","marks":[{"type":"code"}]},{"type":"text","text":" to it, and evaluates to its return value."}]}]}}'),
  ('d15c4296-1f37-7481-a3e5-9e4c57e3937a', 'aG', 'code', '{"language":"python","code":"def read_block(lines):\n    count = 0\n    for line in lines:\n        if line == \"END\":\n            return count                 # becomes the value of \"yield from\"\n        yield line.upper()\n        count += 1\n\ndef document(lines):\n    it = iter(lines)\n    n1 = yield from read_block(it)\n    n2 = yield from read_block(it)\n    yield f\"blocks had {n1} and {n2} lines\"\n\nprint(list(document([\"a\", \"b\", \"END\", \"c\", \"END\"])))\n# [''A'', ''B'', ''C'', ''blocks had 2 and 1 lines'']","filename":"Python"}'),
  ('eb0cf692-254a-7a97-b650-ac882f08678e', 'aH', 'code', '{"language":"text","code":"[''A'', ''B'', ''C'', ''blocks had 2 and 1 lines'']","filename":"Output"}'),
  ('8e8e8f46-60b4-7d00-9607-53c249646e03', 'aI', 'code', '{"language":"python","code":"def tree(node):                          # recursive delegation: walk a nested structure\n    name, children = node\n    yield name\n    for child in children:\n        yield from tree(child)\n\nt = (\"root\", [(\"a\", [(\"a1\", [])]), (\"b\", [])])\nprint(list(tree(t)))                     # [''root'', ''a'', ''a1'', ''b'']","filename":"Python"}'),
  ('37a29447-fa38-76ba-915a-70cb9e45ec0f', 'aJ', 'heading', '{"level":1,"content":[{"type":"text","text":"Pipelines"}]}'),
  ('6d7ca0b6-9927-7ff3-9173-8dfdc77a97a7', 'aK', 'code', '{"language":"python","code":"def parse(lines):\n    for line in lines:\n        name, amount = line.split(\",\")\n        yield name, float(amount)\n\ndef only_large(rows, limit):\n    return ((n, a) for n, a in rows if a >= limit)\n\ndef total(rows):\n    return sum(a for _, a in rows)\n\nlog = [\"tea,40\", \"laptop,55000\", \"phone,18000\", \"pen,10\"]\nprint(total(only_large(parse(log), 1000)))    # 73000.0","filename":"Python"}'),
  ('e560e76b-b7fc-750f-bb9c-db7438e35a94', 'aL', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Each stage pulls one item at a time from the previous one, so the whole pipeline runs in constant memory — whether the input is 4 lines or a 40 GB log file."}]}]}}'),
