filename":"Python"},"revision":1},{"id":"22f5db5f-8c69-77ce-9eb6-c7025abb5d71","type":"callout","position":"a6","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"print","marks":[{"type":"code"}]},{"type":"text","text":" returns "},{"type":"text","text":"None","marks":[{"type":"code"}]},{"type":"text","text":" — it only has a side effect. Errors and diagnostics belong on "},{"type":"text","text":"sys.stderr","marks":[{"type":"code"}]},{"type":"text","text":" ("},{"type":"text","text":"print(msg, file=sys.stderr)","marks":[{"type":"code"}]},{"type":"text","text":") so they don''t mix with the program''s real output."}]}]}},"revision":1},{"id":"b4122cc0-ab4d-7f6c-bda6-7f763aa1dcad","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"input()","marks":[{"type":"code"}]},{"type":"text","text":" — reading a line"}]},"revision":1},{"id":"844ad21b-d73e-7130-98c9-6ef15106ea4c","type":"text","position":"a8","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"input(prompt)","marks":[{"type":"code"}]},{"type":"text","text":" shows the prompt, waits for the user to press Enter and returns the line "},{"type":"text","text":"as a ","marks":[{"type":"bold"}]},{"type":"text","text":"str","marks":[{"type":"bold"},{"type":"code"}]},{"type":"text","text":", without the newline","marks":[{"type":"bold"}]},{"type":"text","text":". Convert it yourself."}]}]}},"revision":1},{"id":"3e096f54-2cba-7c52-9955-f5fd5759d63a","type":"code","position":"a9","content":{"language":"","code":"name = input(\"Your name? \")\nage = int(input(\"Your age? \"))\nprint(f\"Hi {name}, next year you''ll be {age + 1}\")\n\n$ python3 greet.py\nYour name? Asha\nYour age? 24\nHi Asha, next year you''ll be 25","filename":"greet.py"},"revision":1},{"id":"219b9449-a230-7102-98d8-51ed6ba37f8d","type":"text","position":"aA","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Below, "},{"type":"text","text":"sys.stdin","marks":[{"type":"code"}]},{"type":"text","text":" is swapped for an in-memory stream so the example runs without a keyboard — exactly how tests feed input to a program."}]}]}},"revision":1},{"id":"45b768cc-d762-7fe1-bf0d-1afb91cce917","type":"code","position":"aB","content":{"language":"python","code":"import io, sys\nfake = io.StringIO(\"Asha\\n3 1 4 1 5\\n42\\n\")\nold, sys.stdin = sys.stdin, fake          # pretend the user typed three lines\ntry:\n    name = input()                        # ''Asha'' — always a str\n    nums = list(map(int, input().split()))\n    n = int(input())\n    try:\n        input()                           # nothing left to read\n    except EOFError:\n        eof = True\nfinally:\n    sys.stdin = old                       # always restore the real stdin\nprint(name, nums, n + 1, eof)             # Asha [3, 1, 4, 1, 5] 43 True","filename":"Python"},"revision":1},{"id":"53369300-866f-763f-ab7b-de2dbd5d5d2e","type":"callout","position":"aC","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"input()","marks":[{"type":"code"}]},{"type":"text","text":" never returns a number: "},{"type":"text","text":"input() + 1","marks":[{"type":"code"}]},{"type":"text","text":" is a "},{"type":"text","text":"TypeError","marks":[{"type":"code"}]},{"type":"text","text":". And at end of input (Ctrl-D, or a judge''s file running out) it raises "},{"type":"text","text":"EOFError","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"bf52f751-4d65-7c2e-b633-2f74a2619702","type":"heading","position":"aD","content":{"level":1,"content":[{"type":"text","text":"Parsing patterns"}]},"revision":1},{"id":"29c4525c-78c0-77fd-b4e4-788f47c0239f","type":"table","position":"aE","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Input shape"}],[{"type":"text","text":"Code"}]],[[{"type":"text","text":"One integer"}],[{"type":"text","text":"n = int(input())","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Two integers on a line"}],[{"type":"text","text":"a, b = map(int, input().split())","marks":[{"type":"code"}]}]],[[{"type":"text","text":"A list of integers"}],[{"type":"text","text":"nums = list(map(int, input().split()))","marks":[{"type":"code"}]}]],[[{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" lines of text"}],[{"type":"text","text":"lines = [input() for _ in range(n)]","marks":[{"type":"code"}]}]],[[{"type":"text","text":"A grid of characters"}],[{"type":"text","text":"grid = [list(input()) for _ in range(rows)]","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Comma-separated"}],[{"type":"text","text":"parts = input().split('','')","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Everything at once"}],[{"type":"text","text":"tokens = sys.stdin.read().split()","marks":[{"type":"code"}]}]]]},"revision":1},{"id":"ece9c61c-4561-7457-a1a4-15a52a17191f","type":"heading","position":"aF","content":{"level":1,"content":[{"type":"text","text":"Fast input for coding rounds"}]},"revision":1},{"id":"947c2ad9-1f70-76fd-b21e-efc0c0d16bbe","type":"text","position":"aG","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"input()","marks":[{"type":"code"}]},{"type":"text","text":" is slow for 10⁵+ lines. "},{"type":"text","text":"sys.stdin.readline","marks":[{"type":"code"}]},{"type":"text","text":" is much faster, but it "},{"type":"text","text":"keeps the trailing ","marks":[{"type":"bold"}]},{"type":"text","text":"\\n","marks":[{"type":"bold"},{"type":"code"}]},{"type":"text","text":" — strip it (or let "},{"type":"text","text":"int()","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"split()","marks":[{"type":"code"}]},{"type":"text","text":" ignore it)."}]}]}},"revision":1},{"id":"8a3b02d7-a151-7a16-9619-54009a7aad7f","type":"code","position":"aH","content":{"language":"python","code":"import io\ndata = io.StringIO(\"3\\n10 20\\n30 40\\n50 60\\n\")\nreadline = data.readline                  # real code: import sys; readline = sys.stdin.readline\nn = int(readline())                       # int() ignores the trailing newline\npairs = [tuple(map(int, readline().split())) for _ in range(n)]\nprint(pairs)                              # [(10, 20), (30, 40), (50, 60)]\nprint(repr(io.StringIO(\"hi\\n\").readline()))   # ''hi\\n''\n\ntokens = iter(io.StringIO(\"2\\n5 7\\n\").read().split())   # read everything, walk token by token\ncount = int(next(tokens))\nprint(sum(int(next(tokens)) for _ in range(count)))    # 12","filename":"Python"},"revision":1},{"id":"d1ad3511-4259-7272-958b-cfb1f876d72f","type":"heading","position":"aI","content":{"level":1,"content":[{"type":"text","text":"Fast output"}]},"revision":1},{"id":"f4521598-4ec2-790f-a893-21cd4d29464f","type":"code","position":"aJ","content":{"language":"python","code":"import sys\nwritten = sys.stdout.write(\"written \")    # no automatic newline; returns chars written\nprint(written)                            # written 8\n\nresults = [3, 1, 4]\nprint(\" \".join(map(str, results)))        # 3 1 4","filename":"Python"},"revision":1},{"id":"8b94b944-4879-7d70-8a0e-e0aaf6c5bf2a","type":"callout","position":"aK","content":{"variant":"tip","title":"Do","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Collect answers in a list and print once with "},{"type":"text","text":"''\\n''.join(map(str, answers))","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"77fd7274-71fa-799a-8537-c5a26433934a","type":"callout","position":"aL","content":{"variant":"danger","title":"Avoid","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Calling "},{"type":"text","text":"print","marks":[{"type":"code"}]},{"type":"text","text":" a million times in a loop — each call has overhead (and may flush)."}]}]}},"revision":1},{"id":"f5eb5d41-7315-7a0d-a5fb-727a6aa632f4","type":"heading","position":"aM","content":{"level":1,"content":[{"type":"text","text":"Pretty-printing nested data"}]},"revision":1},{"id":"69ba1406-8dc5-7039-a37c-5b384bf3e75b","type":"code","position":"aN","content":{"language":"python","code":"from pprint import pprint\ndata = {\"name\": \"Asha\", \"skills\": [\"python\", \"sql\", \"dsa\"],\n        \"address\": {\"city\": \"Pune\", \"pin\": 411001}}\npprint(data, width=40)","filename":"Python"},"revision":1},{"id":"eca1bce5-e814-743e-a539-237c24b5621c","type":"code","position":"aO","content":{"language":"text","code":"{''address'': {''city'': ''Pune'',\n             ''pin'': 411001},\n ''name'': ''Asha'',\n ''skills'': [''python'', ''sql'', ''dsa'']}","filename":"Output"},"revision":1},{"id":"76bcf04e-7f79-7764-ad7e-c5888b7e8fa7","type":"callout","position":"aP","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"pprint","marks":[{"type":"code"}]},{"type":"text","text":" wraps long structures and sorts dict keys (pass "},{"type":"text","text":"sort_dicts=False","marks":[{"type":"code"}]},{"type":"text","text":" to keep insertion order). "},{"type":"text","text":"pprint.pformat","marks":[{"type":"code"}]},{"type":"text","text":" returns the text instead of printing it."}]}]}},"revision":1},{"id":"1e4afde9-e9d2-79fd-b5c5-6c9ec1846214","type":"heading","position":"aQ","content":{"level":1,"content":[{"type":"text","text":"Formatting output"}]},"revision":1},{"id":"aa092719-e380-7e32-b227-4c393fd4e535","type":"code","position":"aR","content":{"language":"python","code":"price, qty, item = 49.5, 3, \"pen\"\nprint(f\"{item:<6}|{qty:>3}|{price * qty:8.2f}|\")   # pen   |  3|  148.50|\nprint(f\"{0.4567:.1%}  {1234567:,}  {7:03d}\")       # 45.7%  1,234,567  007","filename":"Python"},"revision":1},{"id":"fcf8b900-3469-75c6-a9c7-036c0c181506","type":"text","position":"aS","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"f-strings and the format-spec mini-language ("},{"type":"text","text":":<6","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":".2f","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":",","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"%","marks":[{"type":"code"}]},{"type":"text","text":") are covered in depth in "},{"type":"text","text":"String Formatting","marks":[{"type":"bold"}]},{"type":"text","text":" under "},{"type":"text","text":"Strings & Numbers","marks":[{"type":"italic"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"7f54cd6c-3ab0-77cc-8481-e825bb85653c","type":"question","position":"aT","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What type does input() return?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Always "},{"type":"text","text":"str","marks":[{"type":"code"}]},{"type":"text","text":" (without the trailing newline), even if the user types digits. Convert explicitly: "},{"type":"text","text":"int(input())","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"float(input())","marks":[{"type":"code"}]},{"type":"text","text":", or "},{"type":"text","text":"map(int, input().split())","marks":[{"type":"code"}]},{"type":"text","text":" for several numbers."}]}]}},"revision":1},{"id":"67645607-3560-7f7b-9d8a-46af42e68139","type":"question","position":"aU","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why use sys.stdin.readline instead of input()?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"It avoids "},{"type":"text","text":"input()","marks":[{"type":"code"}]},{"type":"text","text":"''s per-call overhead (prompt handling, newline stripping), which matters with hundreds of thousands of lines. Remember it keeps the "},{"type":"text","text":"\\n","marks":[{"type":"code"}]},{"type":"text","text":", and returns "},{"type":"text","text":"''''","marks":[{"type":"code"}]},{"type":"text","text":" (not "},{"type":"text","text":"EOFError","marks":[{"type":"code"}]},{"type":"text","text":") at end of input."}]}]}},"revision":1},{"id":"ff68d765-958b-72b9-b6cf-1050b7100b8b","type":"question","position":"aV","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the difference between print and sys.stdout.write?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"print","marks":[{"type":"code"}]},{"type":"text","text":" accepts any objects, converts them with "},{"type":"text","text":"str()","marks":[{"type":"code"}]},{"type":"text","text":", adds separators and a newline, and returns "},{"type":"text","text":"None","marks":[{"type":"code"}]},{"type":"text","text":". "},{"type":"text","text":"sys.stdout.write","marks":[{"type":"code"}]},{"type":"text","text":" accepts one string, adds nothing, and returns the number of characters written."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
