FROM (VALUES
  ('39cba9ff-9555-76d8-a53b-9ef4547fc955', 'a0', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The Python questions that come up again and again — with short, precise answers you can say out loud."}]}]}}'),
  ('bdee4e61-9dde-7bbb-837d-bcc9e28a9789', 'a1', 'heading', '{"level":1,"content":[{"type":"text","text":"Core language"}]}'),
  ('98855129-45c1-7b5c-a6d0-8b006b8507c9', 'a2', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the difference between a list and a tuple?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A list is "},{"type":"text","text":"mutable","marks":[{"type":"bold"}]},{"type":"text","text":" (append, remove, assign by index); a tuple is "},{"type":"text","text":"immutable","marks":[{"type":"bold"}]},{"type":"text","text":". Tuples are hashable (if their items are), so they can be dict keys or set items, and they''re slightly smaller and faster. Use tuples for fixed records and lists for collections that change."}]}]}}'),
  ('a35e593e-2d80-7689-8b03-692f66f86a57', 'a3', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How is a Python dict implemented, and why are lookups O(1)?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"It''s a hash table. The key''s "},{"type":"text","text":"hash()","marks":[{"type":"code"}]},{"type":"text","text":" picks a slot; collisions are resolved with open addressing (probing). Average lookup, insert and delete are O(1); the worst case is O(n) with many collisions. Since 3.7 dicts preserve insertion order."}]}]}}'),
  ('8e8ba540-22a4-78b1-beb1-f697ab3419a9', 'a4', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the GIL?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The Global Interpreter Lock in CPython lets only one thread run Python bytecode at a time. Threads still help for "},{"type":"text","text":"I/O-bound","marks":[{"type":"bold"}]},{"type":"text","text":" work (the lock is released while waiting), but for "},{"type":"text","text":"CPU-bound","marks":[{"type":"bold"}]},{"type":"text","text":" work you use "},{"type":"text","text":"multiprocessing","marks":[{"type":"code"}]},{"type":"text","text":" (separate processes, each with its own GIL) or native extensions."}]}]}}'),
  ('9ca83fe7-a820-728e-9bea-b0c5151058a3', 'a5', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"is vs ==?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"==","marks":[{"type":"code"}]},{"type":"text","text":" compares "},{"type":"text","text":"values","marks":[{"type":"bold"}]},{"type":"text","text":" (calls "},{"type":"text","text":"__eq__","marks":[{"type":"code"}]},{"type":"text","text":"); "},{"type":"text","text":"is","marks":[{"type":"code"}]},{"type":"text","text":" compares "},{"type":"text","text":"identity","marks":[{"type":"bold"}]},{"type":"text","text":" (same object in memory). Use "},{"type":"text","text":"is","marks":[{"type":"code"}]},{"type":"text","text":" only for singletons such as "},{"type":"text","text":"None","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('adc60dd0-d611-7819-a4b5-71e55fa642a0', 'a6', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What happens with a mutable default argument?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Defaults are evaluated once, when the function is defined, so "},{"type":"text","text":"def f(x, items=[])","marks":[{"type":"code"}]},{"type":"text","text":" shares one list across calls. Use "},{"type":"text","text":"items=None","marks":[{"type":"code"}]},{"type":"text","text":" and create the list inside the function."}]}]}}'),
  ('40bc07c5-1a0e-72f4-8f67-2b22ba586128', 'a7', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Shallow copy vs deep copy?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A shallow copy ("},{"type":"text","text":"xs[:]","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"copy.copy","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"list(xs)","marks":[{"type":"code"}]},{"type":"text","text":") creates a new container holding "},{"type":"text","text":"the same","marks":[{"type":"bold"}]},{"type":"text","text":" inner objects. A deep copy ("},{"type":"text","text":"copy.deepcopy","marks":[{"type":"code"}]},{"type":"text","text":") recursively copies the inner objects too, so nested changes don''t leak between them."}]}]}}'),
  ('1b28217a-657a-7aed-8604-6b1a5e3956b7', 'a8', 'heading', '{"level":1,"content":[{"type":"text","text":"Functions & objects"}]}'),
  ('11fb653e-5a06-7b34-8775-666eb41a17dd', 'a9', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What are *args and **kwargs?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"*args","marks":[{"type":"code"}]},{"type":"text","text":" collects extra positional arguments into a tuple; "},{"type":"text","text":"**kwargs","marks":[{"type":"code"}]},{"type":"text","text":" collects extra keyword arguments into a dict. At the call site, "},{"type":"text","text":"*","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"**","marks":[{"type":"code"}]},{"type":"text","text":" unpack a sequence or mapping into arguments."}]}]}}'),
  ('f565dca6-fc60-737a-a8cf-572968e587b0', 'aA', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is a decorator?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A callable that takes a function and returns a new one wrapping it. "},{"type":"text","text":"@d","marks":[{"type":"code"}]},{"type":"text","text":" above "},{"type":"text","text":"def f","marks":[{"type":"code"}]},{"type":"text","text":" means "},{"type":"text","text":"f = d(f)","marks":[{"type":"code"}]},{"type":"text","text":". Used for logging, timing, caching ("},{"type":"text","text":"@cache","marks":[{"type":"code"}]},{"type":"text","text":"), access checks and registering routes. Use "},{"type":"text","text":"functools.wraps","marks":[{"type":"code"}]},{"type":"text","text":" to keep the original name and docstring."}]}]}}'),
  ('d18edc1f-61e6-7d40-a649-bd73b3f14ce2', 'aB', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Generator vs list — when would you use each?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A list stores every item in memory and can be iterated many times. A generator produces items lazily on demand, uses O(1) memory and can be iterated "},{"type":"text","text":"once","marks":[{"type":"bold"}]},{"type":"text","text":". Use generators for large or infinite streams and pipelines; lists when you need indexing, "},{"type":"text","text":"len","marks":[{"type":"code"}]},{"type":"text","text":" or repeated passes."}]}]}}'),
  ('bd9535d9-dbe3-713a-aa60-cdcf54c3ec5a', 'aC', 'heading', '{"level":1,"content":[{"type":"text","text":"Runtime, memory & concurrency"}]}'),
  ('6acd3870-4a22-7411-925a-5ce484ae2784', 'aD', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How does Python manage memory?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Objects live on a private heap. CPython frees an object as soon as its "},{"type":"text","text":"reference count","marks":[{"type":"bold"}]},{"type":"text","text":" drops to zero, and a generational "},{"type":"text","text":"garbage collector","marks":[{"type":"bold"}]},{"type":"text","text":" ("},{"type":"text","text":"gc","marks":[{"type":"code"}]},{"type":"text","text":") cleans up reference cycles that refcounting can''t."}]}]}}'),
  ('9bf19ce6-8e3d-7b2d-83b1-11ba7ecfb669', 'aE', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What are @staticmethod and @classmethod?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An instance method receives "},{"type":"text","text":"self","marks":[{"type":"code"}]},{"type":"text","text":". A "},{"type":"text","text":"@classmethod","marks":[{"type":"code"}]},{"type":"text","text":" receives the class ("},{"type":"text","text":"cls","marks":[{"type":"code"}]},{"type":"text","text":") — typically used for alternative constructors like "},{"type":"text","text":"from_json","marks":[{"type":"code"}]},{"type":"text","text":". A "},{"type":"text","text":"@staticmethod","marks":[{"type":"code"}]},{"type":"text","text":" receives neither; it''s a plain function grouped inside the class."}]}]}}'),
  ('7e3c463f-8464-7df3-887b-72e699c247ec', 'aF', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Explain the MRO and super()."}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The Method Resolution Order is the sequence Python searches for attributes in a class hierarchy, computed by C3 linearization ("},{"type":"text","text":"Class.__mro__","marks":[{"type":"code"}]},{"type":"text","text":"). "},{"type":"text","text":"super()","marks":[{"type":"code"}]},{"type":"text","text":" delegates to the "},{"type":"text","text":"next","marks":[{"type":"bold"}]},{"type":"text","text":" class in that order, not necessarily the direct parent — enabling cooperative multiple inheritance."}]}]}}'),
  ('c06b38f6-2381-7256-841f-e07c11e7876c', 'aG', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What does if __name__ == \"__main__\": do?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"__name__","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"\"__main__\"","marks":[{"type":"code"}]},{"type":"text","text":" only when the file is run directly. Code under the guard runs for "},{"type":"text","text":"python file.py","marks":[{"type":"code"}]},{"type":"text","text":" but not when the module is imported — keeping imports free of side effects."}]}]}}'),
  ('6e26490c-f8f1-72bb-a074-47b531487e47', 'aH', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you handle exceptions properly?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Catch specific exceptions, keep "},{"type":"text","text":"try","marks":[{"type":"code"}]},{"type":"text","text":" blocks small, use "},{"type":"text","text":"else","marks":[{"type":"code"}]},{"type":"text","text":" for code that should run only on success and "},{"type":"text","text":"finally","marks":[{"type":"code"}]},{"type":"text","text":" (or "},{"type":"text","text":"with","marks":[{"type":"code"}]},{"type":"text","text":") for cleanup. Chain with "},{"type":"text","text":"raise NewError(...) from e","marks":[{"type":"code"}]},{"type":"text","text":" to keep the cause, and never silence errors with a bare "},{"type":"text","text":"except:","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('b3706880-e909-76e7-a958-a595a6bfb5c7', 'aI', 'heading', '{"level":1,"content":[{"type":"text","text":"Predict the output"}]}'),
  ('01f54886-9486-756e-859d-f06c0191bbac', 'aJ', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the output? (lists vs tuples with +=)"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"x = [1, 2, 3]","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"y = x","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"y += [4]","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"print(x)          # [1, 2, 3, 4]","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"a = (1, 2)","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"b = a","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"b += (3,)","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"print(a, b)       # (1, 2) (1, 2, 3)","marks":[{"type":"code"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Lists are mutable, so "},{"type":"text","text":"+=","marks":[{"type":"code"}]},{"type":"text","text":" extends the shared list in place. Tuples are immutable, so "},{"type":"text","text":"+=","marks":[{"type":"code"}]},{"type":"text","text":" builds a new tuple and rebinds only "},{"type":"text","text":"b","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
