  ('dd691c6d-0786-7841-9bd8-a90fe699c7bb', 'a0', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Iteration is a protocol: an "},{"type":"text","text":"iterable","marks":[{"type":"italic"}]},{"type":"text","text":" gives you an "},{"type":"text","text":"iterator","marks":[{"type":"italic"}]},{"type":"text","text":", and an iterator hands out items with "},{"type":"text","text":"next()","marks":[{"type":"code"}]},{"type":"text","text":" until it raises "},{"type":"text","text":"StopIteration","marks":[{"type":"code"}]},{"type":"text","text":". Generators make writing iterators trivial."}]}]}}'),
