SELECT '5c8a7a54-e353-7cb4-be69-c9831a536df7', 'a8dd076f-d889-754a-a4d7-899757214fc3', 1, 'PUBLISHED', 'itertools Deep Dive', '[{"id":"0b5ed268-ae85-7ee7-8059-d4d02eafdfdc","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"itertools","marks":[{"type":"code"}]},{"type":"text","text":" is a toolkit of fast, memory-efficient iterator building blocks written in C. Combine them to express loops as pipelines."}]}]}},"revision":1},{"id":"bdda478c-5cfc-79ca-a67f-deb12bd61128","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Infinite iterators"}]},"revision":1},{"id":"ecdd2811-6c65-7e55-aa86-914618eb115c","type":"code","position":"a2","content":{"language":"python","code":"from itertools import count, cycle, repeat, islice\n\nprint(list(islice(count(10, 5), 4)))          # [10, 15, 20, 25]\nprint(list(islice(cycle(\"AB\"), 5)))           # [''A'', ''B'', ''A'', ''B'', ''A'']\nprint(list(repeat(\"x\", 3)))                   # [''x'', ''x'', ''x'']\nprint(list(map(pow, [2, 3, 4], repeat(2))))   # [4, 9, 16]","filename":"Python"},"revision":1},{"id":"a698126a-e44e-7dcf-b935-9c8d9a98735a","type":"callout","position":"a3","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"count()","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"cycle()","marks":[{"type":"code"}]},{"type":"text","text":" never stop — always bound them with "},{"type":"text","text":"islice","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"zip","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"takewhile","marks":[{"type":"code"}]},{"type":"text","text":" or a "},{"type":"text","text":"break","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"bfe80816-2ab9-786f-991f-cc493f520b71","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Slicing & filtering"}]},"revision":1},{"id":"8fd12d2a-b8bf-7b32-a8dc-79179659e46b","type":"code","position":"a5","content":{"language":"python","code":"from itertools import islice, takewhile, dropwhile, filterfalse, compress\n\nnums = [1, 4, 6, 3, 8, 2]\nprint(list(islice(nums, 1, 5, 2)))                  # [4, 3]\nprint(list(takewhile(lambda n: n < 5, nums)))       # [1, 4]\nprint(list(dropwhile(lambda n: n < 5, nums)))       # [6, 3, 8, 2]\nprint(list(filterfalse(lambda n: n % 2, nums)))     # [4, 6, 8, 2]\nprint(list(compress(\"abcdef\", [1, 0, 1, 0, 0, 1]))) # [''a'', ''c'', ''f'']","filename":"Python"},"revision":1},{"id":"ed58672f-1879-78b1-aab1-faa64bccde37","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"Combining & reshaping"}]},"revision":1},{"id":"482567dc-17b1-7322-843d-7b0a7291a943","type":"code","position":"a7","content":{"language":"python","code":"from itertools import chain, zip_longest, pairwise, batched, starmap, accumulate\nimport operator\n\nprint(list(chain.from_iterable([[1, 2], [3], []])))       # [1, 2, 3]\nprint(list(zip_longest(\"abc\", [1], fillvalue=0)))          # [(''a'', 1), (''b'', 0), (''c'', 0)]\nprint(list(pairwise([1, 4, 9, 16])))                       # [(1, 4), (4, 9), (9, 16)]\nprint(list(batched(range(7), 3)))                          # [(0, 1, 2), (3, 4, 5), (6,)]\nprint(list(starmap(operator.mul, [(2, 3), (4, 5)])))       # [6, 20]\nprint(list(accumulate([3, 1, 4, 1, 5], max)))              # [3, 3, 4, 4, 5]\nprint(list(accumulate([1, 2, 3], initial=100)))            # [100, 101, 103, 106]","filename":"Python"},"revision":1},{"id":"73cda2d3-3248-7620-b747-6f736e244048","type":"table","position":"a8","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Function"}],[{"type":"text","text":"Since"}],[{"type":"text","text":"Use it for"}]],[[{"type":"text","text":"chain.from_iterable(xss)","marks":[{"type":"code"}]}],[{"type":"text","text":"—"}],[{"type":"text","text":"Flatten one level lazily"}]],[[{"type":"text","text":"zip_longest(a, b, fillvalue=…)","marks":[{"type":"code"}]}],[{"type":"text","text":"—"}],[{"type":"text","text":"Zip without truncating to the shortest"}]],[[{"type":"text","text":"pairwise(it)","marks":[{"type":"code"}]}],[{"type":"text","text":"3.10"}],[{"type":"text","text":"Consecutive pairs — differences, gaps, edges of a path"}]],[[{"type":"text","text":"batched(it, n)","marks":[{"type":"code"}]}],[{"type":"text","text":"3.12"}],[{"type":"text","text":"Fixed-size chunks ("},{"type":"text","text":"strict=True","marks":[{"type":"code"}]},{"type":"text","text":" in 3.13 demands full batches)"}]],[[{"type":"text","text":"accumulate(it, func)","marks":[{"type":"code"}]}],[{"type":"text","text":"—"}],[{"type":"text","text":"Running totals / max / products (prefix sums)"}]],[[{"type":"text","text":"starmap(f, pairs)","marks":[{"type":"code"}]}],[{"type":"text","text":"—"}],[{"type":"text","text":"f(*args)","marks":[{"type":"code"}]},{"type":"text","text":" for each tuple of args"}]],[[{"type":"text","text":"tee(it, n)","marks":[{"type":"code"}]}],[{"type":"text","text":"—"}],[{"type":"text","text":"Split one iterator into "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" independent ones (buffers items)"}]]]},"revision":1},{"id":"b08de765-8698-78b0-b8d1-398f3af39cd7","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Combinatorics"}]},"revision":1},{"id":"b2c17a37-9544-7c96-9c9e-c6ec6a8bc052","type":"code","position":"aA","content":{"language":"python","code":"from itertools import product, permutations, combinations, combinations_with_replacement\nfrom math import comb, perm\n\nprint(list(product(\"ab\", repeat=2)))               # [(''a'', ''a''), (''a'', ''b''), (''b'', ''a''), (''b'', ''b'')]\nprint(list(permutations(\"abc\", 2)))                # [(''a'', ''b''), (''a'', ''c''), (''b'', ''a''), (''b'', ''c''), (''c'', ''a''), (''c'', ''b'')]\nprint(list(combinations([1, 2, 3], 2)))            # [(1, 2), (1, 3), (2, 3)]\nprint(list(combinations_with_replacement(\"ab\", 2)))  # [(''a'', ''a''), (''a'', ''b''), (''b'', ''b'')]\nprint(len(list(permutations(range(5), 3))), perm(5, 3), comb(5, 3))   # 60 60 10","filename":"Python"},"revision":1},{"id":"619ea651-7502-7a64-b832-02282559856e","type":"table","position":"aB","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Function"}],[{"type":"text","text":"Order matters?"}],[{"type":"text","text":"Repeats?"}],[{"type":"text","text":"Count for n items, size r"}]],[[{"type":"text","text":"product(xs, repeat=r)","marks":[{"type":"code"}]}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"nʳ"}]],[[{"type":"text","text":"permutations(xs, r)","marks":[{"type":"code"}]}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"No"}],[{"type":"text","text":"n! / (n−r)!"}]],[[{"type":"text","text":"combinations(xs, r)","marks":[{"type":"code"}]}],[{"type":"text","text":"No"}],[{"type":"text","text":"No"}],[{"type":"text","text":"n! / (r!(n−r)!)"}]],[[{"type":"text","text":"combinations_with_replacement(xs, r)","marks":[{"type":"code"}]}],[{"type":"text","text":"No"}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"(n+r−1)! / (r!(n−1)!)"}]]]},"revision":1},{"id":"5b3ff574-b61c-7cab-b4c3-59ff5af1b454","type":"heading","position":"aC","content":{"level":1,"content":[{"type":"text","text":"groupby — done right"}]},"revision":1},{"id":"8db7434b-0ed3-7294-9e37-15d45f5e07ee","type":"code","position":"aD","content":{"language":"python","code":"from itertools import groupby\nfrom operator import itemgetter\n\nsales = [(\"fruit\", \"apple\"), (\"veg\", \"kale\"), (\"fruit\", \"kiwi\"), (\"veg\", \"leek\")]\nprint([k for k, _ in groupby(sales, key=itemgetter(0))])   # [''fruit'', ''veg'', ''fruit'', ''veg'']\n\nsales.sort(key=itemgetter(0))                               # sort by the SAME key first\ngrouped = {k: [name for _, name in g] for k, g in groupby(sales, key=itemgetter(0))}\nprint(grouped)                                              # {''fruit'': [''apple'', ''kiwi''], ''veg'': [''kale'', ''leek'']}\n\n# Run-length encoding: the classic groupby interview question\nprint(\"\".join(f\"{ch}{len(list(g))}\" for ch, g in groupby(\"aaabccdd\")))   # a3b1c2d2","filename":"Python"},"revision":1},{"id":"1b4270f9-47e3-7250-a5fb-54cbe605ce09","type":"callout","position":"aE","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Each group is an iterator tied to the parent "},{"type":"text","text":"groupby","marks":[{"type":"code"}]},{"type":"text","text":". Advancing to the next group invalidates the previous one — consume (e.g. "},{"type":"text","text":"list(g)","marks":[{"type":"code"}]},{"type":"text","text":") before moving on."}]}]}},"revision":1},{"id":"e5dbee54-5efa-70dd-940d-53f590a256b9","type":"heading","position":"aF","content":{"level":1,"content":[{"type":"text","text":"Recipes"}]},"revision":1},{"id":"5f3aacc8-8350-7b67-b35c-ed26278d18d2","type":"code","position":"aG","content":{"language":"python","code":"from itertools import islice, chain, cycle\nfrom collections import deque\n\ndef sliding_window(it, n):\n    it = iter(it)\n    window = deque(islice(it, n - 1), maxlen=n)\n    for x in it:\n        window.append(x)\n        yield tuple(window)\n\ndef unique_everseen(it):\n    seen = set()\n    for x in it:\n        if x not in seen:\n            seen.add(x)\n            yield x\n\ndef roundrobin(*its):\n    iterators = cycle(iter(i) for i in its)\n    pending = len(its)\n    while pending:\n        try:\n            yield next(next(iterators))\n        except StopIteration:\n            pending -= 1\n            iterators = cycle(list(islice(iterators, pending)))\n\nprint(list(sliding_window([1, 2, 3, 4, 5], 3)))   # [(1, 2, 3), (2, 3, 4), (3, 4, 5)]\nprint(list(unique_everseen(\"abracadabra\")))       # [''a'', ''b'', ''r'', ''c'', ''d'']\nprint(list(roundrobin(\"ABC\", \"D\", \"EF\")))         # [''A'', ''D'', ''E'', ''B'', ''F'', ''C'']","filename":"Python"},"revision":1},{"id":"a803898d-58f8-7e8b-b242-36207bae64bc","type":"callout","position":"aH","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The official docs end with an "},{"type":"text","text":"Itertools Recipes","marks":[{"type":"italic"}]},{"type":"text","text":" section; the third-party "},{"type":"text","text":"more-itertools","marks":[{"type":"code"}]},{"type":"text","text":" package ships all of them (and many more) ready to import."}]}]}},"revision":1},{"id":"8f015838-649d-7d9a-a971-8196c32f7741","type":"question","position":"aI","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How would you generate all subsets of a list?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"chain.from_iterable(combinations(xs, r) for r in range(len(xs) + 1))","marks":[{"type":"code"}]},{"type":"text","text":" — 2ⁿ subsets, produced lazily. Alternatively, loop a bitmask from "},{"type":"text","text":"0","marks":[{"type":"code"}]},{"type":"text","text":" to "},{"type":"text","text":"2**n - 1","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"3df64a25-f761-776e-bbca-ff35c90a7a29","type":"question","position":"aJ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why does groupby return the same key more than once?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"It only groups "},{"type":"text","text":"consecutive","marks":[{"type":"bold"}]},{"type":"text","text":" items with equal keys, like the Unix "},{"type":"text","text":"uniq","marks":[{"type":"code"}]},{"type":"text","text":" command. Sort by the same key first, or use a "},{"type":"text","text":"defaultdict(list)","marks":[{"type":"code"}]},{"type":"text","text":" if order doesn''t matter."}]}]}},"revision":1},{"id":"ddfc28be-c934-7edf-bbb5-87c84003fb4d","type":"question","position":"aK","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the benefit of itertools over writing loops?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"They are implemented in C and lazy: less memory (items are produced on demand), often faster, composable into pipelines, and they express intent ("},{"type":"text","text":"pairwise","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"batched","marks":[{"type":"code"}]},{"type":"text","text":") instead of index arithmetic."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
