  ('bfe80816-2ab9-786f-991f-cc493f520b71', 'a4', 'heading', '{"level":1,"content":[{"type":"text","text":"Slicing & filtering"}]}'),
  ('8fd12d2a-b8bf-7b32-a8dc-79179659e46b', 'a5', 'code', '{"language":"python","code":"from itertools import islice, takewhile, dropwhile, filterfalse, compress\n\nnums = [1, 4, 6, 3, 8, 2]\nprint(list(islice(nums, 1, 5, 2)))                  # [4, 3]\nprint(list(takewhile(lambda n: n < 5, nums)))       # [1, 4]\nprint(list(dropwhile(lambda n: n < 5, nums)))       # [6, 3, 8, 2]\nprint(list(filterfalse(lambda n: n % 2, nums)))     # [4, 6, 8, 2]\nprint(list(compress(\"abcdef\", [1, 0, 1, 0, 0, 1]))) # [''a'', ''c'', ''f'']","filename":"Python"}'),
  ('ed58672f-1879-78b1-aab1-faa64bccde37', 'a6', 'heading', '{"level":1,"content":[{"type":"text","text":"Combining & reshaping"}]}'),
  ('482567dc-17b1-7322-843d-7b0a7291a943', 'a7', 'code', '{"language":"python","code":"from itertools import chain, zip_longest, pairwise, batched, starmap, accumulate\nimport operator\n\nprint(list(chain.from_iterable([[1, 2], [3], []])))       # [1, 2, 3]\nprint(list(zip_longest(\"abc\", [1], fillvalue=0)))          # [(''a'', 1), (''b'', 0), (''c'', 0)]\nprint(list(pairwise([1, 4, 9, 16])))                       # [(1, 4), (4, 9), (9, 16)]\nprint(list(batched(range(7), 3)))                          # [(0, 1, 2), (3, 4, 5), (6,)]\nprint(list(starmap(operator.mul, [(2, 3), (4, 5)])))       # [6, 20]\nprint(list(accumulate([3, 1, 4, 1, 5], max)))              # [3, 3, 4, 4, 5]\nprint(list(accumulate([1, 2, 3], initial=100)))            # [100, 101, 103, 106]","filename":"Python"}'),
  ('73cda2d3-3248-7620-b747-6f736e244048', 'a8', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Function"}],[{"type":"text","text":"Since"}],[{"type":"text","text":"Use it for"}]],[[{"type":"text","text":"chain.from_iterable(xss)","marks":[{"type":"code"}]}],[{"type":"text","text":"—"}],[{"type":"text","text":"Flatten one level lazily"}]],[[{"type":"text","text":"zip_longest(a, b, fillvalue=…)","marks":[{"type":"code"}]}],[{"type":"text","text":"—"}],[{"type":"text","text":"Zip without truncating to the shortest"}]],[[{"type":"text","text":"pairwise(it)","marks":[{"type":"code"}]}],[{"type":"text","text":"3.10"}],[{"type":"text","text":"Consecutive pairs — differences, gaps, edges of a path"}]],[[{"type":"text","text":"batched(it, n)","marks":[{"type":"code"}]}],[{"type":"text","text":"3.12"}],[{"type":"text","text":"Fixed-size chunks ("},{"type":"text","text":"strict=True","marks":[{"type":"code"}]},{"type":"text","text":" in 3.13 demands full batches)"}]],[[{"type":"text","text":"accumulate(it, func)","marks":[{"type":"code"}]}],[{"type":"text","text":"—"}],[{"type":"text","text":"Running totals / max / products (prefix sums)"}]],[[{"type":"text","text":"starmap(f, pairs)","marks":[{"type":"code"}]}],[{"type":"text","text":"—"}],[{"type":"text","text":"f(*args)","marks":[{"type":"code"}]},{"type":"text","text":" for each tuple of args"}]],[[{"type":"text","text":"tee(it, n)","marks":[{"type":"code"}]}],[{"type":"text","text":"—"}],[{"type":"text","text":"Split one iterator into "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" independent ones (buffers items)"}]]]}'),
