  ('b2c17a37-9544-7c96-9c9e-c6ec6a8bc052', 'aA', 'code', '{"language":"python","code":"from itertools import product, permutations, combinations, combinations_with_replacement\nfrom math import comb, perm\n\nprint(list(product(\"ab\", repeat=2)))               # [(''a'', ''a''), (''a'', ''b''), (''b'', ''a''), (''b'', ''b'')]\nprint(list(permutations(\"abc\", 2)))                # [(''a'', ''b''), (''a'', ''c''), (''b'', ''a''), (''b'', ''c''), (''c'', ''a''), (''c'', ''b'')]\nprint(list(combinations([1, 2, 3], 2)))            # [(1, 2), (1, 3), (2, 3)]\nprint(list(combinations_with_replacement(\"ab\", 2)))  # [(''a'', ''a''), (''a'', ''b''), (''b'', ''b'')]\nprint(len(list(permutations(range(5), 3))), perm(5, 3), comb(5, 3))   # 60 60 10","filename":"Python"}'),
  ('619ea651-7502-7a64-b832-02282559856e', 'aB', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Function"}],[{"type":"text","text":"Order matters?"}],[{"type":"text","text":"Repeats?"}],[{"type":"text","text":"Count for n items, size r"}]],[[{"type":"text","text":"product(xs, repeat=r)","marks":[{"type":"code"}]}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"nʳ"}]],[[{"type":"text","text":"permutations(xs, r)","marks":[{"type":"code"}]}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"No"}],[{"type":"text","text":"n! / (n−r)!"}]],[[{"type":"text","text":"combinations(xs, r)","marks":[{"type":"code"}]}],[{"type":"text","text":"No"}],[{"type":"text","text":"No"}],[{"type":"text","text":"n! / (r!(n−r)!)"}]],[[{"type":"text","text":"combinations_with_replacement(xs, r)","marks":[{"type":"code"}]}],[{"type":"text","text":"No"}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"(n+r−1)! / (r!(n−1)!)"}]]]}'),
