  ('5f3aacc8-8350-7b67-b35c-ed26278d18d2', 'aG', 'code', '{"language":"python","code":"from itertools import islice, chain, cycle\nfrom collections import deque\n\ndef sliding_window(it, n):\n    it = iter(it)\n    window = deque(islice(it, n - 1), maxlen=n)\n    for x in it:\n        window.append(x)\n        yield tuple(window)\n\ndef unique_everseen(it):\n    seen = set()\n    for x in it:\n        if x not in seen:\n            seen.add(x)\n            yield x\n\ndef roundrobin(*its):\n    iterators = cycle(iter(i) for i in its)\n    pending = len(its)\n    while pending:\n        try:\n            yield next(next(iterators))\n        except StopIteration:\n            pending -= 1\n            iterators = cycle(list(islice(iterators, pending)))\n\nprint(list(sliding_window([1, 2, 3, 4, 5], 3)))   # [(1, 2, 3), (2, 3, 4), (3, 4, 5)]\nprint(list(unique_everseen(\"abracadabra\")))       # [''a'', ''b'', ''r'', ''c'', ''d'']\nprint(list(roundrobin(\"ABC\", \"D\", \"EF\")))         # [''A'', ''D'', ''E'', ''B'', ''F'', ''C'']","filename":"Python"}'),
