SELECT 'f87efcb7-7a16-7db8-9985-8c618ddd5439', '756a6e7a-52ec-7741-b100-3ab91dc646e3', 1, 'PUBLISHED', 'Loops & Iteration Patterns', '[{"id":"8405cd88-062a-7330-a117-9f689213d5ef","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Python''s "},{"type":"text","text":"for","marks":[{"type":"code"}]},{"type":"text","text":" walks over "},{"type":"text","text":"any iterable","marks":[{"type":"italic"}]},{"type":"text","text":" — there is no C-style "},{"type":"text","text":"for (i = 0; …)","marks":[{"type":"code"}]},{"type":"text","text":". This topic collects the loop patterns, helpers and pitfalls you meet every day."}]}]}},"revision":1},{"id":"2789ae34-23db-7f3f-a64f-44265a1155fc","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"range","marks":[{"type":"code"}]},{"type":"text","text":" in detail"}]},"revision":1},{"id":"d1a9d663-ac33-79ad-85d9-99d163c4d23b","type":"code","position":"a2","content":{"language":"python","code":"print(list(range(5)))                 # [0, 1, 2, 3, 4]\nprint(list(range(2, 12, 3)))          # [2, 5, 8, 11]\nprint(list(range(5, 0, -1)))          # [5, 4, 3, 2, 1]\nprint(list(range(3, 0)))              # []   ← empty: a negative step is needed to count down\nr = range(0, 10**12, 2)               # no list is built — O(1) memory\nprint(len(r), r[10], r[-1])           # 500000000000 20 999999999998\nprint(999_999 in r, 1_000 in r)       # False True   ← O(1) arithmetic check","filename":"Python"},"revision":1},{"id":"39b58034-9bcc-7df4-b361-c38b67ab46cc","type":"table","position":"a3","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Goal"}],[{"type":"text","text":"Loop header"}]],[[{"type":"text","text":"0 … n−1"}],[{"type":"text","text":"for i in range(n)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"1 … n inclusive"}],[{"type":"text","text":"for i in range(1, n + 1)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"n−1 down to 0"}],[{"type":"text","text":"for i in range(n - 1, -1, -1)","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"reversed(range(n))","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Every other index"}],[{"type":"text","text":"for i in range(0, n, 2)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Items and their index"}],[{"type":"text","text":"for i, x in enumerate(xs)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Two lists in step"}],[{"type":"text","text":"for a, b in zip(xs, ys)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Neighbouring pairs"}],[{"type":"text","text":"for a, b in zip(xs, xs[1:])","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"itertools.pairwise(xs)","marks":[{"type":"code"}]}]]]},"revision":1},{"id":"0d973d9c-194a-74c8-88d8-8503f90fcac1","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"while","marks":[{"type":"code"}]},{"type":"text","text":" loops and "},{"type":"text","text":"while … else","marks":[{"type":"code"}]}]},"revision":1},{"id":"6b6bb623-b685-7820-830d-ac04c4c315d2","type":"text","position":"a5","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Use "},{"type":"text","text":"while","marks":[{"type":"code"}]},{"type":"text","text":" when you don''t know the number of iterations in advance. Like "},{"type":"text","text":"for","marks":[{"type":"code"}]},{"type":"text","text":", it takes an "},{"type":"text","text":"else","marks":[{"type":"code"}]},{"type":"text","text":" that runs only if the loop ended "},{"type":"text","text":"without","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"break","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"66891f5b-ea0e-74b0-ac97-2961bdbdc43d","type":"code","position":"a6","content":{"language":"python","code":"n, steps = 27, 0\nwhile n != 1:                         # Collatz sequence\n    n = n // 2 if n % 2 == 0 else 3 * n + 1\n    steps += 1\nprint(steps)                          # 111\n\ndef is_prime(n):\n    if n < 2:\n        return False\n    d = 2\n    while d * d <= n:\n        if n % d == 0:\n            break                     # found a divisor\n        d += 1\n    else:\n        return True                   # no break → no divisor found\n    return False\n\nprint([k for k in range(20) if is_prime(k)])   # [2, 3, 5, 7, 11, 13, 17, 19]","filename":"Python"},"revision":1},{"id":"21a5e064-faeb-7924-9278-7cc7aa18262b","type":"code","position":"a7","content":{"language":"python","code":"attempts = 0\nwhile True:                           # the do-while idiom: body runs at least once\n    attempts += 1\n    if attempts * attempts > 20:\n        break\nprint(attempts)                       # 5","filename":"Python"},"revision":1},{"id":"f1d279a5-541b-7b49-aa02-165193211fb1","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"Breaking out of nested loops"}]},"revision":1},{"id":"1e903687-f1fb-78e5-bb8f-d057751feb5d","type":"text","position":"a9","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"break","marks":[{"type":"code"}]},{"type":"text","text":" only leaves the innermost loop. Three ways out of two:"}]}]}},"revision":1},{"id":"ac1bd886-87aa-7c4f-84dd-bbd499254690","type":"code","position":"aA","content":{"language":"python","code":"grid = [[1, 2, 3], [4, 5, 6], [7, 8, 9]]\n\n# 1. A flag checked by the outer loop\nfound = None\nfor r, row in enumerate(grid):\n    for c, val in enumerate(row):\n        if val == 5:\n            found = (r, c)\n            break\n    if found:\n        break\nprint(found)                          # (1, 1)\n\n# 2. Put the loops in a function and return (usually the cleanest)\ndef find(grid, target):\n    for r, row in enumerate(grid):\n        for c, val in enumerate(row):\n            if val == target:\n                return r, c\n    return None\nprint(find(grid, 8), find(grid, 0))   # (2, 1) None\n\n# 3. One flat loop over all coordinates\nfrom itertools import product\nhit = next(((r, c) for r, c in product(range(3), range(3)) if grid[r][c] == 9), None)\nprint(hit)                            # (2, 2)","filename":"Python"},"revision":1},{"id":"3e9f74c6-f7ef-7b4b-9cd5-dac9a73de2c2","type":"heading","position":"aB","content":{"level":1,"content":[{"type":"text","text":"Iterating dicts, in order, in reverse, in parallel"}]},"revision":1},{"id":"86d9eaa3-ebb4-7c13-8f83-3cabee45cdda","type":"code","position":"aC","content":{"language":"python","code":"prices = {\"tea\": 20, \"coffee\": 35, \"juice\": 50}\nprint([k for k in prices])                        # [''tea'', ''coffee'', ''juice'']\nprint([f\"{k}={v}\" for k, v in prices.items()])    # [''tea=20'', ''coffee=35'', ''juice=50'']\nprint(sorted(prices, key=prices.get, reverse=True))   # [''juice'', ''coffee'', ''tea'']\n\nnames = [\"asha\", \"ravi\", \"kiran\"]\nscores = [91, 84, 77]\nprint(list(enumerate(names, start=1)))    # [(1, ''asha''), (2, ''ravi''), (3, ''kiran'')]\nprint(dict(zip(names, scores)))           # {''asha'': 91, ''ravi'': 84, ''kiran'': 77}\nprint(list(zip(names, [1, 2])))           # [(''asha'', 1), (''ravi'', 2)]   ← stops at the shortest\ntry:\n    list(zip(names, [1, 2], strict=True)) # 3.10+: insist on equal lengths\nexcept ValueError as e:\n    print(e)                              # zip() argument 2 is shorter than argument 1\nprint(list(reversed(names)))              # [''kiran'', ''ravi'', ''asha'']\n\npairs = [(\"a\", 1), (\"b\", 2)]\nletters, numbers = zip(*pairs)            # \"unzip\"\nprint(letters, numbers)                   # (''a'', ''b'') (1, 2)","filename":"Python"},"revision":1},{"id":"561831b0-092f-7623-98a7-2b610f576225","type":"heading","position":"aD","content":{"level":1,"content":[{"type":"text","text":"Don''t modify a collection while looping over it"}]},"revision":1},{"id":"e80ff0e2-2a66-7cfc-aa19-5bba655595e0","type":"code","position":"aE","content":{"language":"python","code":"nums = [1, 2, 2, 3, 4]\nfor x in nums:\n    if x % 2 == 0:\n        nums.remove(x)        # shifts later items left → the loop skips one\nprint(nums)                   # [1, 2, 3]   ← a 2 survived!\n\nnums = [1, 2, 2, 3, 4]\nprint([x for x in nums if x % 2])       # [1, 3]   ← build a new list instead\n\nd = {\"a\": 1, \"b\": 2}\ntry:\n    for k in d:\n        if d[k] == 1:\n            del d[k]\nexcept RuntimeError as e:\n    print(e)                  # dictionary changed size during iteration\nd = {k: v for k, v in d.items() if v != 1}\nprint(d)                      # {''b'': 2}","filename":"Python"},"revision":1},{"id":"97d7061b-36b8-7ef4-b442-a67bab7a0bcc","type":"callout","position":"aF","content":{"variant":"note","title":"Build a new collection","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A comprehension that keeps what you want — the idiomatic fix."}]}]}},"revision":1},{"id":"07ce8c21-7683-76b9-b25f-569908fc5d94","type":"callout","position":"aG","content":{"variant":"note","title":"Loop over a copy","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"for x in nums[:]:","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"for k in list(d):","marks":[{"type":"code"}]},{"type":"text","text":" — then mutating the original is safe."}]}]}},"revision":1},{"id":"425d0baf-d468-7754-bfb9-633d52e99c87","type":"callout","position":"aH","content":{"variant":"note","title":"Loop backwards by index","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"for i in range(len(xs) - 1, -1, -1): del xs[i]","marks":[{"type":"code"}]},{"type":"text","text":" — deletions don''t shift unvisited items."}]}]}},"revision":1},{"id":"e914e60a-7bfc-73f0-ab40-f7927d5ee8b2","type":"heading","position":"aI","content":{"level":1,"content":[{"type":"text","text":"Sentinel loops & "},{"type":"text","text":"iter(callable, sentinel)","marks":[{"type":"code"}]}]},"revision":1},{"id":"921507a7-3b04-7a29-a04f-6585450283c0","type":"code","position":"aJ","content":{"language":"python","code":"import io\nfrom functools import partial\n\nstream = io.StringIO(\"alpha\\nbeta\\n\\ngamma\\n\")\nlines = []\nwhile (line := stream.readline().rstrip(\"\\n\")):   # stop at the first empty line\n    lines.append(line)\nprint(lines)                                      # [''alpha'', ''beta'']\n\nf = io.StringIO(\"abcdefgh\")\nchunks = list(iter(partial(f.read, 3), \"\"))       # call f.read(3) until it returns \"\"\nprint(chunks)                                     # [''abc'', ''def'', ''gh'']","filename":"Python"},"revision":1},{"id":"bce8de98-5cf4-7375-973c-28564fa5562c","type":"callout","position":"aK","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The two-argument "},{"type":"text","text":"iter(func, sentinel)","marks":[{"type":"code"}]},{"type":"text","text":" calls "},{"type":"text","text":"func()","marks":[{"type":"code"}]},{"type":"text","text":" repeatedly and stops when it returns "},{"type":"text","text":"sentinel","marks":[{"type":"code"}]},{"type":"text","text":" — perfect for reading fixed-size blocks from files and sockets."}]}]}},"revision":1},{"id":"3eded5f5-ab25-7c40-8e43-6205410ae7c0","type":"heading","position":"aL","content":{"level":1,"content":[{"type":"text","text":"Loop variables & scope"}]},"revision":1},{"id":"5a25f713-9f5c-7903-a1fb-ff62f4405e42","type":"code","position":"aM","content":{"language":"python","code":"for i in range(3):\n    pass\nprint(i)                      # 2   ← the loop variable survives the loop\n\nsquares = [j * j for j in range(3)]\nprint(\"j\" in dir())           # False   ← comprehension variables don''t leak","filename":"Python"},"revision":1},{"id":"353f8096-2fb5-739c-a7ff-c322d003150a","type":"callout","position":"aN","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"If the loop body never runs (empty iterable), the loop variable is never assigned — using it afterwards raises "},{"type":"text","text":"NameError","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"4b9cdf08-c0f0-70fd-bc61-c19703aa71f2","type":"heading","position":"aO","content":{"level":1,"content":[{"type":"text","text":"Faster loops"}]},"revision":1},{"id":"681cddf8-6f3c-764d-8751-e80cdfa048f1","type":"table","position":"aP","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Slower"}],[{"type":"text","text":"Faster"}],[{"type":"text","text":"Why"}]],[[{"type":"text","text":"total = 0","marks":[{"type":"code"}]},{"type":"text","text":" + "},{"type":"text","text":"for x in xs: total += x","marks":[{"type":"code"}]}],[{"type":"text","text":"sum(xs)","marks":[{"type":"code"}]}],[{"type":"text","text":"Built-ins loop in C"}]],[[{"type":"text","text":"Loop + "},{"type":"text","text":"append","marks":[{"type":"code"}]}],[{"type":"text","text":"List comprehension"}],[{"type":"text","text":"No repeated "},{"type":"text","text":".append","marks":[{"type":"code"}]},{"type":"text","text":" lookup and call"}]],[[{"type":"text","text":"if x in big_list","marks":[{"type":"code"}]},{"type":"text","text":" inside a loop"}],[{"type":"text","text":"Convert to a "},{"type":"text","text":"set","marks":[{"type":"code"}]},{"type":"text","text":" once"}],[{"type":"text","text":"O(1) instead of O(n) per check"}]],[[{"type":"text","text":"for i in range(len(xs)): xs[i]","marks":[{"type":"code"}]}],[{"type":"text","text":"for x in xs","marks":[{"type":"code"}]}],[{"type":"text","text":"No indexing per step"}]],[[{"type":"text","text":"s += piece","marks":[{"type":"code"}]},{"type":"text","text":" in a loop"}],[{"type":"text","text":"''''.join(pieces)","marks":[{"type":"code"}]}],[{"type":"text","text":"Avoids O(n²) copying"}]],[[{"type":"text","text":"obj.method","marks":[{"type":"code"}]},{"type":"text","text":" looked up each time"}],[{"type":"text","text":"m = obj.method","marks":[{"type":"code"}]},{"type":"text","text":" before the loop"}],[{"type":"text","text":"One attribute lookup instead of n"}]]]},"revision":1},{"id":"6e42d9ca-a24b-771d-82a4-cf8100a449a4","type":"question","position":"aQ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When would you use for … else?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"For searches: the "},{"type":"text","text":"else","marks":[{"type":"code"}]},{"type":"text","text":" runs only when the loop completed without "},{"type":"text","text":"break","marks":[{"type":"code"}]},{"type":"text","text":", i.e. when nothing was found. It replaces a separate "},{"type":"text","text":"found = False","marks":[{"type":"code"}]},{"type":"text","text":" flag."}]}]}},"revision":1},{"id":"50cdd4b0-cf72-725b-a60a-de8c6a058005","type":"question","position":"aR","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you iterate over two lists at the same time?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"for a, b in zip(xs, ys)","marks":[{"type":"code"}]},{"type":"text","text":". "},{"type":"text","text":"zip","marks":[{"type":"code"}]},{"type":"text","text":" stops at the shortest input; use "},{"type":"text","text":"zip(..., strict=True)","marks":[{"type":"code"}]},{"type":"text","text":" (3.10+) to raise on a length mismatch, or "},{"type":"text","text":"itertools.zip_longest","marks":[{"type":"code"}]},{"type":"text","text":" to pad the shorter one."}]}]}},"revision":1},{"id":"15dad08c-a936-7777-be73-cd90af52dd31","type":"question","position":"aS","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why is removing items from a list while iterating over it a bug?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The list iterator walks by index. Removing an item shifts the rest left, so the item right after the removed one is skipped. Iterate over a copy, iterate backwards, or build a new list with a comprehension."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
WHERE EXISTS (SELECT 1 FROM "notes"."Note" n WHERE n.id = '756a6e7a-52ec-7741-b100-3ab91dc646e3' AND n."ownerId" = '019a118c-f480-7000-8000-000000000001' AND n."publishedVersionId" IS NULL AND n.visibility = 'PRIVATE' AND n."deletedAt" IS NULL AND n."draftUpdatedAt" = TIMESTAMPTZ '2026-10-07 03:23:53+00')
ON CONFLICT DO NOTHING;

