SELECT c.id::uuid, '756a6e7a-52ec-7741-b100-3ab91dc646e3', c.position, c.type::"notes"."CardType", c.content::jsonb, 1, TIMESTAMPTZ '2026-10-07 03:23:53+00', TIMESTAMPTZ '2026-10-07 03:23:53+00'
FROM (VALUES
  ('8405cd88-062a-7330-a117-9f689213d5ef', 'a0', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Python''s "},{"type":"text","text":"for","marks":[{"type":"code"}]},{"type":"text","text":" walks over "},{"type":"text","text":"any iterable","marks":[{"type":"italic"}]},{"type":"text","text":" — there is no C-style "},{"type":"text","text":"for (i = 0; …)","marks":[{"type":"code"}]},{"type":"text","text":". This topic collects the loop patterns, helpers and pitfalls you meet every day."}]}]}}'),
  ('2789ae34-23db-7f3f-a64f-44265a1155fc', 'a1', 'heading', '{"level":1,"content":[{"type":"text","text":"range","marks":[{"type":"code"}]},{"type":"text","text":" in detail"}]}'),
  ('d1a9d663-ac33-79ad-85d9-99d163c4d23b', 'a2', 'code', '{"language":"python","code":"print(list(range(5)))                 # [0, 1, 2, 3, 4]\nprint(list(range(2, 12, 3)))          # [2, 5, 8, 11]\nprint(list(range(5, 0, -1)))          # [5, 4, 3, 2, 1]\nprint(list(range(3, 0)))              # []   ← empty: a negative step is needed to count down\nr = range(0, 10**12, 2)               # no list is built — O(1) memory\nprint(len(r), r[10], r[-1])           # 500000000000 20 999999999998\nprint(999_999 in r, 1_000 in r)       # False True   ← O(1) arithmetic check","filename":"Python"}'),
  ('39b58034-9bcc-7df4-b361-c38b67ab46cc', 'a3', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Goal"}],[{"type":"text","text":"Loop header"}]],[[{"type":"text","text":"0 … n−1"}],[{"type":"text","text":"for i in range(n)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"1 … n inclusive"}],[{"type":"text","text":"for i in range(1, n + 1)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"n−1 down to 0"}],[{"type":"text","text":"for i in range(n - 1, -1, -1)","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"reversed(range(n))","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Every other index"}],[{"type":"text","text":"for i in range(0, n, 2)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Items and their index"}],[{"type":"text","text":"for i, x in enumerate(xs)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Two lists in step"}],[{"type":"text","text":"for a, b in zip(xs, ys)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Neighbouring pairs"}],[{"type":"text","text":"for a, b in zip(xs, xs[1:])","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"itertools.pairwise(xs)","marks":[{"type":"code"}]}]]]}'),
  ('0d973d9c-194a-74c8-88d8-8503f90fcac1', 'a4', 'heading', '{"level":1,"content":[{"type":"text","text":"while","marks":[{"type":"code"}]},{"type":"text","text":" loops and "},{"type":"text","text":"while … else","marks":[{"type":"code"}]}]}'),
  ('6b6bb623-b685-7820-830d-ac04c4c315d2', 'a5', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Use "},{"type":"text","text":"while","marks":[{"type":"code"}]},{"type":"text","text":" when you don''t know the number of iterations in advance. Like "},{"type":"text","text":"for","marks":[{"type":"code"}]},{"type":"text","text":", it takes an "},{"type":"text","text":"else","marks":[{"type":"code"}]},{"type":"text","text":" that runs only if the loop ended "},{"type":"text","text":"without","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"break","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('66891f5b-ea0e-74b0-ac97-2961bdbdc43d', 'a6', 'code', '{"language":"python","code":"n, steps = 27, 0\nwhile n != 1:                         # Collatz sequence\n    n = n // 2 if n % 2 == 0 else 3 * n + 1\n    steps += 1\nprint(steps)                          # 111\n\ndef is_prime(n):\n    if n < 2:\n        return False\n    d = 2\n    while d * d <= n:\n        if n % d == 0:\n            break                     # found a divisor\n        d += 1\n    else:\n        return True                   # no break → no divisor found\n    return False\n\nprint([k for k in range(20) if is_prime(k)])   # [2, 3, 5, 7, 11, 13, 17, 19]","filename":"Python"}'),
  ('21a5e064-faeb-7924-9278-7cc7aa18262b', 'a7', 'code', '{"language":"python","code":"attempts = 0\nwhile True:                           # the do-while idiom: body runs at least once\n    attempts += 1\n    if attempts * attempts > 20:\n        break\nprint(attempts)                       # 5","filename":"Python"}'),
  ('f1d279a5-541b-7b49-aa02-165193211fb1', 'a8', 'heading', '{"level":1,"content":[{"type":"text","text":"Breaking out of nested loops"}]}'),
  ('1e903687-f1fb-78e5-bb8f-d057751feb5d', 'a9', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"break","marks":[{"type":"code"}]},{"type":"text","text":" only leaves the innermost loop. Three ways out of two:"}]}]}}'),
  ('ac1bd886-87aa-7c4f-84dd-bbd499254690', 'aA', 'code', '{"language":"python","code":"grid = [[1, 2, 3], [4, 5, 6], [7, 8, 9]]\n\n# 1. A flag checked by the outer loop\nfound = None\nfor r, row in enumerate(grid):\n    for c, val in enumerate(row):\n        if val == 5:\n            found = (r, c)\n            break\n    if found:\n        break\nprint(found)                          # (1, 1)\n\n# 2. Put the loops in a function and return (usually the cleanest)\ndef find(grid, target):\n    for r, row in enumerate(grid):\n        for c, val in enumerate(row):\n            if val == target:\n                return r, c\n    return None\nprint(find(grid, 8), find(grid, 0))   # (2, 1) None\n\n# 3. One flat loop over all coordinates\nfrom itertools import product\nhit = next(((r, c) for r, c in product(range(3), range(3)) if grid[r][c] == 9), None)\nprint(hit)                            # (2, 2)","filename":"Python"}'),
  ('3e9f74c6-f7ef-7b4b-9cd5-dac9a73de2c2', 'aB', 'heading', '{"level":1,"content":[{"type":"text","text":"Iterating dicts, in order, in reverse, in parallel"}]}'),
