SELECT 'f7bab139-7b66-7d1a-b41d-b8968e2e2717', '343ab22f-da61-753e-a55f-c1328db40de3', 1, 'PUBLISHED', 'Metaclasses & Class Creation', '[{"id":"4de75157-1238-7df4-a031-814ae187394b","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Classes are objects too — created at runtime by a "},{"type":"text","text":"metaclass","marks":[{"type":"italic"}]},{"type":"text","text":", which is "},{"type":"text","text":"type","marks":[{"type":"code"}]},{"type":"text","text":" by default. Knowing how class creation works explains "},{"type":"text","text":"__new__","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"__init_subclass__","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"ABC","marks":[{"type":"code"}]},{"type":"text","text":" and how frameworks like Django build models."}]}]}},"revision":1},{"id":"ee0c6a6a-2be2-7b8a-8f97-d740af8e5d86","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Classes are objects created by type"}]},"revision":1},{"id":"e5793ae8-0516-798a-be80-b8ec5a217f42","type":"code","position":"a2","content":{"language":"python","code":"class Dog:\n    sound = \"woof\"\n\nprint(type(Dog), type(type))          # <class ''type''> <class ''type''>\nprint(isinstance(Dog, object))        # True\n\n# The class statement is sugar for calling type(name, bases, namespace):\nCat = type(\"Cat\", (), {\"sound\": \"meow\", \"speak\": lambda self: self.sound})\nprint(Cat().speak(), Cat.__name__)    # meow Cat","filename":"Python"},"revision":1},{"id":"b51b94fa-1551-7d54-9585-520384389084","type":"callout","position":"a3","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Metaclass","marks":[{"type":"bold"}]},{"type":"text","text":" — the class of a class. "},{"type":"text","text":"type(obj)","marks":[{"type":"code"}]},{"type":"text","text":" gives an object''s class; "},{"type":"text","text":"type(SomeClass)","marks":[{"type":"code"}]},{"type":"text","text":" gives its metaclass. Instances are made by classes; classes are made by metaclasses."}]}]}},"revision":1},{"id":"5efae070-15f5-7f7d-8237-affa39e1f1c7","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"What happens when "},{"type":"text","text":"class","marks":[{"type":"code"}]},{"type":"text","text":" runs"}]},"revision":1},{"id":"5dfeabd1-ebf3-7ea7-a17d-789d10ef8d15","type":"text","position":"a5","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Pick the metaclass","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"The explicit "},{"type":"text","text":"metaclass=","marks":[{"type":"code"}]},{"type":"text","text":" keyword, else the most derived metaclass of the bases, else "},{"type":"text","text":"type","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Prepare the namespace","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"metaclass.__prepare__(name, bases)","marks":[{"type":"code"}]},{"type":"text","text":" returns the mapping the body will fill (a plain "},{"type":"text","text":"dict","marks":[{"type":"code"}]},{"type":"text","text":" by default)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Run the body","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"The class body executes like a function body; every assignment and "},{"type":"text","text":"def","marks":[{"type":"code"}]},{"type":"text","text":" lands in that namespace."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Create the class","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"metaclass(name, bases, namespace)","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"__new__","marks":[{"type":"code"}]},{"type":"text","text":" builds the class object, "},{"type":"text","text":"__init__","marks":[{"type":"code"}]},{"type":"text","text":" initialises it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Notify","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"type.__new__","marks":[{"type":"code"}]},{"type":"text","text":" calls "},{"type":"text","text":"__set_name__","marks":[{"type":"code"}]},{"type":"text","text":" on each attribute (descriptors) and "},{"type":"text","text":"__init_subclass__","marks":[{"type":"code"}]},{"type":"text","text":" on the parent."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Decorate","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Finally, class decorators are applied ("},{"type":"text","text":"@dataclass","marks":[{"type":"code"}]},{"type":"text","text":" runs here)."}]}]}]}]}},"revision":1},{"id":"d9df2136-e45f-7ed2-980d-4a8d18d3dfae","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"__new__ vs __init__"}]},"revision":1},{"id":"4ece5358-f6aa-7baf-801a-93a9c4b1c8a8","type":"text","position":"a7","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"__new__(cls, …)","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"creates","marks":[{"type":"bold"}]},{"type":"text","text":" and returns the instance; "},{"type":"text","text":"__init__(self, …)","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"initialises","marks":[{"type":"bold"}]},{"type":"text","text":" it. You rarely override "},{"type":"text","text":"__new__","marks":[{"type":"code"}]},{"type":"text","text":" — except for immutable types (whose value must be fixed at creation) and instance control such as singletons or caching."}]}]}},"revision":1},{"id":"453b2dd3-d7dd-76ed-b22a-e4c6132af816","type":"code","position":"a8","content":{"language":"python","code":"class Singleton:\n    _instance = None\n\n    def __new__(cls, *args, **kwargs):\n        if cls._instance is None:\n            cls._instance = super().__new__(cls)\n        return cls._instance\n\n    def __init__(self, value):\n        self.value = value            # NOTE: still runs on every call\n\na = Singleton(1)\nb = Singleton(2)\nprint(a is b, a.value)                # True 2\n\nclass Celsius(float):                 # float is immutable → customise __new__, not __init__\n    def __new__(cls, degrees):\n        if degrees < -273.15:\n            raise ValueError(\"below absolute zero\")\n        return super().__new__(cls, round(degrees, 1))\n\nprint(Celsius(21.456), Celsius(10) + 5)   # 21.5 15.0","filename":"Python"},"revision":1},{"id":"1f0389fb-f8c9-796d-b405-b798175079e7","type":"callout","position":"a9","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"If "},{"type":"text","text":"__new__","marks":[{"type":"code"}]},{"type":"text","text":" returns an instance of the class, "},{"type":"text","text":"__init__","marks":[{"type":"code"}]},{"type":"text","text":" is called on it "},{"type":"text","text":"every time","marks":[{"type":"bold"}]},{"type":"text","text":" — which is why "},{"type":"text","text":"a.value","marks":[{"type":"code"}]},{"type":"text","text":" became 2 above. For a real singleton, a module-level instance is usually simpler."}]}]}},"revision":1},{"id":"d21446e8-fe0c-708c-8e00-96bac1bc51a3","type":"heading","position":"aA","content":{"level":1,"content":[{"type":"text","text":"__init_subclass__: the easy hook (preferred)"}]},"revision":1},{"id":"30547ef8-b024-7a1a-b75f-34a0ccae3cf0","type":"text","position":"aB","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Most metaclass use cases are really “do something whenever a subclass is defined”. "},{"type":"text","text":"__init_subclass__","marks":[{"type":"code"}]},{"type":"text","text":" (3.6+) does exactly that with an ordinary classmethod — no metaclass needed."}]}]}},"revision":1},{"id":"9b865c01-f131-7ea6-9b36-4518e9a1b398","type":"code","position":"aC","content":{"language":"python","code":"class Plugin:\n    registry = {}\n\n    def __init_subclass__(cls, /, name=None, **kwargs):\n        super().__init_subclass__(**kwargs)\n        Plugin.registry[name or cls.__name__.lower()] = cls\n\nclass CsvLoader(Plugin, name=\"csv\"):     # class keyword arguments reach __init_subclass__\n    pass\n\nclass JsonLoader(Plugin):\n    pass\n\nprint(list(Plugin.registry))             # [''csv'', ''jsonloader'']\nprint(Plugin.registry[\"csv\"] is CsvLoader)   # True","filename":"Python"},"revision":1},{"id":"a5dd299b-4fea-7503-843f-6ba4de8483a0","type":"heading","position":"aD","content":{"level":1,"content":[{"type":"text","text":"Writing a metaclass"}]},"revision":1},{"id":"ce2688ab-83fe-7566-9b97-442d016152f5","type":"code","position":"aE","content":{"language":"python","code":"class RequireDocs(type):\n    \"\"\"Reject public methods without a docstring — checked when the class is defined.\"\"\"\n    def __new__(mcls, name, bases, ns):\n        for attr, value in ns.items():\n            if callable(value) and not attr.startswith(\"_\") and not value.__doc__:\n                raise TypeError(f\"{name}.{attr} needs a docstring\")\n        return super().__new__(mcls, name, bases, ns)\n\nclass Service(metaclass=RequireDocs):\n    def run(self):\n        \"\"\"Run the service.\"\"\"\n\nprint(type(Service).__name__)            # RequireDocs\ntry:\n    class Worker(Service):               # the metaclass is inherited by subclasses\n        def stop(self):\n            pass\nexcept TypeError as e:\n    print(e)                             # Worker.stop needs a docstring\n\nclass SingletonMeta(type):\n    _instances = {}\n    def __call__(cls, *args, **kwargs):  # runs on Config(...) — before __new__/__init__\n        if cls not in cls._instances:\n            cls._instances[cls] = super().__call__(*args, **kwargs)\n        return cls._instances[cls]\n\nclass Config(metaclass=SingletonMeta):\n    pass\n\nprint(Config() is Config())              # True","filename":"Python"},"revision":1},{"id":"5416b5c5-61ea-70a6-b4d7-c7ab1cd91fd0","type":"table","position":"aF","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Metaclass method"}],[{"type":"text","text":"Runs when"}],[{"type":"text","text":"Used for"}]],[[{"type":"text","text":"__prepare__","marks":[{"type":"code"}]}],[{"type":"text","text":"Before the class body"}],[{"type":"text","text":"Custom namespace (e.g. record definition order, forbid duplicates)"}]],[[{"type":"text","text":"__new__","marks":[{"type":"code"}]}],[{"type":"text","text":"Class object is created"}],[{"type":"text","text":"Inspect / modify the namespace, validate, register"}]],[[{"type":"text","text":"__init__","marks":[{"type":"code"}]}],[{"type":"text","text":"After "},{"type":"text","text":"__new__","marks":[{"type":"code"}]}],[{"type":"text","text":"Post-creation setup"}]],[[{"type":"text","text":"__call__","marks":[{"type":"code"}]}],[{"type":"text","text":"MyClass(...)","marks":[{"type":"code"}]},{"type":"text","text":" is called"}],[{"type":"text","text":"Control instance creation: singletons, caching, pooling"}]]]},"revision":1},{"id":"64d14860-2cdd-7800-9d99-400f674ae369","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Lighter alternatives"}]},"revision":1},{"id":"05845909-bd77-7c94-a3e6-9890b3341256","type":"code","position":"aH","content":{"language":"python","code":"class Box:\n    def __class_getitem__(cls, item):    # powers Box[int] without a metaclass\n        return f\"Box of {item.__name__}\"\n\ndef add_repr(cls):                        # a class decorator: receives the finished class\n    cls.__repr__ = lambda self: f\"<{cls.__name__} {vars(self)}>\"\n    return cls\n\n@add_repr\nclass Point:\n    def __init__(self, x):\n        self.x = x\n\nfrom abc import ABC\nprint(Box[int], Point(3))                 # Box of int <Point {''x'': 3}>\nprint(type(ABC).__name__)                 # ABCMeta","filename":"Python"},"revision":1},{"id":"78c41fe0-cef1-7c9f-b51b-485a54926053","type":"table","position":"aI","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Need"}],[{"type":"text","text":"Reach for"}]],[[{"type":"text","text":"Modify or register one class after it''s built"}],[{"type":"text","text":"Class decorator"}]],[[{"type":"text","text":"React to every subclass being defined"}],[{"type":"text","text":"__init_subclass__","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Know the attribute name a field was assigned to"}],[{"type":"text","text":"Descriptor "},{"type":"text","text":"__set_name__","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Make "},{"type":"text","text":"MyClass[...]","marks":[{"type":"code"}]},{"type":"text","text":" work"}],[{"type":"text","text":"__class_getitem__","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Change how the class namespace or "},{"type":"text","text":"MyClass()","marks":[{"type":"code"}]},{"type":"text","text":" itself behaves"}],[{"type":"text","text":"Metaclass"}]]]},"revision":1},{"id":"d7aa565b-db27-7c51-a580-4aed0be9a1c9","type":"callout","position":"aJ","content":{"variant":"note","title":"Rule of thumb","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"“Metaclasses are deeper magic than 99% of users should ever worry about. If you wonder whether you need them, you don''t.” — Tim Peters"}]}]}},"revision":1},{"id":"15026b5d-6695-7567-8ade-4499aa339a53","type":"callout","position":"aK","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A class can have only one metaclass. Inheriting from two bases with unrelated metaclasses (e.g. an "},{"type":"text","text":"ABC","marks":[{"type":"code"}]},{"type":"text","text":" and a Django model) raises "},{"type":"text","text":"TypeError: metaclass conflict","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"5f871892-a7bb-7436-b7e2-a7e47367b682","type":"heading","position":"aL","content":{"level":1,"content":[{"type":"text","text":"Interview angle"}]},"revision":1},{"id":"d4c57ee5-52f8-7c63-8a45-50b334419f50","type":"question","position":"aM","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is a metaclass?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The class of a class — the object that creates class objects. The default is "},{"type":"text","text":"type","marks":[{"type":"code"}]},{"type":"text","text":". Defining "},{"type":"text","text":"__new__","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"__init__","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"__call__","marks":[{"type":"code"}]},{"type":"text","text":" on a custom metaclass lets you customise class creation and instantiation. "},{"type":"text","text":"ABCMeta","marks":[{"type":"code"}]},{"type":"text","text":", Django''s "},{"type":"text","text":"ModelBase","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"EnumType","marks":[{"type":"code"}]},{"type":"text","text":" are real examples."}]}]}},"revision":1},{"id":"cf5d6a42-66c1-75f3-bffe-bb064088c6d4","type":"question","position":"aN","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the difference between __new__ and __init__?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"__new__","marks":[{"type":"code"}]},{"type":"text","text":" is a static method that creates and returns the new object; "},{"type":"text","text":"__init__","marks":[{"type":"code"}]},{"type":"text","text":" receives that object and sets it up, returning "},{"type":"text","text":"None","marks":[{"type":"code"}]},{"type":"text","text":". Override "},{"type":"text","text":"__new__","marks":[{"type":"code"}]},{"type":"text","text":" for immutable subclasses ("},{"type":"text","text":"int","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"str","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"tuple","marks":[{"type":"code"}]},{"type":"text","text":"), singletons or instance caching."}]}]}},"revision":1},{"id":"e4ebfcf2-0243-7db4-9f81-bb583a1d4b14","type":"question","position":"aO","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How would you auto-register every subclass of a base class?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Define "},{"type":"text","text":"__init_subclass__","marks":[{"type":"code"}]},{"type":"text","text":" on the base and add "},{"type":"text","text":"cls","marks":[{"type":"code"}]},{"type":"text","text":" to a registry dict. It''s simpler and composes better than a metaclass, and it can take class keyword arguments ("},{"type":"text","text":"class A(Base, name=''a'')","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
