SELECT 'd1c69e92-f15f-7a10-be6f-30e03313a4a0', '7d8ce889-d558-7b8b-84a0-a2e8fcf21972', 1, 'PUBLISHED', 'Mocking & Test Doubles', '[{"id":"e2c4f9ee-ba03-7df2-832d-80c9df927c1d","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A test double stands in for a slow, flaky or external dependency — an API, the clock, the database — so a unit test checks only "},{"type":"text","text":"your","marks":[{"type":"italic"}]},{"type":"text","text":" code. "},{"type":"text","text":"unittest.mock","marks":[{"type":"code"}]},{"type":"text","text":" is the standard toolkit."}]}]}},"revision":1},{"id":"9b6f283f-c401-7436-b451-d143a7f0e54c","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Kinds of test doubles"}]},"revision":1},{"id":"3b0b725b-8b38-7b27-b8e2-2bde1e71d70f","type":"table","position":"a2","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Double"}],[{"type":"text","text":"What it does"}],[{"type":"text","text":"Example"}]],[[{"type":"text","text":"Stub"}],[{"type":"text","text":"Returns canned answers"}],[{"type":"text","text":"get_rate()","marks":[{"type":"code"}]},{"type":"text","text":" always returns "},{"type":"text","text":"83.0","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Mock"}],[{"type":"text","text":"Records calls so you can assert on them"}],[{"type":"text","text":"“"},{"type":"text","text":"send_email","marks":[{"type":"code"}]},{"type":"text","text":" was called once with this address”"}]],[[{"type":"text","text":"Fake"}],[{"type":"text","text":"A working lightweight implementation"}],[{"type":"text","text":"An in-memory dict instead of a real database"}]],[[{"type":"text","text":"Spy"}],[{"type":"text","text":"Wraps the real object and records calls"}],[{"type":"text","text":"Mock(wraps=real_func)","marks":[{"type":"code"}]}]]]},"revision":1},{"id":"a61264c6-db7f-7fdc-a99a-2b59d2f8194b","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"Mock basics"}]},"revision":1},{"id":"25855ea2-eb84-7a7d-9059-35c605154e47","type":"code","position":"a4","content":{"language":"python","code":"from unittest.mock import Mock\n\napi = Mock()\napi.get_user.return_value = {\"id\": 7, \"name\": \"Asha\"}   # stub a method\n\nprint(api.get_user(7)[\"name\"])                    # Asha\nprint(api.get_user.call_count)                    # 1\nprint(api.get_user.call_args)                     # call(7)\napi.get_user.assert_called_once_with(7)           # passes silently\n\nprint(type(api.anything.you.like).__name__)       # Mock   ← attributes are created on demand","filename":"Python"},"revision":1},{"id":"01deb5f9-0f3b-7d0b-96a4-72087ab94c5e","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"side_effect: exceptions and sequences"}]},"revision":1},{"id":"dfb347af-673f-7e81-8cd1-e1bf451cf095","type":"code","position":"a6","content":{"language":"python","code":"from unittest.mock import Mock\n\ndef fetch_with_retry(client, attempts=3):\n    for i in range(attempts):\n        try:\n            return client.fetch()\n        except ConnectionError:\n            if i == attempts - 1:\n                raise\n\nclient = Mock()\nclient.fetch.side_effect = [ConnectionError(), ConnectionError(), \"data\"]   # fail, fail, succeed\nprint(fetch_with_retry(client), client.fetch.call_count)   # data 3\n\nclient.fetch.side_effect = ConnectionError(\"down\")          # always fail\ntry:\n    fetch_with_retry(client)\nexcept ConnectionError as e:\n    print(\"gave up:\", e)                                     # gave up: down\n\ndouble = Mock(side_effect=lambda x: x * 2)                   # compute the return value\nprint(double(21))                                            # 42","filename":"Python"},"revision":1},{"id":"128db885-a708-7eaa-afab-b95feefbf35d","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"patch: replace a name during a test"}]},"revision":1},{"id":"20d90175-9cbb-717c-b1b7-e17315a5b0d7","type":"text","position":"a8","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"patch","marks":[{"type":"code"}]},{"type":"text","text":" swaps an attribute for a mock and restores it afterwards. Patch "},{"type":"text","text":"where the name is looked up","marks":[{"type":"bold"}]},{"type":"text","text":", not where it was defined: if "},{"type":"text","text":"app.py","marks":[{"type":"code"}]},{"type":"text","text":" does "},{"type":"text","text":"from time import time","marks":[{"type":"code"}]},{"type":"text","text":", patch "},{"type":"text","text":"app.time","marks":[{"type":"code"}]},{"type":"text","text":", not "},{"type":"text","text":"time.time","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"45d336ff-8755-7341-8b59-17adad76e46d","type":"code","position":"a9","content":{"language":"python","code":"import time\nfrom unittest.mock import patch\n\nclass Greeter:\n    def greeting(self):\n        hour = time.localtime().tm_hour\n        return \"Good morning\" if hour < 12 else \"Good afternoon\"\n\nfake = time.struct_time((2026, 9, 29, 9, 0, 0, 1, 272, 0))\nwith patch.object(time, \"localtime\", return_value=fake):      # context-manager form\n    print(Greeter().greeting())                                # Good morning\n\n@patch.object(Greeter, \"greeting\", return_value=\"Hi\")          # decorator form\ndef check(mock_greeting):\n    result = Greeter().greeting()\n    mock_greeting.assert_called_once()\n    return result\n\nprint(check())                                                 # Hi\nprint(time.localtime is not None)                              # True   ← original restored","filename":"Python"},"revision":1},{"id":"b37fba68-a918-76fd-9f3b-89dd0d679446","type":"code","position":"aA","content":{"language":"python","code":"import os\nfrom unittest.mock import patch, mock_open\n\nwith patch.dict(os.environ, {\"FEATURE_X\": \"on\"}):     # temporary environment\n    print(os.environ[\"FEATURE_X\"])                    # on\nprint(\"FEATURE_X\" in os.environ)                      # False\n\nwith patch(\"builtins.open\", mock_open(read_data=\"line1\\nline2\")):\n    with open(\"any/path.txt\") as f:                   # no real file touched\n        print(f.read().splitlines())                  # [''line1'', ''line2'']","filename":"Python"},"revision":1},{"id":"0ef77047-7d6b-7c26-92d3-439d9dd40408","type":"heading","position":"aB","content":{"level":1,"content":[{"type":"text","text":"spec & autospec: mocks that fail like the real thing"}]},"revision":1},{"id":"ac48db0b-ef59-75d5-bd2c-bc190ec8e413","type":"code","position":"aC","content":{"language":"python","code":"from unittest.mock import create_autospec\n\nclass PaymentGateway:\n    def charge(self, amount: int, currency: str) -> str:\n        raise NotImplementedError\n\ngateway = create_autospec(PaymentGateway, instance=True)\ngateway.charge.return_value = \"txn-1\"\nprint(gateway.charge(500, \"INR\"))                     # txn-1\n\ntry:\n    gateway.charge(500)                               # wrong signature → error, like the real method\nexcept TypeError:\n    print(\"signature checked\")                        # signature checked\ntry:\n    gateway.refund(1)                                 # no such method on the real class\nexcept AttributeError:\n    print(\"unknown method rejected\")                  # unknown method rejected","filename":"Python"},"revision":1},{"id":"c7d3071e-701b-7585-80d8-ca509b4996c5","type":"callout","position":"aD","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A plain "},{"type":"text","text":"Mock()","marks":[{"type":"code"}]},{"type":"text","text":" accepts any call and any attribute, so a typo like "},{"type":"text","text":"mock.assert_caled_once()","marks":[{"type":"code"}]},{"type":"text","text":" or a renamed method can make a broken test pass. Use "},{"type":"text","text":"spec=","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"autospec","marks":[{"type":"code"}]},{"type":"text","text":" (and Python rejects "},{"type":"text","text":"assert_*","marks":[{"type":"code"}]},{"type":"text","text":" typos since 3.12)."}]}]}},"revision":1},{"id":"c207a8be-a26c-720f-8939-ed97ff74c52e","type":"heading","position":"aE","content":{"level":1,"content":[{"type":"text","text":"pytest''s monkeypatch"}]},"revision":1},{"id":"ba7b8dd7-ab33-7951-b15d-5e390c24b167","type":"code","position":"aF","content":{"language":"python","code":"def test_uses_api_key(monkeypatch):\n    monkeypatch.setenv(\"API_KEY\", \"test-key\")\n    monkeypatch.setattr(\"shop.payments.charge\", lambda amount: \"ok\")\n    assert checkout(100) == \"ok\"          # undone automatically after the test","filename":"Python"},"revision":1},{"id":"e0c027f0-1cde-7940-b6e5-a4468fc921a6","type":"callout","position":"aG","content":{"variant":"tip","title":"Do","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Mock at the boundaries: network, time, randomness, file system, third-party services."}]}]}},"revision":1},{"id":"5fd9edea-fefd-7f2d-8fe4-c7742be771e9","type":"callout","position":"aH","content":{"variant":"danger","title":"Avoid","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Mocking your own internal functions everywhere — tests then mirror the implementation and break on every refactor while missing real bugs."}]}]}},"revision":1},{"id":"7309da7f-109e-7dd8-9168-f8715e812e53","type":"question","position":"aI","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why do you patch where an object is used, not where it''s defined?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"from module import name","marks":[{"type":"code"}]},{"type":"text","text":" copies the reference into the importing module''s namespace. Patching the original module doesn''t change that copy, so the code under test still calls the real function. Patch "},{"type":"text","text":"consumer_module.name","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"a6915754-62c2-757b-bd2b-c16b134e47b6","type":"question","position":"aJ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Mock vs MagicMock?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"MagicMock","marks":[{"type":"code"}]},{"type":"text","text":" is a "},{"type":"text","text":"Mock","marks":[{"type":"code"}]},{"type":"text","text":" that also pre-configures magic methods ("},{"type":"text","text":"__len__","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"__iter__","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"__enter__","marks":[{"type":"code"}]},{"type":"text","text":", …), so it can stand in for containers or context managers. "},{"type":"text","text":"patch","marks":[{"type":"code"}]},{"type":"text","text":" uses "},{"type":"text","text":"MagicMock","marks":[{"type":"code"}]},{"type":"text","text":" by default."}]}]}},"revision":1},{"id":"a87c1001-3df5-7562-9611-f6554655c721","type":"question","position":"aK","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is side_effect used for?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"To make a mock raise an exception, return successive values from an iterable, or compute its result with a function — for testing error handling and retries."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
