SELECT '6ce4c594-f1e1-763b-a284-898eed9b3dbd', 'ae9ef263-a535-7ad7-9aa1-65b919837de7', 1, 'PUBLISHED', 'Multiprocessing', '[{"id":"a1187708-a6c3-72d4-b040-d89dd9e2682e","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"multiprocessing","marks":[{"type":"code"}]},{"type":"text","text":" runs code in separate processes — each with its own interpreter, memory and GIL — so CPU-bound Python work finally uses every core."}]}]}},"revision":1},{"id":"908cf3eb-d129-717b-af7b-fbb345ba7c75","type":"callout","position":"a1","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Process","marks":[{"type":"bold"}]},{"type":"text","text":" — an independent program instance with its own address space. Processes share nothing by default; data moves between them by "},{"type":"text","text":"pickling","marks":[{"type":"bold"}]},{"type":"text","text":" it through pipes or queues."}]}]}},"revision":1},{"id":"0b53a06a-b7c5-7135-860b-c7778136e88b","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"Processes vs threads"}]},"revision":1},{"id":"0bf9f317-27d4-73b1-ae4f-865fe10442ac","type":"table","position":"a3","content":{"hasHeaderRow":true,"rows":[[[],[{"type":"text","text":"Threads"}],[{"type":"text","text":"Processes"}]],[[{"type":"text","text":"Memory"}],[{"type":"text","text":"Shared"}],[{"type":"text","text":"Separate (copy or explicit sharing)"}]],[[{"type":"text","text":"GIL"}],[{"type":"text","text":"One GIL for all threads"}],[{"type":"text","text":"One GIL "},{"type":"text","text":"per process","marks":[{"type":"bold"}]},{"type":"text","text":" → true parallelism"}]],[[{"type":"text","text":"Start-up cost"}],[{"type":"text","text":"~microseconds"}],[{"type":"text","text":"~milliseconds (a new interpreter)"}]],[[{"type":"text","text":"Communication"}],[{"type":"text","text":"Any object, directly"}],[{"type":"text","text":"Pickled messages: "},{"type":"text","text":"Queue","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Pipe","marks":[{"type":"code"}]},{"type":"text","text":", shared memory"}]],[[{"type":"text","text":"A crash"}],[{"type":"text","text":"Can take down the whole program"}],[{"type":"text","text":"Isolated to that process"}]],[[{"type":"text","text":"Use for"}],[{"type":"text","text":"I/O-bound work"}],[{"type":"text","text":"CPU-bound work"}]]]},"revision":1},{"id":"e6d3d483-268a-7ed0-a787-a5392cc73a84","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Process","marks":[{"type":"code"}]},{"type":"text","text":": start, join, exit code"}]},"revision":1},{"id":"0dab6fbb-6707-7731-ade8-65d1ac4f29ce","type":"code","position":"a5","content":{"language":"python","code":"from multiprocessing import Process, current_process\n\ndef work(n):\n    print(f\"{current_process().name}: {n * n}\")\n\nif __name__ == \"__main__\":\n    procs = [Process(target=work, args=(i,), name=f\"P{i}\") for i in range(3)]\n    for p in procs:\n        p.start()\n    for p in procs:\n        p.join()\n    print(\"exit codes:\", [p.exitcode for p in procs])","filename":"Python"},"revision":1},{"id":"e21b9027-2bf4-750a-91d6-ad2a1bded1f4","type":"code","position":"a6","content":{"language":"text","code":"P0: 0\nP1: 1\nP2: 4\nexit codes: [0, 0, 0]","filename":"Output (the P lines can appear in any order)"},"revision":1},{"id":"5ebf92b8-9924-72ec-917b-14634cf245cf","type":"callout","position":"a7","content":{"variant":"warning","title":"Required","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"if __name__ == \"__main__\":","marks":[{"type":"code"}]},{"type":"text","text":" guard is "},{"type":"text","text":"mandatory","marks":[{"type":"bold"}]},{"type":"text","text":" with the "},{"type":"text","text":"spawn","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"forkserver","marks":[{"type":"code"}]},{"type":"text","text":" start methods: each child re-imports your module, and without the guard it would start children of its own, recursively."}]}]}},"revision":1},{"id":"d7c16a24-439d-7f21-9ea9-21be8be08f8a","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"Pool","marks":[{"type":"code"}]},{"type":"text","text":": parallel map"}]},"revision":1},{"id":"4a3b801b-f83d-7997-80fd-569f7e664579","type":"code","position":"a9","content":{"language":"python","code":"from multiprocessing import Pool\n\ndef square(x):\n    return x * x\n\ndef power(base, exp):\n    return base ** exp\n\nif __name__ == \"__main__\":\n    with Pool(processes=4) as pool:\n        print(pool.map(square, range(6)))                 # [0, 1, 4, 9, 16, 25]\n        print(list(pool.imap(square, range(3))))          # [0, 1, 4]  ← lazy, in order\n        print(sorted(pool.imap_unordered(square, range(3))))   # [0, 1, 4]  ← as they finish\n        print(pool.starmap(power, [(2, 3), (3, 2)]))      # [8, 9]  ← unpacks tuples\n        r = pool.apply_async(square, (7,))\n        print(r.get(timeout=5))                           # 49","filename":"Python"},"revision":1},{"id":"aec78722-ace8-75a3-a4b8-a4440a3ab465","type":"table","position":"aA","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Method"}],[{"type":"text","text":"Returns"}],[{"type":"text","text":"Use when"}]],[[{"type":"text","text":"map(f, it, chunksize)","marks":[{"type":"code"}]}],[{"type":"text","text":"A list, in input order (blocks)"}],[{"type":"text","text":"All inputs known, results fit in memory"}]],[[{"type":"text","text":"imap(f, it)","marks":[{"type":"code"}]}],[{"type":"text","text":"A lazy iterator, in order"}],[{"type":"text","text":"Large inputs; process results as a stream"}]],[[{"type":"text","text":"imap_unordered(f, it)","marks":[{"type":"code"}]}],[{"type":"text","text":"A lazy iterator, completion order"}],[{"type":"text","text":"Order doesn''t matter — fastest feedback"}]],[[{"type":"text","text":"starmap(f, pairs)","marks":[{"type":"code"}]}],[{"type":"text","text":"A list; each tuple is unpacked into args"}],[{"type":"text","text":"Functions of several arguments"}]],[[{"type":"text","text":"apply_async(f, args)","marks":[{"type":"code"}]}],[{"type":"text","text":"An "},{"type":"text","text":"AsyncResult","marks":[{"type":"code"}]},{"type":"text","text":" ("},{"type":"text","text":".get()","marks":[{"type":"code"}]},{"type":"text","text":")"}],[{"type":"text","text":"One-off background calls"}]]]},"revision":1},{"id":"da8a1d6f-62e2-7af3-a925-780bc1a5524b","type":"callout","position":"aB","content":{"variant":"note","title":"Performance","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"For many tiny tasks, pass a larger "},{"type":"text","text":"chunksize","marks":[{"type":"code"}]},{"type":"text","text":" to "},{"type":"text","text":"map","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"imap","marks":[{"type":"code"}]},{"type":"text","text":" — sending each item separately costs more in pickling and IPC than the work itself."}]}]}},"revision":1},{"id":"13b8062c-d781-780a-84ec-38a7f4bc4b22","type":"heading","position":"aC","content":{"level":1,"content":[{"type":"text","text":"Start methods"}]},"revision":1},{"id":"e615e729-2d5b-7332-a107-870f421011c1","type":"table","position":"aD","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Method"}],[{"type":"text","text":"How the child starts"}],[{"type":"text","text":"Default on"}]],[[{"type":"text","text":"spawn","marks":[{"type":"code"}]}],[{"type":"text","text":"A fresh interpreter imports your module, then runs the target. Safe, slower."}],[{"type":"text","text":"Windows, "},{"type":"text","text":"macOS","marks":[{"type":"bold"}]},{"type":"text","text":" (since 3.8)"}]],[[{"type":"text","text":"fork","marks":[{"type":"code"}]}],[{"type":"text","text":"The OS copies the parent process (memory included). Fast, but unsafe if the parent has threads."}],[{"type":"text","text":"Linux before 3.14"}]],[[{"type":"text","text":"forkserver","marks":[{"type":"code"}]}],[{"type":"text","text":"A clean server process is started once and forks children on request."}],[{"type":"text","text":"Linux since 3.14","marks":[{"type":"bold"}]}]]]},"revision":1},{"id":"fc6222dd-a28a-73e7-b475-3a88bee88a92","type":"code","position":"aE","content":{"language":"python","code":"import multiprocessing as mp\n\nprint(mp.cpu_count() > 0)                                     # True\nprint(mp.get_start_method() in {\"fork\", \"spawn\", \"forkserver\"})   # True\nprint(\"spawn\" in mp.get_all_start_methods())                  # True  ← available everywhere","filename":"Python"},"revision":1},{"id":"4400aba5-5398-7d2f-bf8e-309763b9b876","type":"text","position":"aF","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Choose explicitly with "},{"type":"text","text":"mp.set_start_method(\"spawn\")","marks":[{"type":"code"}]},{"type":"text","text":" once at start-up, or better, a context: "},{"type":"text","text":"ctx = mp.get_context(\"spawn\"); ctx.Pool(...)","marks":[{"type":"code"}]},{"type":"text","text":". Code that works under "},{"type":"text","text":"spawn","marks":[{"type":"code"}]},{"type":"text","text":" works everywhere."}]}]}},"revision":1},{"id":"68f4d846-49b4-75c9-96d1-bb3cf5c99ebe","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Everything crosses the boundary by pickling"}]},"revision":1},{"id":"4f51e9ff-bcfd-7748-a3c9-f93f00dc5b2d","type":"text","position":"aH","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Arguments, return values and queue items are pickled in the parent and unpickled in the child. Functions are pickled "},{"type":"text","text":"by name","marks":[{"type":"bold"}]},{"type":"text","text":", so the target must be importable: a module-level "},{"type":"text","text":"def","marks":[{"type":"code"}]},{"type":"text","text":", not a lambda, nested function or something defined in the REPL."}]}]}},"revision":1},{"id":"2d533296-12d3-7ee3-a1f2-7e78f82cba70","type":"code","position":"aI","content":{"language":"python","code":"import pickle\n\ndef module_level(x):\n    return x\n\ntry:\n    pickle.dumps(lambda x: x)\nexcept pickle.PicklingError:\n    print(\"lambdas can''t be sent to a worker\")   # lambdas can''t be sent to a worker","filename":"Python"},"revision":1},{"id":"cb930867-dfde-7563-871f-acf06c2ad4ce","type":"callout","position":"aJ","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Large arguments are copied for every task. Send small descriptions (file paths, index ranges) and let workers load the data, or use shared memory."}]}]}},"revision":1},{"id":"0f5ae9fd-93d5-7543-80f4-21d426a98ae3","type":"heading","position":"aK","content":{"level":1,"content":[{"type":"text","text":"Communicating: Queue & Pipe"}]},"revision":1},{"id":"9410c246-4a30-7f55-8136-51e14c080a5a","type":"code","position":"aL","content":{"language":"python","code":"from multiprocessing import Process, Queue, Pipe\n\ndef producer(q):\n    for i in range(3):\n        q.put(i * 10)\n    q.put(None)                           # sentinel: \"no more\"\n\ndef echo(conn):\n    msg = conn.recv()\n    conn.send(msg.upper())\n    conn.close()\n\nif __name__ == \"__main__\":\n    q = Queue()\n    p = Process(target=producer, args=(q,)); p.start()\n    items = []\n    while (item := q.get()) is not None:\n        items.append(item)\n    p.join()\n    print(items)                          # [0, 10, 20]\n\n    parent, child = Pipe()                # two connected ends\n    p = Process(target=echo, args=(child,)); p.start()\n    parent.send(\"hello\")\n    print(parent.recv())                  # HELLO\n    p.join()","filename":"Python"},"revision":1},{"id":"c4dc8523-38b8-781f-b706-3c60bb5bc6b3","type":"heading","position":"aM","content":{"level":1,"content":[{"type":"text","text":"Sharing state"}]},"revision":1},{"id":"5138d258-ff28-7373-a0ca-cb53f2900e16","type":"callout","position":"aN","content":{"variant":"note","title":"Value / Array","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A single number or fixed array in shared memory, with an optional lock: "},{"type":"text","text":"Value(''i'', 0)","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Array(''d'', 10)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"33d0672a-23fa-77f6-9c07-20dcf451aadb","type":"callout","position":"aO","content":{"variant":"note","title":"shared_memory","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A raw named block of bytes any process can attach to — zero-copy for NumPy arrays (3.8+)."}]}]}},"revision":1},{"id":"16f38d1b-ce62-7b76-839d-04a3fa31d05b","type":"callout","position":"aP","content":{"variant":"note","title":"Manager()","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A server process holding real "},{"type":"text","text":"dict","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"list","marks":[{"type":"code"}]},{"type":"text","text":" objects; others use proxies. Flexible but slow (every access is IPC)."}]}]}},"revision":1},{"id":"d296719d-9a86-75f4-9c12-9cf65b15f7c2","type":"code","position":"aQ","content":{"language":"python","code":"from multiprocessing import Process, Value, Manager\n\ndef add(counter, n):\n    for _ in range(n):\n        with counter.get_lock():          # += on shared memory still needs the lock\n            counter.value += 1\n\ndef record(d, key):\n    d[key] = key * 2\n\nif __name__ == \"__main__\":\n    counter = Value(\"i\", 0)\n    ps = [Process(target=add, args=(counter, 1000)) for _ in range(4)]\n    for p in ps: p.start()\n    for p in ps: p.join()\n    print(counter.value)                  # 4000\n\n    with Manager() as m:\n        d = m.dict()\n        ps = [Process(target=record, args=(d, k)) for k in range(3)]\n        for p in ps: p.start()\n        for p in ps: p.join()\n        print(dict(sorted(d.items())))    # {0: 0, 1: 2, 2: 4}","filename":"Python"},"revision":1},{"id":"99a07c1e-c0ef-78c8-a3c6-6abc3b625263","type":"text","position":"aR","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"shared_memory","marks":[{"type":"code"}]},{"type":"text","text":" hands out a named buffer; another process attaches by name. Here both ends live in one process to show the API:"}]}]}},"revision":1},{"id":"2b37d559-c445-7498-97f3-3bbdd21ccdd7","type":"code","position":"aS","content":{"language":"python","code":"from multiprocessing import shared_memory\n\nshm = shared_memory.SharedMemory(create=True, size=4)\ntry:\n    shm.buf[:4] = bytes([1, 2, 3, 4])\n    other = shared_memory.SharedMemory(name=shm.name)   # normally done in another process\n    print(list(other.buf[:4]))                          # [1, 2, 3, 4]\n    other.close()\nfinally:\n    shm.close()\n    shm.unlink()                          # free the block (only the creator does this)","filename":"Python"},"revision":1},{"id":"2c2d7c12-c4e3-763c-8d7c-b2829088bb54","type":"callout","position":"aT","content":{"variant":"tip","title":"Do","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Use processes for CPU-heavy, independent chunks of work; keep messages small; prefer "},{"type":"text","text":"ProcessPoolExecutor","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"Pool","marks":[{"type":"code"}]},{"type":"text","text":" over hand-managed "},{"type":"text","text":"Process","marks":[{"type":"code"}]},{"type":"text","text":" objects."}]}]}},"revision":1},{"id":"896cb50e-5345-7395-8fbb-48b32b5dfff6","type":"callout","position":"aU","content":{"variant":"danger","title":"Avoid","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Spawning a process per tiny task, sharing huge objects through a "},{"type":"text","text":"Manager","marks":[{"type":"code"}]},{"type":"text","text":", or forgetting the "},{"type":"text","text":"__main__","marks":[{"type":"code"}]},{"type":"text","text":" guard."}]}]}},"revision":1},{"id":"f75c6ab3-cfef-7827-86f3-405494e771c4","type":"question","position":"aV","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why does multiprocessing need if __name__ == \"__main__\"?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"With "},{"type":"text","text":"spawn","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"forkserver","marks":[{"type":"code"}]},{"type":"text","text":" the child process imports your main module to find the target function. Without the guard, that import would execute the process-creating code again — infinite recursion (Python raises a "},{"type":"text","text":"RuntimeError","marks":[{"type":"code"}]},{"type":"text","text":" to stop it)."}]}]}},"revision":1},{"id":"236d7ba5-fa20-79e0-88a2-4b92fba10c1c","type":"question","position":"aW","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do processes share data?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"By default they don''t — each has its own memory. You send pickled messages ("},{"type":"text","text":"Queue","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Pipe","marks":[{"type":"code"}]},{"type":"text","text":", pool arguments/results), or share explicitly with "},{"type":"text","text":"Value","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"Array","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"shared_memory","marks":[{"type":"code"}]},{"type":"text","text":", or a "},{"type":"text","text":"Manager","marks":[{"type":"code"}]},{"type":"text","text":" proxy."}]}]}},"revision":1},{"id":"cfda4edb-e100-78e1-a3ea-ac003bd89b1c","type":"question","position":"aX","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"fork vs spawn?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"fork","marks":[{"type":"code"}]},{"type":"text","text":" copies the running parent (fast, inherits everything — including held locks from other threads, which can deadlock). "},{"type":"text","text":"spawn","marks":[{"type":"code"}]},{"type":"text","text":" starts a fresh interpreter (slower, but clean and portable). macOS and Windows default to "},{"type":"text","text":"spawn","marks":[{"type":"code"}]},{"type":"text","text":"; Linux moved from "},{"type":"text","text":"fork","marks":[{"type":"code"}]},{"type":"text","text":" to "},{"type":"text","text":"forkserver","marks":[{"type":"code"}]},{"type":"text","text":" in 3.14."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
