  ('e6d3d483-268a-7ed0-a787-a5392cc73a84', 'a4', 'heading', '{"level":1,"content":[{"type":"text","text":"Process","marks":[{"type":"code"}]},{"type":"text","text":": start, join, exit code"}]}'),
  ('0dab6fbb-6707-7731-ade8-65d1ac4f29ce', 'a5', 'code', '{"language":"python","code":"from multiprocessing import Process, current_process\n\ndef work(n):\n    print(f\"{current_process().name}: {n * n}\")\n\nif __name__ == \"__main__\":\n    procs = [Process(target=work, args=(i,), name=f\"P{i}\") for i in range(3)]\n    for p in procs:\n        p.start()\n    for p in procs:\n        p.join()\n    print(\"exit codes:\", [p.exitcode for p in procs])","filename":"Python"}'),
