  ('5ebf92b8-9924-72ec-917b-14634cf245cf', 'a7', 'callout', '{"variant":"warning","title":"Required","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"if __name__ == \"__main__\":","marks":[{"type":"code"}]},{"type":"text","text":" guard is "},{"type":"text","text":"mandatory","marks":[{"type":"bold"}]},{"type":"text","text":" with the "},{"type":"text","text":"spawn","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"forkserver","marks":[{"type":"code"}]},{"type":"text","text":" start methods: each child re-imports your module, and without the guard it would start children of its own, recursively."}]}]}}'),
