FROM (VALUES
  ('cdc675ab-2241-71f3-8552-7ce9dba12b67', 'a0', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Python has unlimited-size integers, IEEE-754 binary floats, exact "},{"type":"text","text":"Decimal","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"Fraction","marks":[{"type":"code"}]},{"type":"text","text":" types and a rich "},{"type":"text","text":"math","marks":[{"type":"code"}]},{"type":"text","text":" module. Picking the right one avoids rounding bugs and overflow."}]}]}}'),
  ('2c519817-c14c-73f8-8954-640d3318b93d', 'a1', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Type"}],[{"type":"text","text":"Precision"}],[{"type":"text","text":"Speed"}],[{"type":"text","text":"Use for"}]],[[{"type":"text","text":"int","marks":[{"type":"code"}]}],[{"type":"text","text":"Exact, "},{"type":"text","text":"unlimited","marks":[{"type":"bold"}]},{"type":"text","text":" size"}],[{"type":"text","text":"Fast"}],[{"type":"text","text":"Counting, indices, IDs, big-number math"}]],[[{"type":"text","text":"float","marks":[{"type":"code"}]}],[{"type":"text","text":"~15–17 significant digits (64-bit binary)"}],[{"type":"text","text":"Fastest (hardware)"}],[{"type":"text","text":"Science, measurements, ML — where tiny errors are fine"}]],[[{"type":"text","text":"decimal.Decimal","marks":[{"type":"code"}]}],[{"type":"text","text":"Exact decimal, configurable precision"}],[{"type":"text","text":"Slower"}],[{"type":"text","text":"Money","marks":[{"type":"bold"}]},{"type":"text","text":", financial rounding rules"}]],[[{"type":"text","text":"fractions.Fraction","marks":[{"type":"code"}]}],[{"type":"text","text":"Exact rational "},{"type":"text","text":"p/q","marks":[{"type":"code"}]}],[{"type":"text","text":"Slowest"}],[{"type":"text","text":"Exact ratios, probability, teaching"}]],[[{"type":"text","text":"complex","marks":[{"type":"code"}]}],[{"type":"text","text":"Pair of floats"}],[{"type":"text","text":"Fast"}],[{"type":"text","text":"Signal processing, maths ("},{"type":"text","text":"2 + 3j","marks":[{"type":"code"}]},{"type":"text","text":")"}]]]}'),
  ('5dc75b64-78cd-7188-8ebf-3a9c43f94e05', 'a2', 'heading', '{"level":1,"content":[{"type":"text","text":"Integers: unlimited & many literals"}]}'),
  ('7a97d22d-a4a9-7b00-b7bb-ec538de51bdf', 'a3', 'code', '{"language":"python","code":"print(2 ** 100)                               # 1267650600228229401496703205376\nprint(0b1010, 0o17, 0xFF, 1_000_000)          # 10 15 255 1000000\nprint(int(\"1010\", 2), int(\"z\", 36), int(\" 42 \"))   # 10 35 42\nn = 37\nprint(n.bit_length(), n.bit_count(), bin(n))  # 6 3 0b100101\nprint(7 // 2, -7 // 2, -7 % 3, int(-3.9))     # 3 -4 2 -3\nprint(divmod(17, 5), divmod(-17, 5))          # (3, 2) (-4, 3)","filename":"Python"}'),
  ('33465886-f9e6-7252-8099-a426df9e7b3b', 'a4', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"//","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"%","marks":[{"type":"code"}]},{"type":"text","text":" round toward "},{"type":"text","text":"negative infinity","marks":[{"type":"bold"}]},{"type":"text","text":", so "},{"type":"text","text":"-7 // 2 == -4","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"-7 % 3 == 2","marks":[{"type":"code"}]},{"type":"text","text":" (the result has the sign of the divisor). C and Java truncate toward zero. "},{"type":"text","text":"int()","marks":[{"type":"code"}]},{"type":"text","text":" truncates toward zero."}]}]}}'),
  ('1546f7a8-a3e4-799a-8376-878d2b1b7905', 'a5', 'code', '{"language":"python","code":"print(pow(2, 10), pow(2, 10, 1000))    # 1024 24     ← fast modular exponentiation\nprint(pow(3, -1, 7))                   # 5           ← modular inverse: 3 * 5 % 7 == 1\nprint(True + True, isinstance(True, int))   # 2 True\nprint((255).to_bytes(2, \"big\"), int.from_bytes(b\"\\x01\\x00\", \"big\"))   # b''\\x00\\xff'' 256","filename":"Python"}'),
  ('e94178a2-dc66-776b-bc6d-7377d7061858', 'a6', 'callout', '{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Converting a huge "},{"type":"text","text":"int","marks":[{"type":"code"}]},{"type":"text","text":" to/from "},{"type":"text","text":"str","marks":[{"type":"code"}]},{"type":"text","text":" is limited to 4300 digits by default (a DoS protection since 3.11): "},{"type":"text","text":"str(10**5000)","marks":[{"type":"code"}]},{"type":"text","text":" raises "},{"type":"text","text":"ValueError","marks":[{"type":"code"}]},{"type":"text","text":". Raise it with "},{"type":"text","text":"sys.set_int_max_str_digits(n)","marks":[{"type":"code"}]},{"type":"text","text":" if you really need to."}]}]}}'),
  ('3ad049b3-e8b9-7132-8cbb-76d8ea7adb44', 'a7', 'heading', '{"level":1,"content":[{"type":"text","text":"Floats are binary approximations"}]}'),
  ('8267cc0d-c055-77d4-a82d-773804a96775', 'a8', 'code', '{"language":"python","code":"print(0.1 + 0.2)                        # 0.30000000000000004\nprint(0.1 + 0.2 == 0.3)                 # False\nimport math\nprint(math.isclose(0.1 + 0.2, 0.3))     # True\nprint((0.1).as_integer_ratio())         # (3602879701896397, 36028797018963968)\nprint(f\"{0.1:.20f}\")                    # 0.10000000000000000555\ntotal = 0.0\nfor _ in range(10):\n    total += 0.1                        # error accumulates step by step\nprint(total, math.fsum([0.1] * 10))     # 0.9999999999999999 1.0\nprint(sum([0.1] * 10))                  # 1.0   ← sum() of floats is compensated since 3.12\nprint(2 ** 53 + 1.0 == 2 ** 53)         # True   ← integers above 2**53 lose precision","filename":"Python"}'),
  ('e882dd58-b0a8-751a-8191-87392954cb6b', 'a9', 'callout', '{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"IEEE 754 double","marks":[{"type":"bold"}]},{"type":"text","text":" — 64 bits: 1 sign bit, 11 exponent bits, 52 fraction bits. Only numbers of the form "},{"type":"text","text":"m × 2ᵉ","marks":[{"type":"italic"}]},{"type":"text","text":" are exact, so decimal fractions like 0.1 are stored as the nearest binary value."}]}]}}'),
  ('8b4ddf6c-6a59-7696-be82-6be9d9f767c3', 'aA', 'callout', '{"variant":"tip","title":"Do","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Compare floats with "},{"type":"text","text":"math.isclose(a, b, rel_tol=1e-9, abs_tol=…)","marks":[{"type":"code"}]},{"type":"text","text":"; sum many floats with "},{"type":"text","text":"math.fsum","marks":[{"type":"code"}]},{"type":"text","text":"; keep money in integer cents or "},{"type":"text","text":"Decimal","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('d2eb7b9a-ab78-7262-b85c-dd6623b5dfaf', 'aB', 'callout', '{"variant":"danger","title":"Avoid","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"if total == 0.3:","marks":[{"type":"code"}]},{"type":"text","text":" or storing prices as floats — errors accumulate and comparisons fail."}]}]}}'),
  ('f4893506-bc89-749a-8202-c856ec309e32', 'aC', 'heading', '{"level":1,"content":[{"type":"text","text":"inf, nan & float limits"}]}'),
  ('fb6de504-7e33-73b5-9ea6-471d8127c8e2', 'aD', 'code', '{"language":"python","code":"import math, sys\ninf, nan = float(\"inf\"), float(\"nan\")\nprint(inf > 10**308, -inf < 0, inf - inf)     # True True nan\nprint(nan == nan, math.isnan(nan))            # False True\nprint(1e308 * 10, 2.0 ** -1075)               # inf 0.0\nprint(sys.float_info.max, sys.float_info.epsilon)   # 1.7976931348623157e+308 2.220446049250313e-16\nprint(sorted([3, nan, 1]))                    # [3, nan, 1]   ← nan breaks sorting","filename":"Python"}'),
  ('c725ffee-55c4-780d-a8aa-eeee34debd26', 'aE', 'callout', '{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"nan","marks":[{"type":"code"}]},{"type":"text","text":" is not equal to anything, including itself, so "},{"type":"text","text":"x in list","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"sort","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"max","marks":[{"type":"code"}]},{"type":"text","text":" and dict lookups behave strangely with it. Filter with "},{"type":"text","text":"math.isnan","marks":[{"type":"code"}]},{"type":"text","text":" first. Also "},{"type":"text","text":"1 / 0","marks":[{"type":"code"}]},{"type":"text","text":" raises "},{"type":"text","text":"ZeroDivisionError","marks":[{"type":"code"}]},{"type":"text","text":" — Python does not return "},{"type":"text","text":"inf","marks":[{"type":"code"}]},{"type":"text","text":" for division."}]}]}}'),
  ('5d8c5b1d-1aee-7a5e-93d4-1e9f05134b6e', 'aF', 'heading', '{"level":1,"content":[{"type":"text","text":"Rounding"}]}'),
  ('aede5f98-5eca-724c-ade2-31540c2298c4', 'aG', 'code', '{"language":"python","code":"import math\nprint(round(2.5), round(3.5), round(-2.5))       # 2 4 -2   ← banker''s rounding\nprint(round(2.675, 2))                           # 2.67     ← 2.675 is really 2.67499999…\nprint(round(1234.5678, -2))                      # 1200.0\nprint(math.floor(-2.5), math.ceil(-2.5), math.trunc(-2.5))   # -3 -2 -2\nprint(int(2.99), math.floor(2.99))               # 2 2","filename":"Python"}'),
  ('9945f220-de12-7aa6-8468-7e1c8aff772e', 'aH', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Function"}],[{"type":"text","text":"Rounds"}],[{"type":"text","text":"2.5","marks":[{"type":"code"}]}],[{"type":"text","text":"-2.5","marks":[{"type":"code"}]}]],[[{"type":"text","text":"round(x)","marks":[{"type":"code"}]}],[{"type":"text","text":"To nearest, ties to "},{"type":"text","text":"even","marks":[{"type":"bold"}]}],[{"type":"text","text":"2","marks":[{"type":"code"}]}],[{"type":"text","text":"-2","marks":[{"type":"code"}]}]],[[{"type":"text","text":"math.floor(x)","marks":[{"type":"code"}]}],[{"type":"text","text":"Down (toward −∞)"}],[{"type":"text","text":"2","marks":[{"type":"code"}]}],[{"type":"text","text":"-3","marks":[{"type":"code"}]}]],[[{"type":"text","text":"math.ceil(x)","marks":[{"type":"code"}]}],[{"type":"text","text":"Up (toward +∞)"}],[{"type":"text","text":"3","marks":[{"type":"code"}]}],[{"type":"text","text":"-2","marks":[{"type":"code"}]}]],[[{"type":"text","text":"math.trunc(x)","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"int(x)","marks":[{"type":"code"}]}],[{"type":"text","text":"Toward zero"}],[{"type":"text","text":"2","marks":[{"type":"code"}]}],[{"type":"text","text":"-2","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Decimal.quantize(…, ROUND_HALF_UP)","marks":[{"type":"code"}]}],[{"type":"text","text":"Ties away from zero (school rounding)"}],[{"type":"text","text":"3","marks":[{"type":"code"}]}],[{"type":"text","text":"-3","marks":[{"type":"code"}]}]]]}'),
  ('28051a0b-2631-7a06-afec-5b8a4d0bc92e', 'aI', 'heading', '{"level":1,"content":[{"type":"text","text":"Decimal: exact decimal arithmetic"}]}'),
  ('d9d452bf-9d89-78a3-ad14-0a87c4680d38', 'aJ', 'code', '{"language":"python","code":"from decimal import Decimal, ROUND_HALF_UP, getcontext, localcontext\nprint(Decimal(\"0.1\") + Decimal(\"0.2\"))               # 0.3\nprint(Decimal(0.1))                                  # 0.1000000000000000055511151231257827021181583404541015625\nprice = Decimal(\"19.99\")\ntotal = price * 3\nprint(total, total * Decimal(\"1.18\"))                # 59.97 70.7646\ntax = (total * Decimal(\"0.18\")).quantize(Decimal(\"0.01\"), rounding=ROUND_HALF_UP)\nprint(tax)                                           # 10.79\nprint(Decimal(\"2.5\").quantize(Decimal(\"1\"), rounding=ROUND_HALF_UP))   # 3\nprint(getcontext().prec)                             # 28\nwith localcontext() as ctx:\n    ctx.prec = 5\n    print(Decimal(1) / Decimal(7))                   # 0.14286","filename":"Python"}'),
  ('f1d5e006-0446-70bb-8e6a-87145cef5ff6', 'aK', 'callout', '{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Build "},{"type":"text","text":"Decimal","marks":[{"type":"code"}]},{"type":"text","text":" from "},{"type":"text","text":"strings","marks":[{"type":"bold"}]},{"type":"text","text":" ("},{"type":"text","text":"Decimal(''0.1'')","marks":[{"type":"code"}]},{"type":"text","text":"), never from floats — "},{"type":"text","text":"Decimal(0.1)","marks":[{"type":"code"}]},{"type":"text","text":" faithfully copies the float''s binary error. Also don''t mix "},{"type":"text","text":"Decimal","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"float","marks":[{"type":"code"}]},{"type":"text","text":" in arithmetic: it raises "},{"type":"text","text":"TypeError","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('6b98661a-1f03-7900-bab6-21941bc762c1', 'aL', 'heading', '{"level":1,"content":[{"type":"text","text":"Fraction & complex"}]}'),
  ('5d29f89f-b185-7514-80e8-2a11f5fad7cd', 'aM', 'code', '{"language":"python","code":"from fractions import Fraction\nf = Fraction(1, 3) + Fraction(1, 6)\nprint(f, f.numerator, f.denominator)            # 1/2 1 2\nprint(Fraction(\"0.75\"), Fraction(0.1).limit_denominator(100))   # 3/4 1/10\nprint(float(Fraction(22, 7)))                   # 3.142857142857143\n\nz = 3 + 4j\nprint(z.real, z.imag, abs(z), z.conjugate())    # 3.0 4.0 5.0 (3-4j)\nimport cmath\nprint(cmath.sqrt(-1))                           # 1j","filename":"Python"}'),
  ('298299d5-5b88-7711-9678-2cdebf1eb268', 'aN', 'heading', '{"level":1,"content":[{"type":"text","text":"The "},{"type":"text","text":"math","marks":[{"type":"code"}]},{"type":"text","text":" module"}]}'),
  ('b2168f89-8c4a-705c-b3b4-62d3224fbd83', 'aO', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Function"}],[{"type":"text","text":"Does"}],[{"type":"text","text":"Example"}]],[[{"type":"text","text":"sqrt","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"isqrt","marks":[{"type":"code"}]}],[{"type":"text","text":"Float root / exact integer floor root"}],[{"type":"text","text":"math.isqrt(17)","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"4","marks":[{"type":"code"}]}]],[[{"type":"text","text":"gcd","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"lcm","marks":[{"type":"code"}]}],[{"type":"text","text":"Greatest common divisor / least common multiple (any number of args)"}],[{"type":"text","text":"math.lcm(4, 6)","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"12","marks":[{"type":"code"}]}]],[[{"type":"text","text":"comb","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"perm","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"factorial","marks":[{"type":"code"}]}],[{"type":"text","text":"nCr, nPr, n!"}],[{"type":"text","text":"math.comb(5, 2)","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"10","marks":[{"type":"code"}]}]],[[{"type":"text","text":"prod","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"fsum","marks":[{"type":"code"}]}],[{"type":"text","text":"Product / precise float sum"}],[{"type":"text","text":"math.prod([2, 3, 4])","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"24","marks":[{"type":"code"}]}]],[[{"type":"text","text":"log","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"log2","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"log10","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"exp","marks":[{"type":"code"}]}],[{"type":"text","text":"Logarithms ("},{"type":"text","text":"log(x, base)","marks":[{"type":"code"}]},{"type":"text","text":")"}],[{"type":"text","text":"math.log2(1024)","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"10.0","marks":[{"type":"code"}]}]],[[{"type":"text","text":"hypot","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"dist","marks":[{"type":"code"}]}],[{"type":"text","text":"Euclidean length / distance between points"}],[{"type":"text","text":"math.dist((0, 0), (3, 4))","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"5.0","marks":[{"type":"code"}]}]],[[{"type":"text","text":"floor","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"ceil","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"trunc","marks":[{"type":"code"}]}],[{"type":"text","text":"Rounding to int"}],[{"type":"text","text":"math.ceil(2.1)","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"3","marks":[{"type":"code"}]}]],[[{"type":"text","text":"pi","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"e","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"tau","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"inf","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"nan","marks":[{"type":"code"}]}],[{"type":"text","text":"Constants"}],[{"type":"text","text":"math.tau == 2 * math.pi","marks":[{"type":"code"}]}]],[[{"type":"text","text":"isclose","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"isfinite","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"isnan","marks":[{"type":"code"}]}],[{"type":"text","text":"Float checks"}],[{"type":"text","text":"math.isclose(0.1 + 0.2, 0.3)","marks":[{"type":"code"}]}]]]}'),
  ('98940c3d-c484-761b-8745-b45f0cde7fb9', 'aP', 'code', '{"language":"python","code":"import math\nprint(math.isqrt(10**20), math.sqrt(2))        # 10000000000 1.4142135623730951\nprint(math.gcd(12, 18, 30), math.lcm(4, 6))    # 6 12\nprint(math.comb(52, 5), math.perm(5, 2), math.factorial(10))   # 2598960 20 3628800\nprint(math.prod(range(1, 6)), math.log2(1024), math.log(8, 2))  # 120 10.0 3.0\nprint(math.hypot(3, 4), math.dist((1, 1), (4, 5)))   # 5.0 5.0\nprint(math.degrees(math.pi), round(math.sin(math.pi / 6), 3))   # 180.0 0.5","filename":"Python"}'),
  ('82c6780f-44be-7441-90e1-c98c36b6eb3a', 'aQ', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Use "},{"type":"text","text":"math.isqrt(n)","marks":[{"type":"code"}]},{"type":"text","text":" — not "},{"type":"text","text":"int(math.sqrt(n))","marks":[{"type":"code"}]},{"type":"text","text":" — for perfect-square checks on big integers: the float version is wrong once "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" exceeds 2⁵³."}]}]}}'),
  ('afe9c622-6dbc-778a-9134-a9dd3a676e1d', 'aR', 'heading', '{"level":1,"content":[{"type":"text","text":"Interview questions"}]}'),
  ('23e6e83c-80f5-7c81-8da6-2d1b886e52aa', 'aS', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why is 0.1 + 0.2 != 0.3?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Floats are binary (IEEE 754). 0.1, 0.2 and 0.3 have no exact binary representation, so each is stored as the nearest double; the rounding errors don''t cancel. Compare with "},{"type":"text","text":"math.isclose","marks":[{"type":"code"}]},{"type":"text","text":", or use "},{"type":"text","text":"Decimal","marks":[{"type":"code"}]},{"type":"text","text":" / integer cents when exactness matters."}]}]}}'),
  ('708454dd-d7e1-7a49-adfd-d029903d8d72', 'aT', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Can Python integers overflow?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"No. "},{"type":"text","text":"int","marks":[{"type":"code"}]},{"type":"text","text":" is arbitrary precision — it grows to use as much memory as needed (slower as it grows). Floats can overflow to "},{"type":"text","text":"inf","marks":[{"type":"code"}]},{"type":"text","text":", and "},{"type":"text","text":"numpy","marks":[{"type":"code"}]},{"type":"text","text":" fixed-width integers "},{"type":"text","text":"do","marks":[{"type":"italic"}]},{"type":"text","text":" wrap around."}]}]}}'),
  ('48b34e28-f487-7555-aaab-623841840de2', 'aU', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What does round(2.5) return and why?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"2","marks":[{"type":"code"}]},{"type":"text","text":". Python 3 uses round-half-to-even (banker''s rounding), which avoids a systematic upward bias when rounding many values. Use "},{"type":"text","text":"Decimal.quantize(..., rounding=ROUND_HALF_UP)","marks":[{"type":"code"}]},{"type":"text","text":" for school-style rounding."}]}]}}'),
  ('a8805389-cf21-7fcb-aff8-77c080efd81e', 'aV', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How would you check whether a large number is a perfect square?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"import math","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"def is_square(n):","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"    return n >= 0 and math.isqrt(n) ** 2 == n","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"print(is_square(10**30), is_square(10**30 + 1))   # True False","marks":[{"type":"code"}]}]}]}}')
) AS c(id, position, type, content)
